// ── Auth prehash ("prehash-v1") for re-auth prompts ──────────────────────────
// Matches login.html / the server: PBKDF2-SHA256(password, 'sentinel-auth-v1|'+auth_salt, 600k).
// accountAuthCreds() returns { authHash } for a migrated row, or { password } when the row is
// still on the plaintext scheme (or the params fetch fails) — the server's legacy path verifies
// that form and upgrades the row at next login.
async function _authPrehash(password, saltB64, iterations) {
  const domain = new TextEncoder().encode('sentinel-auth-v1|');
  const raw    = Uint8Array.from(atob(saltB64), c => c.charCodeAt(0));
  const salt   = new Uint8Array(domain.length + raw.length);
  salt.set(domain); salt.set(raw, domain.length);
  const key  = await crypto.subtle.importKey('raw', new TextEncoder().encode(password), 'PBKDF2', false, ['deriveBits']);
  const bits = await crypto.subtle.deriveBits({ name: 'PBKDF2', salt, iterations: iterations || 600000, hash: 'SHA-256' }, key, 256);
  return btoa(String.fromCharCode(...new Uint8Array(bits)));
}
async function accountAuthCreds(password) {
  try {
    const d = await fetch('/api/account/auth-params').then(r => r.ok ? r.json() : null);
    if (d && d.scheme === 'prehash-v1' && d.auth_salt)
      return { authHash: await _authPrehash(password, d.auth_salt, d.iterations) };
  } catch (_) {}
  return { password };
}

// Reflects currentUser.totp_verified into the on/off panel of the 2FA section.
