// ── "Enable 2FA" — password re-auth (POST /api/account/totp/setup) issues a fresh QR,
// then a confirmed code (POST /api/account/totp/enable) turns it on. Skipped at signup?
// This is that flow, just authenticated instead of pre-auth. ────────────────────────
function openEnable2faModal() {
  try { bootstrap.Modal.getInstance(document.getElementById('accountSettingsModal'))?.hide(); } catch (_) {}
  document.getElementById('tfa-pw').value = '';
  document.getElementById('tfa-code').value = '';
  document.getElementById('tfa-qr-img').src = '';
  document.getElementById('tfa-secret-text').textContent = '';
  document.getElementById('tfa-step-start').classList.remove('d-none');
  document.getElementById('tfa-step-verify').classList.add('d-none');
  document.getElementById('tfa-start-go').classList.remove('d-none');
  document.getElementById('tfa-verify-go').classList.add('d-none');
  hideEl('tfa-start-err'); hideEl('tfa-verify-err');
  bootstrap.Modal.getOrCreateInstance(document.getElementById('enable2faModal')).show();
}

async function submitEnable2faStart() {
  const pw  = document.getElementById('tfa-pw').value || '';
  const err = document.getElementById('tfa-start-err');
  const btn = document.getElementById('tfa-start-go');
  const fail = m => { err.textContent = m; err.classList.remove('d-none'); };
  hideEl('tfa-start-err');
  if (!pw) return fail('Enter your password.');
  btn.disabled = true; btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Starting…';
  try {
    const r = await fetch('/api/account/totp/setup', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(await accountAuthCreds(pw)),
    });
    const d = await r.json().catch(() => ({}));
    btn.disabled = false; btn.innerHTML = '<i class="bi bi-arrow-right-circle me-1"></i>Continue';
    if (!r.ok) return fail(d.error || 'Failed — please try again.');
    document.getElementById('tfa-qr-img').src = d.qr_data_url || '';
    try { document.getElementById('tfa-secret-text').textContent = new URL(d.otpauth).searchParams.get('secret') || ''; } catch (_) {}
    document.getElementById('tfa-step-start').classList.add('d-none');
    document.getElementById('tfa-step-verify').classList.remove('d-none');
    document.getElementById('tfa-start-go').classList.add('d-none');
    document.getElementById('tfa-verify-go').classList.remove('d-none');
  } catch (_) {
    btn.disabled = false; btn.innerHTML = '<i class="bi bi-arrow-right-circle me-1"></i>Continue';
    fail('Network error — please try again.');
  }
}

async function submitEnable2faVerify() {
  const code = (document.getElementById('tfa-code').value || '').replace(/\s/g, '');
  const err  = document.getElementById('tfa-verify-err');
  const btn  = document.getElementById('tfa-verify-go');
  const fail = m => { err.textContent = m; err.classList.remove('d-none'); };
  hideEl('tfa-verify-err');
  if (!/^\d{6}$/.test(code)) return fail('Enter the 6-digit code from your authenticator app.');
  btn.disabled = true; btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Enabling…';
  try {
    const r = await fetch('/api/account/totp/enable', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ code }),
    });
    const d = await r.json().catch(() => ({}));
    btn.disabled = false; btn.innerHTML = '<i class="bi bi-check2-circle me-1"></i>Enable 2FA';
    if (!r.ok) return fail(d.error || 'Failed — please try again.');
    try { bootstrap.Modal.getInstance(document.getElementById('enable2faModal'))?.hide(); } catch (_) {}
    currentUser.totp_verified = true;
    _refreshTfaStatus();
    showToast('Two-factor authentication enabled', 'success');
  } catch (_) {
    btn.disabled = false; btn.innerHTML = '<i class="bi bi-check2-circle me-1"></i>Enable 2FA';
    fail('Network error — please try again.');
  }
}

