// ── Discord webhook (public owners) ──
// The owner's own webhook: notifyUser() fans the same alerts out to email/push/Discord from
// notif_prefs. Saves via PATCH /api/users/me/notif-prefs — the server re-validates with
// isDiscordWebhookUrl(); this client check mirrors it for instant feedback.
function _isDiscordWebhookUrl(u) {
  try {
    const url = new URL(String(u));
    return url.protocol === 'https:' &&
      ['discord.com', 'discordapp.com', 'canary.discord.com', 'ptb.discord.com']
        .includes(url.hostname.toLowerCase()) &&
      url.pathname.startsWith('/api/webhooks/');
  } catch { return false; }
}

async function onNotifDiscordSave() {
  const inp = document.getElementById('notif-set-discord-webhook');
  if (!inp) return;
  const url = inp.value.trim();
  if (url && !_isDiscordWebhookUrl(url)) {
    showToast('Invalid Discord webhook URL', 'danger');
    return;
  }
  try {
    const r = await fetch('/api/users/me/notif-prefs', {
      method: 'PATCH', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ discord_webhook: url }),
    });
    if (!r.ok) throw new Error('save failed');
    const clearEl = document.getElementById('notif-discord-clear');
    if (clearEl) clearEl.classList.toggle('d-none', !url);
    showToast(url ? 'Discord alerts on' : 'Discord webhook cleared', url ? 'success' : 'secondary');
  } catch (_) {
    showToast('Failed to save Discord webhook', 'danger');
  }
}

function onNotifDiscordClear() {
  const inp = document.getElementById('notif-set-discord-webhook');
  if (inp) inp.value = '';
  onNotifDiscordSave();
}

