// ── "Secure my account" — zero-knowledge compromise recovery (public users) ──
// Re-auth (password + 2FA) → POST /api/account/secure, which rotates the ZK keypair: it abandons
// all server-side encrypted data (wrapped to the burned key), releases the owner's devices to their
// email lineage, and revokes every session. The owner recovers by re-registering with the same
// email and re-linking each device from the device itself.
function openSecureAccountModal() {
  try { bootstrap.Modal.getInstance(document.getElementById('accountSettingsModal'))?.hide(); } catch (_) {}
  const pw = document.getElementById('secacct-pw');   if (pw) pw.value = '';
  const tp = document.getElementById('secacct-totp'); if (tp) tp.value = '';
  const err = document.getElementById('secacct-err'); if (err) { err.classList.add('d-none'); err.textContent = ''; }
  // 2FA is optional at signup — only ask for a code if this account actually has it enabled.
  document.getElementById('secacct-totp-wrap')?.classList.toggle('d-none', !currentUser?.totp_verified);
  bootstrap.Modal.getOrCreateInstance(document.getElementById('secureAccountModal')).show();
}

async function submitSecureAccount() {
  const pw   = (document.getElementById('secacct-pw')?.value || '');
  const code = (document.getElementById('secacct-totp')?.value || '').replace(/\s/g, '');
  const err  = document.getElementById('secacct-err');
  const btn  = document.getElementById('secacct-go');
  const fail = (m) => { if (err) { err.textContent = m; err.classList.remove('d-none'); } };
  const reset = () => { if (btn) { btn.disabled = false; btn.innerHTML = '<i class="bi bi-shield-lock me-1"></i>Rotate keys &amp; secure'; } };
  if (err) { err.classList.add('d-none'); err.textContent = ''; }
  if (!pw) return fail('Enter your password.');
  if (currentUser?.totp_verified && !/^\d{6}$/.test(code)) return fail('Enter your 6-digit 2FA code.');
  if (btn) { btn.disabled = true; btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Securing…'; }
  try {
    const r = await fetch('/api/account/secure', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ...(await accountAuthCreds(pw)), code }),
    });
    const data = await r.json().catch(() => ({}));
    if (!r.ok) { reset(); return fail(data.error || 'Failed — please try again.'); }
    // Re-keyed + all sessions revoked. Drop local key material and guide re-signup with the same email.
    try { sessionStorage.removeItem('zk_priv_key'); } catch (_) {}
    try { bootstrap.Modal.getInstance(document.getElementById('secureAccountModal'))?.hide(); } catch (_) {}
    const mail = data.reRegisterEmail || '';
    alert('Your account has been secured and your encryption keys rotated.\n\n' +
          (data.devicesReleased ? data.devicesReleased + ' device(s) were unlinked. ' : '') +
          'Every session has been signed out.\n\n' +
          'Next: sign up again with the same email' + (mail ? ' (' + mail + ')' : '') +
          ', then re-link each device from the device itself.');
    window.location.href = '/register' + (mail ? ('?em=' + encodeURIComponent(mail)) : '');
  } catch (_) {
    reset();
    fail('Network error — please try again.');
  }
}

// Deep link from the sign-in security email: /?secure=account auto-opens the modal (public users).
// Strips the param so a refresh/back doesn't re-trigger. Called once currentUser is loaded.
function maybeOpenSecureAccountFromLink() {
  try {
    const p = new URLSearchParams(location.search);
    if (p.get('secure') !== 'account') return;
    p.delete('secure');
    const qs = p.toString();
    history.replaceState(null, '', location.pathname + (qs ? '?' + qs : '') + location.hash);
    if (currentUser?.account_type === 'public') {
      setTimeout(() => { try { openSecureAccountModal(); } catch (_) {} }, 400);
    }
  } catch (_) {}
}

// ── "Convert to Business Account" — one-way compliance toggle (public users) ─
// Re-auth (password + 2FA if enabled) → POST /api/account/business-mode, which can only ever turn
// this ON. Once on, audio/video/screen-recording/keylog/manual-photo commands are permanently
// blocked server-side on every device this account owns; only an admin can revert it.
function openBusinessModeModal() {
  try { bootstrap.Modal.getInstance(document.getElementById('accountSettingsModal'))?.hide(); } catch (_) {}
  const pw = document.getElementById('bizmode-pw');   if (pw) pw.value = '';
  const tp = document.getElementById('bizmode-totp'); if (tp) tp.value = '';
  const err = document.getElementById('bizmode-err'); if (err) { err.classList.add('d-none'); err.textContent = ''; }
  document.getElementById('bizmode-totp-wrap')?.classList.toggle('d-none', !currentUser?.totp_verified);
  bootstrap.Modal.getOrCreateInstance(document.getElementById('businessModeModal')).show();
}

async function submitBusinessMode() {
  const pw   = (document.getElementById('bizmode-pw')?.value || '');
  const code = (document.getElementById('bizmode-totp')?.value || '').replace(/\s/g, '');
  const err  = document.getElementById('bizmode-err');
  const btn  = document.getElementById('bizmode-go');
  const fail = (m) => { if (err) { err.textContent = m; err.classList.remove('d-none'); } };
  const reset = () => { if (btn) { btn.disabled = false; btn.innerHTML = '<i class="bi bi-briefcase me-1"></i>Convert to Business Account'; } };
  if (err) { err.classList.add('d-none'); err.textContent = ''; }
  if (!pw) return fail('Enter your password.');
  if (currentUser?.totp_verified && !/^\d{6}$/.test(code)) return fail('Enter your 6-digit 2FA code.');
  if (btn) { btn.disabled = true; btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Converting…'; }
  try {
    const r = await fetch('/api/account/business-mode', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ...(await accountAuthCreds(pw)), code }),
    });
    const data = await r.json().catch(() => ({}));
    if (!r.ok) { reset(); return fail(data.error || 'Failed — please try again.'); }
    try { bootstrap.Modal.getInstance(document.getElementById('businessModeModal'))?.hide(); } catch (_) {}
    currentUser.business_mode = true;
    document.getElementById('business-mode-section')?.classList.add('d-none');
    document.getElementById('team-section')?.classList.remove('d-none');
    showToast('Business Account mode enabled', 'success');
    _updateBusinessAccountBadge();
    if (typeof loadDevices === 'function') {
      // Wait for the fresh business_mode flag to land in deviceCache before re-applying the
      // currently-open device's tab restrictions — otherwise it'd re-check the stale (false) flag.
      loadDevices().then(() => {
        if (selectedDeviceId) {
          applyPermissionsForDevice(selectedDeviceId);
          applyBusinessModeTabRestrictions(selectedDeviceId);
        }
      });
    }
  } catch (_) {
    reset();
    fail('Network error — please try again.');
  }
}

// ── "Team" — Business Account owners create sub-users scoped to their own devices ────────
// Full ZK parity by design: creating a team member re-wraps a COPY of the OWNER's existing EC
// private key (never generates a new one) under the new member's password via _zkRewrapPrivKey,
// so their login can decrypt exactly the devices the owner grants them (server-side scoping via
// parent_owner_id + the same per-device permissions map admin sub-users use).
// The Team modal is only reachable when the account is in Business Account mode (see
// openAccountSettings()/team-section) — so every device here is under the same compliance
// restrictions. Exclude the permanently-disabled permission keys (BUSINESS_MODE_HIDDEN_TABS,
// declared further down in this file) from the grantable set entirely, rather than showing
// checkboxes for features the account can never actually use.
function _teamGrantablePerms() {
  return Object.keys(PERM_LABELS).filter(p => !BUSINESS_MODE_HIDDEN_TABS.includes(p));
}

function _teamPermRow(subUserId, deviceId, deviceName, dp) {
  const checks = _teamGrantablePerms().map(p => `
    <label class="form-check form-check-inline mb-0" title="${PERM_LABELS[p]}">
      <input class="form-check-input" type="checkbox" id="tdp-${subUserId}-${deviceId}-${p}"
        ${dp[p] ? 'checked' : ''} onchange="saveTeamDevicePerms(${subUserId},'${deviceId}')">
      <span class="form-check-label" style="font-size:.7rem">${PERM_LABELS[p]}</span>
    </label>`).join('');
  return `<tr>
    <td class="align-middle text-nowrap small fw-medium" style="min-width:110px">${esc(deviceName)}</td>
    <td class="align-middle">${checks}</td>
    <td class="align-middle">
      <button class="btn btn-sm btn-outline-danger py-0" onclick="revokeTeamDeviceAccess(${subUserId},'${deviceId}')" title="Revoke access">
        <i class="bi bi-x-lg"></i>
      </button>
    </td>
  </tr>`;
}

async function loadTeamList() {
  const container = document.getElementById('team-list-container');
  if (!container) return;
  container.innerHTML = '<div class="text-muted small">Loading…</div>';
  try {
    const [subusers, ownDevices] = await Promise.all([
      fetch('/api/account/subusers').then(r => r.json()),
      fetch('/api/devices').then(r => r.json()),
    ]);
    const deviceMap = Object.fromEntries(ownDevices.map(d => [d.id, safeName(d.name, d.id)]));
    if (!Array.isArray(subusers) || !subusers.length) {
      container.innerHTML = '<p class="text-muted small mb-0">No team members yet — add one above.</p>';
      return;
    }
    container.innerHTML = subusers.map(u => {
      const perms = u.permissions || {};
      const grantedIds = Object.keys(perms).filter(id => deviceMap[id]);
      const ungranted = ownDevices.filter(d => !perms[d.id]);
      const rows = grantedIds.map(id => _teamPermRow(u.id, id, deviceMap[id], perms[id] || {})).join('');
      const addOption = ungranted.length ? `
        <div class="d-flex align-items-center gap-2 mt-1">
          <select class="form-select form-select-sm" style="max-width:220px" id="team-add-dev-${u.id}">
            ${ungranted.map(d => `<option value="${d.id}">${esc(safeName(d.name, d.id))}</option>`).join('')}
          </select>
          <button class="btn btn-sm btn-outline-primary" onclick="grantTeamDeviceAccess(${u.id})">
            <i class="bi bi-plus-lg me-1"></i>Grant device
          </button>
        </div>` : '';
      return `
        <div class="border rounded p-2 mb-2">
          <div class="d-flex align-items-center justify-content-between mb-1">
            <span class="fw-semibold">${esc(u.username)}</span>
            <button class="btn btn-sm btn-outline-danger py-0" onclick="removeTeamMember(${u.id}, '${escJsAttr(u.username)}')" title="Remove team member">
              <i class="bi bi-trash"></i>
            </button>
          </div>
          ${rows ? `<table class="table table-sm mb-1"><tbody>${rows}</tbody></table>` : '<div class="text-muted small mb-1">No devices granted yet.</div>'}
          ${addOption}
        </div>`;
    }).join('');
  } catch (_) {
    container.innerHTML = '<p class="text-danger small mb-0">Failed to load team.</p>';
  }
}

function openTeamModal() {
  try { bootstrap.Modal.getInstance(document.getElementById('accountSettingsModal'))?.hide(); } catch (_) {}
  loadTeamList();
  bootstrap.Modal.getOrCreateInstance(document.getElementById('teamModal')).show();
}

async function grantTeamDeviceAccess(subUserId) {
  const sel = document.getElementById(`team-add-dev-${subUserId}`);
  const deviceId = sel?.value;
  if (!deviceId) return;
  const defaultPerms = {};
  for (const p of _teamGrantablePerms()) defaultPerms[p] = false;
  try {
    await fetch(`/api/account/subusers/${subUserId}/devices/${deviceId}`, {
      method: 'PUT', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ permissions: defaultPerms }),
    });
  } catch (_) {}
  loadTeamList();
}

async function saveTeamDevicePerms(subUserId, deviceId) {
  const permissions = {};
  for (const p of _teamGrantablePerms()) {
    const el = document.getElementById(`tdp-${subUserId}-${deviceId}-${p}`);
    permissions[p] = !!el?.checked;
  }
  try {
    await fetch(`/api/account/subusers/${subUserId}/devices/${deviceId}`, {
      method: 'PUT', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ permissions }),
    });
    showToast('Permissions saved', 'success');
  } catch (_) {
    showToast('Failed to save permissions', 'danger');
  }
}

async function revokeTeamDeviceAccess(subUserId, deviceId) {
  try {
    await fetch(`/api/account/subusers/${subUserId}/devices/${deviceId}`, { method: 'DELETE' });
  } catch (_) {}
  loadTeamList();
}

function removeTeamMember(subUserId, username) {
  showConfirm({
    title: 'Remove team member',
    body: `<p class="mb-0 text-muted">Remove <strong>${esc(username)}</strong>? They will be signed out immediately and lose all device access.</p>`,
    okLabel: 'Remove',
    okClass: 'btn-danger',
    onConfirm: async () => {
      try {
        await fetch(`/api/account/subusers/${subUserId}`, { method: 'DELETE' });
        showToast('Team member removed', 'secondary');
      } catch (_) {}
      loadTeamList();
    },
  });
}

function openCreateSubuserModal() {
  const u = document.getElementById('subuser-username'); if (u) u.value = '';
  const p = document.getElementById('subuser-password'); if (p) p.value = '';
  const c = document.getElementById('subuser-confirm');  if (c) c.value = '';
  hideEl('subuser-err');
  bootstrap.Modal.getOrCreateInstance(document.getElementById('createSubuserModal')).show();
}

async function submitCreateSubuser() {
  const username = (document.getElementById('subuser-username')?.value || '').trim();
  const pw       = document.getElementById('subuser-password')?.value || '';
  const conf     = document.getElementById('subuser-confirm')?.value || '';
  const err      = document.getElementById('subuser-err');
  const btn      = document.getElementById('subuser-go');
  const fail  = m => { if (err) { err.textContent = m; err.classList.remove('d-none'); } };
  const reset = () => { if (btn) { btn.disabled = false; btn.innerHTML = '<i class="bi bi-person-plus me-1"></i>Add team member'; } };
  if (err) { err.classList.add('d-none'); err.textContent = ''; }
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(username)) return fail('Enter a valid email address.');
  if (pw.length < 10) return fail('Password must be at least 10 characters.');
  if (pw !== conf) return fail('Passwords do not match.');
  const rawPriv = sessionStorage.getItem('zk_priv_key');
  if (!rawPriv) return fail('Your encryption key is not loaded in this session — sign out and back in, then try again.');
  if (btn) { btn.disabled = true; btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Adding…'; }
  try {
    const saltBytes = crypto.getRandomValues(new Uint8Array(16));
    const auth_salt = btoa(String.fromCharCode(...saltBytes));
    const auth_hash = await _authPrehash(pw, auth_salt, 600000);
    const zkWrapped = await _zkRewrapPrivKey(rawPriv, pw);
    const r = await fetch('/api/account/subusers', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username, auth_hash, auth_salt, ...zkWrapped }),
    });
    const data = await r.json().catch(() => ({}));
    if (!r.ok) { reset(); return fail(data.error || 'Failed — please try again.'); }
    try { bootstrap.Modal.getInstance(document.getElementById('createSubuserModal'))?.hide(); } catch (_) {}
    showToast('Team member added', 'success');
    loadTeamList();
    bootstrap.Modal.getOrCreateInstance(document.getElementById('teamModal')).show();
  } catch (_) {
    reset();
    fail('Network error — please try again.');
  }
}

// ── Hybrid Managed: "Grant support access" (dedicated support delegate, no Business mode) ──────
// Top-level dashboard entry point (navbar btn-support-access) — not buried in Account & Security.
function openSupportAccessModal() {
  loadSupportAccess();
  bootstrap.Modal.getOrCreateInstance(document.getElementById('supportAccessModal')).show();
}
// Renders the support-access panel: either a "Grant" button or the active state + a "Revoke" button.
async function loadSupportAccess() {
  const el = document.getElementById('support-access-body');
  if (!el) return;
  el.innerHTML = '<div class="text-muted small">Loading…</div>';
  try {
    const d = await fetch('/api/account/support-access').then(r => r.json());
    if (!d || d.active !== true) {
      el.innerHTML = `<button class="btn btn-sm btn-outline-info" onclick="openGrantSupportModal()">
        <i class="bi bi-life-preserver me-1"></i>Grant support access</button>`;
      return;
    }
    const since = d.created_at ? _subDate(d.created_at) : '—';
    el.innerHTML = `
      <div class="d-flex align-items-center gap-2 mb-2">
        <span class="badge bg-info-subtle text-info border border-info"><i class="bi bi-check-circle me-1"></i>Active</span>
        <span class="text-muted">Granted ${esc(since)} · ${Number(d.devices || 0)} device(s)</span>
      </div>
      <div class="text-muted mb-2">Your support code was delivered to our team automatically (end-to-end encrypted — you don't need to share it yourself). Support access covers every device on your account, including any you add later. Revoking while subscribed to Hybrid Managed will downgrade you to Unlimited.</div>
      <button class="btn btn-sm btn-outline-danger" onclick="revokeSupportAccess()">
        <i class="bi bi-x-circle me-1"></i>Revoke support access</button>`;
  } catch (_) {
    el.innerHTML = '<div class="text-danger small">Could not load support access.</div>';
  }
}
function openGrantSupportModal() {
  try { bootstrap.Modal.getInstance(document.getElementById('supportAccessModal'))?.hide(); } catch (_) {}
  const c = document.getElementById('support-code'); if (c) c.value = '';
  const cc = document.getElementById('support-code-confirm'); if (cc) cc.value = '';
  hideEl('support-grant-err');
  bootstrap.Modal.getOrCreateInstance(document.getElementById('grantSupportModal')).show();
}
async function submitGrantSupportAccess() {
  const code = document.getElementById('support-code')?.value || '';
  const conf = document.getElementById('support-code-confirm')?.value || '';
  const err  = document.getElementById('support-grant-err');
  const btn  = document.getElementById('support-grant-go');
  const fail  = m => { if (err) { err.textContent = m; err.classList.remove('d-none'); } };
  const reset = () => { if (btn) { btn.disabled = false; btn.innerHTML = '<i class="bi bi-life-preserver me-1"></i>Grant access'; } };
  if (err) { err.classList.add('d-none'); err.textContent = ''; }
  if (code.length < 10) return fail('Support code must be at least 10 characters.');
  if (code !== conf)    return fail('Support codes do not match.');
  const rawPriv = sessionStorage.getItem('zk_priv_key');
  if (!rawPriv) return fail('Your encryption key is not loaded in this session — sign out and back in, then try again.');
  if (btn) { btn.disabled = true; btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Granting…'; }
  try {
    // Deliver the code to admin via genuine E2E (same mechanism as the Conversations support chat)
    // so it reaches us automatically — no manual copy/paste into chat needed.
    const supportPub = await _scGetSupportPub();
    if (!supportPub) { reset(); return fail('Support access isn\'t available right now — please contact us.'); }
    const saltBytes = crypto.getRandomValues(new Uint8Array(16));
    const auth_salt = btoa(String.fromCharCode(...saltBytes));
    const auth_hash = await _authPrehash(code, auth_salt, 600000);
    const zkWrapped = await _zkRewrapPrivKey(rawPriv, code);
    const { payload, dek_support } = await _scEncryptSupportCode(code, supportPub);
    const r = await fetch('/api/account/support-access', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ auth_hash, auth_salt, ...zkWrapped, support_code_payload: payload, support_code_dek_support: dek_support }),
    });
    const data = await r.json().catch(() => ({}));
    if (!r.ok) { reset(); return fail(data.error || 'Failed — please try again.'); }
    try { bootstrap.Modal.getInstance(document.getElementById('grantSupportModal'))?.hide(); } catch (_) {}
    showToast('Support access granted', 'success');
    loadSupportAccess();
  } catch (_) {
    reset();
    fail('Network error — please try again.');
  }
}
async function revokeSupportAccess() {
  if (!confirm('Revoke SentinelMDM support access? Any active support session ends immediately.')) return;
  try {
    const r = await fetch('/api/account/support-access', { method: 'DELETE' });
    const data = await r.json().catch(() => ({}));
    if (!r.ok) { showToast(data.error || 'Could not revoke.', 'danger'); return; }
    showToast('Support access revoked', 'success');
    loadSupportAccess();
  } catch (_) { showToast('Network error — please try again.', 'danger'); }
}

// ── "Change my email" — self-service, same account row (public users) ────────
// Re-auth (password + 2FA if enabled) → send a code to the NEW email → confirm. Unlike
// "Secure my account", nothing is wiped: devices, trial countdown, and subscription all stay
// on this row, so trial/sub status carries over to the new email exactly as-is.
function openChangeEmailModal() {
  try { bootstrap.Modal.getInstance(document.getElementById('accountSettingsModal'))?.hide(); } catch (_) {}
  document.getElementById('cemail-pw').value = '';
  document.getElementById('cemail-totp').value = '';
  document.getElementById('cemail-new').value = '';
  document.getElementById('cemail-code').value = '';
  document.getElementById('cemail-totp-wrap')?.classList.toggle('d-none', !currentUser?.totp_verified);
  document.getElementById('cemail-step-start').classList.remove('d-none');
  document.getElementById('cemail-step-verify').classList.add('d-none');
  document.getElementById('cemail-start-go').classList.remove('d-none');
  document.getElementById('cemail-verify-go').classList.add('d-none');
  hideEl('cemail-start-err'); hideEl('cemail-verify-err');
  bootstrap.Modal.getOrCreateInstance(document.getElementById('changeEmailModal')).show();
}
function hideEl(id) { const el = document.getElementById(id); if (el) { el.classList.add('d-none'); el.textContent = ''; } }

async function submitChangeEmailStart() {
  const pw      = document.getElementById('cemail-pw').value || '';
  const code    = (document.getElementById('cemail-totp').value || '').replace(/\s/g, '');
  const newMail = (document.getElementById('cemail-new').value || '').trim();
  const err = document.getElementById('cemail-start-err');
  const btn = document.getElementById('cemail-start-go');
  const fail = m => { err.textContent = m; err.classList.remove('d-none'); };
  hideEl('cemail-start-err');
  if (!pw) return fail('Enter your password.');
  if (currentUser?.totp_verified && !/^\d{6}$/.test(code)) return fail('Enter your 6-digit 2FA code.');
  if (!newMail.includes('@')) return fail('Enter a valid new email address.');
  btn.disabled = true; btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Sending…';
  try {
    const r = await fetch('/api/account/change-email/start', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ...(await accountAuthCreds(pw)), code, newEmail: newMail }),
    });
    const d = await r.json().catch(() => ({}));
    btn.disabled = false; btn.innerHTML = '<i class="bi bi-envelope-arrow-up me-1"></i>Send code';
    if (!r.ok) return fail(d.error || 'Failed — please try again.');
    document.getElementById('cemail-dest').textContent = newMail;
    document.getElementById('cemail-step-start').classList.add('d-none');
    document.getElementById('cemail-step-verify').classList.remove('d-none');
    document.getElementById('cemail-start-go').classList.add('d-none');
    document.getElementById('cemail-verify-go').classList.remove('d-none');
  } catch (_) {
    btn.disabled = false; btn.innerHTML = '<i class="bi bi-envelope-arrow-up me-1"></i>Send code';
    fail('Network error — please try again.');
  }
}

async function submitChangeEmailVerify() {
  const code = (document.getElementById('cemail-code').value || '').replace(/\s/g, '');
  const err  = document.getElementById('cemail-verify-err');
  const btn  = document.getElementById('cemail-verify-go');
  const fail = m => { err.textContent = m; err.classList.remove('d-none'); };
  hideEl('cemail-verify-err');
  if (!/^\d{6}$/.test(code)) return fail('Enter the 6-digit code from your email.');
  btn.disabled = true; btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Confirming…';
  try {
    const r = await fetch('/api/account/change-email/verify', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ code }),
    });
    const d = await r.json().catch(() => ({}));
    btn.disabled = false; btn.innerHTML = '<i class="bi bi-check2-circle me-1"></i>Confirm change';
    if (!r.ok) return fail(d.error || 'Failed — please try again.');
    try { bootstrap.Modal.getInstance(document.getElementById('changeEmailModal'))?.hide(); } catch (_) {}
    showToast('Email updated — signed in as ' + d.email, 'success');
  } catch (_) {
    btn.disabled = false; btn.innerHTML = '<i class="bi bi-check2-circle me-1"></i>Confirm change';
    fail('Network error — please try again.');
  }
}

// ── "Change password" — self-service, all account types ──────────────────────
// Zero-knowledge safe: the plaintext password is NEVER sent. We re-auth with the CURRENT password's
// prehash, derive a FRESH auth_salt + authHash for the new one, and — if this browser holds the ZK
// private key — re-wrap that SAME key under the new password (the keypair identity is preserved, so
// all existing encrypted data stays decryptable; this is NOT the destructive "Secure my account"
// re-key). POST /api/account/change-password stores bcrypt(new authHash) + the new wrapped key and
// signs out every OTHER session.
function openChangePasswordModal() {
  try { bootstrap.Modal.getInstance(document.getElementById('accountSettingsModal'))?.hide(); } catch (_) {}
  for (const id of ['cpw-current', 'cpw-totp', 'cpw-new', 'cpw-confirm']) {
    const el = document.getElementById(id); if (el) el.value = '';
  }
  document.getElementById('cpw-totp-wrap')?.classList.toggle('d-none', !currentUser?.totp_verified);
  hideEl('cpw-err');
  bootstrap.Modal.getOrCreateInstance(document.getElementById('changePasswordModal')).show();
}

// Re-wrap the EXISTING raw PKCS8 private key (base64, from sessionStorage) under a KEK derived from
// the new password — fresh 16-byte salt, PBKDF2-600k → AES-256-GCM. Wire format matches register /
// login / deriveAndStoreZkKey: <iv12><ct+tag16>, base64. Returns { zk_encrypted_priv_key, zk_salt }.
async function _zkRewrapPrivKey(rawPrivB64, newPassword) {
  const privPkcs8 = Uint8Array.from(atob(rawPrivB64), c => c.charCodeAt(0));
  const salt      = crypto.getRandomValues(new Uint8Array(16));
  const passKey   = await crypto.subtle.importKey('raw', new TextEncoder().encode(newPassword), 'PBKDF2', false, ['deriveBits']);
  const kekBits   = await crypto.subtle.deriveBits({ name: 'PBKDF2', salt, iterations: 600000, hash: 'SHA-256' }, passKey, 256);
  const kek       = await crypto.subtle.importKey('raw', kekBits, { name: 'AES-GCM' }, false, ['encrypt']);
  const iv        = crypto.getRandomValues(new Uint8Array(12));
  const ct        = new Uint8Array(await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, kek, privPkcs8));
  const combined  = new Uint8Array(iv.length + ct.length); combined.set(iv); combined.set(ct, iv.length);
  const b64       = u8 => btoa(String.fromCharCode(...u8));
  return { zk_encrypted_priv_key: b64(combined), zk_salt: b64(salt) };
}
// Reverse of _zkRewrapPrivKey — unwraps zk_encrypted_priv_key using `password` (PBKDF2-600k over
// zk_salt -> AES-256-GCM decrypt), storing the resulting raw private key into sessionStorage
// exactly as a normal login does (mirrors login.html's deriveAndStoreZkKey, same wire format:
// 12-byte IV prefix). Used by admin impersonation, where the "password" is the E2E-decrypted
// support code rather than something the admin typed in a form.
async function _zkUnwrapAndStorePrivKey(password, zkSalt, zkEncPriv) {
  const saltBytes = Uint8Array.from(atob(zkSalt), c => c.charCodeAt(0));
  const passKey    = await crypto.subtle.importKey('raw', new TextEncoder().encode(password), 'PBKDF2', false, ['deriveBits']);
  const kekBits    = await crypto.subtle.deriveBits({ name: 'PBKDF2', salt: saltBytes, iterations: 600000, hash: 'SHA-256' }, passKey, 256);
  const kek        = await crypto.subtle.importKey('raw', kekBits, { name: 'AES-GCM' }, false, ['decrypt']);
  const combined   = Uint8Array.from(atob(zkEncPriv), c => c.charCodeAt(0));
  const iv = combined.slice(0, 12), ct = combined.slice(12);
  const privDer    = await crypto.subtle.decrypt({ name: 'AES-GCM', iv }, kek, ct);
  sessionStorage.setItem('zk_priv_key', btoa(String.fromCharCode(...new Uint8Array(privDer))));
}

async function submitChangePassword() {
  const cur  = document.getElementById('cpw-current').value || '';
  const code = (document.getElementById('cpw-totp').value || '').replace(/\s/g, '');
  const npw  = document.getElementById('cpw-new').value || '';
  const conf = document.getElementById('cpw-confirm').value || '';
  const err  = document.getElementById('cpw-err');
  const btn  = document.getElementById('cpw-go');
  const fail  = m => { err.textContent = m; err.classList.remove('d-none'); };
  const reset = () => { btn.disabled = false; btn.innerHTML = '<i class="bi bi-check2-circle me-1"></i>Update password'; };
  hideEl('cpw-err');
  if (!cur) return fail('Enter your current password.');
  if (currentUser?.totp_verified && !/^\d{6}$/.test(code)) return fail('Enter your 6-digit 2FA code.');
  if (npw.length < 10) return fail('New password must be at least 10 characters.');
  if (npw !== conf)   return fail('New passwords do not match.');
  if (npw === cur)    return fail('Choose a password different from your current one.');
  btn.disabled = true; btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Updating…';
  try {
    // Re-auth credential for the CURRENT password (prehash, or plaintext for a legacy row).
    const body = {
      ...(await accountAuthCreds(cur)),
      code,
      new_auth_salt: '',   // filled below
      new_auth_hash: '',
    };
    // Fresh salt + prehash for the NEW password — the server only ever stores bcrypt over this.
    const newSaltBytes = crypto.getRandomValues(new Uint8Array(16));
    body.new_auth_salt = btoa(String.fromCharCode(...newSaltBytes));
    body.new_auth_hash = await _authPrehash(npw, body.new_auth_salt, 600000);
    // Re-wrap the ZK private key under the new password, if this browser holds it. The server
    // REQUIRES this whenever the account has a stored key, so a missing key here is a hard stop.
    const rawPriv = sessionStorage.getItem('zk_priv_key');
    if (rawPriv) {
      try { Object.assign(body, await _zkRewrapPrivKey(rawPriv, npw)); }
      catch (_) { reset(); return fail('Could not re-secure your encryption key — sign out and back in, then try again.'); }
    }
    const r = await fetch('/api/account/change-password', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    const d = await r.json().catch(() => ({}));
    if (!r.ok) { reset(); return fail(d.error || 'Failed — please try again.'); }
    reset();
    try { bootstrap.Modal.getInstance(document.getElementById('changePasswordModal'))?.hide(); } catch (_) {}
    showToast('Password updated' + (d.sessionsRevoked ? ' — other sessions signed out' : ''), 'success');
  } catch (_) {
    reset();
    fail('Network error — please try again.');
  }
}

// Any <div class="modal"> authored as a descendant of #main-panel (e.g. it-forensics-modal,
// nested deep inside the device-detail Remote Assist tab markup) gets silently trapped in a
// stacking context on mobile: _applyResponsiveLayout() below gives #mobile-content
// `position:fixed; z-index:100` and moves #main-panel into it, and per the CSS spec a
// position:fixed ancestor ALWAYS establishes a new stacking context regardless of z-index — so
// no matter how high the modal's own z-index (Bootstrap default 1055, this app bumps some to
// 9500+), it only ever competes against siblings INSIDE that trapped context. Bootstrap's
// `.modal-backdrop` is appended as a sibling of <body> at the OUTER/root stacking level, where it
// only has to outrank #mobile-content's z-index:100 — so the backdrop wins every hit-test and
// silently swallows every touch/click anywhere in the modal (not just scroll gestures), while
// still painting visually almost identically (50%-black-on-an-already-near-black theme is barely
// perceptible). Desktop (≥960px) never triggers this — #main-panel stays in the normal #body-row
// flow with no fixed-position ancestor — which is why this class of bug is invisible in a desktop
// browser and only bites on an actual phone. Root-caused live via chrome://inspect-style CDP
// debugging over adb + a real OS-level touch/tap injection (`adb shell input swipe/tap`), which
// showed touchstart/click both hit-testing to `.modal-backdrop` instead of the table/buttons.
// Fix: hoist every modal out of #main-panel to be a direct child of <body> ONCE, unconditionally
// (works identically on desktop — Bootstrap modals are position:fixed and don't depend on their
// DOM parent for visual placement, only for stacking-context nesting), so none of them can ever
// be trapped inside #mobile-content's fixed+z-index wrapper again.
function _hoistModalsOutOfMainPanel() {
  const panel = document.getElementById('main-panel');
  if (!panel) return;
  panel.querySelectorAll(':scope .modal.fade').forEach(m => {
    if (m.parentElement !== document.body) document.body.appendChild(m);
  });
}
document.addEventListener('DOMContentLoaded', _hoistModalsOutOfMainPanel);

// ── Responsive layout (mobile <960 ↔ desktop ≥960) ───────────────────────────
// Mobile (<960): Android WebView bug — position:fixed + display:flex ignores explicit height
// (computes h=0). Workaround: a fixed-position display:block #mobile-content with an inner flex
// wrapper, sized to the viewport, holding #main-panel.
// Desktop (≥960): the normal #body-row flex layout (sidebar | main-panel).
// MUST run on resize, not just load: a window that starts small pins #mobile-content to hardcoded
// px; growing it left the content stuck small with empty space. This now recomputes the mobile
// size on resize AND tears the wrapper down (panel back into #body-row) when crossing to desktop.
//
// _chromeTopOffset() is the height of ALL fixed page chrome above the content area: the navbar,
// plus the impersonation banner whenever it's visible. Anything that measures the navbar ALONE
// silently slides the whole dashboard UP underneath the banner (found live 2026-08-02 while
// impersonating a support delegate: the banner text and the "Device Overview"/filter row painted
// on top of each other, because #mobile-content's z-index:100 also puts it ABOVE the banner).
// The banner is rendered after page load by _renderImpersonationBanner(), which re-runs this
// layout once it toggles.
function _chromeTopOffset() {
  const nav    = document.querySelector('nav.navbar');
  const banner = document.getElementById('impersonation-banner');
  const navH   = nav ? (nav.getBoundingClientRect().height || nav.offsetHeight) : 0;
  const banH   = (banner && !banner.classList.contains('d-none'))
    ? (banner.getBoundingClientRect().height || banner.offsetHeight) : 0;
  return Math.round(navH + banH);
}

function _applyResponsiveLayout() {
  const nav     = document.querySelector('nav.navbar');
  const panel   = document.getElementById('main-panel');
  const mc      = document.getElementById('mobile-content');
  const bodyRow = document.getElementById('body-row');
  if (!panel || !mc || !bodyRow) return;

  if (window.innerWidth < 960) {
    if (!nav) return;
    const navH = _chromeTopOffset();
    const W = window.innerWidth, H = window.innerHeight, availH = H - navH;
    // Background is TRANSPARENT so the faded dashboard watermark (body::before) shows on mobile too;
    // the content panels/cards inside provide their own backdrops.
    mc.style.cssText =
      'position:fixed;top:' + navH + 'px;left:0;right:0;bottom:auto;' +
      'width:' + W + 'px;height:' + availH + 'px;' +
      'display:block;overflow:hidden;z-index:100;background:transparent;';
    let wrap = mc.querySelector(':scope > .mobile-wrap');
    if (!wrap) {
      wrap = document.createElement('div'); wrap.className = 'mobile-wrap';
      wrap.style.cssText = 'display:flex;flex-direction:column;width:100%;height:100%;overflow:hidden;';
      mc.appendChild(wrap);
    }
    if (panel.parentElement !== wrap) wrap.appendChild(panel);
    panel.style.cssText = 'display:flex;flex-direction:column;flex:1;min-height:0;overflow:hidden;';
  } else {
    // Desktop: restore the panel into #body-row and drop the mobile wrapper + inline overrides so
    // the stylesheet's responsive (flex-grow) layout fills the window again.
    if (panel.parentElement !== bodyRow) bodyRow.appendChild(panel);
    const wrap = mc.querySelector(':scope > .mobile-wrap');
    if (wrap) wrap.remove();
    mc.style.cssText = '';
    panel.style.cssText = '';   // className (flex-grow-1 d-flex flex-column overflow-hidden) takes over
    // Drawer state is mobile-only — clear it when we cross back to desktop.
    const sb = document.querySelector('.sidebar');
    if (sb) { sb.classList.remove('sidebar-mobile-open'); sb.style.top = ''; }
    document.getElementById('sidebar-backdrop')?.classList.remove('show');
  }
}
document.addEventListener('DOMContentLoaded', _applyResponsiveLayout);
let _layoutRaf = null;
window.addEventListener('resize', () => {
  if (_layoutRaf) cancelAnimationFrame(_layoutRaf);
  _layoutRaf = requestAnimationFrame(_applyResponsiveLayout);
});

