  bar.style.cssText = 'position:fixed;left:50%;bottom:18px;transform:translateX(-50%);z-index:9999;background:#1f2937;border:1px solid #fb923c;border-radius:10px;padding:8px 12px;display:flex;gap:8px;align-items:center;box-shadow:0 4px 18px rgba(0,0,0,.5);font-size:.8rem;color:#e5e7eb;';
  const label = document.createElement('span');
