        /** @type {{ lat: any, lng: any, accuracy: any, ts?: number, delta?: number } | null} */
        let ref = scanTs ? _nearestCachedFix(deviceId, scanTs, 10 * 60 * 1000) : null;
        if (!ref && (!scanTs || (nowTs - scanTs) <= 2 * 60 * 1000)) ref = { lat, lng, accuracy: gpsAccM };
