    _rfBadgeEl.textContent = `${src} indoor fix · ±${btFix.accuracyM} m${age != null ? ' · ' + age + 'm ago' : ''}${btFix.anchorsUsed ? ' · ' + btFix.anchorsUsed + ' anchors' : ''}`;
    _rfBadgeEl.style.display = '';
