let _fixLinksSig = '';      // args of the last fix-link render (the 10s poll repeats them exactly)
function clearFixAnchorLinks() {
  for (const k of Object.keys(_fixAnchorLines)) { _fixAnchorLines[k].setMap(null); delete _fixAnchorLines[k]; }
  for (const k of Object.keys(_fixAnchorRings)) { _fixAnchorRings[k].map = null; delete _fixAnchorRings[k]; }
}
// Emphasize the anchors a fix was actually built from: dashed fix→anchor links +
// colored rings (base anchor markers show everything nearby; rings show what's USED).
// Cleared and redrawn on every fix render — stale links would lie.
function renderFixAnchorLinks(fixPos, usedPts, color) {
  const sig = `${fixPos ? fixPos.lat + ',' + fixPos.lng : ''}|${color || ''}|` +
    (usedPts || []).map(p => p ? (p.address || `${p.lat},${p.lng}`) : '').join(',');
  if (sig === _fixLinksSig) return;   // 10s poll re-invokes with an identical fix — no rebuild
  _fixLinksSig = sig;
  clearFixAnchorLinks();
  if (!window.google?.maps || typeof map === 'undefined' || !map || !fixPos || !usedPts) return;
  for (const p of usedPts) {
    if (p == null || !Number.isFinite(p.lat) || !Number.isFinite(p.lng)) continue;
    const key = String(p.address || (p.lat + ',' + p.lng));
    try {
      _fixAnchorLines[key] = new google.maps.Polyline({
        clickable: false,
        map, path: [fixPos, { lat: p.lat, lng: p.lng }],
        strokeColor: color || '#22c55e', strokeOpacity: 0.6, strokeWeight: 1.2,
        icons: [{ icon: { path: 'M 0,-1 0,1', strokeOpacity: 1, scale: 2 }, offset: '0', repeat: '10px' }],
        zIndex: 3
      });
      const ring = document.createElement('div');
      ring.style.cssText = 'width:26px;height:26px;border-radius:50%;background:transparent;border:2px solid ' + (color || '#22c55e') + ';box-sizing:border-box;pointer-events:none;';
      _fixAnchorRings[key] = new google.maps.marker.AdvancedMarkerElement({
        position: { lat: p.lat, lng: p.lng }, map, content: ring,
        title: `IN USE · ${p.name || p.address || ''}${p.kind === 'wifi' ? ' (WiFi)' : p.kind === 'bt' ? ' (BT)' : ''}`
      });
    } catch (e) { console.warn('fix anchor link skip:', e); }
  }
}

// ── Anchors panel (inside the Indoor anchors card) ──────────────────────────
function renderAnchorList(hasElsewhere) {
  const list = document.getElementById('anchor-list');
  if (!list) return;
  if (!_anchors.length) {
    list.innerHTML = hasElsewhere
      ? '<p class="text-muted mb-0" style="font-size:.7rem">No calibrated anchors in range for this device (anchors learned by other devices are hidden). They auto-learn as this device moves with an accurate GPS fix.</p>'
      : '<p class="text-muted mb-0" style="font-size:.7rem">No calibrated anchors in range yet — they auto-learn from accurate GPS fixes as the device moves around the building, or add one manually below.</p>';
    return;
  }
  list.innerHTML = _anchors.map(a => {
    const inUse = _lastRfAnchors && _lastRfAnchors.some(p => p.lat === a.lat && p.lng === a.lng);
    return `<div class="d-flex align-items-center gap-2 py-1 border-bottom border-secondary" style="font-size:.7rem">
      <span>${a.kind === 'wifi' ? '📶' : '🔵'}</span>
      <div class="flex-grow-1 text-truncate"><span class="fw-semibold">${esc(a.name || a.address)}</span>
        <span class="text-muted" style="font-size:.62em">${esc(a.address)} · ref ${a.ref_rssi} dBm</span>
        ${a.origin === 'auto' ? '<span class="badge bg-info text-dark" style="font-size:.56em" title="Position learned automatically from GPS-accurate fixes">auto</span>' : ''}</div>
      ${inUse ? '<span class="badge bg-success" style="font-size:.58em">in use</span>' : ''}
      <button class="btn btn-sm btn-outline-danger py-0 px-1" style="font-size:.62rem" title="Delete anchor" onclick="deleteAnchor(${a.id})"><i class="bi bi-trash3"></i></button>
    </div>`;
  }).join('');
}

// ── Mapped structures layer (OSM steel) ───────────────────────────────────────
// Every mapped mast/tower in the current viewport (zoom ≥ 11, bbox-capped at 400).
// Display-only ground truth for judging tower positions against.
let _mastMarkers = {};   // osmid -> AME
// Default OFF: this layer used to fetch/render up to 400 DOM-backed markers and redo
// the whole fetch+rebuild on every map idle — a major source of pan/zoom lag on mobile
// WebViews. Opt-in via the 🗼 masts checkbox; capped and cached when enabled.
let _mastsOn = false;    // layer toggle (checkbox in the indoor card)
let _mastIdleHooked = false;
let _mastFetchTimer = null;
let _mastPendingKey = null; // bbox currently backfilling server-side (one retry scheduled)
let _mastLastBounds = null; // LatLngBounds covered by the last successful fetch
const MAX_MAST_MARKERS = 150;
function hookMastLayer() {
  if (_mastIdleHooked || typeof map === 'undefined' || !map) return;
  _mastIdleHooked = true;
  map.addListener('idle', () => {
    clearTimeout(_mastFetchTimer);
    _mastFetchTimer = setTimeout(loadMasts, 500);
  });
}
function clearMasts() {
  _dotClear(_mastMarkers);
}
async function loadMasts() {
  if (!_mastsOn || !window.google?.maps || typeof map === 'undefined' || !map) return;
  try {
    if (map.getZoom() < 11) { clearMasts(); _mastLastBounds = null; return; }
    const b = map.getBounds();
    if (!b) return;
    // Already covered by the last fetch? Don't refetch/rebuild on every idle — only when
    // the viewport leaves the fetched bounds (or the layer was just (re)enabled).
    if (_mastLastBounds && Object.keys(_mastMarkers).length &&
        _mastLastBounds.contains(b.getSouthWest()) && _mastLastBounds.contains(b.getNorthEast())) return;
    const sw = b.getSouthWest(), ne = b.getNorthEast();
    const r = await fetch(`/api/masts?bbox=${sw.lat().toFixed(4)},${sw.lng().toFixed(4)},${ne.lat().toFixed(4)},${ne.lng().toFixed(4)}&limit=${MAX_MAST_MARKERS}`);
    if (!r.ok) return;
    const d = await r.json();
    // Server is backfilling this area from Overpass right now — retry once shortly
    // so fresh steel appears without another pan.
    const pkey = `${sw.lat().toFixed(2)},${sw.lng().toFixed(2)},${ne.lat().toFixed(2)},${ne.lng().toFixed(2)}`;
    if (d.pending) {
      if (_mastPendingKey !== pkey) {
        _mastPendingKey = pkey;
        setTimeout(() => { if (_mastsOn && _mastPendingKey === pkey) loadMasts(); }, 30000);
      }
    } else if (_mastPendingKey === pkey) _mastPendingKey = null;
    const masts = (d.masts || []).slice(0, MAX_MAST_MARKERS);
    const newKeys = new Set(masts.map(m => String(m.osmid)));
    const sameSet = newKeys.size === Object.keys(_mastMarkers).length && [...newKeys].every(k => _mastMarkers[k]);
    _mastLastBounds = new google.maps.LatLngBounds(b.getSouthWest(), b.getNorthEast());
    if (sameSet) return;   // identical result — keep the existing dots, skip churn
    clearMasts();
    for (const m of masts) {
      try {
        let tagTxt = '';
        try { const t = JSON.parse(m.tags || '{}'); tagTxt = [t['tower:type'], t['tower:construction'], t.operator].filter(Boolean).join(' · '); } catch (_) {}
        _mastMarkers[String(m.osmid)] = _makeDot({
          lat: m.lat, lng: m.lng, px: 8,
          stroke: '#9ca3af', strokeOpacity: 0.9,
          fill: '#374151', fillOpacity: 0.92,
          onClick: () => showMastCarriers(m),
        });
      } catch (e) { console.warn('mast skip:', e); }
    }
  } catch (_) {}
}
function toggleMasts(on) {
  _mastsOn = !!on;
  _mastLastBounds = null;   // re-fetch fresh bounds for the new layer state
  if (_mastsOn) { hookMastLayer(); loadMasts(); } else clearMasts();
}
// ── Carriers-on-a-mast panel ──────────────────────────────────────────────────
// Click a 🗼 marker → which providers use that steel (from our own cell data:
// confirmed tenants at the mast vs merely-nearby cells). Replaces on repeat clicks.
let _mastPanel = null;
function hideMastPanel() { if (_mastPanel) { _mastPanel.remove(); _mastPanel = null; } }
async function showMastCarriers(m) {
  hideMastPanel();
  const panel = document.createElement('div');
  panel.style.cssText = 'position:fixed;left:50%;bottom:18px;transform:translateX(-50%);z-index:9999;background:#1f2937;border:1px solid #9ca3af;border-radius:10px;padding:10px 14px;box-shadow:0 4px 18px rgba(0,0,0,.5);font-size:.78rem;color:#e5e7eb;max-width:min(92vw,430px);';
  const head = document.createElement('div');
  head.className = 'd-flex align-items-center gap-2 mb-1';
  head.innerHTML = `<span>🗼 <b>Mapped ${esc(m.kind || 'structure')}</b> <span class="text-muted" style="font-size:.68em">${esc(m.osmid || '')}</span></span>`;
  const x = document.createElement('button');
  x.className = 'btn btn-sm btn-outline-secondary py-0 px-2 ms-auto'; x.textContent = '✕';
  x.onclick = hideMastPanel;
  head.appendChild(x);
  panel.appendChild(head);
  const body = document.createElement('div');
  body.innerHTML = '<span class="text-muted">Loading carriers…</span>';
  panel.appendChild(body);
  document.body.appendChild(panel);
  _mastPanel = panel;
  try {
    const r = await fetch(`/api/masts/carriers?osmid=${encodeURIComponent(m.osmid)}`);
    if (!r.ok) { body.innerHTML = `<span class="text-danger">Failed (${r.status})</span>`; return; }
    const d = await r.json();
    const list = d.carriers || [];
    if (!list.length) { body.innerHTML = '<span class="text-muted">No known cells at or near this structure yet — nothing in range has been identified here.</span>'; return; }
    const tierBadge = t => t === 'confirmed'
      ? '<span class="badge bg-success" style="font-size:.6em">on this mast</span>'
      : t === 'likely'
        ? '<span class="badge bg-warning text-dark" style="font-size:.6em">likely ≤25m</span>'
        : '<span class="badge bg-secondary" style="font-size:.6em">nearby</span>';
    body.innerHTML = list.map(c =>
      `<div class="d-flex align-items-center gap-2 py-1 border-bottom border-secondary">` +
      `<span class="fw-semibold">${esc(c.carrier)} <span class="text-muted" style="font-size:.66em">${c.mcc}-${c.mnc}</span></span>` +
      `<span class="text-muted ms-auto" style="font-size:.68em">${c.cells} cell(s) · ${c.minDistM} m</span>${tierBadge(c.bestTier)}</div>`
    ).join('');
  } catch (e) { body.innerHTML = `<span class="text-danger">Failed: ${esc(e.message)}</span>`; }
}
let _lastRfAnchors = null;   // anchor coords used by the last RF fix (set by renderRfFix)

async function deleteAnchor(id) {
  try {
    const r = await fetch(`/api/anchors/${id}`, { method: 'DELETE' });
    if (r.ok) loadIndoorPosition(selectedDeviceId);
  } catch (_) {}
}

function toggleAnchorForm() {
  const f = document.getElementById('anchor-form');
  if (!f) return;
  const hidden = f.style.display === 'none';
  f.style.display = hidden ? '' : 'none';
  if (hidden) {
    // Prefill from the strongest nearby device of the last proximity payload
    const prox = _lastProx || {};
    const best = (prox.wifi && prox.wifi[0]) || (prox.bt && prox.bt[0]) || null;
    const kind = best && prox.bt && prox.bt[0] && (!prox.wifi || !prox.wifi.length) ? 'bt' : (best && best.bssid ? 'wifi' : 'bt');
    document.getElementById('anchor-kind').value = kind;
    document.getElementById('anchor-address').value = best ? (best.bssid || best.address || '') : '';
    document.getElementById('anchor-name').value = best ? (best.ssid || best.name || '') : '';
    document.getElementById('anchor-ref').value = kind === 'wifi' ? -35 : -59;
    const c = (typeof map !== 'undefined' && map) ? map.getCenter() : null;
    document.getElementById('anchor-pos-hint').textContent = c
      ? `Position: map center (${c.lat().toFixed(6)}, ${c.lng().toFixed(6)})`
      : 'Position: map center';
  }
}

async function saveAnchor() {
  const kind = document.getElementById('anchor-kind').value;
  const address = document.getElementById('anchor-address').value.trim();
  const name = document.getElementById('anchor-name').value.trim();
  const ref = parseInt(document.getElementById('anchor-ref').value, 10);
  const c = (typeof map !== 'undefined' && map) ? map.getCenter() : null;
  if (!address || !c) { showToast('Address + map center required', 'warning'); return; }
  try {
    const r = await fetch('/api/anchors', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ kind, address, name, lat: c.lat(), lng: c.lng(), ref_rssi: Number.isFinite(ref) ? ref : (kind === 'wifi' ? -35 : -59) })
    });
    if (r.ok) {
      showToast('Anchor placed at map center', 'success');
      document.getElementById('anchor-form').style.display = 'none';
      _anchorPick = null;
      loadIndoorPosition(selectedDeviceId);
    } else { showToast('Anchor failed', 'danger'); }
  } catch (_) {}
}

// ── Anchor audit: "is a detected address genuinely seen in two places (a follower), or is
// its saved anchor position simply wrong (mis-calibration)?" ─────────────────────────
// Server runs the scan-history × location join for admin-managed (non-ZK) devices. ZK
// devices are undecryptable server-side, so the owner's browser runs the same join on its
// decrypted data (location-history cache + recently decrypted BT scans).
let _auditDays = 14; // anchor-audit lookback window (days), user-selectable in the modal
async function openAnchorAudit() {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  showToast('Auditing anchors — joining scans to location history…', 'info');
  try {
    let data = null;
    try {
      const r = await fetch(`/api/devices/${deviceId}/anchor-audit?days=${_auditDays}`);
      if (r.ok) data = await r.json();
    } catch (_) {}
    if (data && data.zk) data = await _zkAnchorAudit(deviceId, data.anchors || []);
    if (!data) { showToast('Audit failed', 'danger'); return; }
    _renderAnchorAudit(data);
  } catch (e) { showToast('Audit failed: ' + e.message, 'danger'); }
}

function _auditSetDays(value) {
  _auditDays = parseInt(value, 10) || 14;
  openAnchorAudit();
}

// Group seen positions into ~300 m cells: distinct areas, max span, main area centroid.
function _auditSummarize(points) {
  const cells = new Map();
  for (const p of points) {
    const k = `${Math.round(p.lat * 111320 / 300)}:${Math.round(p.lng * 111320 * Math.cos(p.lat * Math.PI / 180) / 300)}`;
    let c = cells.get(k);
    if (!c) { c = { n: 0, lat: 0, lng: 0 }; cells.set(k, c); }
    c.n++; c.lat += p.lat; c.lng += p.lng;
  }
  const centers = [...cells.values()].map(c => ({ lat: c.lat / c.n, lng: c.lng / c.n, n: c.n }));
  let spanM = 0;
  for (let i = 0; i < centers.length; i++)
    for (let j = i + 1; j < centers.length; j++)
      spanM = Math.max(spanM, _rfDistM(centers[i].lat, centers[i].lng, centers[j].lat, centers[j].lng));
  const main = centers.length ? centers.reduce((a, b) => (b.n > a.n ? b : a)) : null;
  return { areas: centers.length, spanM, main };
}

// Same verdict rules as the server's anchor-audit endpoint.
function _auditBuildRows(occ, anchors) {
  const byAddr = new Map((anchors || []).map(a => [String(a.address).toUpperCase(), a]));
  const fmtKm = m => m >= 1000 ? `${(m / 1000).toFixed(m >= 10000 ? 0 : 1)} km` : `${Math.round(m)} m`;
  const rows = [];     // problem findings only
  const allRows = [];  // every detected address (inventory)
  for (const o of occ.values()) {
    const st = _auditSummarize(o.points);
    const anchor = byAddr.get(o.address) || null;
    const anchorDeltaM = (anchor && st.main) ? _rfDistM(anchor.lat, anchor.lng, st.main.lat, st.main.lng) : null;
    let verdict = 'seen', why;
    if (anchor && anchorDeltaM != null && anchorDeltaM > 1000 && st.spanM <= 1000) {
      verdict = 'anchor_misplaced';
      why = `Saved anchor is ${fmtKm(anchorDeltaM)} from the only area this address is actually seen in.`;
    } else if (st.spanM > 1000) {
      verdict = 'seen_at_multiple_places';
      why = `Seen across ${st.areas} area(s) spanning ${fmtKm(st.spanM)}${anchorDeltaM != null ? ` — saved anchor ${fmtKm(anchorDeltaM)} from the main area` : ''}.`;
    } else if (anchor) {
      verdict = 'ok';
      why = `Seen in one area${anchorDeltaM != null ? `, saved anchor ${fmtKm(anchorDeltaM)} away` : ''}.`;
    } else {
      why = `Seen in ${st.areas} area(s), span ${fmtKm(st.spanM)}.`;
    }
    const entry = {
      address: o.address, name: o.name, kind: o.kind,
      count: o.points.length, firstSeen: o.firstSeen, lastSeen: o.lastSeen,
      areas: st.areas, spanM: Math.round(st.spanM),
      main: st.main ? { lat: Math.round(st.main.lat * 1e6) / 1e6, lng: Math.round(st.main.lng * 1e6) / 1e6 } : null,
      anchor: anchor ? { id: anchor.id, address: anchor.address, name: anchor.name || '', kind: anchor.kind, lat: anchor.lat, lng: anchor.lng, origin: anchor.origin || 'manual' } : null,
      anchorDeltaM: anchorDeltaM == null ? null : Math.round(anchorDeltaM),
      verdict, why,
    };
    allRows.push(entry);
    if (verdict !== 'seen') rows.push(entry);
  }
  const rank = v => v === 'anchor_misplaced' ? 0 : v === 'seen_at_multiple_places' ? 1 : 2;
  rows.sort((a, b) => rank(a.verdict) - rank(b.verdict) || (b.spanM - a.spanM) || ((b.anchorDeltaM || 0) - (a.anchorDeltaM || 0)));
  allRows.sort((a, b) => (b.count - a.count) || (b.spanM - a.spanM));
  return {
    rows: rows.slice(0, 200),
    detected: allRows.slice(0, 200),
    detectedWiFi: allRows.filter(r => r.kind === 'wifi').length,
    detectedBT: allRows.filter(r => r.kind === 'bt').length,
  };
}

async function _zkAnchorAudit(deviceId, anchors) {
  if (!window._zkPrivKey) { showToast('Unlock this device with your key to audit it', 'warning'); return null; }
  // Locations: reuse the decrypted history cache, else fetch + decrypt.
  let locs = _locHistoryCache[deviceId];
  if (!locs || !locs.length) {
    try {
      const r = await fetch(`/api/devices/${deviceId}/locations?limit=10000`);
      const resp = await r.json();
      if (resp?.zk) {
        // Normalize exactly like loadLocationHistory() so the cache shape stays consistent.
        locs = (await _zkRows(resp.rows)).map(p => ({
          id: p._id, timestamp: p._ts, device_id: deviceId,
          lat: p.lat, lng: p.lng, accuracy: p.accuracy ?? 0,
          speed: p.speed ?? null, bearing: p.bearing ?? null,
        }));
      } else {
        locs = Array.isArray(resp) ? resp : [];
      }
      if (locs && locs.length) _locHistoryCache[deviceId] = locs;
    } catch (_) { locs = []; }
  }
  const timeline = (locs || []).map(l => ({ ts: Number(l.timestamp ?? l._ts), lat: Number(l.lat), lng: Number(l.lng) }))
    .filter(l => Number.isFinite(l.ts) && Number.isFinite(l.lat) && Number.isFinite(l.lng))
    .sort((a, b) => a.ts - b.ts);
  const nearest = (ts, win) => {
    let lo = 0, hi = timeline.length - 1, at = -1;
    while (lo <= hi) { const mid = (lo + hi) >> 1; if (timeline[mid].ts <= ts) { at = mid; lo = mid + 1; } else hi = mid - 1; }
    let best = null;
    for (const i of [at, at + 1]) {
      const c = timeline[i];
      if (!c) continue;
      const delta = Math.abs(c.ts - ts);
      if (delta > win) continue;
      if (!best || delta < Math.abs(best.ts - ts)) best = c;
    }
    return best;
  };
  const occ = new Map();
  const add = (addr, name, kind, ts) => {
    const a = String(addr || '').toUpperCase();
    if (!a) return;
    const loc = nearest(ts, 15 * 60 * 1000);
    if (!loc) return;
    let o = occ.get(a);
    if (!o) { o = { address: a, name: name || '', kind, points: [], firstSeen: ts, lastSeen: ts }; occ.set(a, o); }
    if (!o.name && name) o.name = name;
    if (o.points.length < 500) o.points.push({ lat: loc.lat, lng: loc.lng });
    if (ts < o.firstSeen) o.firstSeen = ts;
    if (ts > o.lastSeen) o.lastSeen = ts;
  };
  let scans = 0;
  // BT scan history (bounded — every row is an ECDH decrypt in the browser). Same
  // stale-scan guard as the server: an identical consecutive reading set is one scan.
  try {
    const r = await fetch(`/api/devices/${deviceId}/bluetooth?limit=300`);
    const d = await r.json();
    if (d.zk && d.rows?.length) {
      let lastSig = null;
      for (const row of d.rows) {
        const p = await zkDecryptRow(row);
        if (!p || !Array.isArray(p.devices)) continue;
        const readings = p.devices.filter(x => x && x.address && zkIsValidRssi(x.rssi))
          .map(x => [String(x.address).toUpperCase(), Math.round(Number(x.rssi))]);
        const sig = readings.map(x => x.join(':')).sort().join(',');
        if (sig === lastSig) continue;
        lastSig = sig;
        scans++;
        for (const dev of p.devices) if (dev && dev.address) add(dev.address, dev.name, 'bt', Number(row.timestamp));
      }
    }
  } catch (_) {}
  // WiFi: the browser only holds the latest decrypted snapshot.
  try {
    // Attribute each AP to its own scan time (report − age), mirroring the server audit.
    for (const [b, rr] of zkWifiReadings(_lastNetData)) add(b, rr.name, 'wifi', (_lastNetDataTs || Date.now()) - (rr.ageMs || 0));
    if (_lastNetData) scans++;
  } catch (_) {}
  const built = _auditBuildRows(occ, anchors);
  return {
    zk: true, days: _auditDays, locations: timeline.length, scans,
    rows: built.rows, detected: built.detected,
    detectedWiFi: built.detectedWiFi, detectedBT: built.detectedBT,
    anchors: anchors || [],
  };
}

function _renderAnchorAudit(data) {
  const rows = data?.rows || [];
  const anchors = data?.anchors || [];
  const autoAnchors = anchors.filter(a => (a.origin || 'manual') !== 'manual');
  const badge = v => v === 'anchor_misplaced'
    ? '<span class="badge bg-danger">anchor misplaced</span>'
    : v === 'seen_at_multiple_places'
    ? '<span class="badge bg-warning text-dark">seen in multiple places</span>'
    : '<span class="badge bg-success">ok</span>';
  const fmt = m => m == null ? '—' : (m >= 1000 ? (m / 1000).toFixed(1) + ' km' : m + ' m');
  const when = t => t ? new Date(t).toLocaleString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }) : '—';
  const misplaced = rows.filter(r => r.verdict === 'anchor_misplaced').length;
  const multi = rows.filter(r => r.verdict === 'seen_at_multiple_places').length;
  let lead = '';
  if (misplaced) {
    lead = `<div class="alert alert-warning py-2 mb-2" style="font-size:.82rem">
      <strong>${misplaced} saved anchor(s) are in the wrong place.</strong>
      That's a calibration error, not something following you — those anchors were saved at
      the phone's position instead of the AP's.${multi ? ` ${multi} address(es) are genuinely seen in multiple places.` : ''}
      ${autoAnchors.length ? 'Use the cleanup button below, then let them re-learn.' : ''}
    </div>`;
  } else if (multi) {
    lead = `<div class="alert alert-info py-2 mb-2" style="font-size:.82rem">
      <strong>${multi} address(es) were seen in more than one place</strong> in this window —
      typically car hotspots/Bluetooth, dashcams, wearables. Un-aged scan evidence is excluded.
    </div>`;
  }
  const actions = autoAnchors.length ? `<div class="d-flex align-items-center gap-2 mb-2 flex-wrap">
    <button class="btn btn-sm btn-outline-danger" onclick="_auditPurgeAuto()">
      <i class="bi bi-trash3 me-1"></i>Delete all ${autoAnchors.length} auto-learned anchor(s)
    </button>
    <span class="text-muted" style="font-size:.75rem">Manually placed anchors are kept.</span>
  </div>` : '';
  const days = data?.days || 14;
  // WiFi evidence without a per-AP scan age is EXCLUDED by the server (it can't be placed on
  // the map reliably). Report that plainly so the numbers are auditable.
  const skipped = data?.wifiOccSkipped || 0;
  const included = data?.wifiOccIncluded || 0;
  const controls = `<div class="d-flex align-items-center gap-2 mb-2 flex-wrap">
    <label class="small text-muted mb-0" for="anchor-audit-days">Window</label>
    <select id="anchor-audit-days" class="form-select form-select-sm w-auto" style="font-size:.74rem" onchange="_auditSetDays(this.value)">
      ${[1, 3, 7, 14, 30].map(d => `<option value="${d}" ${d === days ? 'selected' : ''}>Last ${d} day${d > 1 ? 's' : ''}</option>`).join('')}
    </select>
    ${data?.zk ? '' : (included === 0 && skipped === 0
      ? '<span class="text-muted" style="font-size:.72rem">No WiFi scan evidence in this window.</span>'
      : skipped
      ? `<span class="text-warning" style="font-size:.72rem">${Number(skipped).toLocaleString()} pre-update WiFi reading(s) carried no scan age and were excluded; ${Number(included).toLocaleString()} trustworthy reading(s) used. Old rows disappear as the window slides past the agent update.</span>`
      : `<span class="text-success" style="font-size:.72rem">All ${Number(included).toLocaleString()} WiFi readings carry a per-AP scan age — areas/span are trustworthy.</span>`)}
  </div>`;
  const summary = `<p class="text-muted small mb-2">Last ${days} day(s) · ${data?.locations || 0} location fixes · ${data?.scans || 0} scan snapshots · ${anchors.length} saved anchor(s).
    <span title="anchor misplaced = a saved anchor sits far from where the address is actually seen (calibration error). seen in multiple places = the address really moves with you.">What do the verdicts mean?</span></p>`;
  // Full inventory: the audit is a findings report, so a parked device with correctly-placed
  // APs legitimately has zero findings. This list shows everything that WAS detected.
  const detected = data?.detected || [];
  const detectedSection = detected.length
    ? `<details class="mt-3" ${rows.length ? '' : 'open'}>
        <summary class="text-muted small">All detected addresses in this window — ${data?.detectedWiFi || 0} WiFi · ${data?.detectedBT || 0} BT${detected.length >= 200 ? ' (top 200 by sightings)' : ''}</summary>
        <table class="table table-sm table-dark align-middle mt-2 mb-0" style="font-size:.76rem">
        <thead><tr><th>Device / address</th><th>Type</th><th>Seen</th><th>Areas</th><th>Span</th><th>Last seen</th></tr></thead>
        <tbody>${detected.map(r => `<tr>
          <td><div class="fw-semibold">${esc(r.name || '(unnamed)')}</div><div class="text-muted font-monospace" style="font-size:.85em">${esc(r.address)}</div></td>
          <td>${r.kind === 'wifi' ? 'WiFi' : 'BT'}</td>
          <td>${r.count}</td>
          <td>${r.areas}</td>
          <td>${fmt(r.spanM)}</td>
          <td class="text-muted" style="font-size:.9em">${when(r.lastSeen)}</td>
        </tr>`).join('')}</tbody></table>
      </details>`
    : `<p class="text-muted small mt-3 mb-0">No WiFi/BT scan evidence in this window${data?.zk ? '' : ' — check that Bluetooth scanning is enabled and the device is online'}.</p>`;
  const body = `${controls}${lead}${summary}${actions}` + (rows.length
    ? `<table class="table table-sm table-dark align-middle mb-0" style="font-size:.78rem">
    <thead><tr><th>Device / address</th><th>Type</th><th>Seen</th><th>Areas</th><th>Span</th><th>Last seen</th><th>Saved anchor</th><th>Δ anchor</th><th>Verdict</th><th></th></tr></thead>
    <tbody>${rows.map(r => `<tr>
      <td><div class="fw-semibold">${esc(r.name || '(unnamed)')}</div><div class="text-muted font-monospace" style="font-size:.85em">${esc(r.address)}</div></td>
      <td>${r.kind === 'wifi' ? '📶 WiFi' : '🔵 BT'}</td>
      <td>${r.count}</td>
      <td>${r.areas}</td>
      <td>${fmt(r.spanM)}</td>
      <td class="text-muted" style="font-size:.9em">${when(r.lastSeen)}</td>
      <td>${r.anchor ? `<span class="font-monospace">${Number(r.anchor.lat).toFixed(5)}, ${Number(r.anchor.lng).toFixed(5)}</span><div class="text-muted" style="font-size:.85em">${esc(r.anchor.origin)}</div>` : '—'}</td>
      <td>${fmt(r.anchorDeltaM)}</td>
      <td>${badge(r.verdict)}<div class="text-muted" style="font-size:.85em;max-width:280px">${esc(r.why)}</div></td>
      <td>${r.anchor ? `<button class="btn btn-sm btn-outline-danger py-0 px-1" style="font-size:.7rem" title="Delete this saved anchor" onclick="_auditDeleteAnchor(${r.anchor.id})"><i class="bi bi-trash3"></i></button>` : ''}</td>
    </tr>`).join('')}</tbody></table>`
    : '<p class="text-muted mb-0">No mismatched anchors or multi-place devices found in this window — the full detection list is below.</p>') + detectedSection;

  let el = document.getElementById('anchorAuditModal');
  if (!el) {
    el = document.createElement('div');
    el.id = 'anchorAuditModal';
    el.className = 'modal fade';
    el.tabIndex = -1;
    el.innerHTML = `<div class="modal-dialog modal-xl modal-dialog-scrollable"><div class="modal-content" style="background:#12161c">
      <div class="modal-header py-2"><h6 class="modal-title"><i class="bi bi-search me-2"></i>Anchor audit — which device is seen where</h6>
      <button type="button" class="btn-close" data-bs-dismiss="modal"></button></div>
      <div class="modal-body" id="anchor-audit-body"></div></div></div>`;
    document.body.appendChild(el);
  }
  document.getElementById('anchor-audit-body').innerHTML = body;
  (bootstrap.Modal.getInstance(el) || new bootstrap.Modal(el)).show();
}

function _auditPurgeAuto() {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  showConfirm({
    title: 'Delete auto-learned anchors?',
    body: `<p class="mb-2">Deletes every automatically learned anchor for this device's owner. Manually placed anchors are kept.</p>
      <p class="mb-0 text-muted">Auto anchors are re-learned from new scans. This cannot be undone.</p>`,
    okLabel: 'Delete auto anchors', okClass: 'btn-danger',
    onConfirm: async () => {
      try {
        const r = await fetch(`/api/devices/${deviceId}/anchors/purge-auto`, { method: 'POST' });
        const d = await r.json().catch(() => ({}));
        if (!r.ok) throw new Error(d.error || 'purge failed');
        showToast(`Deleted ${d.deleted ?? 0} auto-learned anchor(s) — they will re-learn correctly`, 'success');
        bootstrap.Modal.getInstance(document.getElementById('anchorAuditModal'))?.hide();
        loadIndoorPosition(deviceId);
        openAnchorAudit();
      } catch (e) { showToast('Purge failed: ' + e.message, 'danger'); }
    }
  });
}

async function _auditDeleteAnchor(id) {
  try {
    const r = await fetch(`/api/anchors/${id}`, { method: 'DELETE' });
    if (!r.ok) throw new Error('delete failed');
    showToast('Anchor deleted', 'success');
    bootstrap.Modal.getInstance(document.getElementById('anchorAuditModal'))?.hide();
    loadIndoorPosition(selectedDeviceId);
    openAnchorAudit();
  } catch (_) { showToast('Delete failed', 'danger'); }
}

async function loadBtData(deviceId) {
  if (!deviceId) return;
  _btLoadedFor = deviceId;
  // Reflect the real device-side scan state (works for admin AND ZK devices — the device reports
  // BT on/off via the dedicated plaintext bt_scan_state event, persisted server-side).
  syncBtScanState(deviceId);
  try {
    const r = await fetch(`/api/devices/${deviceId}/bluetooth`);
    if (!r.ok) return;
    const d = await r.json();
    _btScanTs = null;
    // ZK-owned devices: response is { zk: true, rows: [...] } — decrypt the most recent scan
    if (d.zk && d.rows?.length) {
      if (!window._zkPrivKey) { _btDevices = []; _btTrackers = []; renderBtDevices(); renderBtTrackers(); return; }
      const dec = await zkDecryptRow(d.rows[0]);  // most recent scan
      _btScanTs = Number(d.rows[0].timestamp) || null;
      if (dec?.devices) {
        _btDevices  = dec.devices;
        _btTrackers = _btDevices.filter(dev => dev.isTracker);
      }
    } else {
      _btDevices  = d.devices || [];
      _btScanTs   = Number(d.timestamp) || null;
      _btTrackers = _btDevices.filter(dev => dev.isTracker);
    }
    if (Array.isArray(d.safeList)) _btSafelist = d.safeList;
    renderBtDevices();
    renderBtTrackers();
  } catch (_) {}
}

// Pull the authoritative device-side BT scan state and sync the Start/Stop button.
async function syncBtScanState(deviceId) {
  if (!deviceId) return;
  try {
    const r = await fetch(`/api/devices/${deviceId}/bt-scan-state`);
    if (!r.ok) return;
    const d = await r.json();
    _btScanning = !!d.scanning;
    renderBtScanButton();
  } catch (_) {}
}

function renderBtDevices() {
  const el = document.getElementById('bt-device-list');
  const countEl = document.getElementById('bt-device-count');
  if (countEl) countEl.textContent = String(_btDevices.length);
  if (!el) return;
  if (!_btDevices.length) {
    el.innerHTML = '<p class="text-muted small mb-0">No devices found. Click Start Scan.</p>';
    return;
  }
  // Sort: trackers first (by severity), then by RSSI (strongest first)
  const severityOrder = { high: 0, medium: 1, low: 2 };
  const sorted = [..._btDevices].sort((a, b) => {
    if (a.isTracker && !b.isTracker) return -1;
    if (!a.isTracker && b.isTracker) return 1;
    if (a.isTracker && b.isTracker) return (severityOrder[a.trackerSeverity] ?? 9) - (severityOrder[b.trackerSeverity] ?? 9);
    return (b.rssi ?? -999) - (a.rssi ?? -999);
  });
  el.innerHTML = sorted.map(dev => {
    const name = esc(dev.name || dev.address);
    const rssi = Number.isFinite(dev.rssi) ? dev.rssi : null;
    const rssiBar = rssi !== null ? rssiToBar(rssi) : '';
    const typeBadge = dev.type === 'ble' ? 'BLE' : dev.type === 'classic' ? 'BT' : dev.type === 'dual' ? 'Dual' : '';
    const trackerBadge = dev.isTracker
      ? `<span class="badge bg-${dev.trackerSeverity === 'high' ? 'danger' : dev.trackerSeverity === 'medium' ? 'warning' : 'secondary'} me-1" title="${escAttr(dev.trackerDetail || '')}">${esc(dev.trackerBrand || 'Tracker')}</span>`
      : '';
    const safeBadge = (dev.isSafe || (!dev.isTracker && isBtSafe(dev.address)))
      ? `<span class="badge bg-success me-1" title="Marked safe — not flagged as a tracker">Safe${dev.trackerBrand ? ' · ' + esc(dev.trackerBrand) : ''}</span>`
      : '';
    const bonded = dev.bondState === 12 ? '<i class="bi bi-link-45deg text-info" title="Paired"></i>' : '';
    const action = dev.address
      ? (dev.isTracker
          ? `<button class="btn btn-sm btn-outline-success flex-shrink-0 ms-1" style="font-size:0.65em" onclick="markBtSafe('${btJsStr(dev.address)}', '${btJsStr(dev.name || '')}')" title="Stop flagging this device as a tracker">Mark safe</button>`
          : (isBtSafe(dev.address)
              ? `<button class="btn btn-sm btn-outline-secondary flex-shrink-0 ms-1" style="font-size:0.65em" onclick="unmarkBtSafe('${btJsStr(dev.address)}')" title="Allow this device to be flagged again">Undo safe</button>`
              : ''))
      : '';
    return `<div class="d-flex align-items-center gap-2 py-1 border-bottom border-secondary ${dev.isTracker ? 'bg-danger bg-opacity-10' : ''}">${trackerBadge}${safeBadge}<div class="flex-grow-1"><div class="small fw-semibold">${name} ${bonded}</div><div class="text-muted" style="font-size:0.7em">${dev.address} · ${typeBadge}${dev.serviceUuids ? ' · ' + dev.serviceUuids.length + ' svc' : ''}</div></div><div class="text-end d-flex align-items-center"><span class="badge bg-dark">${rssiBar} ${rssi !== null ? rssi + ' dBm' : '?'}</span>${action}</div></div>`;
  }).join('');
}

function renderBtTrackers() {
  const section = document.getElementById('bt-tracker-section');
  const list    = document.getElementById('bt-tracker-list');
  const countEl = document.getElementById('bt-tracker-count');
  if (!section || !list) return;
  if (!_btTrackers.length) {
    section.style.display = 'none';
    return;
  }
  section.style.display = '';
  if (countEl) countEl.textContent = `${_btTrackers.length} tracker(s) detected`;
  list.innerHTML = _btTrackers.map(t => {
    const name   = esc(t.name || 'Unknown Tracker');
    const brand  = esc(t.trackerBrand || 'Unknown');
    const type   = esc(t.trackerType || 'unknown');
    const sev    = t.trackerSeverity || 'low';
    const detail = esc(t.trackerDetail || '');
    const rssi   = Number.isFinite(t.rssi) ? t.rssi : null;
    const addr   = esc(t.address || '');
    return `<div class="d-flex align-items-start gap-2 p-2 mb-1 rounded bg-danger bg-opacity-10 border border-danger border-opacity-25"><div><i class="bi bi-exclamation-triangle-fill text-danger me-1"></i></div><div class="flex-grow-1"><div class="small fw-bold">${name} <span class="badge bg-${sev === 'high' ? 'danger' : sev === 'medium' ? 'warning' : 'secondary'}" style="font-size:0.65em">${brand}</span></div><div class="text-muted" style="font-size:0.75em">${addr}${rssi !== null ? ' · ' + rssi + ' dBm' : ''}</div>${detail ? '<div class="text-muted" style="font-size:0.7em">' + detail + '</div>' : ''}</div>${t.address ? `<button class="btn btn-sm btn-outline-success flex-shrink-0" style="font-size:0.7em" onclick="markBtSafe('${btJsStr(t.address)}', '${btJsStr(t.name || '')}')" title="Stop flagging this device as a tracker">Mark safe</button>` : ''}</div>`;
  }).join('');
}

function rssiToBar(rssi) {
  // RSSI: -30 (very close) to -90 (very weak)
  if (rssi >= -50) return '▂▄▆█';
  if (rssi >= -60) return '▂▄▆░';
  if (rssi >= -70) return '▂▄░░';
  if (rssi >= -80) return '▂░░░';
  return '░░░░';
}

async function toggleDeepSleep(btn) {
  if (!selectedDeviceId) return;
  const cached  = deviceCache.get(selectedDeviceId);
  const enabled = !cached?.deep_sleep;
  btn.disabled  = true;
  try {
    await fetch(`/api/devices/${selectedDeviceId}/deep-sleep`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ enabled })
    });
  } catch (_) {}
  btn.disabled = false;
  // UI will update via devices_updated socket event
}

// ── Theft mode toggle ──────────────────────────────────────────────────────
function updateTheftModeUI(d) {
  const btn   = document.getElementById('btn-theft');
  const label = document.getElementById('theft-label');
  if (!btn || !label) return;
  const active = !!d.theft_mode;
  if (active) {
    btn.className = 'btn btn-danger w-100 emergency-badge-pulse';
    label.textContent = 'Disable Theft Mode';
  } else {
    btn.className = 'btn btn-outline-danger w-100';
    label.textContent = 'Enable Theft Mode';
  }
}

async function toggleTheftMode(btn) {
  if (!selectedDeviceId) return;
  const cached  = deviceCache.get(selectedDeviceId);
  const enabled = !cached?.theft_mode;
  btn.disabled  = true;
  try {
    await fetch(`/api/devices/${selectedDeviceId}/theft-mode`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ enabled })
    });
  } catch (_) {}
  btn.disabled = false;
}

// One-tap release for the fake-shutdown black screen — e.g. after a battery stop
// with theft already off. The server emits stop_theft_mode unconditionally, and the
// device always honors the screen release even when theft isn't active.
async function releaseFakeShutdown(btn) {
  if (!selectedDeviceId) return;
  btn.disabled = true;
  try {
    await fetch(`/api/devices/${selectedDeviceId}/theft-mode`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ enabled: false })
    });
    showToast('Screen release sent', 'info');
  } catch (_) {}
  btn.disabled = false;
}

// ── Remote shell (ADB) opt-in — per device, from the Shell tab ───────────────
let _remoteShellEnabled = false;
async function loadRemoteShellState() {
  const btn = document.getElementById('btn-remote-shell');
  const lbl = document.getElementById('remote-shell-label');
  const cmdEl = document.getElementById('ashell-connect-cmd');
  const shortCmd = selectedDeviceId ? `adb-sentinel -s ${selectedDeviceId.slice(0, 8)} shell` : '';
  if (cmdEl && !cmdEl.value) cmdEl.value = shortCmd;
  if (!selectedDeviceId) return;
  try {
    const r = await fetch(`/api/devices/${selectedDeviceId}/remote-shell`, { cache: 'no-store' });
    const d = r.ok ? await r.json() : {};
    _remoteShellEnabled = !!d.enabled;
  } catch (_) { _remoteShellEnabled = false; }
  if (btn) btn.className = 'btn btn-sm ' + (_remoteShellEnabled ? 'btn-warning' : 'btn-outline-warning');
  if (lbl) lbl.textContent = 'Remote shell: ' + (_remoteShellEnabled ? 'ON' : 'OFF');
  // Full self-contained connect command (URL + per-device key) once enabled.
  // Fetched once per selected device — re-fetching would rotate (invalidate) it.
  if (cmdEl && _remoteShellEnabled) {
    if (window._shellTokenFor === selectedDeviceId && cmdEl.value.includes('--token ')) return;
    try {
      const r = await fetch(`/api/devices/${selectedDeviceId}/shell-token`, { cache: 'no-store' });
      const d = r.ok ? await r.json() : {};
      if (d.token) {
        cmdEl.value = `adb-sentinel --url ${window.location.origin} --token ${d.token} -s ${selectedDeviceId} shell`;
        window._shellTokenFor = selectedDeviceId;
      }
    } catch (_) {}
  } else if (cmdEl) {
    cmdEl.value = shortCmd;
    if (window._shellTokenFor === selectedDeviceId) window._shellTokenFor = null;
  }
}
function openRemoteShellModal() {
  if (!selectedDeviceId) { showToast('No device selected', 'warning'); return; }
  // Inline explainer panel (NOT a Bootstrap modal — no backdrop, nothing to get stuck).
  const enable = !_remoteShellEnabled;
  const panel = document.getElementById('remote-shell-explainer');
  const body = document.getElementById('remote-shell-explainer-body');
  const confirm = document.getElementById('remoteShellInlineConfirm');
  if (!panel || !body || !confirm) { showToast('Panel unavailable — hard-refresh the page', 'danger'); return; }
  body.innerHTML = enable
    ? `Turn <b>ON</b> remote shell access for this device?<br><br>
      This <b>opens the device to remote shell via ADB-style shell</b>: operator tools
      (the <code>adb-sentinel</code> command-line tool) holding a valid API token will be able
      to execute shell commands on this phone as the system user and read their output —
      from anywhere, without using this dashboard. No open ports and no firewall changes:
      everything rides the device's existing encrypted connection to the server.<br><br>
      Only this device. Only token holders. Turn it off here (or revoke the token) anytime
      and CLI access stops immediately.`
    : `Turn <b>OFF</b> remote shell access for this device?<br><br>
      Operator tools (the <code>adb-sentinel</code> CLI) will immediately stop being able to
      run shell commands on it — existing API tokens keep working everywhere else. The
      terminal above is unaffected.`;
  confirm.textContent = enable ? 'Enable' : 'Turn Off';
  confirm.className = 'btn btn-sm ' + (enable ? 'btn-warning' : 'btn-secondary');
  confirm.onclick = () => confirmRemoteShellToggle(enable);
  panel.classList.remove('d-none');
}
async function confirmRemoteShellToggle(forceEnable) {
  if (!selectedDeviceId) return;
  const enable = typeof forceEnable === 'boolean' ? forceEnable : !_remoteShellEnabled;
  try {
    const r = await fetch(`/api/devices/${selectedDeviceId}/remote-shell`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ enabled: enable })
    });
    const d = await r.json().catch(() => ({}));
    if (r.ok) {
      _remoteShellEnabled = !!d.enabled;
      const btn = document.getElementById('btn-remote-shell');
      const lbl = document.getElementById('remote-shell-label');
      if (btn) btn.className = 'btn btn-sm ' + (_remoteShellEnabled ? 'btn-warning' : 'btn-outline-warning');
      if (lbl) lbl.textContent = 'Remote shell: ' + (_remoteShellEnabled ? 'ON' : 'OFF');
      showToast(`Remote shell ${enable ? 'enabled' : 'disabled'}`, enable ? 'warning' : 'info');
    } else {
      showToast(d.error || 'Failed to update', 'danger');
    }
  } catch (_) { showToast('Failed to update', 'danger'); }
  document.getElementById('remote-shell-explainer')?.classList.add('d-none');
  const modalEl = document.getElementById('remoteShellModal');
  if (modalEl) bootstrap.Modal.getInstance(modalEl)?.hide();
}
function copyRemoteShellCmd() {
  const el = document.getElementById('ashell-connect-cmd');
  if (!el?.value) { showToast('No device selected', 'warning'); return; }
  navigator.clipboard?.writeText(el.value).then(
    () => showToast('ADB connect command copied — paste it into your terminal', 'success'),
    () => { el.select(); document.execCommand('copy'); showToast('ADB connect command copied', 'success'); },
  );
}

