const DO_RESTRICTIONS = [
  { group: 'Anti-Tamper' },
  { key: 'factory_reset',    label: 'Block Factory Reset',      desc: 'Prevent wiping the device from Settings' },
  { key: 'safe_boot',        label: 'Block Safe Boot',           desc: 'Prevent booting into safe mode (disables monitoring)' },
  { key: 'usb',              label: 'Block USB Transfer',        desc: 'Prevent PC connection and file transfer' },
  { key: 'debugging',        label: 'Block ADB / Debugging',     desc: '⚠️ Disables developer options — re-enable via server to restore ADB' },
  { key: 'add_user',         label: 'Block Add User',            desc: 'Prevent creating new user profiles' },
  { key: 'power_off',        label: 'Block Power Off/Restart',   desc: 'Remove power off and restart from power menu — SentinelOS (Custom OS) only' },
  { group: 'Monitoring' },
  { key: 'network_logging',  label: 'Network Logging',           desc: 'Log all DNS lookups and TCP connections on device' },
  { key: 'security_logging', label: 'Security Logging',          desc: 'Log unlock attempts, certificate installs, key events' },
  { group: 'System UI' },
  { key: 'status_bar',       label: 'Disable Status Bar',        desc: 'Prevent swiping down to access quick settings' },
  { group: 'Privacy Controls' },
  { key: 'camera_toggle',    label: 'Block Camera Toggle',       desc: 'Remove the camera on/off toggle from quick settings (Android 12+)' },
  { key: 'mic_toggle',       label: 'Block Microphone Toggle',   desc: 'Remove the microphone on/off toggle from quick settings (Android 12+)' },
  { key: 'config_location',  label: 'Block Location Toggle',     desc: 'Remove ability to disable location services from Settings' },
  { key: 'airplane_mode',    label: 'Block Airplane Mode Toggle', desc: 'Remove the airplane mode on/off toggle from quick settings and Settings' },
  { key: 'wifi',             label: 'Block WiFi Toggle',          desc: 'Remove the WiFi on/off toggle from quick settings and Settings' },
  { key: 'cellular',         label: 'Block Cellular Toggle',      desc: 'Remove the ability to turn mobile data / cellular off' },
];

const DO_STATE_KEYS = {
  factory_reset:    'factoryResetBlocked',
  safe_boot:        'safeBootBlocked',
  usb:              'usbBlocked',
  debugging:        'debuggingBlocked',
  add_user:         'addUserBlocked',
  power_off:        'powerOffBlocked',
  network_logging:  'networkLogging',
  security_logging: 'securityLogging',
  status_bar:       'statusBarDisabled',
  camera_toggle:    'cameraToggleBlocked',
  mic_toggle:       'micToggleBlocked',
  config_location:  'locationConfigBlocked',
  airplane_mode:    'airplaneModeBlocked',
  wifi:             'wifiBlocked',
  cellular:         'cellularBlocked',
};

function updateDeviceOwnerUI(doState) {
  const panel = document.getElementById('do-panel');
  if (!panel) return;
  if (!doState || !doState.active) {
    panel.innerHTML = `<p class="text-muted small mb-0 p-2">
      ${doState ? '⚠️ This device is not a Device Owner or Root Agent — run the ADB command to enable Device Owner.' : 'No device selected.'}
    </p>`;
    return;
  }
  const isRoot = !!doState.rootAgent;
  let html = '';
  if (isRoot) {
    html += `<div class="d-flex align-items-center gap-1 small text-success mb-2 px-1">
      <i class="bi bi-shield-fill-check"></i><span>Root Agent active — all restrictions supported</span>
    </div>`;
  }
  // Public (parent/owner) users don't get the raw Network/Security Logging toggles —
  // the Logs tab they feed is admin-only. Drop those keys and any group header left
  // empty as a result (removes the whole "Monitoring" section for public users).
  const publicHiddenDo = new Set(['network_logging', 'security_logging']);
  const isPublicUser = currentUser.account_type === 'public';
  const restrictions = DO_RESTRICTIONS.filter((item, i, arr) => {
    if (item.key) return !(isPublicUser && publicHiddenDo.has(item.key));
    // Group header: keep only if at least one item before the next group survives.
    for (let j = i + 1; j < arr.length && !arr[j].group; j++) {
      if (!(isPublicUser && publicHiddenDo.has(arr[j].key))) return true;
    }
    return false;
  });
  for (const item of restrictions) {
    if (item.group) {
      html += `<div class="text-muted fw-semibold mt-2 mb-1" style="font-size:11px;text-transform:uppercase;letter-spacing:.06em">${item.group}</div>`;
      continue;
    }
    const stateKey = DO_STATE_KEYS[item.key];
    const checked  = !!doState[stateKey];
    html += `
      <div class="d-flex align-items-center justify-content-between py-2 border-bottom border-secondary">
        <div style="max-width:80%">
          <div class="small fw-semibold">${item.label}</div>
          <div class="text-muted" style="font-size:11px">${item.desc}</div>
        </div>
        <div class="form-check form-switch mb-0 ms-2">
          <input class="form-check-input" type="checkbox" role="switch"
            ${checked ? 'checked' : ''}
            onchange="setDeviceRestriction('${item.key}', this.checked, this)">
        </div>
      </div>`;
  }
  html += `
  <div class="d-flex flex-wrap gap-2 mt-3">
    <button class="btn btn-outline-warning btn-sm flex-fill" onclick="confirmReboot()">
      <i class="bi bi-arrow-clockwise me-1"></i>Reboot Device
    </button>
    <button class="btn btn-outline-success btn-sm flex-fill" onclick="confirmLockPerms()">
      <i class="bi bi-shield-lock me-1"></i>Lock App Permissions
    </button>
  </div>
  <div class="d-flex flex-wrap gap-2 mt-2">
    <button class="btn btn-outline-secondary btn-sm flex-fill" onclick="confirmHideApp()">
      <i class="bi bi-eye-slash me-1"></i>Hide from Launcher
    </button>
    <button class="btn btn-outline-info btn-sm flex-fill" onclick="confirmShowApp()">
      <i class="bi bi-eye me-1"></i>Show in Launcher
    </button>
  </div>
`;
  panel.innerHTML = html;
}

async function setDeviceRestriction(restriction, enabled, checkbox) {
  if (!selectedDeviceId) return;
  checkbox.disabled = true;
  const ok = await sendCmd('set_device_restriction', { restriction, enabled });
  if (!ok) {
    checkbox.checked = !enabled; // revert on failure
    showToast('Failed to apply restriction', 'danger');
  }
  checkbox.disabled = false;
}

function confirmReboot() {
  showConfirm({
    title: 'Reboot Device',
    body: '<p class="mb-0">Remotely reboot this device now?</p>',
    okLabel: 'Reboot',
    okClass: 'btn-warning',
    onConfirm: () => sendCmd('reboot_device', {})
  });
}

function confirmLockPerms() {
  showConfirm({
    title: 'Lock App Permissions',
    body: '<p class="mb-0">Pin all app permissions so the device user cannot revoke them from Settings?<br><small class="text-muted">Requires Device Owner or Root Agent. Affects location, camera, microphone, SMS, calls, and storage permissions.</small></p>',
    okLabel: 'Lock Permissions',
    okClass: 'btn-success',
    onConfirm: () => sendCmd('lock_app_permissions', {})
  });
}

function confirmHideApp() {
  showConfirm({
    title: 'Hide from Launcher',
    body: '<p class="mb-0">Hide this app from the device launcher? The app will continue running in the background but the icon will no longer be visible.</p>',
    okLabel: 'Hide App',
    okClass: 'btn-secondary',
    onConfirm: () => sendCmd('hide_app', {})
  });
}

function confirmShowApp() {
  showConfirm({
    title: 'Show in Launcher',
    body: '<p class="mb-0">Make this app visible again in the device launcher?</p>',
    okLabel: 'Show App',
    okClass: 'btn-info',
    onConfirm: () => sendCmd('show_app', {})
  });
}

// ── Device Logs tab ───────────────────────────────────────────────────────
let _netLogs = [], _secLogs = [], _activeLogView = 'network';
const _netLogDayCache = new Map(); // dateKey → entries[]
const _secLogDayCache = new Map();

// Logs pagination. Initial load pulls the newest page; "Show older" pages back
// through the 30-day history via a ?before=<ts> cursor (per active view). Combined
// with lazy day-body rendering (collapsed days build no <tr>s) this keeps the DOM
// small even with many days loaded — the previous full-render of every day was the
// source of the WebUI lag.
// Page sizes are kept ≤ the server's ZK row-limit cap (2000) so a full page is
// detected identically for ZK and plaintext devices (a short page = no more history).
const LOG_PAGE_NET = 2000, LOG_PAGE_SEC = 1000;
let _netLogOldest = 0, _secLogOldest = 0;     // cursor: ts of oldest loaded row
let _netLogHasMore = false, _secLogHasMore = false;
let _netPagedBack = false, _secPagedBack = false;  // user loaded older pages → don't truncate on live batches
let _logsLoadingOlder = false;

const SEC_LOG_TAGS = {
  210001: 'ADB Shell Interactive',
  210002: 'ADB Shell Command',
  210003: 'ADB File Received',
  210004: 'ADB File Sent',
  210005: 'App Process Start',
  210006: 'Screen Unlocked',
  210007: 'Unlock Auth Attempt',
  210008: 'Screen Locked',
  210010: 'OS Startup',
  210011: 'OS Shutdown',
  210012: 'Security Logging Started',
  210013: 'Security Logging Stopped',
  210014: 'Media Mounted',
  210015: 'Media Unmounted',
  210016: 'Log Buffer Critical',
  210017: 'Password Expiry Notice',
  210018: 'Password Changed',
  210019: 'WiFi Connected',
  210020: 'WiFi Disconnected',
  210021: 'Bluetooth Connected',
  210022: 'Bluetooth Disconnected',
  210023: 'Restriction Added',
  210024: 'Restriction Removed',
  210025: 'CA Cert Installed',
  210026: 'CA Cert Removed',
  210027: 'Crypto Self-Test',
  210028: 'Key Destroyed',
  210029: 'Key Generated',
  210030: 'Key Imported',
  210031: 'Key Integrity Violation',
  210032: 'Keyguard Features Changed',
  210033: 'Remote Lock',
  210034: 'Wipe Failed',
  210035: 'User Deleted',
  210036: 'User Created',
  210037: 'Network Stats',
  210041: 'App Process Start (reasons)',
};

function switchLogView(view) {
  _activeLogView = view;
  document.getElementById('log-net-panel').classList.toggle('d-none', view !== 'network');
  document.getElementById('log-sec-panel').classList.toggle('d-none', view !== 'security');
  document.getElementById('log-net-controls').classList.toggle('d-none', view !== 'network');
  document.getElementById('log-sec-controls').classList.toggle('d-none', view !== 'security');
  document.getElementById('btn-clear-logs').dataset.view = view;
  if (view === 'network') renderNetworkLogs();
  else                    renderSecurityLogs();
  _setLogsLoadMore(view === 'network' ? _netLogHasMore : _secLogHasMore);
}

// Fetch one page of a log endpoint, normalizing the plaintext array response and the
// ZK {zk:true,rows} response into the entry shape the renderers consume. `before`=0
// fetches the newest page; a ms timestamp pages older. Returns { entries, noKey?, rows? }.
async function _fetchLogPage(deviceId, endpoint, limit, before) {
  const qs = new URLSearchParams({ limit: String(limit) });
  if (before) qs.set('before', String(before));
  const resp = await fetch(`/api/devices/${deviceId}/${endpoint}?${qs}`).then(r => r.json());
  if (resp && resp.zk) {
    if (!window._zkPrivKey) return { noKey: true, rows: resp.rows, entries: [] };
    const dec = await _zkRows(resp.rows);
    return { entries: dec.map(p => ({ id: p._id, timestamp: p._ts, ...p })) };
  }
  return { entries: Array.isArray(resp) ? resp : [] };
}

// Fetch the COMPLETE retained history for a log endpoint (?limit=all) — independent of
// the paginated tab window — normalized to chronological (oldest→newest) entries, ZK
// decrypted client-side when applicable. Used by Download, Copy All, and Ask AI so they
// always cover everything (including the older rows not yet loaded in the tab). Returns
// the entries array, or null for a ZK device whose private key isn't loaded.
async function _fetchAllLogs(deviceId, endpoint) {
  let resp;
  try { resp = await fetch(`/api/devices/${deviceId}/${endpoint}?limit=all`).then(r => r.json()); }
  catch { return []; }
  let entries;
  if (resp && resp.zk) {
    if (!window._zkPrivKey) return null;
    const dec = await _zkRows(resp.rows);
    entries = dec.map(p => ({ id: p._id, timestamp: p._ts, ...p }));
  } else {
    entries = Array.isArray(resp) ? resp : [];
  }
  entries.sort((a, b) => (a.timestamp || 0) - (b.timestamp || 0));
  return entries;
}

function _logsOldest(entries) {
  let m = Infinity;
  for (const e of entries) { const t = e.timestamp || 0; if (t && t < m) m = t; }
  return isFinite(m) ? m : 0;
}

// Show/hide + reset the shared "Show older" button beneath the log panels.
function _setLogsLoadMore(show) {
  const btn = document.getElementById('btn-logs-older');
  if (!btn) return;
  btn.disabled = false;
  btn.innerHTML = '<i class="bi bi-arrow-down-circle me-1"></i>Show older';
  btn.classList.toggle('d-none', !show);
}

async function loadLogs() {
  if (!selectedDeviceId) return;
  const deviceId = selectedDeviceId;
  try {
    const [net, sec] = await Promise.all([
      _fetchLogPage(deviceId, 'network-logs', LOG_PAGE_NET, 0),
      _fetchLogPage(deviceId, 'security-logs', LOG_PAGE_SEC, 0),
    ]);
    if (deviceId !== selectedDeviceId) return; // device switched mid-fetch — drop stale response
    if (net.noKey || sec.noKey) {              // ZK device, private key not loaded
      const el = document.getElementById(_activeLogView === 'network' ? 'log-net-list' : 'log-sec-list');
      if (el) zkNoKeyMsg(el, 'Device logs', [...(net.rows || []), ...(sec.rows || [])]);
      _netLogs = []; _secLogs = []; _netLogHasMore = false; _secLogHasMore = false;
      _setLogsLoadMore(false);
      return;
    }
    _netLogs = net.entries; _secLogs = sec.entries;
    _netLogOldest = _logsOldest(_netLogs); _secLogOldest = _logsOldest(_secLogs);
    _netLogHasMore = net.entries.length >= LOG_PAGE_NET;
    _secLogHasMore = sec.entries.length >= LOG_PAGE_SEC;
    _netPagedBack = false; _secPagedBack = false;
    if (_activeLogView === 'network') renderNetworkLogs();
    else                              renderSecurityLogs();
    _setLogsLoadMore(_activeLogView === 'network' ? _netLogHasMore : _secLogHasMore);
  } catch (_) {}
}

async function loadOlderLogs() {
  const deviceId = selectedDeviceId;
  if (!deviceId || _logsLoadingOlder) return;
  const isNet   = _activeLogView === 'network';
  const hasMore = isNet ? _netLogHasMore : _secLogHasMore;
  const oldest  = isNet ? _netLogOldest  : _secLogOldest;
  if (!hasMore || !oldest) return;
  _logsLoadingOlder = true;
  const btn = document.getElementById('btn-logs-older');
  if (btn) { btn.disabled = true; btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Loading…'; }
  try {
    const pageSize = isNet ? LOG_PAGE_NET : LOG_PAGE_SEC;
    const res = await _fetchLogPage(deviceId, isNet ? 'network-logs' : 'security-logs', pageSize, oldest);
    if (deviceId !== selectedDeviceId) return; // device switched mid-fetch
    const cur    = isNet ? _netLogs : _secLogs;
    const seen   = new Set(cur.map(e => e.id));
    const added  = res.entries.filter(e => !seen.has(e.id));
    const merged = cur.concat(added);
    const more   = res.entries.length >= pageSize && added.length > 0;
    if (isNet) { _netLogs = merged; if (added.length) _netLogOldest = _logsOldest(merged); _netLogHasMore = more; _netPagedBack = true; renderNetworkLogs(); }
    else       { _secLogs = merged; if (added.length) _secLogOldest = _logsOldest(merged); _secLogHasMore = more; _secPagedBack = true; renderSecurityLogs(); }
  } finally {
    _logsLoadingOlder = false;
    _setLogsLoadMore(_activeLogView === 'network' ? _netLogHasMore : _secLogHasMore);
  }
}

async function refreshLogs(btn) {
  const h = btn.innerHTML;
  btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span>';
  btn.disabled = true;
  await loadLogs();
  btn.innerHTML = h; btn.disabled = false;
}

async function clearLogs(btn) {
  if (!selectedDeviceId) return;
  const isNet = _activeLogView === 'network';
  showConfirm({
    title: `Clear ${isNet ? 'Network' : 'Security'} Logs`,
    body: `<p class="mb-0">Delete all stored ${isNet ? 'network' : 'security'} log entries for this device?</p>`,
    okLabel: 'Clear', okClass: 'btn-danger',
    onConfirm: async () => {
      const ep = isNet ? 'network-logs' : 'security-logs';
      await fetch(`/api/devices/${selectedDeviceId}/${ep}`, { method: 'DELETE' });
      if (isNet) { _netLogs = []; renderNetworkLogs(); }
      else        { _secLogs = []; renderSecurityLogs(); }
      showToast('Logs cleared', 'success');
    }
  });
}

function filterNetworkLogs() { renderNetworkLogs(); }
function filterSecurityLogs() { renderSecurityLogs(); }

function downloadNetLogDay(dateKey) {
  const entries = _netLogDayCache.get(dateKey);
  if (!entries?.length) return;
  const lines = [...entries].reverse().map(e => {
    const t = new Date(e.timestamp).toISOString();
    if (e.type === 'dns') {
      const addrs = e.addresses ? ` (${e.addresses})` : '';
      return `${t}  DNS  ${e.pkg || ''}  ${e.hostname || ''}${addrs}`;
    }
    return `${t}  TCP  ${e.pkg || ''}  ${e.address || ''}:${e.port || ''}`;
  });
  const blob = new Blob([lines.join('\n')], { type: 'text/plain;charset=utf-8' });
  const url  = URL.createObjectURL(blob);
  const a    = document.createElement('a');
  a.href = url; a.download = `netlog_${selectedDeviceId}_${dateKey.replace(/\W/g, '-')}.txt`;
  a.click(); URL.revokeObjectURL(url);
}

function downloadSecLogDay(dateKey) {
  const entries = _secLogDayCache.get(dateKey);
  if (!entries?.length) return;
  const lines = [...entries].reverse().map(e => {
    const t    = new Date(e.timestamp).toISOString();
    const name = e.name || SEC_LOG_TAGS[e.tag] || `Tag ${e.tag}`;
    return `${t}  ${name}  ${e.data || ''}`.trimEnd();
  });
  const blob = new Blob([lines.join('\n')], { type: 'text/plain;charset=utf-8' });
  const url  = URL.createObjectURL(blob);
  const a    = document.createElement('a');
  a.href = url; a.download = `seclog_${selectedDeviceId}_${dateKey.replace(/\W/g, '-')}.txt`;
  a.click(); URL.revokeObjectURL(url);
}

async function collectLogs(btn) {
  if (!selectedDeviceId) return;
  showConfirm({
    title: 'Collect Security Logs',
    body: `<p class="mb-0">Forces immediate delivery of any buffered security log events (unlock attempts, key events, certificate installs).<br><small class="text-muted">Network logs cannot be force-collected — they deliver automatically once ~1,200 DNS/TCP events accumulate on the device.</small></p>`,
    okLabel: 'Collect', okClass: 'btn-warning',
    onConfirm: async () => {
      const orig = btn.innerHTML;
      btn.disabled = true;
      btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span>';
      try {
        await sendCmd('collect_logs');
        showToast('Security log collection triggered — events will appear shortly', 'success');
        setTimeout(() => refreshLogs(document.querySelector('[onclick="refreshLogs(this)"]')), 5000);
      } finally {
        btn.disabled = false;
        btn.innerHTML = orig;
      }
    }
  });
}

function groupLogsByDay(logs, tsField) {
  // logs are newest-first from server; build day groups newest-day-first
  const byDate = new Map();
  for (const e of [...logs].reverse()) {
    const d = new Date(e[tsField] || e.ts || e.timestamp);
    const dateKey   = d.toLocaleDateString([], { year: 'numeric', month: '2-digit', day: '2-digit' });
    const dateLabel = d.toLocaleDateString([], { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
    if (!byDate.has(dateKey)) byDate.set(dateKey, { label: dateLabel, entries: [] });
    byDate.get(dateKey).entries.push(e);
  }
  // reverse so newest day is first
  return [...byDate.entries()].reverse();
}

function renderNetworkLogs() {
  const container = document.getElementById('log-net-list');
  const empty     = document.getElementById('net-log-empty');
  const count     = document.getElementById('log-count');
  const typeF     = document.getElementById('net-log-type-filter')?.value || '';
  const search    = (document.getElementById('net-log-search')?.value || '').toLowerCase();
  if (!container) return;

  const filtered = _netLogs.filter(e => {
    if (typeF && e.type !== typeF) return false;
    if (search) {
      const hay = ((e.pkg || '') + (e.hostname || '') + (e.address || '')).toLowerCase();
      if (!hay.includes(search)) return false;
    }
    return true;
  });

  empty?.classList.toggle('d-none', filtered.length > 0);
  if (count) count.textContent = `${filtered.length.toLocaleString()} of ${_netLogs.length.toLocaleString()} events`;

  if (!filtered.length) { container.innerHTML = ''; return; }

  _netLogDayCache.clear();
  const days = groupLogsByDay(filtered, 'timestamp');
  for (const [k, { entries }] of days) _netLogDayCache.set(k, entries);

  container.innerHTML = days.map(([dateKey, { label, entries: dayEntries }]) => {
    const colId   = 'nl-day-' + dateKey.replace(/\W/g, '-');
    const safeKey = dateKey.replace(/'/g, '');
    const isOpen  = _openDayGroups.has(colId);
    // Lazy rendering: only build the row HTML for days that are currently expanded.
    // Collapsed days emit an empty <tbody> tagged data-lazy and are filled from the
    // day cache on first expand (see the show.bs.collapse handler). This avoids
    // inserting thousands of <tr>s for every day up front — the cause of the lag.
    const body = isOpen
      ? `<tbody>${_netLogRowsHtml(dayEntries)}</tbody>`
      : `<tbody data-lazy="1" data-datekey="${escAttr(dateKey)}"></tbody>`;
    return `<div class="mb-3">
      <div class="d-flex align-items-center gap-2 mb-1">
        <div class="d-flex align-items-center gap-1 flex-shrink-0" role="button"
             data-bs-toggle="collapse" data-bs-target="#${colId}" style="cursor:pointer">
          <span class="badge bg-secondary px-2 py-1" style="font-size:.75rem;white-space:nowrap">
            <i class="bi bi-calendar3 me-1"></i>${esc(label)}
            <span class="ms-2 opacity-75">${dayEntries.length.toLocaleString()} events</span>
            <i class="bi bi-chevron-up ms-1" style="font-size:.6rem"></i>
          </span>
        </div>
        <button class="btn btn-outline-secondary btn-sm py-0 px-1 flex-shrink-0" style="font-size:.7rem"
          onclick="downloadNetLogDay('${safeKey}')" title="Download this day's log">
          <i class="bi bi-download"></i>
        </button>
        <hr class="flex-grow-1 m-0" style="border-color:rgba(255,255,255,.12)">
      </div>
      <div class="collapse${isOpen ? ' show' : ''}" id="${colId}">
        <div class="table-responsive">
          <table class="table table-dark table-sm table-hover align-middle mb-0" style="font-size:.82rem">
            <thead><tr>
              <th style="width:55px">Type</th><th>App / Package</th>
              <th>Host / Address</th><th>Port</th><th style="width:120px">Time</th>
            </tr></thead>
            ${body}
          </table>
        </div>
      </div>
    </div>`;
  }).join('');
}

// Build the <tr> rows for one day of network-log entries (cache holds them oldest-
// first; display newest-first). Shared by the eager render and the lazy fill.
function _netLogRowsHtml(dayEntries) {
  return [...dayEntries].reverse().map(e => {
    const badge = e.type === 'dns'
      ? `<span class="badge bg-info text-dark">DNS</span>`
      : `<span class="badge bg-secondary">TCP</span>`;
    const pkg  = e.pkg ? `<small class="text-muted">${esc(e.pkg)}</small>` : '';
    const dest = e.type === 'dns'
      ? `${esc(e.hostname || '')}${e.addresses ? `<br><small class="text-muted">${esc(e.addresses)}</small>` : ''}`
      : esc(e.address || '');
    const port = e.type === 'tcp' ? (e.port || '') : '';
    const time = new Date(e.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
    return `<tr><td>${badge}</td><td>${pkg}</td><td style="word-break:break-all">${dest}</td><td>${port}</td><td class="text-muted">${time}</td></tr>`;
  }).join('');
}

function renderSecurityLogs() {
  const container = document.getElementById('log-sec-list');
  const empty     = document.getElementById('sec-log-empty');
  const count     = document.getElementById('log-count');
  const nameF     = (document.getElementById('sec-log-tag-filter')?.value || '').toLowerCase();
  if (!container) return;

  const filtered = _secLogs.filter(e => {
    if (!nameF) return true;
    return (e.name || SEC_LOG_TAGS[e.tag] || '').toLowerCase().includes(nameF);
  });
  empty?.classList.toggle('d-none', filtered.length > 0);
  if (count) count.textContent = `${filtered.length.toLocaleString()} of ${_secLogs.length.toLocaleString()} events`;

  if (!filtered.length) { container.innerHTML = ''; return; }

  _secLogDayCache.clear();
  const days = groupLogsByDay(filtered, 'timestamp');
  for (const [k, { entries }] of days) _secLogDayCache.set(k, entries);

  container.innerHTML = days.map(([dateKey, { label, entries: dayEntries }]) => {
    const colId   = 'sl-day-' + dateKey.replace(/\W/g, '-');
    const safeKey = dateKey.replace(/'/g, '');
    const isOpen  = _openDayGroups.has(colId);
    // Lazy rendering (see renderNetworkLogs): collapsed days emit an empty tagged
    // <tbody>, filled from the cache on first expand.
    const body = isOpen
      ? `<tbody>${_secLogRowsHtml(dayEntries)}</tbody>`
      : `<tbody data-lazy="1" data-datekey="${escAttr(dateKey)}"></tbody>`;
    return `<div class="mb-3">
      <div class="d-flex align-items-center gap-2 mb-1">
        <div class="d-flex align-items-center gap-1 flex-shrink-0" role="button"
             data-bs-toggle="collapse" data-bs-target="#${colId}" style="cursor:pointer">
          <span class="badge bg-secondary px-2 py-1" style="font-size:.75rem;white-space:nowrap">
            <i class="bi bi-calendar3 me-1"></i>${esc(label)}
            <span class="ms-2 opacity-75">${dayEntries.length.toLocaleString()} events</span>
            <i class="bi bi-chevron-up ms-1" style="font-size:.6rem"></i>
          </span>
        </div>
        <button class="btn btn-outline-secondary btn-sm py-0 px-1 flex-shrink-0" style="font-size:.7rem"
          onclick="downloadSecLogDay('${safeKey}')" title="Download this day's log">
          <i class="bi bi-download"></i>
        </button>
        <hr class="flex-grow-1 m-0" style="border-color:rgba(255,255,255,.12)">
      </div>
      <div class="collapse${isOpen ? ' show' : ''}" id="${colId}">
        <div class="table-responsive">
          <table class="table table-dark table-sm table-hover align-middle mb-0" style="font-size:.82rem">
            <thead><tr><th>Event</th><th>Details</th><th style="width:120px">Time</th></tr></thead>
            ${body}
          </table>
        </div>
      </div>
    </div>`;
  }).join('');
}

// Build the <tr> rows for one day of security-log entries (cache holds them oldest-
// first; display newest-first). Shared by the eager render and the lazy fill.
function _secLogRowsHtml(dayEntries) {
  return [...dayEntries].reverse().map(e => {
    const name   = e.name || SEC_LOG_TAGS[e.tag] || `Tag ${e.tag}`;
    const badgeCls = e.tag === 210006 ? 'bg-success' :
                     e.tag === 210008 ? 'bg-secondary' :
                     e.tag === 210007 ? 'bg-warning text-dark' :
                     e.tag === 210002 ? 'bg-danger' :
                     e.tag === 210001 ? 'bg-danger' : 'bg-info text-dark';
    const detail = e.data ? `<code style="font-size:.8em;word-break:break-all">${esc(e.data)}</code>` : '';
    const time   = new Date(e.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
    return `<tr><td><span class="badge ${badgeCls}">${esc(name)}</span></td><td>${detail}</td><td class="text-muted">${time}</td></tr>`;
  }).join('');
}

// Format the COMPLETE retained history for the active log view into text lines.
// `entries` are chronological (from _fetchAllLogs); applies the same filters the tab uses.
function _formatAllLogs(entries, isNet) {
  const typeF  = (document.getElementById('net-log-type-filter')?.value || '');
  const search = (document.getElementById('net-log-search')?.value || '').toLowerCase();
  const nameF  = (document.getElementById('sec-log-tag-filter')?.value || '').toLowerCase();
  if (isNet) {
    return entries.filter(e => {
      if (typeF && e.type !== typeF) return false;
      if (search) {
        const hay = ((e.pkg || '') + (e.hostname || '') + (e.address || '')).toLowerCase();
        if (!hay.includes(search)) return false;
      }
      return true;
    }).map(e => {
      const t = ts(e.ts || e.timestamp);
      const pkg = e.pkg || '';
      if (e.type === 'dns') {
        const addrs = e.addresses ? ` (${e.addresses})` : '';
        return `[${t}] DNS  ${pkg}  ${e.hostname || ''}${addrs}`;
      }
      return `[${t}] TCP  ${pkg}  ${e.address || ''}:${e.port || ''}`;
    }).join('\n');
  }
  return entries.filter(e => !nameF || (e.name || SEC_LOG_TAGS[e.tag] || '').toLowerCase().includes(nameF))
    .map(e => {
      const t    = ts(e.ts || e.timestamp);
      const name = e.name || SEC_LOG_TAGS[e.tag] || `Tag ${e.tag}`;
      return `[${t}] ${name}  ${e.data || ''}`.trimEnd();
    }).join('\n');
}

// Copy the currently-loaded entries for the active view to the clipboard. Stays synchronous
// (no await before the clipboard write) so it keeps the user-gesture the clipboard API needs.
// For the COMPLETE retained history use Download (which has no such constraint).
function copyAllLogs(btn) {
  const isNet = _activeLogView === 'network';
  const text  = _formatAllLogs(isNet ? _netLogs : _secLogs, isNet);
  if (!text) { showToast('No log entries to copy', 'warning'); return; }
  navigator.clipboard.writeText(text).then(() => {
    const orig = btn.innerHTML;
    btn.innerHTML = '<i class="bi bi-clipboard-check"></i> Copied!';
    setTimeout(() => { btn.innerHTML = orig; }, 1800);
  }).catch(() => showToast('Clipboard write failed', 'danger'));
}

// Download the FULL retained history for the active view as a .txt (incl. older rows
// not loaded in the tab). ZK-decrypted client-side when applicable.
async function downloadLogs(btn) {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  const isNet = _activeLogView === 'network';
  const orig  = btn ? btn.innerHTML : '';
  if (btn) { btn.disabled = true; btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span>'; }
  try {
    const entries = await _fetchAllLogs(deviceId, isNet ? 'network-logs' : 'security-logs');
    if (entries === null) { showToast('Unlock this device’s private data first, then download.', 'warning'); return; }
    if (!entries.length) { showToast('No logs to download.', 'warning'); return; }
    const text = _formatAllLogs(entries, isNet);
    const blob = new Blob([text], { type: 'text/plain;charset=utf-8' });
    const url  = URL.createObjectURL(blob);
    const a    = document.createElement('a');
    a.href = url;
    a.download = `${isNet ? 'network' : 'security'}_logs_${deviceId}_${Date.now()}.txt`;
    a.click();
    URL.revokeObjectURL(url);
  } catch (_) {
    showToast('Failed to download logs.', 'danger');
  } finally {
    if (btn) { btn.disabled = false; btn.innerHTML = orig; }
  }
}

// ── Remote APK update ─────────────────────────────────────────────────────
let _apkFiles = [];
let serverApkVersion = null;

function populatePushDeviceSelect(devices) {
  const sel = document.getElementById('push-device-select');
  if (!sel) return;
  const prev = sel.value;
  sel.innerHTML = '<option value="">Select device…</option>';
  // Only Android devices receive APK pushes — Windows/Linux devices use a different
  // update mechanism (bastion) and must not appear here.
  const sorted = [...(devices || deviceCache.values())]
    .filter(d => d.platform === 'android')
    .sort((a, b) => (a.name || '').localeCompare(b.name || ''));
  for (const d of sorted) {
    const opt = document.createElement('option');
    opt.value = d.id;
    opt.textContent = safeName(d.name, d.id);
    if (d.id === prev) opt.selected = true;
    sel.appendChild(opt);
  }
  // Keep push button state in sync
  const btn = document.getElementById('btn-push-apk');
  if (btn) btn.disabled = !sel.value;
}

