let _publicApkFile = null;
function handlePublicApkSelected(input) {
  _publicApkFile = input.files[0] || null;
  const label = document.getElementById('public-apk-selected-name');
  const btn   = document.getElementById('btn-upload-public-apk');
  if (_publicApkFile) {
    if (label) label.textContent = `${_publicApkFile.name} (${(_publicApkFile.size/1024/1024).toFixed(1)} MB)`;
    if (btn) btn.disabled = false;
  } else {
    if (label) label.textContent = '';
    if (btn) btn.disabled = true;
  }
}
async function loadPublicApkStatus() {
  const el  = document.getElementById('public-apk-status');
  const del = document.getElementById('btn-delete-public-apk');
  if (!el) return;
  try {
    const m = await fetch('/api/update/apk/public/meta').then(r => r.json());
    if (m.available) {
      const mb = m.size ? (m.size/1024/1024).toFixed(1) + ' MB' : '';
      const ts = m.uploaded_at ? new Date(m.uploaded_at).toLocaleString() : '';
      const ver = m.version ? ` · v${esc(m.version)}` : '';
      el.innerHTML = `<i class="bi bi-check-circle text-success me-1"></i><strong>${esc(m.name || 'self-install.apk')}</strong>${ver}${mb ? ' · ' + mb : ''}<span class="text-muted ms-2">${ts}</span>`;
      if (del) del.style.display = '';
    } else {
      el.textContent = 'No public APK uploaded yet.';
      if (del) del.style.display = 'none';
    }
  } catch { el.textContent = 'Failed to load.'; }
}
async function uploadPublicApk(btn) {
  if (!_publicApkFile) return;
  const savedHtml = btn.innerHTML;
  btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Uploading…';
  btn.disabled = true;
  try {
    const versionMatch = _publicApkFile.name.match(/[\d]+\.[\d]+\.[\d]+(?:\.[\d]+)?/);
    const version = versionMatch ? versionMatch[0] : null;
    const res = await fetch('/api/admin/apk/public', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/octet-stream',
        'X-APK-Name':    _publicApkFile.name,
        ...(version ? { 'X-APK-Version': version } : {}),
      },
      body: _publicApkFile,
    });
    if (res.ok) {
      showToast('Public APK uploaded', 'success');
      document.getElementById('public-apk-file-input').value = '';
      document.getElementById('public-apk-selected-name').textContent = '';
      _publicApkFile = null;
      await loadPublicApkStatus();
    } else {
      const e = await res.json().catch(() => ({}));
      showToast(e.error || 'Upload failed', 'danger');
    }
  } catch (e) { showToast(e.message, 'danger'); }
  btn.innerHTML = savedHtml;
  btn.disabled = !_publicApkFile;
}
async function deletePublicApk() {
  showConfirm({
    title: 'Remove Public APK',
    body: '<p class="mb-0">Remove the self-install APK? Public users will no longer be able to download it until a new one is uploaded.</p>',
    okLabel: 'Remove', okClass: 'btn-danger',
    onConfirm: async () => {
      await fetch('/api/admin/apk/public', { method: 'DELETE' });
      showToast('Public APK removed', 'success');
      await loadPublicApkStatus();
    },
  });
}

