// ── File Backup panel (admin AND public/business_sub device owners) ────────────────────────────
// Entry point — called for every qualifying role (see the shared bootstrap conditional). Admin
// additionally sees + loads the shared S3 bucket config; everyone sees their own encryption
// password + their own device list (server-side scoping already restricts a non-admin's device
// list to devices they own, same as everywhere else in this dashboard).
// Called from switchTab() whenever the File Backup tab (for whichever device is selected) is
// opened — this is a per-device tab now (RA_TABS), not a standalone panel loaded once at bootstrap.
function fbLoadPanel() {
  fbSyncRunButtonsToDeviceState();
  fbLoadRecentAll();
  fbLoadConfig();
  fbLoadMyEncryptionKey();
  fbLoadSchedule();
  fbLoadFolders();
  fbLoadCurrentBackups();
}

// fb-run-btn / fb-run-incr-btn / fb-current-status are shared, static DOM nodes reused across
// every device's File Backup tab (no per-device duplication) -- same class of bug already fixed
// once for ra-audit-run-btn/ra-agent-update-btn in selectDevice(). Starting a backup on device A,
// then navigating to device B and reopening this tab, kept showing device A's "Backing up..."
// (disabled button + spinner) for device B, since nothing ever re-synced the buttons to whichever
// device is now actually selected -- fbLoadPanel() only ever refreshed the backup LIST, never the
// run-button state. Always reset to idle immediately, then paint this device's real latest run
// (and resume polling it, if it's genuinely still running) moments later.
let _fbRunBtnDefaultHtml = null, _fbRunIncrBtnDefaultHtml = null;
function fbSyncRunButtonsToDeviceState() {
  const deviceId = selectedDeviceId;
  const runBtn = document.getElementById('fb-run-btn');
  const incrBtn = document.getElementById('fb-run-incr-btn');
  const statusEl = document.getElementById('fb-current-status');
  if (runBtn && _fbRunBtnDefaultHtml === null) _fbRunBtnDefaultHtml = runBtn.innerHTML;
  if (incrBtn && _fbRunIncrBtnDefaultHtml === null) _fbRunIncrBtnDefaultHtml = incrBtn.innerHTML;
  if (!deviceId || !runBtn || !incrBtn) return;
  runBtn.disabled = false; runBtn.innerHTML = _fbRunBtnDefaultHtml;
  incrBtn.disabled = false; incrBtn.innerHTML = _fbRunIncrBtnDefaultHtml;
  if (statusEl) { statusEl.textContent = ''; statusEl.className = 'small text-muted ms-auto'; }
  fetch(`/api/devices/${deviceId}/file-backup/run-status`)
    .then(r => r.ok ? r.json() : null)
    .then(row => {
      if (selectedDeviceId !== deviceId || !row || row.kind !== 'backup') return; // navigated away, or no runs yet for this device
      if (row.status === 'running') {
        const btn = row.backup_kind === 'incremental' ? incrBtn : runBtn;
        const saved = btn === incrBtn ? _fbRunIncrBtnDefaultHtml : _fbRunBtnDefaultHtml;
        btn.disabled = true;
        btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Backing up…';
        if (statusEl) { statusEl.textContent = 'Running — this can take a while for large profiles…'; statusEl.className = 'small text-info ms-auto'; }
        _fbPollRunStatus(deviceId, row.id, btn, saved, statusEl, updated => {
          if (updated.status === 'completed') {
            const ranKind = updated.backup_kind === 'incremental' ? 'Incremental' : 'Full';
            if (statusEl) { statusEl.textContent = `Last backup: ${ranKind}, ${Math.round((updated.size_bytes || 0) / 1048576)} MB just now`; statusEl.className = 'small text-success ms-auto'; }
            fbLoadCurrentBackups();
          } else if (updated.status === 'skipped') {
            if (statusEl) { statusEl.textContent = updated.error || 'No changes since last backup'; statusEl.className = 'small text-muted ms-auto'; }
          } else if (statusEl) {
            statusEl.textContent = updated.error || 'Backup failed'; statusEl.className = 'small text-danger ms-auto';
          }
        });
      } else if (row.status === 'completed' && statusEl) {
        const ranKind = row.backup_kind === 'incremental' ? 'Incremental' : 'Full';
        statusEl.textContent = `Last backup: ${ranKind}, ${Math.round((row.size_bytes || 0) / 1048576)} MB — ${new Date(row.completed_at || row.started_at).toLocaleString()}`;
        statusEl.className = 'small text-muted ms-auto';
      }
    })
    .catch(() => {});
}

// Fleet-wide "is this actually happening" view — independent of selectedDeviceId, see
// server.js's GET /api/remote-assist/file-backup/recent doc comment for the access scoping.
function fbLoadRecentAll() {
  const el = document.getElementById('fb-recent-all');
  if (!el) return;
  el.innerHTML = '<span class="text-muted">Loading…</span>';
  fetch('/api/remote-assist/file-backup/recent')
    .then(r => r.json())
    .then(data => {
      const runs = data.runs || [];
      if (!runs.length) { el.innerHTML = '<span class="text-muted">No backups have run yet.</span>'; return; }
      el.innerHTML = runs.map(r => {
        const badge = r.status === 'completed' ? '<span class="badge bg-success">✓ Completed</span>'
          : r.status === 'running' ? '<span class="badge bg-info text-dark">Running…</span>'
          : `<span class="badge bg-danger" title="${escAttr(r.error || '')}">Failed</span>`;
        return `<div class="d-flex align-items-center gap-2 py-1 border-bottom border-secondary-subtle flex-wrap">
          <span class="text-truncate" style="max-width:180px">${esc(r.deviceName)}</span>
          ${badge}
          ${r.status === 'completed' ? `<span class="text-muted">${Math.round((r.sizeBytes || 0) / 1048576)} MB</span>` : ''}
          <span class="text-muted ms-auto">${esc(new Date(r.startedAt).toLocaleString())}</span>
        </div>`;
      }).join('');
    })
    .catch(e => { el.innerHTML = `<span class="text-danger">${esc(e.message)}</span>`; });
}

// Per-device schedule/retention — see server.js's getFileBackupSchedule()/pruneFileBackups().
async function fbLoadSchedule() {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  try {
    const sched = await (await fetch(`/api/devices/${deviceId}/file-backup/schedule`)).json();
    if (selectedDeviceId !== deviceId) return; // navigated away -- don't paint onto another device's panel
    const fullEl = document.getElementById('fb-sched-full-minutes');
    if (fullEl) fullEl.value = String(sched.fullScheduleMinutes ?? 0);
    const incrEl = document.getElementById('fb-sched-incremental-minutes');
    if (incrEl) incrEl.value = String(sched.incrementalScheduleMinutes ?? 0);
    const daysEl = document.getElementById('fb-sched-retention-days');
    if (daysEl) daysEl.value = sched.retentionDays ?? 30;
    const countEl = document.getElementById('fb-sched-retention-count');
    if (countEl) countEl.value = sched.retentionCount ?? 10;
  } catch (e) { /* best-effort */ }
}

function fbSaveSchedule(btn) {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  const status = document.getElementById('fb-sched-status');
  const saved = btn.innerHTML;
  btn.disabled = true;
  btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Saving…';
  const body = {
    fullScheduleMinutes: document.getElementById('fb-sched-full-minutes')?.value || 0,
    incrementalScheduleMinutes: document.getElementById('fb-sched-incremental-minutes')?.value || 0,
    retentionDays: document.getElementById('fb-sched-retention-days')?.value || 0,
    retentionCount: document.getElementById('fb-sched-retention-count')?.value || 0,
  };
  fetch(`/api/devices/${deviceId}/file-backup/schedule`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
  })
    .then(r => r.json())
    .then(data => {
      if (data.ok) { showToast('Schedule saved', 'success'); if (status && selectedDeviceId === deviceId) { status.textContent = 'Saved'; status.className = 'small text-success'; } }
      else { showToast(data.error || 'Save failed', 'danger'); if (status && selectedDeviceId === deviceId) { status.textContent = data.error || 'Save failed'; status.className = 'small text-danger'; } }
    })
    .catch(e => { showToast(e.message, 'danger'); if (status && selectedDeviceId === deviceId) { status.textContent = e.message; status.className = 'small text-danger'; } })
    .finally(() => { btn.disabled = false; btn.innerHTML = saved; });
}

// Per-account S3 config — everyone who can see this tab (admin, public, business_sub) sets their
// OWN bucket, applying to every device they control (server.js's resolveFileBackupSettings()).
async function fbLoadConfig() {
  try {
    const cfg = await (await fetch('/api/account/file-backup-s3-config')).json();
    const set = (id, val) => { const el = document.getElementById(id); if (el) el.value = val ?? ''; };
    set('fb-cfg-endpoint', cfg.endpoint);
    set('fb-cfg-bucket', cfg.bucket);
    set('fb-cfg-region', cfg.region);
    set('fb-cfg-bandwidth', cfg.bandwidthMbps || 10);
    const accessEl = document.getElementById('fb-cfg-access-key');
    if (accessEl) accessEl.placeholder = cfg.accessKeySet ? '•••• set — leave blank to keep ••••' : 'Access Key ID';
    const secretEl = document.getElementById('fb-cfg-secret-key');
    if (secretEl) secretEl.placeholder = cfg.secretKeySet ? '•••• set — leave blank to keep ••••' : 'Secret Access Key';
    const status = document.getElementById('fb-cfg-status');
    if (status) status.textContent = cfg.configured ? 'Configured' : 'Not fully configured yet';
  } catch (e) { showToast('Failed to load File Backup config: ' + e.message, 'danger'); }
}

function fbSaveConfig(btn) {
  const saved = btn.innerHTML;
  btn.disabled = true;
  btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Saving…';
  const body = {
    endpoint: document.getElementById('fb-cfg-endpoint')?.value || '',
    bucket: document.getElementById('fb-cfg-bucket')?.value || '',
    accessKey: document.getElementById('fb-cfg-access-key')?.value || '',
    secretKey: document.getElementById('fb-cfg-secret-key')?.value || '',
    region: document.getElementById('fb-cfg-region')?.value || '',
    bandwidthMbps: document.getElementById('fb-cfg-bandwidth')?.value || 10,
  };
  fetch('/api/account/file-backup-s3-config', {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
  })
    .then(r => r.json())
    .then(data => {
      if (data.ok) {
        showToast('File Backup config saved', 'success');
        ['fb-cfg-access-key', 'fb-cfg-secret-key'].forEach(id => { const el = document.getElementById(id); if (el) el.value = ''; });
        fbLoadConfig();
      } else showToast(data.error || 'Save failed', 'danger');
    })
    .catch(e => showToast(e.message, 'danger'))
    .finally(() => { btn.disabled = false; btn.innerHTML = saved; });
}

// Personal backup encryption password — every account (admin or public/business_sub) has its own,
// used whenever THAT account runs a backup/restore for a device it controls (server.js resolves
// which account's password applies per device — see fileBackupEncryptionPasswordFor()).
async function fbLoadMyEncryptionKey() {
  try {
    const data = await (await fetch('/api/account/file-backup-key')).json();
    const el = document.getElementById('fb-my-enc-pw');
    if (el) el.placeholder = data.isSet ? '•••• set — leave blank to keep ••••' : 'Set your encryption password';
    const status = document.getElementById('fb-my-enc-pw-status');
    if (status) { status.textContent = data.isSet ? 'Set' : 'Not set yet — backups will fail until you set one'; status.className = data.isSet ? 'small text-success' : 'small text-warning'; }
  } catch (e) { /* best-effort */ }
}

function fbSaveMyEncryptionKey(btn) {
  const input = document.getElementById('fb-my-enc-pw');
  const password = input?.value || '';
  if (!password) { showToast('Enter a password first', 'warning'); return; }
  const saved = btn.innerHTML;
  btn.disabled = true;
  btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span>';
  fetch('/api/account/file-backup-key', {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ password }),
  })
    .then(r => r.json())
    .then(data => {
      if (data.ok) { showToast('Encryption password saved', 'success'); if (input) input.value = ''; fbLoadMyEncryptionKey(); }
      else showToast(data.error || 'Save failed', 'danger');
    })
    .catch(e => showToast(e.message, 'danger'))
    .finally(() => { btn.disabled = false; btn.innerHTML = saved; });
}

// Backup/restore are fire-and-forget server-side (a real run takes many minutes — see
// server.js's doc comment on the run/restore routes) — POST just returns {runId}, this polls the
// cheap run-status endpoint until it leaves 'running'. Never poll file-backup/list for this (that
// does a live S3 listing every call — fine for a manual refresh, wasteful every few seconds).
// btn/statusEl are shared, static DOM nodes reused across every device's panel (no per-device
// duplication) — if the user has since navigated to a DIFFERENT device, this poll must stop
// touching them (and must not fire onDone at all) or a stale background poll for device A
// silently repaints whatever device B's tab is now showing, moments or minutes later. See
// fbSyncRunButtonsToDeviceState()'s doc comment for the full incident this fixes.
function _fbPollRunStatus(deviceId, runId, btn, savedBtnHtml, statusEl, onDone) {
  const tick = () => {
    if (selectedDeviceId !== deviceId) return; // navigated away — abandon this poll entirely
    fetch(`/api/devices/${deviceId}/file-backup/run-status?runId=${encodeURIComponent(runId)}`)
      .then(r => r.json())
      .then(row => {
        if (selectedDeviceId !== deviceId) return; // navigated away mid-request
        if (row.status === 'running') { setTimeout(tick, 5000); return; }
        if (btn) { btn.disabled = false; btn.innerHTML = savedBtnHtml; }
        onDone(row);
      })
      .catch(() => { if (selectedDeviceId === deviceId) setTimeout(tick, 5000); }); // transient poll failure — keep trying, don't give up
  };
  setTimeout(tick, 3000);
}

// Device-scoped — this whole card lives inside the tab-ra-file-backup panel for whichever device
// is currently selected (unlike the old top-level-panel design, there's no device picker here;
// selecting a different device and reopening this tab just re-targets selectedDeviceId). kind is
// 'full' (default) or 'incremental' — bastion may run 'full' anyway even when 'incremental' was
// requested (nothing to chain from yet) — row.backup_kind on completion reflects what actually ran.
function fbRunBackup(btn, kind) {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  const requestedKind = kind === 'incremental' ? 'incremental' : 'full';
  const label = requestedKind === 'incremental' ? 'Incremental backup' : 'Full backup';
  const statusEl = document.getElementById('fb-current-status');
  const saved = btn.innerHTML;
  btn.disabled = true;
  btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Starting…';
  if (statusEl) { statusEl.textContent = 'Starting…'; statusEl.className = 'small text-info ms-auto'; }
  fetch(`/api/devices/${deviceId}/file-backup/run`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ kind: requestedKind }),
  })
    .then(r => r.json())
    .then(data => {
      if (!data.ok) {
        btn.disabled = false; btn.innerHTML = saved;
        showToast(data.error || `${label} failed to start`, 'danger');
        if (statusEl) { statusEl.textContent = data.error || 'Failed to start'; statusEl.className = 'small text-danger ms-auto'; }
        return;
      }
      btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Backing up…';
      if (statusEl) { statusEl.textContent = 'Running — this can take a while for large profiles…'; statusEl.className = 'small text-info ms-auto'; }
      _fbPollRunStatus(deviceId, data.runId, btn, saved, statusEl, row => {
        if (row.status === 'completed') {
          const ranKind = row.backup_kind === 'incremental' ? 'Incremental' : 'Full';
          showToast(`${ranKind} backup complete (${Math.round((row.size_bytes || 0) / 1048576)} MB)`, 'success');
          if (statusEl) { statusEl.textContent = `Last backup: ${ranKind}, ${Math.round((row.size_bytes || 0) / 1048576)} MB just now`; statusEl.className = 'small text-success ms-auto'; }
        } else if (row.status === 'skipped') {
          showToast(row.error || 'No changes since last backup — nothing to do', 'info');
          if (statusEl) { statusEl.textContent = row.error || 'No changes since last backup'; statusEl.className = 'small text-muted ms-auto'; }
        } else {
          showToast(row.error || 'Backup failed', 'danger');
          if (statusEl) { statusEl.textContent = row.error || 'Backup failed'; statusEl.className = 'small text-danger ms-auto'; }
        }
        fbLoadCurrentBackups();
      });
    })
    .catch(e => { btn.disabled = false; btn.innerHTML = saved; showToast(e.message, 'danger'); if (statusEl) { statusEl.textContent = e.message; statusEl.className = 'small text-danger ms-auto'; } });
}

function fbLoadCurrentBackups() {
  const deviceId = selectedDeviceId;
  const el = document.getElementById('fb-current-backups');
  if (!el || !deviceId) return;
  el.innerHTML = '<span class="text-muted">Loading…</span>';
  fetch(`/api/devices/${deviceId}/file-backup/list`)
    .then(r => r.json())
    .then(data => {
      if (selectedDeviceId !== deviceId) return; // navigated away -- don't paint onto another device's panel
      const backups = data.backups || [];
      if (!backups.length) { el.innerHTML = `<span class="text-muted">${data.error ? esc(data.error) : 'No backups yet.'}</span>`; return; }
      el.innerHTML = backups.map(b => `
        <div class="d-flex align-items-center gap-2 py-1 border-bottom border-secondary-subtle">
          <span class="badge ${b.kind === 'incremental' ? 'bg-info text-dark' : 'bg-secondary'}">${b.kind === 'incremental' ? 'Incremental' : 'Full'}</span>
          <span class="font-monospace">${esc(b.modTime ? new Date(b.modTime).toLocaleString() : b.name)}</span>
          <span class="text-muted">${Math.round((b.size || 0) / 1048576)} MB</span>
          <button class="btn btn-outline-warning btn-sm ms-auto" onclick="fbRestore('${escJsAttr(b.key)}', this)"><i class="bi bi-arrow-counterclockwise me-1"></i>Restore</button>
          <button class="btn btn-outline-success btn-sm" onclick="fbDownload('${escJsAttr(b.key)}', this)"><i class="bi bi-download me-1"></i></button>
          <button class="btn btn-outline-danger btn-sm" onclick="fbDelete('${escJsAttr(b.key)}', this)"><i class="bi bi-trash me-1"></i>Delete</button>
        </div>`).join('');
    })
    .catch(e => { el.innerHTML = `<span class="text-danger">${esc(e.message)}</span>`; });
}

function fbRestore(backupKey, btn) {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  // Let the admin pick where on the device this restore lands, reusing the same live
  // folder-browser modal the "Add Custom Folder" flow uses (fbPickerMode='restore').
  fbOpenPicker('restore', { backupKey, btn });
}

function fbRestoreDefaultLocation(backupKey, btn) {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  fbConfirmAndRestore(deviceId, backupKey, btn, '');
}

function fbConfirmAndRestore(deviceId, backupKey, btn, destPath) {
  const destHtml = destPath
    ? `<code>${esc(destPath)}\\Restored-&lt;timestamp&gt;\\</code>`
    : '<code>C:\\ProgramData\\SentinelRemoteAssist\\Restored\\&lt;timestamp&gt;\\</code>';
  const isIncremental = /\.incr\.tar\.enc$/.test(backupKey);
  const chainNote = isIncremental
    ? ' This is an incremental backup — restoring it replays its full backup plus every incremental up to this point, in order.'
    : '';
  showConfirm({
    title: 'Restore backup?',
    body: `<p class="mb-1">Restores to ${destHtml} on the device — it never overwrites the live profile folders directly.${chainNote}</p>`,
    okLabel: 'Restore',
    okClass: 'btn-warning',
    onConfirm: () => {
      const saved = btn.innerHTML;
      btn.disabled = true;
      btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span>';
      fetch(`/api/devices/${deviceId}/file-backup/restore`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ backupKey, destPath }),
      })
        .then(r => r.json())
        .then(data => {
          if (!data.ok) {
            btn.disabled = false; btn.innerHTML = saved;
            showToast(data.error || 'Restore failed to start', 'danger');
            return;
          }
          showToast('Restore started — this can take a while, you\'ll see a toast when it finishes', 'info');
          _fbPollRunStatus(deviceId, data.runId, btn, saved, null, row => {
            if (row.status === 'completed') showToast(`Restored to ${row.restored_to}`, 'success');
            else showToast(row.error || 'Restore failed', 'danger');
          });
        })
        .catch(e => { btn.disabled = false; btn.innerHTML = saved; showToast(e.message, 'danger'); });
    },
  });
}

function fbDelete(backupKey, btn) {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  showConfirm({
    title: 'Delete this backup?',
    body: '<p class="mb-1">Permanently deletes this backup from S3. This cannot be undone.</p>',
    okLabel: 'Delete',
    okClass: 'btn-danger',
    onConfirm: () => {
      const saved = btn.innerHTML;
      btn.disabled = true;
      btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span>';
      fetch(`/api/devices/${deviceId}/file-backup/delete`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ backupKey }),
      })
        .then(r => r.json())
        .then(data => {
          if (!data.ok) {
            btn.disabled = false; btn.innerHTML = saved;
            showToast(data.error || 'Delete failed', 'danger');
            return;
          }
          showToast('Backup deleted', 'success');
          fbLoadCurrentBackups();
        })
        .catch(e => { btn.disabled = false; btn.innerHTML = saved; showToast(e.message, 'danger'); });
    },
  });
}

// Download now stitches the full chain (base full backup + every incremental up to and including
// the picked one) into ONE complete, already-decrypted zip server-side before any bytes reach the
// browser — that build can take a while for a long incremental chain, so this is fire-and-forget
// + poll (same pattern as fbRunBackup/fbConfirmAndRestore above), not a single synchronous fetch.
function fbDownload(backupKey, btn) {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  const saved = btn.innerHTML;
  btn.disabled = true;
  btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span>';
  fetch(`/api/devices/${deviceId}/file-backup/download`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ backupKey }),
  })
    .then(r => r.json())
    .then(data => {
      if (!data.ok) {
        btn.disabled = false; btn.innerHTML = saved;
        showToast(data.error || 'Download failed to start', 'danger');
        return;
      }
      showToast('Preparing download — stitching full history and decrypting, this can take a while…', 'info');
      _fbPollRunStatus(deviceId, data.runId, btn, saved, null, row => {
        if (row.status !== 'completed') { showToast(row.error || 'Download failed', 'danger'); return; }
        const a = document.createElement('a');
        a.href = `/api/devices/${deviceId}/file-backup/download/${encodeURIComponent(row.id)}/file`;
        a.download = '';
        document.body.appendChild(a); a.click();
        document.body.removeChild(a);
        showToast('Download starting…', 'success');
      });
    })
    .catch(e => { btn.disabled = false; btn.innerHTML = saved; showToast(e.message, 'danger'); });
}

// ── File Backup: folder selection + live folder-browser picker ─────────────────────────────────
// Per-device: which of the 6 well-known personal folders to include (server default = all 6,
// matching the original hardcoded behavior) plus admin-picked custom absolute paths added via the
// live remote folder-browser modal below. fbFolders mirrors the server's last-saved state; edits
// are held here until "Save Folder Selection" is clicked, same pattern as the Schedule/S3-config
// cards elsewhere in this tab.
const FB_KNOWN_FOLDERS = ['Desktop', 'Documents', 'Pictures', 'Videos', 'Music', 'Downloads'];
let fbFolders = { wellKnown: [...FB_KNOWN_FOLDERS], customPaths: [] };
let fbPickerPath = ''; // '' = drive-list root (every local drive letter, not just C:\)
let fbPickerEntries = [];
let fbPickerMode = 'add'; // 'add' = pick a source folder for the backup list; 'restore' = pick a restore destination
let fbPickerRestoreCtx = null; // { backupKey, btn } — set only when fbPickerMode === 'restore'

function fbRenderWellKnown() {
  const el = document.getElementById('fb-wellknown-list');
  if (!el) return;
  el.innerHTML = FB_KNOWN_FOLDERS.map(f => {
    const checked = fbFolders.wellKnown.includes(f) ? 'checked' : '';
    return `<div class="form-check form-check-inline">
      <input class="form-check-input" type="checkbox" id="fb-wk-${esc(f)}" ${checked} onchange="fbToggleWellKnown('${escJsAttr(f)}', this.checked)">
      <label class="form-check-label small" for="fb-wk-${esc(f)}">${esc(f)}</label>
    </div>`;
  }).join('');
}

function fbToggleWellKnown(folder, on) {
  const set = new Set(fbFolders.wellKnown);
  if (on) set.add(folder); else set.delete(folder);
  fbFolders.wellKnown = FB_KNOWN_FOLDERS.filter(f => set.has(f));
}

function fbFormatBytes(n) {
  if (n === null || n === undefined) return 'size unknown';
  if (n < 1024) return `${n} B`;
  if (n < 1048576) return `${(n / 1024).toFixed(1)} KB`;
  if (n < 1073741824) return `${(n / 1048576).toFixed(1)} MB`;
  return `${(n / 1073741824).toFixed(2)} GB`;
}

function fbRenderCustomList() {
  const el = document.getElementById('fb-custom-list');
  if (!el) return;
  if (!fbFolders.customPaths.length) { el.innerHTML = '<span class="text-muted">No custom folders added.</span>'; return; }
  el.innerHTML = fbFolders.customPaths.map((c, i) => `
    <div class="d-flex align-items-center gap-2 py-1 border-bottom border-secondary-subtle flex-wrap">
      <code class="text-truncate" style="max-width:360px">${esc(c.path)}</code>
      <span class="text-muted">${esc(fbFormatBytes(c.sizeBytes))}</span>
      <button class="btn btn-outline-danger btn-sm ms-auto py-0 px-2" onclick="fbRemoveCustomPath(${i})"><i class="bi bi-x-lg"></i></button>
    </div>`).join('');
}

function fbRemoveCustomPath(index) {
  fbFolders.customPaths.splice(index, 1);
  fbRenderCustomList();
}

async function fbLoadFolders() {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  try {
    const data = await (await fetch(`/api/devices/${deviceId}/file-backup/folders`)).json();
    if (selectedDeviceId !== deviceId) return; // navigated away -- don't overwrite the shared fbFolders/render with a stale device's data
    fbFolders = {
      wellKnown: Array.isArray(data.wellKnown) ? data.wellKnown : [...FB_KNOWN_FOLDERS],
      customPaths: Array.isArray(data.customPaths) ? data.customPaths : [],
    };
  } catch (e) {
    fbFolders = { wellKnown: [...FB_KNOWN_FOLDERS], customPaths: [] };
  }
  fbRenderWellKnown();
  fbRenderCustomList();
}

function fbSaveFolders(btn) {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  const status = document.getElementById('fb-folders-status');
  const saved = btn.innerHTML;
  btn.disabled = true;
  btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Saving…';
  fetch(`/api/devices/${deviceId}/file-backup/folders`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(fbFolders),
  })
    .then(r => r.json())
    .then(data => {
      if (data.ok) { showToast('Folder selection saved', 'success'); if (status && selectedDeviceId === deviceId) { status.textContent = 'Saved'; status.className = 'small text-success'; } }
      else { showToast(data.error || 'Save failed', 'danger'); if (status && selectedDeviceId === deviceId) { status.textContent = data.error || 'Save failed'; status.className = 'small text-danger'; } }
    })
    .catch(e => { showToast(e.message, 'danger'); if (status && selectedDeviceId === deviceId) { status.textContent = e.message; status.className = 'small text-danger'; } })
    .finally(() => { btn.disabled = false; btn.innerHTML = saved; });
}

// ── Folder-browser modal ─────────────────────────────────────────────────────────────────────
// Live remote directory listing over the device's Hop-2 tunnel (server.js -> bastionClient.
// fileBackupBrowse -> bastion-web.py's list_remote_directory). Blank path = every local drive
// letter (the picker's root — not just C:\, per user request). Selecting a folder triggers a
// separate one-shot recursive size lookup (fileBackupPathSize) before it's added to the custom
// list, so the size shown in the main tab is a real cached number, never re-computed on load.
function fbOpenPicker(mode, ctx) {
  fbPickerMode = mode === 'restore' ? 'restore' : 'add';
  fbPickerRestoreCtx = fbPickerMode === 'restore' ? ctx : null;
  fbPickerPath = '';
  fbPickerEntries = [];
  const modalEl = document.getElementById('fb-picker-modal');
  if (!modalEl) return;
  const titleEl = document.getElementById('fb-picker-title');
  const labelEl = document.getElementById('fb-picker-select-label');
  const defaultBtn = document.getElementById('fb-picker-default-btn');
  if (titleEl) titleEl.innerHTML = fbPickerMode === 'restore'
    ? '<i class="bi bi-folder2-open me-2"></i>Pick a Restore Destination'
    : '<i class="bi bi-folder2-open me-2"></i>Pick a Folder';
  if (labelEl) labelEl.textContent = fbPickerMode === 'restore' ? 'Restore Here' : 'Select This Folder';
  if (defaultBtn) defaultBtn.classList.toggle('d-none', fbPickerMode !== 'restore');
  bootstrap.Modal.getOrCreateInstance(modalEl).show();
  fbPickerBrowse('');
}

function fbPickerUseDefault() {
  const modalEl = document.getElementById('fb-picker-modal');
  const ctx = fbPickerRestoreCtx;
  if (modalEl) bootstrap.Modal.getInstance(modalEl)?.hide();
  if (ctx) fbRestoreDefaultLocation(ctx.backupKey, ctx.btn);
}

function fbPickerBrowse(path) {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  const listEl = document.getElementById('fb-picker-list');
  const pathEl = document.getElementById('fb-picker-path');
  const selectBtn = document.getElementById('fb-picker-select-btn');
  const sizeStatus = document.getElementById('fb-picker-size-status');
  if (listEl) listEl.innerHTML = '<div class="text-muted small p-2"><span class="spinner-border spinner-border-sm me-1"></span>Loading…</div>';
  if (sizeStatus) sizeStatus.textContent = '';
  if (selectBtn) selectBtn.disabled = true;
  fetch(`/api/devices/${deviceId}/file-backup/browse`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ path }),
  })
    .then(r => r.json())
    .then(data => {
      if (!data.ok) {
        if (listEl) listEl.innerHTML = `<div class="text-danger small p-2">${esc(data.error || 'Browse failed')}</div>`;
        return;
      }
      fbPickerPath = path;
      fbPickerEntries = data.entries || [];
      if (pathEl) pathEl.textContent = path || 'Drives';
      if (selectBtn) selectBtn.disabled = !path; // can't "select" the drive-list root itself
      if (!listEl) return;
      if (!fbPickerEntries.length) {
        listEl.innerHTML = '<div class="text-muted small p-2">No subfolders here.</div>';
        return;
      }
      listEl.innerHTML = fbPickerEntries.map(name => `
        <button type="button" class="list-group-item list-group-item-action bg-transparent text-light border-secondary-subtle py-1"
                onclick="fbPickerNavigate('${escJsAttr(name)}')">
          <i class="bi bi-folder-fill me-2 text-warning"></i>${esc(name)}
        </button>`).join('');
    })
    .catch(e => { if (listEl) listEl.innerHTML = `<div class="text-danger small p-2">${esc(e.message)}</div>`; });
}

function fbPickerNavigate(name) {
  // At the drive-list root, entries ARE already full roots like "C:\" — descend straight into
  // them. Otherwise join onto the current path (Windows paths only carry a trailing backslash
  // right after a bare drive root, never deeper).
  const child = !fbPickerPath ? name : (fbPickerPath.endsWith('\\') ? fbPickerPath + name : fbPickerPath + '\\' + name);
  fbPickerBrowse(child);
}

function fbPickerUp() {
  if (!fbPickerPath) return; // already at the drive-list root
  const trimmed = fbPickerPath.replace(/\\+$/, '');
  const idx = trimmed.lastIndexOf('\\');
  // Anything at or above a bare drive letter ("C:") goes back to the drive-list root instead —
  // a bare drive letter isn't a browsable target the way this picker models paths.
  if (idx <= 2) { fbPickerBrowse(''); return; }
  fbPickerBrowse(trimmed.slice(0, idx));
}

function fbPickerSelectCurrent() {
  const deviceId = selectedDeviceId;
  if (!deviceId || !fbPickerPath) return;
  if (fbPickerMode === 'restore') {
    const ctx = fbPickerRestoreCtx;
    const destPath = fbPickerPath;
    const modalEl = document.getElementById('fb-picker-modal');
    if (modalEl) bootstrap.Modal.getInstance(modalEl)?.hide();
    if (ctx) fbConfirmAndRestore(deviceId, ctx.backupKey, ctx.btn, destPath);
    return;
  }
  if (fbFolders.customPaths.some(c => c.path === fbPickerPath)) {
    showToast('That folder is already in the list', 'warning');
    return;
  }
  const selectBtn = document.getElementById('fb-picker-select-btn');
  const sizeStatus = document.getElementById('fb-picker-size-status');
  if (selectBtn) selectBtn.disabled = true;
  if (sizeStatus) sizeStatus.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Calculating folder size…';
  fetch(`/api/devices/${deviceId}/file-backup/path-size`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ path: fbPickerPath }),
  })
    .then(r => r.json())
    .then(data => {
      // Size is a best-effort convenience, not a gate — still add the folder even if the lookup
      // failed/timed out (a genuinely huge folder can legitimately take a while to measure).
      fbFolders.customPaths.push({ path: fbPickerPath, sizeBytes: data.ok ? data.sizeBytes : null, addedAt: Date.now() });
      fbRenderCustomList();
      showToast(data.ok ? `Added — ${fbFormatBytes(data.sizeBytes)}` : 'Added (size unknown — lookup failed)', 'success');
      const modalEl = document.getElementById('fb-picker-modal');
      if (modalEl) bootstrap.Modal.getInstance(modalEl)?.hide();
    })
    .catch(e => { showToast(e.message, 'danger'); })
    .finally(() => { if (selectBtn) selectBtn.disabled = false; if (sizeStatus) sizeStatus.textContent = ''; });
}

// ── S3 Bucket Network Drive panel (admin AND public/business_sub device owners) ────────────────
// Two independent shares, two independent drive letters, two independently-scoped passwords:
//   - Public: account-wide config/password (applies to every device the account controls) — same
//     UX shape as File Backup's S3 config/key cards above.
//   - Private: THIS device's own password only — set on this device's own tab, never shared.
// Called from switchTab() whenever the S3 Drive tab (for whichever device is selected) is opened.
function s3dLoadPanel() {
  s3dLoadConfig();
  s3dLoadPublicKey();
  s3dLoadPrivateKey();
  s3dLoadEnabled();
  s3dLoadStatus();
  s3dLoadRecoverable();
}

// Per-account S3 connection config — bucket/endpoint/keys shared by BOTH shares.
async function s3dLoadConfig() {
  try {
    const cfg = await (await fetch('/api/account/s3-drive-s3-config')).json();
    const set = (id, val) => { const el = document.getElementById(id); if (el) el.value = val ?? ''; };
    set('s3d-cfg-endpoint', cfg.endpoint);
    set('s3d-cfg-bucket', cfg.bucket);
    set('s3d-cfg-region', cfg.region);
    set('s3d-cfg-bandwidth', cfg.bandwidthMbps || 10);
    const accessEl = document.getElementById('s3d-cfg-access-key');
    if (accessEl) accessEl.placeholder = cfg.accessKeySet ? '•••• set — leave blank to keep ••••' : 'Access Key ID';
    const secretEl = document.getElementById('s3d-cfg-secret-key');
    if (secretEl) secretEl.placeholder = cfg.secretKeySet ? '•••• set — leave blank to keep ••••' : 'Secret Access Key';
    const status = document.getElementById('s3d-cfg-status');
    if (status) status.textContent = cfg.configured ? 'Configured' : 'Not fully configured yet';
  } catch (e) { showToast('Failed to load S3 Drive config: ' + e.message, 'danger'); }
}

function s3dSaveConfig(btn) {
  const saved = btn.innerHTML;
  btn.disabled = true;
  btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Saving…';
  const body = {
    endpoint: document.getElementById('s3d-cfg-endpoint')?.value || '',
    bucket: document.getElementById('s3d-cfg-bucket')?.value || '',
    accessKey: document.getElementById('s3d-cfg-access-key')?.value || '',
    secretKey: document.getElementById('s3d-cfg-secret-key')?.value || '',
    region: document.getElementById('s3d-cfg-region')?.value || '',
    bandwidthMbps: document.getElementById('s3d-cfg-bandwidth')?.value || 10,
  };
  fetch('/api/account/s3-drive-s3-config', {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
  })
    .then(r => r.json())
    .then(data => {
      if (data.ok) {
        showToast('S3 Drive config saved', 'success');
        ['s3d-cfg-access-key', 's3d-cfg-secret-key'].forEach(id => { const el = document.getElementById(id); if (el) el.value = ''; });
        s3dLoadConfig();
      } else showToast(data.error || 'Save failed', 'danger');
    })
    .catch(e => showToast(e.message, 'danger'))
    .finally(() => { btn.disabled = false; btn.innerHTML = saved; });
}

// Public share password — account-wide, applies to every device the account controls.
async function s3dLoadPublicKey() {
  try {
    const data = await (await fetch('/api/account/s3-drive-public-key')).json();
    const el = document.getElementById('s3d-public-pw');
    if (el) el.placeholder = data.isSet ? '•••• set — leave blank to keep ••••' : 'Set the shared Public share password';
    const status = document.getElementById('s3d-public-pw-status');
    if (status) { status.textContent = data.isSet ? 'Set' : 'Not set yet — the Public share stays disabled until you set one'; status.className = data.isSet ? 'small text-success' : 'small text-warning'; }
  } catch (e) { /* best-effort */ }
}

function s3dSavePublicKey(btn) {
  const input = document.getElementById('s3d-public-pw');
  const password = input?.value || '';
  if (!password) { showToast('Enter a password first', 'warning'); return; }
  const saved = btn.innerHTML;
  btn.disabled = true;
  btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span>';
  fetch('/api/account/s3-drive-public-key', {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ password }),
  })
    .then(r => r.json())
    .then(data => {
      if (data.ok) { showToast('Public share password saved', 'success'); if (input) input.value = ''; s3dLoadPublicKey(); }
      else showToast(data.error || 'Save failed', 'danger');
    })
    .catch(e => showToast(e.message, 'danger'))
    .finally(() => { btn.disabled = false; btn.innerHTML = saved; });
}

// Private share password — THIS device only. Setting a fresh one here also clears any prior
// "recovered from another device" prefix pointer server-side (see recover-private below).
async function s3dLoadPrivateKey() {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  try {
    const data = await (await fetch(`/api/devices/${deviceId}/s3-drive/private-key`)).json();
    if (selectedDeviceId !== deviceId) return; // navigated away -- don't paint onto another device's panel
    const el = document.getElementById('s3d-private-pw');
    if (el) el.placeholder = data.isSet ? '•••• set — leave blank to keep ••••' : 'Set this device\'s Private share password';
    const status = document.getElementById('s3d-private-pw-status');
    if (status) { status.textContent = data.isSet ? 'Set' : 'Not set yet — the Private share stays disabled until you set one'; status.className = data.isSet ? 'small text-success' : 'small text-warning'; }
  } catch (e) { /* best-effort */ }
}

function s3dSavePrivateKey(btn) {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  const input = document.getElementById('s3d-private-pw');
  const password = input?.value || '';
  if (!password) { showToast('Enter a password first', 'warning'); return; }
  const saved = btn.innerHTML;
  btn.disabled = true;
  btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span>';
  fetch(`/api/devices/${deviceId}/s3-drive/private-key`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ password }),
  })
    .then(r => r.json())
    .then(data => {
      if (data.ok) { showToast('Private share password saved', 'success'); if (input) input.value = ''; s3dLoadPrivateKey(); s3dLoadStatus(); s3dLoadRecoverable(); }
      else showToast(data.error || 'Save failed', 'danger');
    })
    .catch(e => showToast(e.message, 'danger'))
    .finally(() => { btn.disabled = false; btn.innerHTML = saved; });
}

async function s3dLoadEnabled() {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  try {
    const data = await (await fetch(`/api/devices/${deviceId}/s3-drive/enabled`)).json();
    if (selectedDeviceId !== deviceId) return; // navigated away -- don't paint onto another device's panel
    const toggle = document.getElementById('s3d-enabled-toggle');
    if (toggle) toggle.checked = !!data.enabled;
  } catch (e) { /* best-effort */ }
}

function s3dToggleEnabled(checkbox) {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  const enabled = !!checkbox.checked;
  checkbox.disabled = true;
  fetch(`/api/devices/${deviceId}/s3-drive/enabled`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ enabled }),
  })
    .then(r => r.json())
    .then(data => {
      if (data.ok) { showToast(`S3 Drive ${enabled ? 'enabled' : 'disabled'}`, 'success'); s3dLoadStatus(); }
      else { checkbox.checked = !enabled; showToast(data.error || 'Save failed', 'danger'); }
    })
    .catch(e => { checkbox.checked = !enabled; showToast(e.message, 'danger'); })
    .finally(() => { checkbox.disabled = false; });
}

function s3dForceResync(btn) {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  const saved = btn.innerHTML;
  btn.disabled = true;
  btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Requesting…';
  fetch(`/api/devices/${deviceId}/s3-drive/force-resync`, { method: 'POST' })
    .then(r => r.json())
    .then(data => {
      if (data.ok) showToast('Resync requested — the device will re-baseline both shares on its next check-in', 'success');
      else showToast(data.error || 'Request failed', 'danger');
    })
    .catch(e => showToast(e.message, 'danger'))
    .finally(() => { btn.disabled = false; btn.innerHTML = saved; });
}

// Live status card — drive letters/last-sync/last-error, durably tracked server-side (survives a
// server restart, unlike the ephemeral deviceStatus map — see server.js's s3_drive_status handler).
function s3dLoadStatus() {
  const deviceId = selectedDeviceId;
  const el = document.getElementById('s3d-status-body');
  if (!el || !deviceId) return;
  fetch(`/api/devices/${deviceId}/s3-drive/status`)
    .then(r => r.json())
    .then(data => {
      if (selectedDeviceId !== deviceId) return; // navigated away -- don't paint onto another device's panel
      const row = (label, letter, syncAt, err) => `
        <div class="d-flex align-items-center gap-2 py-1 border-bottom border-secondary-subtle flex-wrap">
          <strong style="min-width:60px">${esc(label)}</strong>
          <span class="font-monospace">${letter ? esc(letter) + ':' : '—'}</span>
          <span class="text-muted">${syncAt ? 'Last sync: ' + esc(new Date(syncAt).toLocaleString()) : 'Never synced yet'}</span>
          ${err ? `<span class="text-danger ms-auto" title="${escAttr(err)}">Error</span>` : ''}
        </div>`;
      el.innerHTML = (data.enabled ? '' : '<div class="text-muted small mb-1">S3 Drive is disabled for this device.</div>')
        + row('Private', data.privateDriveLetter, data.privateLastSyncAt, data.privateLastError)
        + row('Public', data.publicDriveLetter, data.publicLastSyncAt, data.publicLastError);
    })
    .catch(e => { el.innerHTML = `<span class="text-danger">${esc(e.message)}</span>`; });
}

// Recovery — see server.js's /s3-drive/recoverable + /recover-private doc comment. Shown only
// when this device has no Private password set yet (once set, recovery no longer applies).
async function s3dLoadRecoverable() {
  const deviceId = selectedDeviceId;
  const card = document.getElementById('s3d-recover-card');
  const list = document.getElementById('s3d-recover-list');
  if (!card || !list || !deviceId) return;
  try {
    const [keyData, recData] = await Promise.all([
      fetch(`/api/devices/${deviceId}/s3-drive/private-key`).then(r => r.json()),
      fetch(`/api/devices/${deviceId}/s3-drive/recoverable`).then(r => r.json()),
    ]);
    if (selectedDeviceId !== deviceId) return; // navigated away -- don't paint onto another device's panel
    if (keyData.isSet) { card.classList.add('d-none'); return; }
    const candidates = recData.candidates || [];
    card.classList.remove('d-none');
    list.innerHTML = candidates.length
      ? candidates.map(c => `
        <div class="d-flex align-items-center gap-2 py-1 border-bottom border-secondary-subtle flex-wrap">
          <span class="text-truncate" style="max-width:180px">${esc(c.name)}</span>
          <span class="text-muted small">${c.lastSeen ? 'last seen ' + esc(new Date(c.lastSeen).toLocaleString()) : ''}</span>
          <button class="btn btn-outline-warning btn-sm ms-auto" onclick="s3dRecoverPrivate('${escJsAttr(c.id)}', this)">Recover this device's Private share</button>
        </div>`).join('')
      : '<span class="text-muted small">No other devices with a stored Private share found on this account.</span>';
  } catch (e) { /* best-effort — recovery is a convenience, never block the rest of the panel */ }
}

function s3dRecoverPrivate(sourceDeviceId, btn) {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  showConfirm({
    title: "Recover this device's Private share?",
    body: '<p class="mb-1">This device will adopt the selected device\'s Private share password and S3 prefix, and re-sync from what\'s already there. Do this only if that other device is permanently gone (crashed/reinstalled) — otherwise both devices would sync the same Private prefix at once.</p>',
    okLabel: 'Recover',
    okClass: 'btn-warning',
    onConfirm: () => {
      const saved = btn.innerHTML;
      btn.disabled = true;
      btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span>';
      fetch(`/api/devices/${deviceId}/s3-drive/recover-private`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ sourceDeviceId }),
      })
        .then(r => r.json())
        .then(data => {
          if (data.ok) { showToast('Private share recovered — resyncing…', 'success'); s3dLoadPrivateKey(); s3dLoadStatus(); s3dLoadRecoverable(); }
          else { btn.disabled = false; btn.innerHTML = saved; showToast(data.error || 'Recovery failed', 'danger'); }
        })
        .catch(e => { btn.disabled = false; btn.innerHTML = saved; showToast(e.message, 'danger'); });
    },
  });
}

function s3dRecoverPrivateManual(btn) {
  const input = document.getElementById('s3d-recover-manual-id');
  const sourceDeviceId = (input?.value || '').trim();
  if (!sourceDeviceId) { showToast('Enter the old device ID first', 'warning'); return; }
  s3dRecoverPrivate(sourceDeviceId, btn);
}

// ── BitLocker panel (admin AND public/business_sub device owners) ──────────────────────────────
// Enable/status run inline over Hop-2 (no C# agent involvement) — see server.js's
// /api/devices/:id/bitlocker/* routes and bitlocker_enable()/bitlocker_status() in bastion-web.py.
// Recovery keys are downloaded via a plain same-origin authenticated GET (session cookie), same
// pattern as the existing /api/recordings/:id/download anchor elsewhere in this file — no blob/JS
// fetch needed.
function blLoadPanel() {
  blLoadStatus();
  blLoadKeys();
}

function blEnable(btn) {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  const mpSel = document.getElementById('bl-enable-mountpoint');
  const mountPoint = (mpSel?.value || 'C:').trim().toUpperCase();
  showConfirm({
    title: `Enable BitLocker on ${escHtml(mountPoint)}?`,
    body: `<p class="mb-1">Starts encrypting this device's <strong>${escHtml(mountPoint)}</strong> drive. Only proceeds if a usable TPM is present (refuses otherwise, to avoid stranding an unattended device at a recovery-key prompt on next boot). The recovery key is uploaded here automatically once generated.</p>`,
    okLabel: 'Enable',
    okClass: 'btn-primary',
    onConfirm: () => {
      const saved = btn.innerHTML;
      btn.disabled = true;
      btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Enabling…';
      fetch(`/api/devices/${deviceId}/bitlocker/enable`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ mountPoint }),
      })
        .then(r => r.json())
        .then(data => {
          if (!data.ok) { showToast(data.error || 'BitLocker enable failed', 'danger'); return; }
          if (data.alreadyEnabled) showToast(`BitLocker is already fully enabled on ${mountPoint}`, 'info');
          else showToast(`BitLocker encryption started on ${mountPoint}${data.newKeys ? ` — ${data.newKeys} recovery key(s) captured` : ''}`, 'success');
          blLoadStatus();
          blLoadKeys();
        })
        .catch(e => showToast(e.message, 'danger'))
        .finally(() => { btn.disabled = false; btn.innerHTML = saved; });
    },
  });
}

// Keeps the drive-picker's options in sync with whatever volumes the device actually reports
// (Get-BitLockerVolume enumerates every mount point, not just C: — see _BITLOCKER_STATUS_PS1 in
// bastion-web.py), so a second/external disk shows up here without any hardcoded drive-letter list.
// Preserves the current selection across a refresh when it's still a valid option; falls back to
// C: (always present as a fallback option, even before the first successful status load).
function _blRenderMountpointOptions(volumes) {
  const sel = document.getElementById('bl-enable-mountpoint');
  if (!sel) return;
  const mountPoints = Array.from(new Set((volumes || []).map(v => v.mountPoint).filter(Boolean)));
  if (!mountPoints.includes('C:')) mountPoints.unshift('C:');
  mountPoints.sort((a, b) => (a === 'C:' ? -1 : b === 'C:' ? 1 : a.localeCompare(b)));
  const prev = sel.value || 'C:';
  sel.innerHTML = mountPoints.map(mp => `<option value="${escAttr(mp)}">${esc(mp)}</option>`).join('');
  sel.value = mountPoints.includes(prev) ? prev : 'C:';
}

function blLoadStatus() {
  const deviceId = selectedDeviceId;
  const el = document.getElementById('bl-status-body');
  if (!el || !deviceId) return;
  el.innerHTML = '<span class="text-muted">Loading…</span>';
  fetch(`/api/devices/${deviceId}/bitlocker/status`)
    .then(r => r.json())
    .then(data => {
      if (selectedDeviceId !== deviceId) return; // navigated away -- don't paint onto another device's panel
      _blRenderMountpointOptions(data.volumes);
      if (!data.ok && !data.volumes?.length) { el.innerHTML = `<span class="text-muted">${esc(data.error || 'No status available yet.')}</span>`; return; }
      const staleNote = data.live === false ? '<div class="small text-muted mb-1"><i class="bi bi-clock-history me-1"></i>Last known state — device is offline right now.</div>' : '';
      const rows = (data.volumes || []).map(v => {
        const pct = Number(v.encryptionPercentage) || 0;
        const on = v.protectionStatus === 'On';
        const badge = on ? 'bg-success' : (v.volumeStatus === 'FullyDecrypted' ? 'bg-secondary' : 'bg-warning text-dark');
        return `
        <div class="py-1 border-bottom border-secondary-subtle">
          <div class="d-flex align-items-center gap-2 flex-wrap">
            <strong class="font-monospace">${esc(v.mountPoint)}</strong>
            <span class="badge ${badge}">${esc(v.protectionStatus || 'Unknown')}</span>
            <span class="text-muted small">${esc(v.volumeStatus || '')}</span>
            <span class="text-muted small ms-auto">${pct}%</span>
          </div>
          <div class="progress mt-1" style="height:6px">
            <div class="progress-bar ${on ? 'bg-success' : 'bg-warning'}" style="width:${pct}%"></div>
          </div>
        </div>`;
      }).join('');
      el.innerHTML = staleNote + (rows || '<span class="text-muted">BitLocker is not enabled on this device yet.</span>');
    })
    .catch(e => { el.innerHTML = `<span class="text-danger">${esc(e.message)}</span>`; });
}

function blLoadKeys() {
  const deviceId = selectedDeviceId;
  const el = document.getElementById('bl-keys-body');
  if (!el || !deviceId) return;
  el.innerHTML = '<span class="text-muted">Loading…</span>';
  fetch(`/api/devices/${deviceId}/bitlocker/keys`)
    .then(r => r.json())
    .then(data => {
      if (selectedDeviceId !== deviceId) return; // navigated away -- don't paint onto another device's panel
      const keys = data.keys || [];
      if (!keys.length) { el.innerHTML = '<span class="text-muted">No recovery keys captured yet — click Enable (or Refresh Status) to check.</span>'; return; }
      el.innerHTML = keys.map(k => `
        <div class="d-flex align-items-center gap-2 py-1 border-bottom border-secondary-subtle flex-wrap">
          <span class="font-monospace">${esc(k.volume)}</span>
          <span class="text-muted small">${esc(new Date(k.createdAt).toLocaleString())}</span>
          <span class="text-muted small font-monospace" title="Key Protector ID">${esc(k.keyProtectorId.slice(0, 8))}…</span>
          <a class="btn btn-outline-primary btn-sm ms-auto" href="/api/devices/${deviceId}/bitlocker/keys/${encodeURIComponent(k.id)}/download"><i class="bi bi-download me-1"></i>Download</a>
          <button class="btn btn-outline-danger btn-sm" onclick="blDeleteKey('${escJsAttr(k.id)}', this)"><i class="bi bi-trash me-1"></i>Delete</button>
        </div>`).join('');
    })
    .catch(e => { el.innerHTML = `<span class="text-danger">${esc(e.message)}</span>`; });
}

function blDeleteKey(keyId, btn) {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  showConfirm({
    title: 'Delete this recovery key?',
    body: '<p class="mb-1">Permanently removes this stored recovery key from the server. Only do this if the drive has been decrypted or the key is no longer needed — this cannot be undone and there is no other copy here.</p>',
    okLabel: 'Delete',
    okClass: 'btn-danger',
    onConfirm: () => {
      const saved = btn.innerHTML;
      btn.disabled = true;
      btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span>';
      fetch(`/api/devices/${deviceId}/bitlocker/keys/${encodeURIComponent(keyId)}`, { method: 'DELETE' })
        .then(r => r.json())
        .then(data => {
          if (!data.ok) { btn.disabled = false; btn.innerHTML = saved; showToast(data.error || 'Delete failed', 'danger'); return; }
          showToast('Recovery key deleted', 'success');
          blLoadKeys();
        })
        .catch(e => { btn.disabled = false; btn.innerHTML = saved; showToast(e.message, 'danger'); });
    },
  });
}

// ── Boot ISO panel (admin AND public/business_sub device owners) ─────────────────────────────
// Set/Reboot/Restore run inline over Hop-2 (no C# agent involvement) — see server.js's
// /api/devices/:id/remote-assist/boot-iso/* routes, bastionClient.bootIso* and
// boot_iso_set()/boot_iso_reboot()/boot_iso_status()/boot_iso_restore() in bastion-web.py.
// `set` is fire-and-poll: the bastion downloads the ISO on the box in a background thread and
// the status card polls until it lands on a terminal step. The admin upload card streams a
// custom ISO to R2 in 16MB chunks (multipart) — admin-only UI, hidden for non-admin roles.
let biCatalogCache = null;
let biStatusTimer = null;

function biLoadPanel() {
  biLoadCatalog();
  biLoadStatus();
  biLoadUploadUi();
}

function biLoadCatalog() {
  const deviceId = selectedDeviceId;
  const sel = document.getElementById('bi-catalog-select');
  if (!sel || !deviceId) return;
  fetch(`/api/devices/${deviceId}/remote-assist/boot-iso/catalog`)
    .then(r => r.json())
    .then(data => {
      if (selectedDeviceId !== deviceId) return;
      biCatalogCache = data.catalog || [];
      sel.innerHTML = biCatalogCache.map(e => `<option value="${escAttr(e.id)}">${esc(e.name)}</option>`).join('') || '<option value="">No ISOs available</option>';
      biRenderUploadCatalog();
    })
    .catch(() => { sel.innerHTML = '<option value="">Catalog unavailable</option>'; });
}

function _biCurrentEntry() {
  const sel = document.getElementById('bi-catalog-select');
  return (biCatalogCache || []).find(e => e.id === (sel?.value || '')) || null;
}

function biSetBoot(btn) {
  const deviceId = selectedDeviceId;
  const entry = _biCurrentEntry();
  if (!deviceId || !entry) return;
  showConfirm({
    title: `Boot ${escHtml(entry.name)} on next restart?`,
    body: `<p class="mb-1">Downloads <strong>${escHtml(entry.isoFile)}</strong> directly on this device (SHA-256 verified when the catalog knows it), installs a <strong>Secure Boot–signed GRUB</strong> on the EFI partition, and points the Boot Manager at it — works with Secure Boot ON, no keys needed. <strong>No reboot happens yet</strong> — the box boots the ISO on its next restart, or click <strong>Reboot Now</strong> for a 60-second delayed reboot. The GRUB menu always keeps a Windows fallback entry, so a failed ISO boot returns to Windows automatically.</p><p class="mb-1 text-warning"><i class="bi bi-exclamation-triangle me-1"></i>If the OS drive is BitLocker-encrypted, the ISO is stored on the largest unencrypted data drive instead (GRUB cannot read encrypted volumes), or a new unencrypted partition is carved by shrinking the OS drive — or the operation is refused with instructions if neither is possible.</p>`,
    okLabel: 'Set Boot',
    okClass: 'btn-primary',
    onConfirm: () => {
      const saved = btn.innerHTML;
      btn.disabled = true;
      btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Setting…';
      fetch(`/api/devices/${deviceId}/remote-assist/boot-iso/set`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ isoId: entry.id }),
      })
        .then(r => r.json())
        .then(data => {
          if (!data.ok) { showToast(data.error || 'Boot ISO set failed', 'danger'); return; }
          showToast(`Boot ISO staged — ${data.status || 'started'}. The box will boot into it on its next restart.`, 'success');
          biPollStatusUntilSettled();
        })
        .catch(e => showToast(e.message, 'danger'))
        .finally(() => { btn.disabled = false; btn.innerHTML = saved; });
    },
  });
}

function biRebootNow(btn) {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  showConfirm({
    title: 'Reboot into the boot ISO now?',
    body: '<p class="mb-1">Triggers <code>shutdown /r /t 60</code> — the device reboots in 60 seconds (the on-screen banner says to run <code>shutdown /a</code> to cancel). The boot ISO entry must already be set, or this just performs a normal reboot.</p>',
    okLabel: 'Reboot in 60s',
    okClass: 'btn-warning',
    onConfirm: () => {
      const saved = btn.innerHTML;
      btn.disabled = true;
      btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Rebooting…';
      fetch(`/api/devices/${deviceId}/remote-assist/boot-iso/reboot`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' })
        .then(r => r.json())
        .then(data => {
          if (!data.ok) { showToast(data.error || 'Reboot failed', 'danger'); return; }
          showToast(`Reboot scheduled — device restarts in ${data.rebootInSec ?? 60}s (shutdown /a cancels).`, 'success');
        })
        .catch(e => showToast(e.message, 'danger'))
        .finally(() => { btn.disabled = false; btn.innerHTML = saved; });
    },
  });
}

function biRestoreBoot(btn) {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  showConfirm({
    title: 'Restore normal Windows booting?',
    body: '<p class="mb-1">Removes the GRUB bootloader and the downloaded ISO entirely from this device and points the Windows Boot Manager back at <code>bootmgfw.efi</code> — Windows boots exactly as it did before the Boot ISO feature was ever used.</p>',
    okLabel: 'Restore',
    okClass: 'btn-danger',
    onConfirm: () => {
      const saved = btn.innerHTML;
      btn.disabled = true;
      btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Restoring…';
      fetch(`/api/devices/${deviceId}/remote-assist/boot-iso/restore`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' })
        .then(r => r.json())
        .then(data => {
          if (!data.ok) { showToast(data.error || 'Restore failed', 'danger'); return; }
          showToast('Normal Windows booting restored — GRUB and ISO removed.', 'success');
          biLoadStatus();
        })
        .catch(e => showToast(e.message, 'danger'))
        .finally(() => { btn.disabled = false; btn.innerHTML = saved; });
    },
  });
}

function biLoadStatus() {
  const deviceId = selectedDeviceId;
  const el = document.getElementById('bi-status-body');
  if (!el || !deviceId) return;
  el.innerHTML = '<span class="text-muted">Loading…</span>';
  fetch(`/api/devices/${deviceId}/remote-assist/boot-iso/status`)
    .then(r => r.json())
    .then(data => {
      if (selectedDeviceId !== deviceId) return; // navigated away -- don't paint onto another device's panel
      if (!data.ok && !data.bootmgrPath) { el.innerHTML = `<span class="text-muted">${esc(data.error || 'No status available yet.')}</span>`; return; }
      const staleNote = data.live === false ? '<div class="small text-muted mb-1"><i class="bi bi-clock-history me-1"></i>Last known state — device is offline right now.</div>' : '';
      const active = data.sentinelActive;
      const bootBadge = active
        ? '<span class="badge bg-danger">Sentinel GRUB — booting into ISO</span>'
        : '<span class="badge bg-success">Windows Boot Manager (normal)</span>';
      const bootmgr = `<div class="py-1"><span class="text-muted small">Boot Manager path:</span> <span class="font-monospace small">${esc(data.bootmgrPath || '(unreadable)')}</span> ${bootBadge}</div>`;
      let stateRow = '';
      if (data.state) {
        const st = data.state;
        const stepLabels = { downloading: 'Downloading ISO on the box…', verifying: 'Verifying SHA-256…', staging: 'Installing GRUB + setting boot entry…', done: 'Ready — boots into ISO on next restart', failed: 'Failed', restored: 'Restored to normal Windows boot' };
        const label = stepLabels[st.step] || esc(st.step || '');
        const badgeCls = st.step === 'failed' ? 'bg-danger' : (st.step === 'done' || st.step === 'restored' ? 'bg-success' : 'bg-warning text-dark');
        stateRow = `<div class="py-1"><span class="text-muted small">Stage:</span> <span class="badge ${badgeCls}">${esc(label)}</span>${st.detail ? `<div class="small text-danger mt-1">${esc(st.detail)}</div>` : ''}</div>`;
      }
      const files = [
        data.grubInstalled !== undefined ? `<span>GRUB on box: ${data.grubInstalled ? '<span class="text-success">yes</span>' : '<span class="text-muted">no</span>'}</span>` : '',
        data.isoPresent !== undefined ? `<span>ISO on box: ${data.isoPresent ? '<span class="text-success">yes</span>' : '<span class="text-muted">no</span>'}</span>` : '',
      ].filter(Boolean).join(' · ');
      const driveNote = data.isoDrive && data.isoDrive !== 'C:' ? `<div class="py-1 small text-muted"><i class="bi bi-info-circle me-1"></i>ISO stored on <strong>${esc(data.isoDrive)}</strong> — the OS drive is BitLocker-encrypted, and GRUB can't read encrypted volumes at boot.</div>` : '';
      el.innerHTML = staleNote + bootmgr + stateRow + (files ? `<div class="py-1 small text-muted">${files}</div>` : '') + driveNote;
      if (data.staging || (data.state && ['downloading', 'verifying', 'staging'].includes(data.state.step))) {
        biPollStatusUntilSettled();
      } else if (biStatusTimer) { clearTimeout(biStatusTimer); biStatusTimer = null; }
    })
    .catch(e => { el.innerHTML = `<span class="text-danger">${esc(e.message)}</span>`; });
}

// `set` returns before the download finishes — poll status every 5s until the stage settles.
// Self-terminating (clears its own timer) so an offline device can't spin forever.
function biPollStatusUntilSettled() {
  if (biStatusTimer) clearTimeout(biStatusTimer);
  let tries = 0;
  const tick = () => {
    tries++;
    if (tries > 120) { biStatusTimer = null; return; }
    const deviceId = selectedDeviceId;
    if (!deviceId) { biStatusTimer = null; return; }
    fetch(`/api/devices/${deviceId}/remote-assist/boot-iso/status`)
      .then(r => r.json())
      .then(data => {
        if (selectedDeviceId !== deviceId) { biStatusTimer = null; return; }
        const step = data?.state?.step;
        if (!step || ['done', 'failed', 'restored'].includes(step)) {
          biLoadStatus();
          biStatusTimer = null;
          return;
        }
        biLoadStatus();
        biStatusTimer = setTimeout(tick, 5000);
      })
      .catch(() => { biStatusTimer = setTimeout(tick, 10000); });
  };
  tick();
}

// ── Boot ISO admin upload (chunked to R2, multipart) ─────────────────────────
const BI_CHUNK_MB = 16;

function biLoadUploadUi() {
  // The upload card is ALWAYS visible to anyone who can see the Boot ISO tab — the
  // server's requireAdmin on /api/admin/boot-iso/* is the actual gate. Hiding it
  // client-side by role left admins whose session resolved to a non-admin role
  // (sub-user/impersonation/business_sub edge cases) staring at a missing button with
  // no way to know why (found live 2026-08-16). Non-admins get a clear error from the
  // server if they try.
  const msg = document.getElementById('bi-upload-msg');
  if (msg) msg.textContent = '';
  biRenderUploadCatalog();
}

function biRenderUploadCatalog() {
  const el = document.getElementById('bi-catalog-manage');
  if (!el) return;
  // The catalog is per-account: every entry listed is the viewer's own (their
  // boot-iso/<email>/ folder + admin-visible root ISOs), so everyone gets delete.
  const entries = biCatalogCache || [];
  el.innerHTML = entries.length
    ? `<div class="mt-1"><span class="fw-semibold">Your ISOs:</span> ${entries.map(e =>
        `<span class="badge bg-secondary me-1">${esc(e.name)} <a href="#" class="text-danger ms-1" title="Delete from R2" onclick="biDeleteIso('${escJsAttr(e.id)}', this); return false;">×</a></span>`).join('')}</div>`
    : '<div class="mt-1 text-muted">No ISOs in your account folder yet.</div>';
}

function biDeleteIso(isoId, el) {
  if (!window.confirm('Delete this uploaded ISO from the catalog and R2? This cannot be undone.')) return;
  fetch(`/api/admin/boot-iso/catalog/${encodeURIComponent(isoId)}`, { method: 'DELETE' })
    .then(r => r.json())
    .then(data => {
      if (!data.ok) { showToast(data.error || 'Delete failed', 'danger'); return; }
      showToast('Uploaded ISO deleted', 'success');
      biLoadCatalog();
    })
    .catch(e => showToast(e.message, 'danger'));
}

async function biUploadIso(btn) {
  const fileInput = document.getElementById('bi-upload-file');
  const file = fileInput?.files?.[0];
  if (!file) { showToast('Pick a .iso file first', 'warning'); return; }
  if (!/\.iso$/i.test(file.name)) { showToast('Only .iso files can be uploaded', 'warning'); return; }
  const name = (document.getElementById('bi-upload-name')?.value || file.name).trim().slice(0, 80);
  const kernel = (document.getElementById('bi-upload-kernel')?.value || '').trim();
  const initrd = (document.getElementById('bi-upload-initrd')?.value || '').trim();
  const saved = btn.innerHTML;
  btn.disabled = true;
  btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Uploading…';
  const wrap = document.getElementById('bi-upload-progress-wrap');
  const bar = document.getElementById('bi-upload-progress');
  const msg = document.getElementById('bi-upload-msg');
  if (wrap) wrap.classList.remove('d-none');
  if (bar) bar.style.width = '0%';
  if (msg) { msg.textContent = 'Hashing…'; msg.classList.remove('text-danger'); }
  try {
    // Browser-side SHA-256 (WebCrypto) of the whole file — the box re-verifies with
    // Get-FileHash before the boot entry is armed, so this is belt-and-suspenders.
    const buf = await file.arrayBuffer();
    const digest = await crypto.subtle.digest('SHA-256', buf);
    const sha256 = Array.from(new Uint8Array(digest)).map(b => b.toString(16).padStart(2, '0')).join('');
    const startRes = await fetch('/api/admin/boot-iso/upload/start', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ fileName: file.name }),
    });
    const start = await startRes.json();
    if (!start.ok) throw new Error(start.error || 'Upload start failed');
    const chunkSize = start.chunkSize || BI_CHUNK_MB * 1024 * 1024;
    const totalChunks = Math.max(1, Math.ceil(file.size / chunkSize));
    for (let i = 0; i < totalChunks; i++) {
      const slice = file.slice(i * chunkSize, Math.min(file.size, (i + 1) * chunkSize));
      const res = await fetch(`/api/admin/boot-iso/upload/chunk?uploadId=${encodeURIComponent(start.uploadId)}&index=${i}`, {
        method: 'POST', headers: { 'Content-Type': 'application/octet-stream' }, body: slice,
      });
      const j = await res.json();
      if (!j.ok) throw new Error(j.error || `Chunk ${i + 1}/${totalChunks} failed`);
      if (bar) bar.style.width = `${Math.round(((i + 1) / totalChunks) * 100)}%`;
      if (msg) msg.textContent = `Uploading… ${i + 1}/${totalChunks} (${Math.round((j.receivedBytes || 0) / 1048576)} MB)`;
    }
    const compRes = await fetch('/api/admin/boot-iso/upload/complete', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ uploadId: start.uploadId, name, kernel, initrd, sha256 }),
    });
    const comp = await compRes.json();
    if (!comp.ok) throw new Error(comp.error || 'Upload finalize failed');
    if (msg) { msg.textContent = `Uploaded ${file.name} (${(file.size / 1048576).toFixed(0)} MB) — SHA-256 ${sha256.slice(0, 12)}…`; msg.classList.remove('text-danger'); }
    if (bar) bar.style.width = '100%';
    showToast('ISO uploaded to the catalog', 'success');
    fileInput.value = '';
    biLoadCatalog();
  } catch (e) {
    if (msg) { msg.textContent = e.message; msg.classList.add('text-danger'); }
    showToast(e.message, 'danger');
  } finally {
    btn.disabled = false;
    btn.innerHTML = saved;
  }
}

// ── USB Lockdown (USBGuard-style) tab handlers ────────────────────────────────────────────

async function raUsblockSet(mode) {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  const enforceBtn = document.getElementById('ra-usblock-enforce-btn');
  const auditBtn = document.getElementById('ra-usblock-audit-btn');
  const disableBtn = document.getElementById('ra-usblock-disable-btn');
  const statusEl = document.getElementById('ra-usblock-status');
  raUsblockClearError();

  let r;
  if (mode === 'Disable') {
    enforceBtn.disabled = auditBtn.disabled = disableBtn.disabled = true;
    statusEl.textContent = 'Disabling…';
    statusEl.classList.add('text-info');
    try {
      r = await fetch(`/api/devices/${deviceId}/remote-assist/usblock/disable`, { method: 'POST', body: '{}' });
      const data = await r.json();
      if (data.ok) {
        raUsblockUpdateUI(data);
        if (data.deploying) {
          // Disable runs async (purge + rescan can outlast the SSH timeout) — poll to completion
          let polls = 0;
          const poll = setInterval(async () => {
            if (++polls > 40) { clearInterval(poll); return; } // 2 min max
            try {
              const sr = await fetch(`/api/devices/${deviceId}/remote-assist/usblock/status`, { method: 'POST', body: '{}' });
              const sd = await sr.json();
              raUsblockUpdateUI(sd);
              if (!sd.deploying) {
                clearInterval(poll);
                showToast('USB Lockdown disabled', 'success');
              }
            } catch (_) {}
          }, 3000);
        } else {
          showToast('USB Lockdown disabled', 'success');
        }
      } else {
        raUsblockShowError('Disable failed: ' + (data.error || data.stdout || 'unknown'));
      }
    } catch (e) {
      // Non-JSON response — usually a Cloudflare/nginx HTML timeout page when the deploy
      // crossed the proxy's idle timeout mid-run. The async schtasks deploy keeps running on
      // the box regardless; poll status so a slow-but-successful deploy still completes visibly.
      const body = (r && typeof r.text === 'function') ? (await r.text().catch(() => '')).slice(0, 300) : '';
      raUsblockShowError('Network error: ' + e.message + (body ? ' — ' + body : ''));
      let polls = 0;
      const poll = setInterval(async () => {
        if (++polls > 40) { clearInterval(poll); return; } // 2 min max
        try {
          const sr = await fetch(`/api/devices/${deviceId}/remote-assist/usblock/status`, { method: 'POST', body: '{}' });
          const sd = await sr.json();
          raUsblockUpdateUI(sd);
          if (!sd.deploying) {
            clearInterval(poll);
            if (sd.mode) showToast(`USB Lockdown ${sd.mode === 'Enforce' ? 'enabled (blocking)' : 'audit only'} — ${sd.deviceCount || 0} devices allowed`, 'success');
          }
        } catch (_) {}
      }, 3000);
    }
    enforceBtn.disabled = auditBtn.disabled = disableBtn.disabled = false;
    return;
  }

  enforceBtn.disabled = auditBtn.disabled = disableBtn.disabled = true;
  statusEl.textContent = (mode === 'Enforce') ? 'Deploying lockdown…' : 'Deploying audit mode…';
  statusEl.classList.add('text-info');
  try {
    r = await fetch(`/api/devices/${deviceId}/remote-assist/usblock/enable`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ mode: mode }),
    });
    const data = await r.json();
    if (data.ok) {
      raUsblockUpdateUI(data);
      if (data.deploying) {
        // Auto-poll for completion
        let polls = 0;
        const poll = setInterval(async () => {
          if (++polls > 40) { clearInterval(poll); return; } // 2 min max
          try {
            const sr = await fetch(`/api/devices/${deviceId}/remote-assist/usblock/status`, { method: 'POST', body: '{}' });
            const sd = await sr.json();
            raUsblockUpdateUI(sd);
            if (!sd.deploying) {
              clearInterval(poll);
              if (sd.mode && sd.ok !== false) {
                showToast(`USB Lockdown ${sd.mode === 'Enforce' ? 'enabled (blocking)' : 'audit only'} — ${sd.deviceCount || 0} devices allowed`, 'success');
              }
            }
          } catch (_) {}
        }, 3000);
      } else {
        showToast(`USB Lockdown ${mode === 'Enforce' ? 'enabled (blocking)' : 'audit only'} — ${data.deviceCount || 0} devices allowed`, 'success');
      }
    } else {
      raUsblockShowError('Enable failed: ' + (data.error || data.stdout || 'unknown'));
    }
  } catch (e) {
    // Same as the disable path: a non-JSON response (proxy HTML timeout page) doesn't mean
    // the deploy failed — the async schtasks kickoff may have landed before the request died.
    const body = (r && typeof r.text === 'function') ? (await r.text().catch(() => '')).slice(0, 300) : '';
    raUsblockShowError('Network error: ' + e.message + (body ? ' — ' + body : ''));
    let polls = 0;
    const poll = setInterval(async () => {
      if (++polls > 40) { clearInterval(poll); return; } // 2 min max
      try {
        const sr = await fetch(`/api/devices/${deviceId}/remote-assist/usblock/status`, { method: 'POST', body: '{}' });
        const sd = await sr.json();
        raUsblockUpdateUI(sd);
        if (!sd.deploying) {
          clearInterval(poll);
          if (sd.mode && sd.ok !== false) {
            showToast(`USB Lockdown ${sd.mode === 'Enforce' ? 'enabled (blocking)' : 'audit only'} — ${sd.deviceCount || 0} devices allowed`, 'success');
          }
        }
      } catch (_) {}
    }, 3000);
  }
  enforceBtn.disabled = auditBtn.disabled = disableBtn.disabled = false;
}

function raUsblockShowError(msg) {
  const el = document.getElementById('ra-usblock-error');
  if (!el) return;
  el.textContent = msg;
  el.classList.remove('d-none');
}

function raUsblockClearError() {
  const el = document.getElementById('ra-usblock-error');
  if (!el) return;
  el.classList.add('d-none');
}

async function raUsblockLoadApproved() {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  const listEl = document.getElementById('ra-usblock-approved-list');
  if (!listEl) return;
  try {
    const r = await fetch(`/api/devices/${deviceId}/remote-assist/usblock/approved`, { method: 'POST', body: '{}' });
    if (!r.ok) { listEl.innerHTML = '<span class="text-muted">Approved list unavailable (HTTP ' + r.status + ')</span>'; return; }
    const data = await r.json();
    if (!data.ok) { listEl.innerHTML = '<span class="text-muted">Approved list unavailable</span>'; return; }
    const approvals = data.approvals || [];
    if (!approvals.length) { listEl.innerHTML = '<span class="text-muted">No persisted approvals — approve a device to persist it across disable/re-enable</span>'; return; }
    listEl.innerHTML = '';
    approvals.forEach(a => {
      const row = document.createElement('div');
      row.className = 'd-flex align-items-center justify-content-between py-1 border-bottom border-secondary';
      row.style.fontSize = '0.72rem';
      const nameSpan = document.createElement('span');
      nameSpan.innerHTML = '<strong>' + (a.friendlyName || a.vidPid || 'Device').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;') + '</strong>';
      const mid = document.createElement('span');
      mid.className = 'text-muted ms-2';
      mid.style.cssText = 'font-family:monospace;font-size:0.65rem';
      mid.textContent = (a.friendlyName && a.friendlyName !== a.vidPid) ? a.vidPid : '';
      const rmBtn = document.createElement('button');
      rmBtn.className = 'btn btn-sm btn-outline-danger border-0 py-0 px-1 flex-shrink-0';
      rmBtn.style.fontSize = '0.65rem';
      rmBtn.innerHTML = '<i class="bi bi-x-circle me-1"></i>Remove';
      rmBtn.onclick = () => raUsblockRemoveApproved(a.vidPid);
      row.appendChild(nameSpan);
      row.appendChild(mid);
      row.appendChild(rmBtn);
      listEl.appendChild(row);
    });
  } catch (e) { listEl.innerHTML = '<span class="text-muted">Approved list error</span>'; }
}

async function raUsblockRemoveApproved(vidPid) {
  const deviceId = selectedDeviceId;
  if (!deviceId || !vidPid) return;
  if (!confirm('Remove approval for ' + vidPid + '?\n\nIts allow rule will be dropped immediately and it will be blocked again when plugged in. This cannot be undone (re-approve by plugging it in and clicking Approve).')) return;
  const statusEl = document.getElementById('ra-usblock-approved-status');
  const listEl = document.getElementById('ra-usblock-approved-list');
  if (statusEl) statusEl.textContent = 'Removing ' + vidPid + '…';
  try {
    const r = await fetch(`/api/devices/${deviceId}/remote-assist/usblock/remove`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ vidPid }),
    });
    const data = await r.json().catch(() => ({}));
    if (data && data.ok) {
      if (statusEl) { statusEl.textContent = 'Approval removed'; statusEl.classList.remove('text-danger'); statusEl.classList.add('text-success'); }
      raUsblockLoadApproved();
      raUsblockLoadHistory();
      raUsblockLoadStatus();
    } else {
      const msg = (data && data.error) ? data.error : ('HTTP ' + r.status);
      if (statusEl) { statusEl.textContent = 'Remove failed: ' + msg; statusEl.classList.remove('text-success'); statusEl.classList.add('text-danger'); }
    }
  } catch (e) {
    if (statusEl) { statusEl.textContent = 'Remove error: ' + e.message; statusEl.classList.remove('text-success'); statusEl.classList.add('text-danger'); }
  }
}

async function raUsblockLoadHistory() {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  const listEl = document.getElementById('ra-usblock-history-list');
  if (!listEl) return;
  try {
    const r = await fetch(`/api/devices/${deviceId}/remote-assist/usblock/history`);
    if (!r.ok) { listEl.innerHTML = '<span class="text-muted">History unavailable (HTTP ' + r.status + ')</span>'; return; }
    const data = await r.json();
    if (!data.ok) { listEl.innerHTML = '<span class="text-muted">History unavailable</span>'; return; }
    const approvals = data.approvals || [];
    if (!approvals.length) { listEl.innerHTML = '<span class="text-muted">No approvals recorded yet</span>'; return; }
    listEl.innerHTML = '';
    approvals.forEach(a => {
      const row = document.createElement('div');
      row.className = 'd-flex align-items-center justify-content-between py-1 border-bottom border-secondary';
      row.style.fontSize = '0.72rem';
      const nameSpan = document.createElement('span');
      nameSpan.innerHTML = '<strong>' + (a.friendly_name || 'Unknown device').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;') + '</strong>';
      const right = document.createElement('span');
      right.className = 'text-muted';
      right.style.cssText = 'font-family:monospace;font-size:0.65rem';
      right.textContent = (a.instance_id || '').slice(0, 50) + ' · ' + (a.approved_at ? new Date(a.approved_at).toLocaleString() : '');
      row.appendChild(nameSpan);
      row.appendChild(right);
      listEl.appendChild(row);
    });
  } catch (e) { listEl.innerHTML = '<span class="text-muted">History error</span>'; }
}

async function raUsblockLoadStatus() {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  try {
    const r = await fetch(`/api/devices/${deviceId}/remote-assist/usblock/status`, { method: 'POST', body: '{}' });
    if (!r.ok) { raUsblockShowError('Status HTTP ' + r.status); return; }
    const data = await r.json();
    raUsblockUpdateUI(data);
  } catch (e) { raUsblockShowError('Status error: ' + e.message); }
}

function raUsblockUpdateUI(data) {
  const enforceBtn = document.getElementById('ra-usblock-enforce-btn');
  const auditBtn = document.getElementById('ra-usblock-audit-btn');
  const disableBtn = document.getElementById('ra-usblock-disable-btn');
  const statusEl = document.getElementById('ra-usblock-status');
  const devicesDiv = document.getElementById('ra-usblock-devices');
  const deviceListEl = document.getElementById('ra-usblock-device-list');

  if (data && data.deploying) {
    enforceBtn.classList.add('d-none');
    auditBtn.classList.add('d-none');
    disableBtn.classList.remove('d-none');
    statusEl.textContent = 'Deploying… (waiting for background job to finish)';
    statusEl.classList.remove('text-success', 'text-warning', 'text-muted');
    statusEl.classList.add('text-info');
    return;
  }

  if (data && (data.devices || data.deviceCount > 0)) {
    const listEl = document.getElementById('ra-usblock-device-list');
    if (listEl) {
      const devices = data.devices || [];
      if (devices.length) {
        listEl.innerHTML = '';
        devices.forEach(d => {
          const row = document.createElement('div');
          row.className = 'd-flex align-items-center justify-content-between py-1 border-bottom border-secondary';
          row.style.fontSize = '0.8rem';
          const nameSpan = document.createElement('span');
          nameSpan.innerHTML = '<strong>' + (d.friendlyName || d.instanceId || '?').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;') + '</strong> <span class="text-muted">' + (d.class || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;') + '</span>';
          const idSpan = document.createElement('span');
          idSpan.className = 'text-muted';
          idSpan.style.cssText = 'font-family:monospace;font-size:0.7rem';
          idSpan.textContent = (d.instanceId || '').slice(0, 60);
          row.appendChild(nameSpan);
          row.appendChild(idSpan);
          listEl.appendChild(row);
        });
      } else {
        listEl.textContent = 'Loading\u2026';
      }
    }
  }

  if (!data || data.error || !data.ok || !data.mode) {
    // Not active
    enforceBtn.classList.remove('d-none');
    auditBtn.classList.remove('d-none');
    disableBtn.classList.add('d-none');
    statusEl.textContent = 'Not active';
    statusEl.classList.remove('text-success', 'text-warning');
    statusEl.classList.add('text-muted');
    devicesDiv?.classList.add('d-none');
    return;
  }

  enforceBtn.classList.add('d-none');
  auditBtn.classList.add('d-none');
  disableBtn.classList.remove('d-none');

  const mode = data.mode;
  const blocked = data.blocked;
  const count = data.deviceCount || 0;

  if (mode === 'Enforce') {
    statusEl.textContent = `Active — blocking (${count} devices allowed)`;
    statusEl.classList.remove('text-muted', 'text-warning');
    statusEl.classList.add('text-success');
  } else if (mode === 'Audit') {
    statusEl.textContent = `Audit only — not blocking (${count} devices tracked)`;
    statusEl.classList.remove('text-muted', 'text-success');
    statusEl.classList.add('text-warning');
  }

  if (data.blockedAt) {
    statusEl.title = `${mode} since ${new Date(data.blockedAt).toLocaleString()}`;
  }

  if (data.blockedCount > 0) {
    // Devices the policy still refuses right after a deploy — surface immediately instead of
    // leaving the user to discover a dead keyboard/mouse (the 2026-08-01 the test Windows host failure).
    statusEl.textContent += ` — ${data.blockedCount} device(s) still blocked (Refresh & Approve below)`;
    statusEl.classList.remove('text-success', 'text-warning');
    statusEl.classList.add('text-danger');
  }
  if (data.allowListOk === false) {
    statusEl.textContent += ' — allowlist integrity FAILED (REG_SZ name!=data)';
    statusEl.classList.remove('text-success', 'text-warning');
    statusEl.classList.add('text-danger');
  }

  devicesDiv?.classList.remove('d-none');
}

let _raUsblockApproveMeta = null;

async function raUsblockApprove() {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  const input = document.getElementById('ra-usblock-approve-input');
  const statusEl = document.getElementById('ra-usblock-approve-status');
  if (!input || !input.value.trim()) { if(statusEl) statusEl.textContent = 'Paste an instance ID first'; return; }
  const instanceId = input.value.trim();
  if (statusEl) { statusEl.textContent = 'Approving…'; statusEl.className = 'small text-info mt-1'; }
  try {
    const r = await fetch(`/api/devices/${deviceId}/remote-assist/usblock/approve`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ instanceId, friendlyName: (_raUsblockApproveMeta && _raUsblockApproveMeta.friendlyName) || null, deviceClass: (_raUsblockApproveMeta && _raUsblockApproveMeta.deviceClass) || null }),
    });
    const data = await r.json();
    if (data.ok) {
      if (statusEl) { statusEl.textContent = 'Approved — device added to allowlist and rescanned'; statusEl.className = 'small text-success mt-1'; }
      input.value = '';
      _raUsblockApproveMeta = null;
      raUsblockLoadStatus();
      raUsblockLoadHistory();
      raUsblockLoadApproved();
    } else {
      if (statusEl) { statusEl.textContent = 'Failed: ' + (data.error || 'unknown'); statusEl.className = 'small text-danger mt-1'; }
    }
  } catch (e) {
    if (statusEl) { statusEl.textContent = 'Error: ' + e.message; statusEl.className = 'small text-danger mt-1'; }
  }
}

// Linux-only: software replug for an approved device whose drivers never bound (USBGuard quirk —
// a drive plugged in while blocked never gets its block device created, even after approval).
async function raUsblockReprobe() {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  const input = document.getElementById('ra-usblock-approve-input');
  const statusEl = document.getElementById('ra-usblock-reprobe-status');
  if (!input || !input.value.trim()) { if(statusEl) statusEl.textContent = 'Paste the device ID first (or use Approve from the blocked list)'; return; }
  const instanceId = input.value.trim();
  if (statusEl) { statusEl.textContent = 'Re-enumerating…'; statusEl.className = 'small text-info mt-1'; }
  try {
    const r = await fetch(`/api/devices/${deviceId}/remote-assist/usblock/reprobe`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ instanceId }),
    });
    const data = await r.json();
    if (data.ok) {
      if (statusEl) {
        const statusText = data.status ? ` — usbguard status: ${data.status}` : '';
        statusEl.textContent = 'Re-enumerated — device replugged (via port ' + (data.viaPort || '?') + ')' + statusText + '. Check the file manager / Allowed list.';
        statusEl.className = 'small text-success mt-1';
      }
      raUsblockLoadStatus();
    } else {
      if (statusEl) { statusEl.textContent = 'Failed: ' + (data.error || 'unknown'); statusEl.className = 'small text-danger mt-1'; }
    }
  } catch (e) {
    if (statusEl) { statusEl.textContent = 'Error: ' + e.message; statusEl.className = 'small text-danger mt-1'; }
  }
}

async function raUsblockRefresh() {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  const statusEl = document.getElementById('ra-usblock-blocked-status');
  const listEl = document.getElementById('ra-usblock-blocked-list');
  if (statusEl) { statusEl.textContent = 'Scanning…'; }
  try {
    const r = await fetch(`/api/devices/${deviceId}/remote-assist/usblock/blocked`, { method: 'POST', body: '{}' });
    const data = await r.json();
    if (data.ok && data.devices) {
      if (statusEl) { statusEl.textContent = data.devices.length ? `${data.devices.length} blocked device(s) found` : 'No blocked devices found'; }
      if (listEl) {
        if (data.devices.length) {
          listEl.classList.remove('d-none');
          listEl.innerHTML = '';
          data.devices.forEach(d => {
            const row = document.createElement('div');
            row.className = 'd-flex align-items-center justify-content-between py-1 border-bottom border-secondary';
            row.style.fontSize = '0.78rem';
            const info = document.createElement('span');
            info.innerHTML = '<strong>' + (d.friendlyName || d.instanceId || '?').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;') + '</strong> <span class="text-danger">' + (d.problem || '') + '</span>';
            const btnWrap = document.createElement('span');
            const btn = document.createElement('button');
            btn.className = 'btn btn-sm btn-outline-success py-0 px-1';
            btn.style.fontSize = '0.7rem';
            btn.textContent = 'Approve';
            btn.onclick = function() {
              document.getElementById('ra-usblock-approve-input').value = d.instanceId;
              _raUsblockApproveMeta = { friendlyName: d.friendlyName || null, deviceClass: d.class || null };
              raUsblockApprove();
            };
            btnWrap.appendChild(btn);
            row.appendChild(info);
            row.appendChild(btnWrap);
            listEl.appendChild(row);
          });
        } else {
          listEl.classList.add('d-none');
        }
      }
    } else {
      if (statusEl) { statusEl.textContent = 'Failed: ' + (data.error || 'unknown'); }
    }
  } catch (e) {
    if (statusEl) { statusEl.textContent = 'Error: ' + e.message; }
  }
}

// ── User Lockdown — per-device system tool restrictions ────────────────────────
async function raLockdownApply() {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  const status = document.getElementById('ra-lockdown-status');
  if (status) { status.textContent = 'Locking down...'; status.className = 'small text-info'; }
  const script = `$ErrorActionPreference = 'Stop'
$raDir = 'C:\\ProgramData\\SentinelRemoteAssist'
New-Item -ItemType Directory -Force -Path $raDir | Out-Null
$kill = "$raDir\\sentinel_lockdown_kill.ps1"
$flag = "$raDir\\sentinel_lockdown_stop.flag"
Remove-Item $flag -Force -ErrorAction SilentlyContinue
$loop = @'
$flag = 'C:\\ProgramData\\SentinelRemoteAssist\\sentinel_lockdown_stop.flag'
while (-not (Test-Path $flag)) {
  taskkill /F /IM regedit.exe /T | Out-Null
  taskkill /F /IM cmd.exe /T | Out-Null
  taskkill /F /IM mmc.exe /T | Out-Null
  taskkill /F /IM schtasks.exe /T | Out-Null
  Start-Sleep -Milliseconds 800
}
Remove-Item $flag -Force -ErrorAction SilentlyContinue
'@
Set-Content -Path $kill -Value $loop -Encoding ASCII
if (-not (Test-Path $kill)) { throw "Failed to write $kill" }
Unregister-ScheduledTask -TaskName 'SentinelLockdownWatch' -Confirm:$false -ErrorAction SilentlyContinue
$action = New-ScheduledTaskAction -Execute 'powershell.exe' -Argument "-NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File $kill"
$tOnce = New-ScheduledTaskTrigger -Once -At (Get-Date)
$tStart = New-ScheduledTaskTrigger -AtStartup
$trigger = @($tOnce, $tStart)
$settings = New-ScheduledTaskSettingsSet -MultipleInstances IgnoreNew -ExecutionTimeLimit ([TimeSpan]::Zero)
$principal = New-ScheduledTaskPrincipal -UserId 'SYSTEM' -LogonType ServiceAccount -RunLevel Highest
Register-ScheduledTask -TaskName 'SentinelLockdownWatch' -Action $action -Trigger $trigger -Settings $settings -Principal $principal -Force | Out-Null
Start-ScheduledTask -TaskName 'SentinelLockdownWatch'
$loopAlive = $false
$t = $null
for ($i = 0; $i -lt 6 -and -not $loopAlive; $i++) {
  Start-Sleep -Seconds 1
  $t = Get-ScheduledTask -TaskName 'SentinelLockdownWatch' -ErrorAction SilentlyContinue
  $loopAlive = [bool](Get-CimInstance Win32_Process -Filter "Name='powershell.exe'" -ErrorAction SilentlyContinue | Where-Object { $_.CommandLine -like '*sentinel_lockdown_kill*' })
}
if (-not $t -or $t.State -ne 'Running' -or -not $loopAlive) { throw 'Lockdown task registered but the kill loop is not running — lockdown NOT active (badge will say Unlocked)' }
$sysKey = 'HKLM:\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System'
$backupPath = "$raDir\\lockdown-uac-backup.json"
$uac = Get-ItemProperty -Path $sysKey
$backup = @{ ConsentPromptBehaviorAdmin = $uac.ConsentPromptBehaviorAdmin; PromptOnSecureDesktop = $uac.PromptOnSecureDesktop } | ConvertTo-Json
Set-Content -Path $backupPath -Value $backup -Encoding ASCII
Set-ItemProperty -Path $sysKey -Name 'ConsentPromptBehaviorAdmin' -Value 1 -Type DWord -Force
Set-ItemProperty -Path $sysKey -Name 'PromptOnSecureDesktop' -Value 1 -Type DWord -Force
New-Item -ItemType Directory -Force -Path 'HKLM:\\SOFTWARE\\Microsoft\\Windows Script Host\\Settings' | Out-Null
Set-ItemProperty -Path 'HKLM:\\SOFTWARE\\Microsoft\\Windows Script Host\\Settings' -Name 'Enabled' -Value 0 -Type DWord -Force
Write-Output 'LOCKDOWN_APPLIED'`;
  try {
    const r = await fetch(`/api/devices/${deviceId}/remote-assist/powershell`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ script }),
    });
    const data = await r.json();
    if (status) { status.textContent = data.ok ? 'Locked down' : 'Failed: ' + (data.error || 'unknown'); status.className = data.ok ? 'small text-success' : 'small text-danger'; }
    if (data.ok) { const badge = document.getElementById('ra-lockdown-state'); if (badge) { badge.textContent = 'Locked Down'; badge.className = 'badge bg-danger'; } }
  } catch (e) { if (status) { status.textContent = 'Error: ' + e.message; status.className = 'small text-danger'; } }
}

async function raLockdownRemove() {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  const status = document.getElementById('ra-lockdown-status');
  if (status) { status.textContent = 'Restoring...'; status.className = 'small text-info'; }
  const script = `$raDir = 'C:\\ProgramData\\SentinelRemoteAssist'
$sysKey = 'HKLM:\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System'
Set-Content -Path "$raDir\\sentinel_lockdown_stop.flag" -Value 'stop' -Encoding ASCII
Start-Sleep -Seconds 2
Stop-ScheduledTask -TaskName 'SentinelLockdownWatch' -ErrorAction SilentlyContinue
Get-CimInstance Win32_Process -Filter "Name='powershell.exe'" -ErrorAction SilentlyContinue | Where-Object { $_.CommandLine -like '*sentinel_lockdown_kill*' } | ForEach-Object { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue }
$stillThere = Get-ScheduledTask -TaskName 'SentinelLockdownWatch' -ErrorAction SilentlyContinue
if ($stillThere) { Unregister-ScheduledTask -TaskName 'SentinelLockdownWatch' -Confirm:$false -ErrorAction Stop }
Remove-Item "$raDir\\sentinel_lockdown_kill.ps1" -Force -ErrorAction SilentlyContinue
Remove-Item "$raDir\\sentinel_lockdown_stop.flag" -Force -ErrorAction SilentlyContinue
$backupPath = "$raDir\\lockdown-uac-backup.json"
$uacVal = 5
if (Test-Path $backupPath) {
  $bk = Get-Content $backupPath -Raw | ConvertFrom-Json
  $saved = $bk.ConsentPromptBehaviorAdmin
  if ($saved -in 0,2,4,5) { $uacVal = $saved }
  Remove-Item $backupPath -Force -ErrorAction SilentlyContinue
}
Set-ItemProperty -Path $sysKey -Name 'ConsentPromptBehaviorAdmin' -Value $uacVal -Type DWord -Force
Remove-ItemProperty -Path 'HKLM:\\SOFTWARE\\Microsoft\\Windows Script Host\\Settings' -Name 'Enabled' -ErrorAction SilentlyContinue
$stillThere2 = Get-ScheduledTask -TaskName 'SentinelLockdownWatch' -ErrorAction SilentlyContinue
if ($stillThere2) { throw 'SentinelLockdownWatch could not be unregistered — the PC may still be locked down' }
Write-Output 'UNLOCKED'`;
  try {
    const r = await fetch(`/api/devices/${deviceId}/remote-assist/powershell`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ script }),
    });
    const data = await r.json();
    if (status) { status.textContent = data.ok ? 'Restored' : 'Failed: ' + (data.error || 'unknown'); status.className = data.ok ? 'small text-success' : 'small text-danger'; }
    if (data.ok) { const badge = document.getElementById('ra-lockdown-state'); if (badge) { badge.textContent = 'Unlocked'; badge.className = 'badge bg-success'; } }
  } catch (e) { if (status) { status.textContent = 'Error: ' + e.message; status.className = 'small text-danger'; } }
}

