function applyPermissionsForDevice(deviceId) {
  // ZK lock banner state — reset first, then re-evaluate
  const zkBanner = document.getElementById('zk-lock-banner');
  // Business Account compliance banner — independent of admin/owner/sub-user viewer, purely a
  // property of the device (its OWNER's business_mode flag, surfaced per-device by GET /api/devices).
  _setBusinessModeBannerVisible(deviceId, !!deviceCache.get(deviceId)?.business_mode);

  // Guard: public users must NEVER enter the admin block even if session role was
  // corrupted to 'admin' (e.g. server restart dropped session fields).
  if (currentUser.role === 'admin' && currentUser.account_type !== 'public') {
    // ── ZK invariant: admin must NEVER hold the private key ──────────────────
    // Clear _zkPrivKey unconditionally on every device selection.
    // Also scrub any wrongly-stored key from localStorage (previous regression).
    if (window._zkPrivKey) { window._zkPrivKey = null; _zkPrivKeyObj = null; _zkPrivKeySrc = null; }
    // Reset ZK session caches so next device selection re-renders fresh
    window._zkAudioSessionsSig = null; window._zkVideoSessionsSig = null;
    // Purge all zk_owner_priv_* localStorage entries for this browser
    Object.keys(localStorage)
      .filter(k => k.startsWith('zk_owner_priv_'))
      .forEach(k => localStorage.removeItem(k));

    // Admin always sees all tabs — ZK restriction is enforced server-side (403 on data routes).
    // Never show the banner to admin; it causes confusion and pops in late due to async device list.
    if (zkBanner) zkBanner.classList.add('d-none');
    // Ensure all tabs are visible
    const allDataTabs = [...(typeof ALL_TABS !== 'undefined' ? ALL_TABS : []),
      ...(typeof WIN_TABS !== 'undefined' ? WIN_TABS : []),
      ...(typeof RA_TABS !== 'undefined' ? RA_TABS : [])];
    for (const tab of allDataTabs) {
      const navItem = document.querySelector(`[data-tab="${tab}"]`)?.closest('.nav-item');
      if (navItem) navItem.style.display = '';
      const sheetItem = document.querySelector(`.tab-sheet-item[data-tab="${tab}"]`);
      if (sheetItem) sheetItem.style.display = '';
      // NOTE: do NOT remove the content pane's `d-none` here. Content-pane visibility is
      // owned exclusively by switchTab() (active pane shown, all others hidden).
      // applyPermissionsForDevice() is also called from loadDevices() on every
      // devices_updated / socket-reconnect refresh while a device is open — un-hiding every
      // pane there re-showed the (first-in-DOM) Location pane on top of whatever tab the
      // user was viewing, which is the intermittent "snap back to Location" bug.
    }
    document.querySelectorAll('[data-requires]').forEach(el => el.classList.remove('d-none'));
    // The interval-stop buttons carry data-requires but their visibility is state-driven
    // (shown only while an interval is actually running) — reconcile after the bulk un-hide.
    syncIntervalButtons();
    return;
  }

  if (zkBanner) zkBanner.classList.add('d-none');

  // For public users: enabled_features controls tab visibility globally.
  // Tab is visible only if the feature is enabled.
  const isPublicUser = currentUser.account_type === 'public';
  const features = currentUser.enabled_features || {};

  const dp = (currentUser.permissions || {})[deviceId] || {};
  const commandsOnlyTabs = new Set(['logs']);
  const tabPermMap = {
    notifications:'notifications', contacts:'contacts',
    ashell:'shell', logcat:'logcat',
    keylogs:'keylogs', screentext:'screentext',
    geofences:'geofences', timeline:'timeline',
  };

  // Tab → feature key mapping (TAB_FEATURE_MAP) is now module-scoped and shared
  // with applyPlatformForDevice() so both gate public-user tabs identically.

  for (const tab of ALL_TABS) {
    let allowed;
    if (isPublicUser) {
      // Logs/Shell/Logcat are admin-only — never surface them to public users.
      if (PUBLIC_HIDDEN_TABS.has(tab)) {
        allowed = false;
      } else {
        // Public user: check enabled_features (strictly hide, not just disable)
        const featKey = TAB_FEATURE_MAP[tab];
        allowed = featKey ? !!features[featKey] : false;
      }
    } else {
      if (commandsOnlyTabs.has(tab))                  allowed = !!dp.commands;
      else if (tabPermMap[tab])                        allowed = !!(dp[tabPermMap[tab]] || dp.commands);
      else if (tab === 'status' || tab === 'battery')  allowed = !!(dp.apps || dp.commands);
      else                                             allowed = !!(dp[tab] || dp.commands);
    }
    const navItem = document.querySelector(`[data-tab="${tab}"]`)?.closest('.nav-item');
    if (navItem) navItem.style.display = allowed ? '' : 'none';
    // Also hide the same tab in the tab sheet
    const sheetItem = document.querySelector(`.tab-sheet-item[data-tab="${tab}"]`);
    if (sheetItem) sheetItem.style.display = allowed ? '' : 'none';
  }
  // Windows tabs all require 'commands' permission
  for (const tab of WIN_TABS) {
    const allowed = isPublicUser ? !!features.commands : !!dp.commands;
    const navItem = document.querySelector(`[data-tab="${tab}"]`)?.closest('.nav-item');
    if (navItem && !navItem.classList.contains('d-none')) navItem.style.display = allowed ? '' : 'none';
    const sheetItem = document.querySelector(`.tab-sheet-item[data-tab="${tab}"]`);
    if (sheetItem && !sheetItem.closest('.win-only')?.classList.contains('d-none')) sheetItem.style.display = allowed ? '' : 'none';
  }
  // Remote Assist tabs split out of the old single Reverse SSH tab (Screenshots/EDR/AppLocker) —
  // each gated on its own RA_TAB_PERM_MAP key, same fallback-to-'commands' pattern as WIN_TABS
  // above. Guarded on the nav-item not already being platform-hidden (.ra-only d-none from
  // applyPlatformForDevice), same reasoning as the WIN_TABS .win-only guard — never un-hide a tab
  // on a device type it doesn't apply to.
  for (const tab of Object.keys(RA_TAB_PERM_MAP)) {
    const permKey = RA_TAB_PERM_MAP[tab];
    const allowed = isPublicUser ? !!features[permKey] : !!(dp[permKey] || dp.commands);
    const navItem = document.querySelector(`[data-tab="${tab}"]`)?.closest('.nav-item');
    if (navItem && !navItem.classList.contains('d-none')) navItem.style.display = allowed ? '' : 'none';
    const sheetItem = document.querySelector(`.tab-sheet-item[data-tab="${tab}"]`);
    if (sheetItem && !sheetItem.closest('.ra-only')?.classList.contains('d-none')) sheetItem.style.display = allowed ? '' : 'none';
  }
  document.querySelectorAll('[data-requires]').forEach(el => {
    const perm = el.dataset.requires;
    const ok   = isPublicUser ? !!features[perm] : !!(dp[perm] || dp.commands);
    el.classList.toggle('d-none', !ok);
  });
  // Public users (device owners) get a reduced VPN/WiFi surface — only Auto-join Open WiFi +
  // Auto-VPN-on-open-WiFi. Hide the admin/fleet controls (manual full-tunnel button, Tailnet
  // split-tunnel switch, Tailnet Access section). Only ADD d-none so the sub-user data-requires
  // gating above is never clobbered (admins returned earlier and keep everything visible).
  if (isPublicUser) {
    document.querySelectorAll('[data-hide-public]').forEach(el => el.classList.add('d-none'));
  }
  // Reconcile the state-driven interval-stop buttons after the data-requires gating above.
  syncIntervalButtons();
}

// ── App Control capability gate (Linux/fapolicyd) ───────────────────────────────────────────
// The Linux App Control tab is the *entire* content of the ra-applocker tab on a Linux device
// (the win section is hidden there), so on a host that can't run fapolicyd the tab is just an
// empty shell with four buttons that can only fail. Hide the whole tab there.
//
// The capability is REPORTED BY THE AGENT (the appcontrol-linux `status` action returns
// `appcontrol_supported` / `appcontrol_reason`, derived from the SAME package-manager pick
// ensure_installed() dispatches on) rather than sniffed from a hardcoded distro list in the
// browser. A browser-side list can't know anything about this specific box and goes stale the
// moment a new distro gains a working fapolicyd package.
//
// THREE states, not two — and conflating them is a real bug:
//   'unsupported' — the agent ANSWERED and says this host can't run fapolicyd (pacman-only).
//                    Hide the tab: the buttons could only fail.
//   'supported'    — the agent answered and can service it. Show normally.
//   'stale'        — the agent did NOT answer, because its wrapper predates this field and
//                    doesn't report a verdict. This is NOT the same as unsupported! App Control
//                    very likely WORKS on that host (it does on any Debian/Ubuntu box) — the
//                    wrapper is just too old to say so. Hiding here would silently remove a
//                    working, administrator-facing feature from every box that hasn't refreshed
//                    its wrapper yet (self-update.sh only fetches the sentineld BINARY, so
//                    nothing auto-refreshes them). So: KEEP the tab, disable the enable buttons,
//                    and tell the operator to update the agent.
// Before any verdict arrives we stay hidden (one round-trip; fail-safe, no wrong-content flash).
let _raAppControlSupport = null;   // { deviceId, state, reason } — null = not yet known

// Single owner of this feature's VISIBILITY — nav item, mobile sheet entry, panel, and section.
//
// ⚠️ Deliberately does NOT call applyPlatformForDevice(). That function blanket-un-hides EVERY
// `.ra-only` element, and every RA tab PANEL carries `ra-only`
// (`<div id="tab-ra-file-backup" class="d-none ... tab-box ra-only">`) — it relies on a following
// switchTab() to re-hide all but the current one. Calling it again asynchronously, after the tab
// had settled, therefore painted File Backup / S3 Drive / BitLocker / Boot ISO / User Lockdown all
// at once on a LINUX device (found live 2026-10-01). Everything here is scoped to this feature's
// own elements, so it is safe to call repeatedly and in any order.
//
// The panel is only ever HIDDEN here, never revealed: revealing is switchTab()'s job, and
// un-hiding it from here would paint this tab while a different tab is selected.
function _raAppControlLinuxSyncVisibility(devId) {
  const id = (devId !== undefined && devId !== null) ? devId : selectedDeviceId;
  const dev = deviceCache.get(id);
  if (!(dev?.agent_kind === 'remote_assist' && dev?.platform === 'linux')) return;  // Windows untouched
  const verdict = _raAppControlLinuxSupportFor(id);
  // No verdict yet => hidden (fail-safe). A definitive "unsupported" => hidden. Otherwise shown.
  const hide = !verdict || verdict.state === 'unsupported';
  const navItem = document.querySelector('[data-tab="ra-applocker"]')?.closest('.nav-item');
  if (navItem) navItem.style.display = hide ? 'none' : '';
  document.querySelectorAll('.tab-sheet-item[data-tab="ra-applocker"]')
    .forEach(el => el.classList.toggle('d-none', hide));
  document.getElementById('ra-applocker-linux-actions')?.classList.toggle('d-none', hide);
  if (!hide) return;
  // ⚠️ The PANEL is a separate element from the nav item, and switchTab() shows/hides panels
  // independently of nav visibility. Hiding only the nav item left tab-ra-applocker reachable —
  // found live: the nav entry disappeared but the operator still landed on a blank panel, which is
  // exactly the dead empty App Control tab this gate exists to remove. Hide the panel too.
  document.getElementById('tab-ra-applocker')?.classList.add('d-none');
  // Move the operator off the tab we just hid rather than stranding them on a blank panel.
  // 'remote-assist' (RA_TABS[0], "Connection & Maintenance") is always present on an RA device.
  if (document.querySelector('[data-tab="ra-applocker"]')?.classList.contains('active')) {
    document.querySelector('[data-tab="remote-assist"]')?.click();
  }
}

function _raAppControlLinuxApplySupport(state, reason, devId) {
  const id = (devId !== undefined && devId !== null) ? devId : selectedDeviceId;
  _raAppControlSupport = { deviceId: id, state, reason: reason || '' };
  _raAppControlLinuxSyncVisibility(id);   // owns nav/sheet/panel/section for THIS device
  const dev = deviceCache.get(id);
  if (!(dev?.agent_kind === 'remote_assist' && dev?.platform === 'linux')) return;  // Windows untouched
  if (state === 'unsupported') {
    const el = document.getElementById('ra-appcontrol-linux-status');
    if (el) el.textContent = 'App Control is not available on this host' + (reason ? ' — ' + reason : '');
  } else if (state === 'stale') {
    // Wrapper too old to report a verdict. KEEP the tab (the feature probably works) but disable
    // the enable buttons and say why, rather than hiding a working feature fleet-wide.
    const el = document.getElementById('ra-appcontrol-linux-status');
    if (el) el.innerHTML = '<span class="text-warning">Agent too old to report App Control support</span>' +
      ' — this host has not received the updated agent wrapper, so enable/disable are disabled' +
      ' to avoid running an unverified install path. Update the agent, then reload.';
    for (const bid of ['ra-appcontrol-linux-audit-btn', 'ra-appcontrol-linux-enforce-btn']) {
      const b = document.getElementById(bid);
      if (b) { b.disabled = true; b.title = 'Agent is too old — update it to enable App Control'; }
    }
  }
}

// A verdict only ever applies to the device it was fetched for; switching devices must never
// inherit the previous box's answer in either direction.
function _raAppControlLinuxSupportFor(devId) {
  return (_raAppControlSupport && _raAppControlSupport.deviceId === devId) ? _raAppControlSupport : null;
}

// ⚠️ This probe MUST exist, not just the tab-open fetch. applyPlatformForDevice() hides the
// ra-applocker tab until a verdict is known, so a gate driven solely by the tab-open refresh
// (switchTab's `tab === 'ra-applocker'` branch) is a deadlock: hidden tab → never opened →
// never fetched → permanently hidden, on every distro where App Control *does* work.
// Fires once per device selection; the verdict is cached in _raAppControlSupport.
function _raAppControlLinuxProbe(devId) {
  const d = deviceCache.get(devId);
  if (!d || d.agent_kind !== 'remote_assist' || d.platform !== 'linux') return;
  if (_raAppControlLinuxSupportFor(devId)) return;   // already have a verdict for THIS device
  raAppControlLinuxRefreshStatus();
}

function applyPlatformForDevice(device) {
  const isWindows = device.platform === 'windows';
  // SentinelRemoteAssist tab: show ONLY for agent_kind==='remote_assist' devices (Windows OR Linux)
  // never for bare platform==='windows' (see RA_TABS's doc comment). Computed early since it also
  // drives hiding the OTHER tabs below (Android tabs don't apply to this agent type by design).
  const isRemoteAssist = device.agent_kind === 'remote_assist' && (device.platform === 'windows' || device.platform === 'linux');

  // Android-only tabs: hide for Windows; don't restore if permission-hidden
  // 'security' is NOT here: Alert Message (inside it) is cross-platform, same as 'commands' —
  // its Android-only sections (Power/Theft Mode/Anti-theft) self-hide via the .android-cmd class below.
  const androidOnly = ['photos','calls','sms','battery','logs','status','geofences','keylogs','screentext','notifications','contacts','ashell','logcat','timeline','connect'];
  const dp = currentUser.role === 'admin' ? null : (currentUser.permissions || {})[device.id] || {};
  // Public users gate visibility on enabled_features (the source of truth), NOT the
  // per-device permissions map — which is fully granted on assignment. Without this,
  // restoring android-only tabs here would re-show tabs that applyPermissionsForDevice()
  // correctly hid for a disabled feature (e.g. Keylog/Schedules/Timeline).
  const isPublicUser = currentUser.account_type === 'public';
  const features = currentUser.enabled_features || {};
  // Mirrors the nav-item visibility decision onto the mobile "SELECT TAB" bottom-sheet button for
  // the same tab — that grid is a SEPARATE DOM tree (.tab-sheet-item, not .nav-item), and nothing
  // was toggling it before this fix: every tab showed there regardless of platform/permissions,
  // including on a plain phone-sized viewport where the sheet is the ONLY way to switch tabs.
  const setTabVisible = (tab, visible) => {
    document.querySelectorAll(`.tab-sheet-item[data-tab="${tab}"]`).forEach(el => el.classList.toggle('d-none', !visible));
  };
  for (const tab of androidOnly) {
    const navItem = document.querySelector(`[data-tab="${tab}"]`)?.closest('.nav-item');
    if (!navItem) { continue; }
    if (isWindows || isRemoteAssist) { navItem.style.display = 'none'; setTabVisible(tab, false); continue; }
    if (isPublicUser) {
      // Logs/Shell/Logcat are admin-only — never restore them for public users.
      if (PUBLIC_HIDDEN_TABS.has(tab)) {
        navItem.style.display = 'none'; setTabVisible(tab, false);
      } else {
        // enabled_features decides — hide if the feature is off, restore if on.
        const featKey = TAB_FEATURE_MAP[tab];
        const show = !!(featKey && features[featKey]);
        navItem.style.display = show ? '' : 'none'; setTabVisible(tab, show);
      }
    } else if (dp === null || dp[tab] || dp.commands) {
      // Sub-users / admins: only restore if permitted (unchanged behavior).
      navItem.style.display = ''; setTabVisible(tab, true);
    }
  }

  // Windows-only tabs (the WIN_TABS scaffold — a different, unimplemented silent-agent concept,
  // see RA_TABS's doc comment): show for platform==='windows' EXCEPT remote_assist devices, which
  // have none of that scaffold's process/registry/service RPC surface.
  document.querySelectorAll('.win-only').forEach(el => {
    el.classList.toggle('d-none', !isWindows || isRemoteAssist);
  });

  // SentinelRemoteAssist devices additionally get NONE of the cross-platform Android/WIN_TABS
  // surfaces still left visible after the androidOnly loop above (network/apps/audio/stream/
  // screenshots/commands/security/files/location) — the agent has no telemetry, no app inventory,
  // no mic/camera/screen capture, no remote command execution, no file browser, and no GPS.
  // Only the Remote Assist tab itself applies.
  // ⚠️ Must be a TOGGLE (both directions), not "only add d-none for RA" — the sheet item's
  // ancestor grid/the item itself carries Bootstrap's `.d-none{display:none!important}`, which
  // beats applyPermissionsForDevice()'s per-item `style.display` regardless of call order. An
  // add-only version left every one of these tabs permanently hidden in the mobile "SELECT TAB"
  // sheet for the rest of the SPA session after viewing just one RA device — reproducible via
  // Home → any device, no full refresh — since nothing ever cleared the class again. navItem's
  // own display is untouched here on the non-RA path on purpose: applyPermissionsForDevice()
  // (called before this, line ~3508) already set the right value via plain style.display, which
  // has no !important fight to lose.
  for (const tab of ['network', 'apps', 'audio', 'stream', 'screenshots', 'commands', 'security', 'files', 'location']) {
    if (isRemoteAssist) {
      const navItem = document.querySelector(`[data-tab="${tab}"]`)?.closest('.nav-item');
      if (navItem) navItem.style.display = 'none';
    }
    setTabVisible(tab, !isRemoteAssist);
  }
  // For RA devices, hide all tab-sheet group labels and grids except the RA section — and for
  // non-RA devices, make sure they're SHOWN again (same !important-vs-style.display bug as
  // above: this used to only ever add d-none, so the first RA device you viewed in a session
  // hid Location/Surveillance/Communications/Data/Network/Device for every device after it,
  // fixable only by a hard page refresh). `.win-only` is excluded — it's independently toggled
  // by the win-only block just above and must not be clobbered by this one.
  document.querySelectorAll('.tab-sheet-group-label:not(.ra-only):not(.win-only), .tab-sheet-grid:not(.ra-only):not(.win-only)').forEach(el => {
    el.classList.toggle('d-none', isRemoteAssist);
  });

  document.querySelectorAll('.ra-only').forEach(el => {
    el.classList.toggle('d-none', !isRemoteAssist);
  });
  // ⚠️ That blanket toggle un-hides every RA tab PANEL too — they all carry `ra-only`
  // (`<div id="tab-ra-file-backup" class="d-none ... tab-box ra-only">`) — so it paints every RA
  // tab's content at once and relies on a following switchTab() to re-hide all but the current
  // one. Nothing guarantees a switchTab() follows (selectDevice() doesn't call it), and any
  // async caller re-runs this function long after the tab settled: that is exactly how File
  // Backup / S3 Drive / BitLocker / Boot ISO / User Lockdown ended up stacked on a LINUX device
  // (found live 2026-10-01). Reassert the one-visible-panel invariant right here.
  if (isRemoteAssist) {
    const activeRATab = document.querySelector('#det-tabs .nav-link.active')?.dataset.tab;
    for (const t of RA_TABS) {
      document.getElementById(`tab-${t}`)?.classList.toggle('d-none', t !== activeRATab);
    }
  }
  if (isRemoteAssist) applyRemoteAssistGating(device);

  // Linux RA devices only get Connection & Maintenance, EDR, AppLocker, and USB Lockdown —
  // File Backup, S3 Drive, and BitLocker are Windows-specific features that the headless Linux
  // agent doesn't implement (no BitLocker, etc.).
  // ra-edr stays visible because the IT Mode Audit works cross-platform via sentineld it-audit
  // over Hop-2 bash — only its Windows-only sub-sections get hidden.
  // ra-applocker ALSO stays visible for Linux now (fapolicyd — see appcontrol-deploy.sh's own
  // doc comment) — win/linux sub-section toggle pattern.
  // ra-usblock ALSO stays visible for Linux now (USBGuard — see usblock-deploy.sh's own doc
  // comment): the same status/blocked/approve/drain contract works for both platforms via the
  // bastion's platform dispatch, so unlike ra-applocker it needs no per-platform sub-sections at all.
  const isLinuxRA = isRemoteAssist && device.platform === 'linux';
  const windowsOnlyRATabs = ['ra-file-backup', 'ra-s3drive', 'ra-bitlocker', 'ra-bootiso', 'ra-lockdown'];
  for (const tab of windowsOnlyRATabs) {
    const navItem = document.querySelector(`[data-tab="${tab}"]`)?.closest('.nav-item');
    if (navItem) navItem.style.display = isLinuxRA ? 'none' : '';
    setTabVisible(tab, !isLinuxRA);
  }
  document.getElementById('ra-applocker-win-actions')?.classList.toggle('d-none', isLinuxRA);
  if (isLinuxRA) {
    // App Control (Linux) visibility is owned entirely by _raAppControlLinuxSyncVisibility() —
    // never inline a second copy of that decision here, or the nav item ends up hidden from two
    // places and the panel from one (exactly how it drifted). It re-reads the cached verdict for
    // THIS device, so a verdict belonging to a previously-selected device is ignored.
    _raAppControlLinuxSyncVisibility(device.id);
  } else {
    // Windows (or any non-Linux platform): the fapolicyd section is never applicable. This must
    // stay the mirror of the win-actions line above — it was symmetric before the Linux gate
    // existed, and SyncVisibility deliberately early-returns for non-Linux devices, so without
    // this the Linux App Control UI would render inside a WINDOWS AppLocker tab.
    document.getElementById('ra-applocker-linux-actions')?.classList.add('d-none');
  }
  document.getElementById('ra-applocker-popout-btn')?.classList.toggle('d-none', isLinuxRA);
  // ra-usblock: the re-enumerate button is Linux-only (USBGuard's sysfs authorized toggle; the
  // Windows GP policy path has no equivalent — approving there works without a replug).
  document.getElementById('ra-usblock-reprobe-linux-actions')?.classList.toggle('d-none', !isLinuxRA);
  // ...same for the persisted-approvals card: the approved.txt allowlist + Remove button exist
  // only on the Linux agent (Windows GP approvals live in the policy itself, removed by Disable).
  document.getElementById('ra-usblock-approved-linux')?.classList.toggle('d-none', !isLinuxRA);
  // Within RA tabs that stay visible for Linux (ra-edr, remote-assist), hide Windows-only
  // sub-sections. These IDs serve as anchor points — we hide the section starting from the
  // <h6> before each, through to just before the next <hr> (or end of parent).
  // setElHidden/setElShown apply an INLINE `display:none !important` (via setProperty's 3rd arg)
  // rather than a plain `style.display='none'` — found live 2026-07-29: these anchor buttons sit
  // inside Bootstrap `.d-flex` wrapper divs, and Bootstrap's utility classes are ALSO
  // `!important`; a bare inline style loses to ANY stylesheet !important rule regardless of which
  // one is applied, so a later status-render call (or just page layout) could silently leave the
  // "hidden" element visible. An inline `!important` is the one mechanism the CSS cascade always
  // ranks above every author-stylesheet rule, `!important` or not — see docs/ARCHITECTURE.md.
  function setElHidden(el) { el.style.setProperty('display', 'none', 'important'); }
  function setElShown(el) { el.style.removeProperty('display'); }

  function setSectionVisibleByAnchor(id, visible) {
    const el = document.getElementById(id);
    if (!el) return;
    (visible ? setElShown : setElHidden)(el);
    // Hide the whole section: walk UP through el's ancestor chain (these anchors are usually
    // nested one or more levels inside a wrapper div, not a direct sibling of the section's
    // <h6>) until a level's backward-sibling search reaches an <h6 class="cmd-section"> before
    // hitting an <hr> or running out of siblings — that's the section's actual heading. Then
    // toggle the heading and every sibling forward until the next <hr> (or end of parent).
    let heading = null;
    let node = el;
    while (node && !heading) {
      let sib = node.previousElementSibling;
      while (sib) {
        if (sib.tagName === 'H6' || sib.classList.contains('cmd-section')) { heading = sib; break; }
        if (sib.tagName === 'HR') break;
        sib = sib.previousElementSibling;
      }
      node = node.parentElement;
    }
    if (heading) {
      (visible ? setElShown : setElHidden)(heading);
      let sib = heading.nextElementSibling;
      while (sib && sib.tagName !== 'HR') {
        (visible ? setElShown : setElHidden)(sib);
        sib = sib.nextElementSibling;
      }
      // Also toggle the <hr> separator before the section (if one exists)
      if (heading.previousElementSibling?.tagName === 'HR') {
        (visible ? setElShown : setElHidden)(heading.previousElementSibling);
      }
    }
  }
  const edrHideAnchors = [
    // NOTE: Network Discovery (ARP Scan) + ARP Sweep Detection are NOT here anymore — since
    // sentineld 1.2.0 (2026-08-05) the Linux agent implements both natively (internal/arpwatch
    // via the sudoers-granted arpsweep-deploy.sh wrapper), speaking the SAME JSON contracts as
    // the Windows pktmon/PS1 path, so these two sections render for Linux RA devices too. The
    // remaining anchors are still genuinely Windows-only (no Linux counterpart exists).
    'ra-edr-enable-btn',        // EDR — Behavioral Telemetry (Sysmon)
    'ra-sentry-enable-btn',     // Sentry Mode — Endpoint Honeypot
    'ra-edr-isolate-block-btn', // Dynamic Host Isolation
    'ra-screentext-enable-btn', // Screen Text Capture (Windows UI Automation only)
  ];
  for (const id of edrHideAnchors) setSectionVisibleByAnchor(id, !isLinuxRA);
  // Windows Update / Block Telemetry / Defender Exclusion live in the Connection & Maintenance
  // tab itself (which stays visible for Linux) — Windows-only (no Defender/no equivalent
  // kill-switch on Linux), so hide them there specifically, unlike the tab as a whole.
  const connMaintWindowsOnlyAnchors = [
    'ra-wu-disable-btn',        // Windows Update (+ Force Update Now, same section)
    'ra-telemetry-block-btn',   // Block Telemetry
    'ra-defender-block-btn',    // Defender Exclusion
  ];
  for (const id of connMaintWindowsOnlyAnchors) setSectionVisibleByAnchor(id, !isLinuxRA);
  // Reverse SSH Tunnel description text — platform-specific copy (PowerShell/admin account
  // language doesn't apply to the Linux daemon's sentinel-support shell).
  document.getElementById('ra-tunnel-desc-windows')?.classList.toggle('d-none', isLinuxRA);
  document.getElementById('ra-tunnel-desc-linux')?.classList.toggle('d-none', !isLinuxRA);

  // Commands tab: hide camera/mic/find-phone/antitheft sections for Windows AND Linux RA
  document.querySelectorAll('.android-cmd').forEach(el => {
    el.classList.toggle('d-none', isWindows || isRemoteAssist);
  });

  // Screenshot tab: toggle Android single-button vs Windows multi-monitor controls
  document.getElementById('btn-screenshot-android')?.classList.toggle('d-none', isWindows || isRemoteAssist);
  document.getElementById('sc-win-controls')?.classList.toggle('d-none', !isWindows);
  // Clear cached monitor list when switching devices
  document.getElementById('sc-monitor-btns').innerHTML = '';

  // Reset file browser for this device's platform
  filesPathStack.length = 0;
  if (isWindows) {
    currentFilesPath = 'C:\\';
    currentFilesPathSep = '\\';
  } else {
    currentFilesPath = '/sdcard';
    currentFilesPathSep = '/';
  }
  const pathEl = document.getElementById('files-path');
  if (pathEl) pathEl.textContent = currentFilesPath;
  const browser = document.getElementById('files-browser');
  if (browser) browser.innerHTML = `<div class="text-center text-muted py-5">
    <i class="bi bi-folder2" style="font-size:2rem;opacity:.3"></i>
    <p class="mt-2 small">Click Refresh to browse device files</p>
  </div>`;
}

// Business Account compliance: audio/stream/screenshots/keylog/screentext are permanently
// disabled on a business-mode device, so hide those tabs entirely rather than just disabling
// their action buttons. Photos tab stays visible, but its manual-capture toolbar (camera
// buttons, interval controls, and that grid's own Select All/Deselect/Delete) is hidden too —
// only Unlock Capture Settings + Unlock Attempts remain, since the automatic unlock photo is
// the only capture that still works. Called AFTER applyPermissionsForDevice()+
// applyPlatformForDevice() (the latter can re-show keylogs/screentext for a public owner via
// enabled_features) so this always wins last.
const BUSINESS_MODE_HIDDEN_TABS = ['audio', 'stream', 'screenshots', 'keylogs', 'screentext'];
function applyBusinessModeTabRestrictions(deviceId) {
  const isBiz = !!deviceCache.get(deviceId)?.business_mode;
  // Toggled both ways — nothing else manages these tabs' visibility for the non-business-mode
  // case, so switching from a business-mode device to a normal one must explicitly restore them.
  // ⚠️ Previously this returned early on `!isBiz` and only ever set style.display='none', never
  // back — a business-mode device viewed once left audio/stream/screenshots/keylogs/screentext
  // permanently hidden for every device selected afterward in the same SPA session, same
  // "add-only" bug class as applyPlatformForDevice()'s RA group-hiding fix (memory
  // webui-tab-sheet-stale-dnone). Uses the dedicated `.biz-hidden` class (style.css), NOT raw
  // style.display and NOT Bootstrap's `.d-none` — this function runs AFTER
  // applyPermissionsForDevice()/applyPlatformForDevice() specifically so the business-compliance
  // hide can override whatever those already decided; toggling a separate class both ways means
  // removing it on a non-business device never has to guess or replay their logic, it just stops
  // overriding it and their own style.display value (already set correctly before this ran) shows
  // through again.
  document.getElementById('photos-manual-capture-section')?.classList.toggle('d-none', isBiz);
  for (const tab of BUSINESS_MODE_HIDDEN_TABS) {
    const navItem = document.querySelector(`[data-tab="${tab}"]`)?.closest('.nav-item');
    if (navItem) navItem.classList.toggle('biz-hidden', isBiz);
    const sheetItem = document.querySelector(`.tab-sheet-item[data-tab="${tab}"]`);
    if (sheetItem) sheetItem.classList.toggle('biz-hidden', isBiz);
  }
}

// Business Account banner: auto-closes 10 minutes after it appears, or sooner via the close
// button. Repeated calls for the SAME device (e.g. an incidental refresh) don't restart the
// countdown — only a genuine device switch (or the timer elapsing) does.
let _businessModeBannerTimer = null;
let _businessModeBannerDeviceId = null;
// Device IDs the viewer has already closed (via the × button or the 10-min auto-close) this
// browser session. applyPermissionsForDevice() -> _setBusinessModeBannerVisible(id, true) reruns
// on EVERY device open/re-open (and on every devices_updated/socket-reconnect refresh while one is
// open) — without this, dismissing just cleared the timer/device-id state, which is indistinguishable
// from "never shown", so the very next re-visit to the same device silently un-hid the banner again.
const _businessModeBannerDismissed = new Set();
const BUSINESS_MODE_BANNER_MS = 10 * 60 * 1000;
function _setBusinessModeBannerVisible(deviceId, show) {
  const el = document.getElementById('business-mode-banner');
  if (!el) return;
  // currentUser.biz_banner_dismissed is the PERMANENT, server-persisted "don't show again" for
  // this account (set once via dismissBusinessModeBanner() below, read back on every /api/me at
  // page load) — checked ahead of the in-memory Set, which only ever covered "this browser tab,
  // this page load" and reset on every refresh, which was the actual bug being fixed here.
  if (!show || currentUser.biz_banner_dismissed || _businessModeBannerDismissed.has(deviceId)) {
    el.classList.add('d-none');
    if (_businessModeBannerTimer) { clearTimeout(_businessModeBannerTimer); _businessModeBannerTimer = null; }
    _businessModeBannerDeviceId = null;
    return;
  }
  el.classList.remove('d-none');
  if (_businessModeBannerDeviceId !== deviceId || !_businessModeBannerTimer) {
    if (_businessModeBannerTimer) clearTimeout(_businessModeBannerTimer);
    _businessModeBannerDeviceId = deviceId;
    _businessModeBannerTimer = setTimeout(() => {
      el.classList.add('d-none');
      _businessModeBannerDismissed.add(deviceId);
      _businessModeBannerTimer = null;
      _businessModeBannerDeviceId = null;
    }, BUSINESS_MODE_BANNER_MS);
  }
}
function dismissBusinessModeBanner() {
  document.getElementById('business-mode-banner')?.classList.add('d-none');
  if (_businessModeBannerDeviceId) _businessModeBannerDismissed.add(_businessModeBannerDeviceId);
  if (_businessModeBannerTimer) { clearTimeout(_businessModeBannerTimer); _businessModeBannerTimer = null; }
  _businessModeBannerDeviceId = null;
  // Persist server-side so this stays dismissed for this account permanently — across refreshes
  // and a different browser/device signed into the same account, not just this tab (the click-X
  // used to only ever suppress it for the current page load, which is the bug this fixes).
  currentUser.biz_banner_dismissed = true;
  apiFetchJSON('/api/account/business-banner-dismiss', { method: 'POST' }).catch(() => {});
}

// Persistent "Business Account" badge in the top navbar — reflects the LOGGED-IN account (not
// the selected device): shown for a business_mode owner, or for one of their business_sub team
// members (their whole account is inherently tied to a business-mode owner).
function _updateBusinessAccountBadge() {
  const badge = document.getElementById('business-account-navbar-badge');
  if (!badge) return;
  const show = !!currentUser?.business_mode || currentUser?.account_type === 'business_sub';
  badge.classList.toggle('d-none', !show);
}

