async function loadEnrollmentList() {
  if (currentUser.role !== 'admin') return;
  const container = document.getElementById('enrollment-list');
  const badge = document.getElementById('enrollment-badge');
  const countBadge = document.getElementById('enrollment-count-badge');
  if (!container) return;
  try {
    const [list, users] = await Promise.all([
      fetch('/api/enrollment/pending').then(r => r.json()),
      fetch('/api/users').then(r => r.json()).catch(() => []),
    ]);
    const n = list.length;
    if (badge) { badge.textContent = String(n || ''); badge.classList.toggle('d-none', !n); }
    if (countBadge) { countBadge.textContent = n || ''; countBadge.classList.toggle('d-none', !n); }
    if (!n) {
      container.innerHTML = '<p class="text-muted small mb-0">No pending enrollments. All devices are connected with approved keys.</p>';
      return;
    }

    // Build user dropdown options (public + admin-created active users)
    const activeUsers = (Array.isArray(users) ? users : []).filter(u => u.status === 'active');
    const makeUserOpts = (matchedUserId) => `<option value="">— Unassigned —</option>` +
      activeUsers.map(u =>
        `<option value="${u.id}"${matchedUserId && u.id === matchedUserId ? ' selected' : ''}>${esc(u.username)}${u.account_type === 'public' ? ' 🔒' : ''}</option>`
      ).join('');

    const safeId = id => id.replace(/[^a-zA-Z0-9_-]/g, '_');

    container.innerHTML = `
      <p class="text-muted small mb-2">
        <i class="bi bi-info-circle me-1"></i>
        Assign each device to a user before approving. Devices assigned to <strong>🔒 registered users</strong>
        will be zero-knowledge — admin cannot see their data after assignment.
      </p>
      <div class="table-responsive">
      <table class="table table-sm mb-0 align-middle" style="font-size:.8rem">
        <thead><tr>
          <th>Device ID</th><th>Model</th><th>Android</th>
          <th>Assign to user</th>
          <th class="text-end" style="width:1%">Action</th>
        </tr></thead>
        <tbody>${list.map(e => `<tr>
          <td class="font-monospace" style="font-size:.65rem;max-width:150px;word-break:break-all">${esc(e.device_id)}</td>
          <td class="text-truncate" style="max-width:150px" title="${escAttr(e.model || '')}">${esc(e.model || '—')}</td>
          <td class="text-muted text-truncate" style="max-width:80px" title="${escAttr(e.android_version || '')}">${esc(e.android_version || '—')}</td>
          <td>
            ${e.matched_username ? `<span class="badge bg-success bg-opacity-25 text-success border border-success border-opacity-25 me-1" title="Auto-matched via enrollment token">🔗 ${esc(e.matched_username)}</span>` : ''}
            <select id="enroll-user-${safeId(e.device_id)}" class="form-select form-select-sm" style="min-width:150px">
              ${makeUserOpts(e.enrollment_user_id)}
            </select>
          </td>
          <td class="text-end" style="white-space:nowrap">
            <div class="d-inline-flex gap-1 flex-nowrap">
              <button class="btn btn-sm btn-outline-success py-0 px-2"
                onclick="approveEnrollment('${escJsAttr(e.device_id)}')">
                <i class="bi bi-check-lg"></i> Approve
              </button>
              <button class="btn btn-sm btn-outline-danger py-0 px-2"
                onclick="rejectEnrollment('${escJsAttr(e.device_id)}')" title="Reject">
                <i class="bi bi-x-lg"></i>
              </button>
            </div>
          </td>
        </tr>`).join('')}</tbody>
      </table>
      </div>`;
  } catch (err) {
    if (container) container.innerHTML = `<p class="text-danger small">Failed to load: ${esc(String(err))}</p>`;
  }
}

async function approveEnrollment(deviceId) {
  // Read the user assignment dropdown for this device
  const safeId = deviceId.replace(/[^a-zA-Z0-9_-]/g, '_');
  const sel = document.getElementById(`enroll-user-${safeId}`);
  const userId = sel ? (sel.value ? parseInt(sel.value, 10) : null) : null;

  const r = await fetch(`/api/enrollment/${deviceId}/approve`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(userId ? { userId } : {}),
  });
  if (r.ok) {
    const msg = userId
      ? 'Device approved and assigned to user'
      : 'Device enrollment approved (unassigned)';
    showToast(msg, 'success');
    loadEnrollmentList();
  } else {
    const d = await r.json().catch(() => ({}));
    showToast(d.error || 'Failed to approve', 'danger');
  }
}

async function rejectEnrollment(deviceId) {
  if (!confirm(`Reject enrollment from device ${deviceId}? The device will not be able to connect.`)) return;
  const r = await fetch(`/api/enrollment/${deviceId}`, { method: 'DELETE' });
  if (r.ok) { showToast('Enrollment rejected', 'success'); loadEnrollmentList(); }
  else showToast('Failed to reject', 'danger');
}

function openHoneypotWebui() {
  trackPageView('/admin/honeypot');
  // Browsers block HTTP iframes inside HTTPS pages (Mixed Content).
  // The honeypot mgmt UI is an internal HTTP-only service on the Tailscale network.
  // We must open it in a new tab to avoid the block.
  const base = currentUser.hp_mgmt_url || window.SENTINEL_HP_MGMT_URL || '';
  if (!base) { showToast('Honeypot management URL is not configured', 'warning'); return; }
  const url = currentUser.hp_mgmt_key
    ? `${base.replace(/\/$/, '')}/?k=${encodeURIComponent(currentUser.hp_mgmt_key)}`
    : base;
  window.open(url, '_blank');
}

function closeHoneypotWebui() {
  // No longer used since we open in a new tab
}

function openUsersPanel() {
  trackPageView('/admin/users');
  if (!usersModal) usersModal = new bootstrap.Modal(document.getElementById('usersModal'));
  loadEnrollmentList();
  loadUsers();
  loadProvisionUserSelect();
  usersModal.show();
}

