// ── Per-account 30-day trial badge (label + live countdown) ───────────────────
function formatTrialRemaining(deadline) {
  const ms = deadline - Date.now();
  if (ms <= 0) return 'expired';
  const d = Math.floor(ms / 86400000), h = Math.floor((ms % 86400000) / 3600000), m = Math.floor((ms % 3600000) / 60000);
  return d > 0 ? `${d}d ${h}h left` : h > 0 ? `${h}h ${m}m left` : `${m}m left`;
}
function trialBadgeHtml(u) {
  const t = u.trial;
  if (!t) return '';
  if (t.state === 'pending')
    return `<span class="badge bg-secondary" title="30-day trial starts when this account's first device connects"><i class="bi bi-hourglass-split me-1"></i>Trial: awaiting first device</span>`;
  if (t.state === 'active') {
    const soon = t.ms_remaining < 48 * 3600 * 1000;
    return `<span class="badge ${soon ? 'bg-warning text-dark' : 'bg-success'} trial-countdown" data-deadline="${t.deadline}" title="30-day trial — started ${new Date(t.started_at).toLocaleString()}"><i class="bi bi-stopwatch me-1"></i>Trial: <span class="trial-rem">${formatTrialRemaining(t.deadline)}</span></span>`;
  }
  const agoDays = Math.max(0, Math.floor((Date.now() - t.deadline) / 86400000));
  return `<span class="badge bg-danger" title="30-day trial expired ${new Date(t.deadline).toLocaleString()}"><i class="bi bi-exclamation-octagon me-1"></i>Trial EXPIRED${agoDays > 0 ? ` · ${agoDays}d ago` : ''}</span>`;
}
// Admin-granted complimentary ("comp") subscription badge — shown INSTEAD of the trial badge
// when active (a comp overrides the trial: no lock, no auto-wipe).
function compBadgeHtml(u) {
  const c = u.comp;
  if (!c) return '';
  const planTxt = { '1device': '5 Devices', hybrid: 'Hybrid Managed', unlimited: 'Per Device' }[c.plan] || (c.label || c.plan);
  const by = c.granted_by ? ` — granted by ${esc(c.granted_by)}` : '';
  if (c.expires_at) {
    const exp = new Date(c.expires_at);
    return `<span class="badge bg-primary" title="Complimentary ${planTxt} plan${by} — expires ${exp.toLocaleString()}"><i class="bi bi-gift me-1"></i>Comp: ${planTxt} · until ${exp.toLocaleDateString()}</span>`;
  }
  return `<span class="badge bg-primary" title="Complimentary ${planTxt} plan${by} — no expiry"><i class="bi bi-gift me-1"></i>Comp: ${planTxt}</span>`;
}
let _trialTicker = null;
function startTrialTicker() {
  if (_trialTicker) return;
  _trialTicker = setInterval(() => {
    const live = document.querySelectorAll('.trial-countdown[data-deadline]');
    if (!live.length) return;
    live.forEach(el => {
      const dl = parseInt(el.getAttribute('data-deadline'), 10);
      const rem = el.querySelector('.trial-rem');
      if (rem) rem.textContent = formatTrialRemaining(dl);
      const ms = dl - Date.now();
      if (ms <= 0) { el.classList.remove('bg-success', 'bg-warning'); el.classList.add('bg-danger', 'text-dark'); }
      else if (ms < 48 * 3600 * 1000) { el.classList.remove('bg-success'); el.classList.add('bg-warning', 'text-dark'); }
    });
  }, 30000);
}

async function loadUsers() {
  const container = document.getElementById('user-list-container');
  container.innerHTML = '<div class="text-muted small">Loading…</div>';
  try {
    const [users, allDevices] = await Promise.all([
      fetch('/api/devices').then(r => r.json()),
      fetch('/api/users').then(r => r.json()),
    ]).then(([d, u]) => [u, d]);
    const deviceMap = Object.fromEntries(allDevices.map(d => [d.id, safeName(d.name, d.id)]));

    // Business sub-users (a business owner's own team, created via their Team modal — see the
    // Account & Security dashboard) are grouped under their owning public account instead of
    // cluttering the flat admin list as their own top-level rows.
    const subUsersByOwner = {};
    for (const u of users) {
      if (u.account_type === 'business_sub' && u.parent_owner_id != null) {
        (subUsersByOwner[u.parent_owner_id] ||= []).push(u);
      }
    }
    const topLevelUsers = users.filter(u => u.account_type !== 'business_sub');

    if (!topLevelUsers.length) { container.innerHTML = '<p class="text-muted small">No users found.</p>'; return; }

    const FEATURE_LABELS = {
      location:'Location', photos:'Photos', audio:'Audio', screenshots:'Screen Captures',
      stream:'Live Stream', network:'Network', files:'Files', calls:'Call Logs',
      sms:'SMS', apps:'Apps', contacts:'Contacts', notifications:'Alerts',
      keylogs:'Keylog', screentext:'Screen Text', geofences:'Geofences',
      timeline:'Timeline', commands:'Commands', connect:'Connect', security:'Security',
        };

    const blocks = topLevelUsers.map(u => {
      if (u.role === 'admin') {
        const searchHay = `${u.username} ${u.email || ''}`.toLowerCase();
        return `<div class="border-bottom py-2 d-flex align-items-center gap-2 user-row" data-search="${escAttr(searchHay)}">
          <span class="fw-semibold">${esc(u.username)}</span>
          <span class="badge bg-danger">admin</span>
          <span class="text-muted small fst-italic ms-1">All permissions on all devices</span>
        </div>`;
      }
      const perms   = u.permissions || {};
      const isPublic = u.account_type === 'public';
      const features = u.enabled_features || {};
      const grantedDeviceIds = Object.keys(perms);
      const ungranted = allDevices.filter(d => !perms[d.id]);

      const statusBadge = isPublic
        ? (u.status === 'active'   ? '<span class="badge bg-success ms-1">active</span>'
         : u.status === 'rejected' ? '<span class="badge bg-danger ms-1">rejected</span>'
         : '<span class="badge bg-warning text-dark ms-1">pending</span>')
        : '';
      const typeBadge = isPublic
        ? '<span class="badge bg-info text-dark">public</span>'
        : '<span class="badge bg-secondary">sub-user</span>';
      // One-way user-set toggle — only an admin can revert it (see /api/users/:id/business-mode).
      const businessBadge = u.business_mode
        ? '<span class="badge bg-warning text-dark" title="Business Account compliance mode is active — only an admin can revert it"><i class="bi bi-briefcase me-1"></i>Business</span>'
        : '';

      // Feature toggles (for public users)
      const featureRow = isPublic ? `
        <div class="mb-2">
          <div class="small fw-semibold mb-1 text-muted text-uppercase" style="font-size:.7rem;letter-spacing:.06em">
            <i class="bi bi-toggles me-1"></i>Feature Access
          </div>
          <div class="d-flex flex-wrap gap-1">
            ${Object.entries(FEATURE_LABELS).map(([k, lbl]) => `
              <label class="form-check form-check-inline mb-0" style="font-size:.75rem">
                <input class="form-check-input" type="checkbox" id="feat-${u.id}-${k}"
                  ${features[k] ? 'checked' : ''}
                  onchange="saveUserFeature(${u.id})">
                <span class="form-check-label">${lbl}</span>
              </label>`).join('')}
          </div>
        </div>` : '';

      // Notification preferences (for public users)
      const notifRow = isPublic ? `
        <div class="mb-2">
          <div class="small fw-semibold mb-1 text-muted text-uppercase" style="font-size:.7rem;letter-spacing:.06em">
            <i class="bi bi-bell me-1"></i>Notification Preferences
          </div>
          <div id="notif-prefs-${u.id}">
            <div class="text-muted small fst-italic">
              <i class="bi bi-arrow-repeat spin me-1"></i>Loading…
            </div>
          </div>
        </div>` : '';

      // Complimentary subscription control (for public users) — admin override of trial/billing.
      const compRow = isPublic ? `
        <div class="mb-2">
          <div class="small fw-semibold mb-1 text-muted text-uppercase" style="font-size:.7rem;letter-spacing:.06em">
            <i class="bi bi-gift me-1"></i>Complimentary Subscription
          </div>
          <div class="d-flex flex-wrap align-items-center gap-2" style="font-size:.82rem">
            <select id="comp-plan-${u.id}" class="form-select form-select-sm" style="max-width:140px">
              <option value="unlimited"${(u.comp?.plan ?? 'unlimited') === 'unlimited' ? ' selected' : ''}>Per Device (no cap)</option>
              <option value="1device"${u.comp?.plan === '1device' ? ' selected' : ''}>5 Devices</option>
              <option value="hybrid"${u.comp?.plan === 'hybrid' ? ' selected' : ''}>Hybrid Managed (no cap)</option>
            </select>
            <div class="input-group input-group-sm" style="max-width:200px">
              <input type="number" min="1" step="1" id="comp-days-${u.id}" class="form-control py-0" placeholder="days (blank = forever)">
              <span class="input-group-text py-0" style="font-size:.78rem">days</span>
            </div>
            <button class="btn btn-sm btn-primary" onclick="grantCompSub(${u.id})"><i class="bi bi-gift me-1"></i>${u.comp ? 'Update' : 'Grant free sub'}</button>
            ${u.comp ? `<button class="btn btn-sm btn-outline-danger" onclick="revokeCompSub(${u.id})"><i class="bi bi-x-lg me-1"></i>Revoke</button>` : ''}
          </div>
          ${u.comp
            ? `<div class="small text-success mt-1"><i class="bi bi-check-circle me-1"></i>Active: <strong>${esc(u.comp.label)}</strong>${u.comp.expires_at ? ` · until ${new Date(u.comp.expires_at).toLocaleString()}` : ' · no expiry'}${u.comp.granted_by ? ` · by ${esc(u.comp.granted_by)}` : ''}</div>`
            : `<div class="small text-muted mt-1">Grants a free plan — the account skips the trial lock &amp; 48h auto-wipe and gets the chosen device cap.</div>`}
        </div>` : '';

      // Business sub-users ("team members") this owner created via their own Team modal —
      // listed read-only here (managed by the owner, not the admin); hidden by default.
      const mySubUsers = isPublic ? (subUsersByOwner[u.id] || []) : [];
      const teamRow = mySubUsers.length ? `
        <div class="mb-2">
          <div class="small fw-semibold mb-1 text-muted text-uppercase" style="font-size:.7rem;letter-spacing:.06em">
            <i class="bi bi-people me-1"></i>Team Members (business sub-users)
          </div>
          <table class="table table-sm mb-1 align-middle" style="font-size:.8rem">
            <thead><tr><th>Email / Username</th><th>Status</th><th>Devices granted</th></tr></thead>
            <tbody>${mySubUsers.map(su => {
              const suDevCount = Object.keys(su.permissions || {}).length;
              return `<tr>
                <td>${esc(su.username)}</td>
                <td>${su.status === 'active' ? '<span class="badge bg-success">active</span>' : `<span class="badge bg-secondary">${esc(su.status || 'unknown')}</span>`}</td>
                <td>${suDevCount ? `${suDevCount} device${suDevCount === 1 ? '' : 's'}` : '<span class="text-muted fst-italic">none yet</span>'}</td>
              </tr>`;
            }).join('')}</tbody>
          </table>
          <div class="small text-muted">Managed by the account owner via their own dashboard's Team panel — not editable here.</div>
        </div>` : '';

      // Manual trial-days control (for public users) — admin can SET the exact countdown (not just
      // extend it, shorten it too), or reset it back to "awaiting first device". Separate from the
      // comp-sub override above: comp EXEMPTS the account from the trial; this edits the trial clock itself.
      const trialRow = isPublic ? `
        <div class="mb-2">
          <div class="small fw-semibold mb-1 text-muted text-uppercase" style="font-size:.7rem;letter-spacing:.06em">
            <i class="bi bi-stopwatch me-1"></i>Trial Countdown
          </div>
          <div class="d-flex flex-wrap align-items-center gap-2" style="font-size:.82rem">
            <div class="input-group input-group-sm" style="max-width:170px">
              <input type="number" min="0" max="3650" step="1" id="trial-days-${u.id}" class="form-control py-0"
                placeholder="days left" value="${u.trial?.days_remaining ?? ''}">
              <span class="input-group-text py-0" style="font-size:.78rem">days left</span>
            </div>
            <button class="btn btn-sm btn-primary" onclick="setTrialDays(${u.id})"><i class="bi bi-check-lg me-1"></i>Set exact</button>
            <button class="btn btn-sm btn-outline-secondary" onclick="resetTrialDays(${u.id})"><i class="bi bi-arrow-counterclockwise me-1"></i>Reset</button>
          </div>
          <div class="small text-muted mt-1">Sets the 30-day countdown to exactly this many days left, as of now — can shorten or lengthen it, not just extend. "Reset" un-starts it back to "awaiting first device".${u.comp ? ' This account currently has a complimentary override active, so the trial clock below is exempt/inactive regardless of this value.' : ''}</div>
        </div>` : '';

      // Public users: show owned devices as a simple read-only list (no per-device permissions)
      // Sub-users: show full permissions table with per-permission checkboxes
      const deviceRows = isPublic
        ? (grantedDeviceIds.length
            ? `<div class="py-1">${grantedDeviceIds.map(did =>
                `<span class="badge bg-secondary me-1 mb-1">${esc(deviceMap[did] || did)}</span>`
              ).join('')}</div>`
            : `<p class="text-muted small mb-1 fst-italic">No device assigned yet.</p>`)
        : (grantedDeviceIds.length
            ? `<table class="table table-sm mb-1 align-middle" style="font-size:.8rem">
                <thead><tr>
                  <th style="width:110px">Device</th><th>Permissions</th><th style="width:40px"></th>
                </tr></thead>
                <tbody>${grantedDeviceIds.map(did =>
                  _devicePermRow(u, did, deviceMap[did] || did, perms[did] || {})
                ).join('')}</tbody>
              </table>`
            : `<p class="text-muted small mb-1">No device access granted.</p>`);

      // Grant Access dropdown only for sub-users; public user devices are assigned via device owner
      const addDropdown = (!isPublic && ungranted.length) ? `
        <div class="d-flex gap-1 mt-1">
          <select id="add-dev-${u.id}" class="form-select form-select-sm" style="max-width:200px">
            ${ungranted.map(d => `<option value="${d.id}">${esc(safeName(d.name, d.id))}</option>`).join('')}
          </select>
          <button class="btn btn-sm btn-outline-primary" onclick="grantDeviceAccess(${u.id})">
            <i class="bi bi-plus-lg"></i> Grant Access
          </button>
        </div>` : '';

      // Wipe button only for public users — safe account reset for a forgotten key.
      const wipeBtn = isPublic ? `
        <button class="btn btn-outline-warning py-0" onclick="wipeUser(${u.id}, '${escJsAttr(u.username)}')"
          title="Wipe account — deletes all ZK data and account (forgotten key reset)"><i class="bi bi-radioactive"></i></button>` : '';

      // Search haystack (also matches this owner's team members, so an admin can find a business
      // sub-user's account by searching either their own name or their owner's).
      const searchHay = `${u.username} ${u.email || ''} ${mySubUsers.map(su => `${su.username} ${su.email || ''}`).join(' ')}`.toLowerCase();

      // Secondary details (type/status/trial/email) are tucked behind a collapse by default — the
      // Business badge stays visible inline since it must be clearly labeled at a glance.
      const infoRow = `
        <div class="d-flex flex-wrap align-items-center gap-2">
          ${typeBadge}${statusBadge}${u.comp ? compBadgeHtml(u) : trialBadgeHtml(u)}
          ${u.email ? `<span class="text-muted small">${esc(u.email)}</span>` : ''}
        </div>`;

      // Condensed: one compact row per account; details / Features / Notifications / Devices
      // are tucked behind per-section toggle buttons (Bootstrap collapse).
      return `<div class="border-bottom py-2 user-row" data-search="${escAttr(searchHay)}">
        <div class="d-flex align-items-center gap-2 flex-wrap">
          <span class="user-info-toggle" data-bs-toggle="collapse" data-bs-target="#info-${u.id}" style="cursor:pointer" title="Show details">
            <i class="bi bi-chevron-right small"></i>
            <span class="fw-semibold ms-1">${esc(u.username)}</span>
          </span>
          ${businessBadge}
          <div class="btn-group btn-group-sm ms-auto" role="group">
            ${isPublic ? `<button class="btn btn-outline-secondary py-0" data-bs-toggle="collapse" data-bs-target="#feat-${u.id}" title="Feature access"><i class="bi bi-toggles"></i></button>` : ''}
            ${isPublic ? `<button class="btn btn-outline-secondary py-0" data-bs-toggle="collapse" data-bs-target="#notif-${u.id}" title="Notification preferences"><i class="bi bi-bell"></i></button>` : ''}
            ${isPublic ? `<button class="btn ${u.comp ? 'btn-primary' : 'btn-outline-secondary'} py-0" data-bs-toggle="collapse" data-bs-target="#comp-${u.id}" title="Complimentary subscription"><i class="bi bi-gift"></i></button>` : ''}
            ${isPublic ? `<button class="btn btn-outline-secondary py-0" data-bs-toggle="collapse" data-bs-target="#trial-${u.id}" title="Edit trial countdown"><i class="bi bi-stopwatch"></i></button>` : ''}
            ${isPublic && u.business_mode ? `<button class="btn btn-outline-warning py-0" onclick="revertBusinessMode(${u.id}, '${escJsAttr(u.username)}')" title="Revert Business Account mode"><i class="bi bi-briefcase"></i></button>` : ''}
            ${mySubUsers.length ? `<button class="btn btn-outline-secondary py-0" data-bs-toggle="collapse" data-bs-target="#team-${u.id}" title="Team members (business sub-users)"><i class="bi bi-people me-1"></i>${mySubUsers.length}</button>` : ''}
            <button class="btn btn-outline-secondary py-0" data-bs-toggle="collapse" data-bs-target="#dev-${u.id}" title="Device access"><i class="bi bi-phone me-1"></i>${grantedDeviceIds.length}</button>
            ${!isPublic ? `<button class="btn btn-outline-danger py-0" onclick="deleteUser(${u.id})" title="Delete user account only"><i class="bi bi-trash-fill"></i></button>` : ''}
            ${wipeBtn}
          </div>
        </div>
        <div class="collapse mt-2" id="info-${u.id}">${infoRow}</div>
        ${isPublic ? `<div class="collapse mt-2" id="feat-${u.id}">${featureRow}</div>` : ''}
        ${isPublic ? `<div class="collapse mt-2" id="notif-${u.id}">${notifRow}</div>` : ''}
        ${isPublic ? `<div class="collapse mt-2" id="comp-${u.id}">${compRow}</div>` : ''}
        ${isPublic ? `<div class="collapse mt-2" id="trial-${u.id}">${trialRow}</div>` : ''}
        ${mySubUsers.length ? `<div class="collapse mt-2" id="team-${u.id}">${teamRow}</div>` : ''}
        <div class="collapse mt-2" id="dev-${u.id}">${deviceRows}${addDropdown}</div>
      </div>`;
    }).join('');

    container.innerHTML = blocks;
    // Async-populate per-user notification prefs (only for public users)
    for (const u of users) {
      if (u.account_type === 'public') _renderUserNotifPrefs(u.id, u.email);
    }
    startTrialTicker();   // keep the trial countdowns live while the panel is open
    filterUserList();     // re-apply any in-progress search text to the freshly rendered rows
  } catch (_) {
    container.innerHTML = '<p class="text-danger small">Failed to load users.</p>';
  }
}

// Client-side filter over the rendered account list (matches username, email, and — for a
// business account — its team members' usernames/emails too), so the admin can jump straight
// to an account without scrolling a long flat list.
function filterUserList() {
  const input = document.getElementById('user-search-input');
  const q = (input?.value || '').trim().toLowerCase();
  document.getElementById('user-search-clear-btn')?.classList.toggle('d-none', !q);
  const rows = document.querySelectorAll('#user-list-container > .user-row');
  let anyVisible = false;
  rows.forEach(row => {
    const match = !q || (row.dataset.search || '').includes(q);
    row.style.display = match ? '' : 'none';
    if (match) anyVisible = true;
  });
  document.getElementById('user-search-empty')?.classList.toggle('d-none', !q || anyVisible);
}

// Fetch and render a public user's notification prefs inside their card
async function _renderUserNotifPrefs(userId, email) {
  const el = document.getElementById(`notif-prefs-${userId}`);
  if (!el) return;
  try {
    const prefs = await fetch(`/api/users/${userId}/notif-prefs`).then(r => r.json());
    const emailOn = !!prefs.email_alerts;
    el.innerHTML = `
      <div class="d-flex flex-wrap align-items-center gap-2" style="font-size:.82rem">
        <div class="input-group input-group-sm" style="max-width:340px">
          <span class="input-group-text py-0" style="font-size:.78rem">
            <i class="bi bi-discord me-1"></i>Discord Webhook
          </span>
          <input type="url" class="form-control py-0" id="notif-discord-${userId}"
            placeholder="https://discord.com/api/webhooks/…"
            value="${escAttr(prefs.discord_webhook || '')}">
        </div>
        <div class="form-check form-switch mb-0 ms-1"
          title="${email ? 'Email these alerts to ' + esc(email) : 'No email on file for this account'}">
          <input class="form-check-input" type="checkbox" role="switch" id="notif-email-${userId}"
            ${emailOn ? 'checked' : ''} ${email ? '' : 'disabled'} onchange="saveUserNotifPrefs(${userId})">
          <label class="form-check-label" for="notif-email-${userId}" style="font-size:.8rem">
            <i class="bi bi-envelope me-1"></i>Email alerts${email ? ` <span class="text-muted">(${esc(email)})</span>` : ' <span class="text-muted">(no email on file)</span>'}
          </label>
        </div>
        <button class="btn btn-sm btn-primary py-0" onclick="saveUserNotifPrefs(${userId})"
          title="Save notification preferences">
          <i class="bi bi-floppy me-1"></i>Save
        </button>
        <button class="btn btn-sm btn-outline-secondary py-0" onclick="testUserNotif(${userId})"
          title="Send a test notification to this user">
          <i class="bi bi-send me-1"></i>Test
        </button>
      </div>
      <div class="mt-1 ps-1" style="font-size:.72rem;color:#888;line-height:1.5">
        <strong style="color:#aaa">Alerts sent to this user:</strong>
        &nbsp;🔐 Account login &nbsp;·&nbsp;
        📷 Photo captured &nbsp;·&nbsp;
        🎙️ Audio recorded &nbsp;·&nbsp;
        📹 Camera stream started / stopped &nbsp;·&nbsp;
        🖥️ Screenshot capture started / stopped &nbsp;·&nbsp;
        🚨 Geofence crossings &nbsp;·&nbsp;
        📵 Device offline
        <br>Delivered to push (bell), Discord, and/or email. <strong>Metadata only</strong> —
        event label, device name, and time; never media or message content (it's end-to-end encrypted).
      </div>`;
  } catch {
    el.innerHTML = '<span class="text-danger small">Failed to load notification prefs.</span>';
  }
}

async function saveUserNotifPrefs(userId) {
  const webhookEl = document.getElementById(`notif-discord-${userId}`);
  const emailEl   = document.getElementById(`notif-email-${userId}`);
  const body = {};
  if (webhookEl) body.discord_webhook = webhookEl.value.trim();
  if (emailEl)   body.email_alerts    = emailEl.checked;
  const r = await fetch(`/api/users/${userId}/notif-prefs`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
  if (r.ok) showToast('Notification preferences saved', 'success');
  else showToast('Failed to save notification preferences', 'danger');
}

async function testUserNotif(userId) {
  const r = await fetch(`/api/users/${userId}/notif-test`, { method: 'POST' });
  const data = await r.json().catch(() => ({}));
  if (r.ok) showToast('Test notification sent', 'success');
  else showToast(data.error || 'Failed to send test notification', 'danger');
}

async function saveDevicePerms(userId, deviceId) {
  const perms = {};
  for (const p of Object.keys(PERM_LABELS)) {
    const el = document.getElementById(`udp-${userId}-${deviceId}-${p}`);
    if (el) perms[p] = el.checked;
  }
  const r = await fetch(`/api/users/${userId}/devices/${deviceId}`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ permissions: perms }),
  });
  if (r.ok) showToast('Permissions saved', 'success');
  else showToast('Failed to save permissions', 'danger');
}

async function grantDeviceAccess(userId) {
  const sel = document.getElementById(`add-dev-${userId}`);
  if (!sel || !sel.value) return;
  const deviceId = sel.value;
  const defaultPerms = {};
  for (const p of Object.keys(PERM_LABELS)) defaultPerms[p] = false;
  const r = await fetch(`/api/users/${userId}/devices/${deviceId}`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ permissions: defaultPerms }),
  });
  if (r.ok) { showToast('Device access granted', 'success'); loadUsers(); }
  else showToast('Failed to grant access', 'danger');
}

async function revokeDeviceAccess(userId, deviceId) {
  const r = await fetch(`/api/users/${userId}/devices/${deviceId}`, { method: 'DELETE' });
  if (r.ok) { showToast('Device access revoked', 'success'); loadUsers(); }
  else showToast('Failed to revoke access', 'danger');
}

// Grant (or update) a complimentary subscription — a free admin override of trial/billing for a
// public user. Plan from the select; optional duration in days (blank ⇒ perpetual).
async function grantCompSub(userId) {
  const plan = document.getElementById(`comp-plan-${userId}`)?.value || 'unlimited';
  const daysRaw = (document.getElementById(`comp-days-${userId}`)?.value || '').trim();
  const body = { plan };
  if (daysRaw) {
    const days = parseInt(daysRaw, 10);
    if (!Number.isFinite(days) || days <= 0) { showToast('Enter a positive number of days, or leave it blank for no expiry.', 'warning'); return; }
    body.days = days;
  }
  const r = await fetch(`/api/users/${userId}/comp-sub`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
  });
  const d = await r.json().catch(() => ({}));
  if (r.ok) { showToast('Complimentary subscription granted', 'success'); loadUsers(); }
  else showToast(d.error || 'Failed to grant complimentary subscription', 'danger');
}

function revokeCompSub(userId) {
  showConfirm({
    title: 'Revoke Complimentary Subscription',
    body: '<p class="mb-0">Revoke this free subscription? The account reverts to normal trial/billing rules (and may re-enter the trial-ended lock if its trial has already expired).</p>',
    okLabel: 'Revoke',
    okClass: 'btn-danger',
    onConfirm: async () => {
      const r = await fetch(`/api/users/${userId}/comp-sub`, { method: 'DELETE' });
      const d = await r.json().catch(() => ({}));
      if (r.ok) { showToast('Complimentary subscription revoked', 'success'); loadUsers(); }
      else showToast(d.error || 'Failed to revoke', 'danger');
    }
  });
}

// Admin-only revert of the one-way Business Account toggle (the user can only ever turn it ON —
// see POST /api/account/business-mode). Re-enables audio/video/screen recording, screenshots,
// keylogging, and screen-text capture on every device the account owns.
function revertBusinessMode(userId, username) {
  showConfirm({
    title: 'Revert Business Account',
    body: `<p class="mb-0 text-muted">Turn OFF Business Account compliance mode for <strong>${esc(username)}</strong>? Audio/video/screen recording, screenshots, keylogging, and screen-text capture become available again on every device they own.</p>`,
    okLabel: 'Revert',
    okClass: 'btn-warning',
    onConfirm: async () => {
      const r = await fetch(`/api/users/${userId}/business-mode`, { method: 'DELETE' });
      const d = await r.json().catch(() => ({}));
      if (r.ok) { showToast('Business Account mode reverted', 'success'); loadUsers(); }
      else showToast(d.error || 'Failed to revert Business Account mode', 'danger');
    }
  });
}

// Set the trial countdown to an EXACT number of days remaining, as of right now — can shorten
// or lengthen it (not just extend). Separate from the comp-sub grant above.
async function setTrialDays(userId) {
  const raw = (document.getElementById(`trial-days-${userId}`)?.value || '').trim();
  const days = Number(raw);
  if (raw === '' || !Number.isFinite(days) || days < 0 || days > 3650) {
    showToast('Enter a number of days between 0 and 3650', 'warning');
    return;
  }
  const r = await fetch(`/api/users/${userId}/trial`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ daysRemaining: days }),
  });
  const d = await r.json().catch(() => ({}));
  if (r.ok) { showToast(`Trial set to ${days} day${days === 1 ? '' : 's'} remaining`, 'success'); loadUsers(); }
  else showToast(d.error || 'Failed to set trial days', 'danger');
}

function resetTrialDays(userId) {
  showConfirm({
    title: 'Reset Trial Countdown',
    body: '<p class="mb-0">Reset this account’s trial back to "awaiting first device"? The countdown will restart the next time one of their devices connects.</p>',
    okLabel: 'Reset',
    okClass: 'btn-warning',
    onConfirm: async () => {
      const r = await fetch(`/api/users/${userId}/trial`, { method: 'DELETE' });
      const d = await r.json().catch(() => ({}));
      if (r.ok) { showToast('Trial countdown reset', 'success'); loadUsers(); }
      else showToast(d.error || 'Failed to reset', 'danger');
    }
  });
}

async function createUser() {
  const username = document.getElementById('new-user-name').value.trim();
  const password = document.getElementById('new-user-pass').value;
  const role     = document.getElementById('new-user-role').value;
  if (!username || !password) { showToast('Username and password required', 'warning'); return; }
  // Create the row pre-hashed ("prehash-v1") so the new user's plaintext never crosses the wire.
  const saltBytes = crypto.getRandomValues(new Uint8Array(16));
  const auth_salt = btoa(String.fromCharCode(...saltBytes));
  const auth_hash = await _authPrehash(password, auth_salt);
  const r = await fetch('/api/users', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ username, auth_hash, auth_salt, role, permissions: {} }),
  });
  const data = await r.json().catch(() => ({}));
  if (!r.ok) { showToast(data.error || 'Failed to create user', 'danger'); return; }
  document.getElementById('new-user-name').value = '';
  document.getElementById('new-user-pass').value = '';
  showToast(`User "${username}" created — grant device access below`, 'success');
  loadUsers();
}

function deleteUser(id) {
  showConfirm({
    title: 'Delete User',
    body: '<p class="mb-0">Delete this user? They will no longer be able to log in.</p>',
    okLabel: 'Delete User',
    okClass: 'btn-danger',
    onConfirm: async () => {
      await fetch(`/api/users/${id}`, { method: 'DELETE' });
      loadUsers();
    }
  });
}

// ── Calls ──────────────────────────────────────────────────────────────────
// ── Installed Apps ─────────────────────────────────────────────────────────
let appsData = [];

var loadApps = async function(deviceId) {
  if (!deviceId) return;
  const container = document.getElementById('apps-list');
  const countEl = document.getElementById('apps-count');
  container.innerHTML = '<p class="text-muted small">Loading…</p>';
  if (countEl) countEl.textContent = '';
  try {
    appsData = await fetch(`/api/devices/${deviceId}/apps`).then(r => r.json());
    if (deviceId !== selectedDeviceId) return; // device switched mid-fetch — drop stale response
    if (!appsData.length) {
      container.innerHTML = '<p class="text-muted">No app data. Click Refresh to fetch from device.</p>';
      return;
    }
    renderApps();
    loadAppSchedules(deviceId).then(renderApps);
    loadInstallFilter();
    sendCmd('get_uninstall_blocked', {}, null);
  } catch (_) { container.innerHTML = '<p class="text-danger small">Failed to load.</p>'; }
}

