// package -> short schedule summary string (filled by loadAppSchedules; drives the ⏰ chip)
let _appSchedules = {};

// Escape a value for safe embedding inside a single-quoted JS string that itself
// sits inside a double-quoted HTML attribute (esc() only handles HTML, not the JS
// string layer — names like "McDonald's" would otherwise break onclick handlers).
function jsAttr(s) {
  return String(s ?? '')
    .replace(/\\/g, '\\\\').replace(/'/g, "\\'")
    .replace(/&/g, '&amp;').replace(/"/g, '&quot;')
    .replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function _letterAvatar(name) {
  const label = (name || '?').trim() || '?';
  const ch = (label[0] || '?').toUpperCase();
  const palette = ['#e74c3c','#e67e22','#f1c40f','#16a085','#2ecc71','#3498db','#9b59b6','#fd79a8','#0984e3','#6c5ce7','#00b894','#e84393'];
  let h = 0; for (let i = 0; i < label.length; i++) h = (h * 31 + label.charCodeAt(i)) >>> 0;
  return `<span class="app-icon app-letter" style="background:${palette[h % palette.length]}">${esc(ch)}</span>`;
}

function appIconHtml(a) {
  if (a.icon) return `<img class="app-icon" src="data:image/png;base64,${a.icon}" alt="" width="40" height="40" loading="lazy" onerror="this.remove()">`;
  return _letterAvatar(a.name || a.package);
}

function appRowHtml(a) {
  const paused = !!a.suspended;
  const sched  = _appSchedules[a.package];
  const pkg = jsAttr(a.package), nm = jsAttr(a.name);
  return `
    <div class="list-group-item app-row px-2 py-2 border-0 border-bottom${paused ? ' app-row-paused' : ''}">
      <div class="d-flex align-items-center gap-2">
        ${appIconHtml(a)}
        <div class="flex-grow-1 overflow-hidden">
          <div class="d-flex align-items-center gap-2 flex-wrap">
            <span class="fw-semibold text-truncate" style="font-size:.95rem;max-width:100%">${esc(a.name)}</span>
            ${paused ? '<span class="app-paused-pill"><i class="bi bi-pause-fill"></i>PAUSED</span>' : ''}
            ${a.system ? '<span class="badge bg-secondary" style="font-size:.58rem">system</span>' : ''}
            ${a.uninstall_blocked ? '<span class="badge bg-warning text-dark" style="font-size:.58rem"><i class="bi bi-lock-fill me-1"></i>protected</span>' : ''}
          </div>
          <div class="d-flex align-items-center gap-2 mt-1">
            <small class="text-muted font-monospace text-truncate" style="font-size:.66rem">${esc(a.package)}</small>
            ${sched ? `<small class="app-sched-chip"><i class="bi bi-clock-history"></i>${esc(sched)}</small>` : ''}
          </div>
        </div>
        <button class="btn btn-sm flex-shrink-0 ${paused ? 'btn-success' : 'btn-warning'}" data-requires="commands"
          style="min-width:108px;font-weight:600" onclick="toggleAppSuspend('${pkg}', ${paused})">
          <i class="bi bi-${paused ? 'play-fill' : 'pause-fill'} me-1"></i>${paused ? 'Unpause' : 'Pause'}
        </button>
        <button class="btn btn-sm btn-outline-info flex-shrink-0" data-requires="commands"
          onclick="openAppSchedule('${pkg}','${nm}')" title="Schedule pause / unpause">
          <i class="bi bi-clock"></i>
        </button>
        <div class="dropdown flex-shrink-0">
          <button class="btn btn-sm btn-outline-secondary" type="button" data-bs-toggle="dropdown" aria-expanded="false" title="More actions">
            <i class="bi bi-three-dots-vertical"></i>
          </button>
          <ul class="dropdown-menu dropdown-menu-dark dropdown-menu-end">
            <li><button class="dropdown-item" data-requires="commands" onclick="openAppPermissions('${pkg}','${nm}')"><i class="bi bi-shield-lock me-2"></i>Permissions</button></li>
            <li><button class="dropdown-item" data-requires="commands" onclick="toggleUninstallBlock('${pkg}','${nm}',${!!a.uninstall_blocked})"><i class="bi bi-lock${a.uninstall_blocked ? '-fill' : ''} me-2"></i>${a.uninstall_blocked ? 'Unprotect uninstall' : 'Block uninstall'}</button></li>
            <li><button class="dropdown-item" data-requires="commands" onclick="confirmClearAppData('${pkg}','${nm}')"><i class="bi bi-trash2 me-2"></i>Clear data &amp; cache</button></li>
            <li><button class="dropdown-item" data-requires="files" onclick="confirmPullApk('${pkg}','${nm}')"><i class="bi bi-cloud-download me-2"></i>Pull APK to server</button></li>
            <li><hr class="dropdown-divider"></li>
            <li><button class="dropdown-item text-danger" data-requires="commands" onclick="confirmUninstallApp('${pkg}','${nm}')"><i class="bi bi-trash3 me-2"></i>Uninstall</button></li>
          </ul>
        </div>
      </div>
    </div>`;
}

function renderApps() {
  const query = (document.getElementById('apps-search')?.value || '').toLowerCase();
  const userOnly = document.getElementById('apps-hide-system')?.checked;
  const filtered = appsData.filter(a => {
    if (userOnly && a.system) return false;
    if (query && !a.name.toLowerCase().includes(query) && !a.package.toLowerCase().includes(query)) return false;
    return true;
  });
  const countEl = document.getElementById('apps-count');
  if (countEl) countEl.textContent = `${filtered.length} of ${appsData.length} apps`;
  const container = document.getElementById('apps-list');
  if (!container) return;
  if (!filtered.length) { container.innerHTML = '<p class="text-muted">No matching apps.</p>'; return; }

  const popular = filtered.filter(a => POPULAR_APPS[a.package] != null)
                          .sort((a, b) => POPULAR_APPS[a.package] - POPULAR_APPS[b.package]);
  const rest = filtered.filter(a => POPULAR_APPS[a.package] == null)
                       .sort((a, b) => (a.name || '').toLowerCase().localeCompare((b.name || '').toLowerCase()));

  // While searching, show a single ranked list; otherwise group into Popular / All apps.
  if (query) {
    container.innerHTML = `<div class="list-group list-group-flush">${[...popular, ...rest].map(appRowHtml).join('')}</div>`;
    return;
  }
  const section = (title, list) => !list.length ? '' :
    `<div class="apps-section-label">${title}</div><div class="list-group list-group-flush mb-3">${list.map(appRowHtml).join('')}</div>`;
  container.innerHTML = section('Popular', popular) + section('All apps', rest);
}

function filterApps() { renderApps(); }

function confirmUninstallApp(pkg, name) {
  if (!selectedDeviceId) return;
  showConfirm({
    title: 'Uninstall App',
    body: `<p class="mb-0">Uninstall <strong>${esc(name)}</strong>?<br><small class="text-muted font-monospace">${esc(pkg)}</small><br><small class="text-warning mt-1 d-block">Requires Device Owner or Root Agent for system apps.</small></p>`,
    okLabel: 'Uninstall',
    okClass: 'btn-danger',
    onConfirm: () => sendCmd('uninstall_app', { package: pkg }, null),
  });
}

function confirmClearAppData(pkg, name) {
  if (!selectedDeviceId) return;
  showConfirm({
    title: 'Clear App Data',
    body: `<p class="mb-0">Clear all storage and cache for <strong>${esc(name)}</strong>?<br><small class="text-muted font-monospace">${esc(pkg)}</small><br><small class="text-danger mt-1 d-block">Permanently deletes all app data, accounts, files, settings, and cache. Requires Device Owner or Root Agent.</small></p>`,
    okLabel: 'Clear Data',
    okClass: 'btn-danger',
    onConfirm: () => sendCmd('clear_app_data', { package: pkg }, null),
  });
}

// ── Install Filter ─────────────────────────────────────────────────────────────

let installFilterData = { mode: 'blacklist', list: [] };

function loadInstallFilter() {
  if (!selectedDeviceId) return;
  sendCmd('get_install_filter', {}, null);
}

function renderInstallFilter() {
  const { mode, list } = installFilterData;
  const blBtn = document.getElementById('install-filter-blacklist-btn');
  const wlBtn = document.getElementById('install-filter-whitelist-btn');
  const hint  = document.getElementById('install-filter-mode-hint');
  const listEl = document.getElementById('install-filter-list');
  if (!listEl) return;
  if (blBtn) { blBtn.classList.toggle('active', mode === 'blacklist'); blBtn.classList.toggle('btn-outline-danger', true); }
  if (wlBtn) { wlBtn.classList.toggle('active', mode === 'whitelist'); wlBtn.classList.toggle('btn-outline-success', true); }
  if (hint) hint.textContent = mode === 'whitelist'
    ? 'Only listed apps may be installed. Everything else is auto-removed.'
    : 'Listed apps are automatically removed after install.';
  if (!list.length) { listEl.innerHTML = '<span class="text-muted small">No entries.</span>'; return; }
  listEl.innerHTML = list.map(pkg => `
    <span class="badge d-inline-flex align-items-center gap-1 font-monospace" style="background:#2a2a3e;color:#cdd6f4;font-size:.68rem">
      ${esc(pkg)}
      <button class="btn-close btn-close-white" style="font-size:.55rem" aria-label="Remove"
        onclick="removeInstallFilterEntry('${escJsAttr(pkg)}')"></button>
    </span>`).join('');
}

function setInstallFilterMode(mode) {
  if (!selectedDeviceId) return;
  sendCmd('set_install_filter_mode', { mode }, null);
}

function addInstallFilterEntry() {
  if (!selectedDeviceId) return;
  const input = document.getElementById('install-filter-input');
  const pkg = (input?.value || '').trim();
  if (!pkg) return;
  sendCmd('add_install_filter', { package: pkg }, null);
  if (input) input.value = '';
}

function removeInstallFilterEntry(pkg) {
  if (!selectedDeviceId) return;
  sendCmd('remove_install_filter', { package: pkg }, null);
}

socket.on('install_filter_result', d => {
  if (d.deviceId !== selectedDeviceId) return;
  installFilterData = { mode: d.mode || 'blacklist', list: d.list || [] };
  renderInstallFilter();
});

// ── Uninstall Blocking ─────────────────────────────────────────────────────────

let uninstallBlockedList = [];

function renderUninstallBlockedPanel() {
  const el = document.getElementById('uninstall-blocked-list');
  if (!el) return;
  if (!uninstallBlockedList.length) { el.innerHTML = '<span class="text-muted small">No packages protected.</span>'; return; }
  el.innerHTML = uninstallBlockedList.map(pkg => `
    <span class="badge d-inline-flex align-items-center gap-1 font-monospace me-1 mb-1" style="background:#2a2a3e;color:#f9e2af;font-size:.68rem">
      <i class="bi bi-lock-fill" style="font-size:.6rem"></i>${esc(pkg)}
    </span>`).join('');
}

function toggleUninstallBlock(pkg, name, currentlyBlocked) {
  if (!selectedDeviceId) return;
  const action = currentlyBlocked ? 'Unprotect' : 'Protect';
  showConfirm({
    title: `${action} Uninstall`,
    body: `<p class="mb-0">${currentlyBlocked ? 'Allow' : 'Block'} uninstall of <strong>${esc(name)}</strong>?<br>
      <small class="text-muted font-monospace">${esc(pkg)}</small><br>
      ${!currentlyBlocked ? '<small class="text-warning d-block mt-1">The user will not be able to uninstall this app. Requires Device Owner or Root Agent.</small>' : ''}</p>`,
    okLabel: action,
    okClass: currentlyBlocked ? 'btn-secondary' : 'btn-warning',
    onConfirm: () => sendCmd('set_uninstall_blocked', { package: pkg, blocked: !currentlyBlocked }, null),
  });
}

socket.on('uninstall_blocked_result', d => {
  if (d.deviceId !== selectedDeviceId) return;
  uninstallBlockedList = d.list || [];
  renderUninstallBlockedPanel();
  if (d.package != null) {
    const app = appsData.find(a => a.package === d.package);
    if (app) { app.uninstall_blocked = !!d.blocked; renderApps(); }
    if (d.blocked) showToast(`🔒 Uninstall protected: ${esc(d.package)}`, 'warning');
    else showToast(`🔓 Uninstall protection removed: ${esc(d.package)}`, 'secondary');
  }
});

function confirmPullApk(pkg, name) {
  if (!selectedDeviceId) return;
  showConfirm({
    title: 'Pull APK',
    body: `<p class="mb-0">Download the APK for <strong>${esc(name)}</strong> to the server?<br><small class="text-muted font-monospace">${esc(pkg)}</small><br><small class="text-info mt-1 d-block">The file will appear in the Files tab (Pulled Files).</small></p>`,
    okLabel: 'Pull APK',
    okClass: 'btn-primary',
    onConfirm: () => sendCmd('pull_apk', { package: pkg }, null),
  });
}

let _appPermModal = null;
let _appPermCurrentPkg = null;

function openAppPermissions(pkg, name) {
  if (!selectedDeviceId) return;
  _appPermCurrentPkg = pkg;
  document.getElementById('appPermissionsModal-title').textContent = name;
  document.getElementById('appPermissionsModal-pkg').textContent = pkg;
  document.getElementById('appPermissionsModal-body').innerHTML =
    '<div class="text-center py-4"><div class="spinner-border spinner-border-sm text-secondary"></div></div>';
  if (!_appPermModal) _appPermModal = new bootstrap.Modal(document.getElementById('appPermissionsModal'));
  _appPermModal.show();
  sendCmd('get_app_permissions', { package: pkg }, null);
}

function renderAppPermissionsModal(pkg, permissions, suspended) {
  if (pkg !== _appPermCurrentPkg) return;
  const body = document.getElementById('appPermissionsModal-body');
  if (!body) return;

  const STATE_LABELS = { default: 'Default', granted: 'Grant', denied: 'Deny' };
  const STATE_CLASSES = { default: 'btn-outline-secondary', granted: 'btn-success', denied: 'btn-danger' };

  const suspendLabel = suspended ? 'Unsuspend App' : 'Suspend App';
  const suspendClass = suspended ? 'btn-warning' : 'btn-outline-warning';

  const permRows = permissions.length ? permissions.map(p => `
    <tr>
      <td class="font-monospace small py-1" style="word-break:break-all">${esc(p.name)}</td>
      <td class="py-1">
        <div class="btn-group btn-group-sm" role="group">
          ${['default','granted','denied'].map(s => `
            <button type="button"
              class="btn ${p.state === s ? STATE_CLASSES[s] : 'btn-outline-secondary'}"
              onclick="setAppPermission('${escJsAttr(pkg)}','${escJsAttr(p.permission)}','${s}')"
              ${p.state === s ? 'disabled' : ''}>
              ${STATE_LABELS[s]}
            </button>`).join('')}
        </div>
      </td>
    </tr>`).join('')
    : '<tr><td colspan="2" class="text-muted small py-2">No runtime permissions declared by this app.</td></tr>';

  body.innerHTML = `
    <div class="px-3 py-2 border-bottom d-flex align-items-center gap-3">
      <span class="small fw-semibold">App state:</span>
      ${suspended ? '<span class="badge bg-warning text-dark">Suspended</span>' : '<span class="badge bg-success">Active</span>'}
      <button class="btn btn-sm ${suspendClass} ms-auto" data-requires="commands"
        onclick="toggleAppSuspend('${escJsAttr(pkg)}', ${suspended})">
        <i class="bi bi-${suspended ? 'play' : 'pause'}-circle me-1"></i>${suspendLabel}
      </button>
    </div>
    <div class="px-3 pt-2 pb-1">
      <p class="small text-muted mb-2">Requires Device Owner or Root Agent. <strong>Grant</strong> / <strong>Deny</strong> override the user; <strong>Default</strong> restores user control.</p>
      <table class="table table-sm table-borderless mb-0">
        <thead><tr><th class="small text-muted py-1">Permission</th><th class="small text-muted py-1">State</th></tr></thead>
        <tbody>${permRows}</tbody>
      </table>
    </div>`;
}

function setAppPermission(pkg, permission, state) {
  if (!selectedDeviceId) return;
  sendCmd('set_app_permission', { package: pkg, permission, state }, null);
}

function toggleAppSuspend(pkg, currentlySuspended) {
  if (!selectedDeviceId) return;
  sendCmd('suspend_app', { package: pkg, suspended: !currentlySuspended }, null);
}

async function clearLocationHistory(btn) {
  if (!selectedDeviceId) return;
  showConfirm({
    title: 'Clear Location History',
    body: '<p class="mb-0">Delete all stored location history for this device? This cannot be undone.</p>',
    okLabel: 'Clear',
    okClass: 'btn-danger',
    onConfirm: async () => {
      try {
        await fetch(`/api/devices/${selectedDeviceId}/locations`, { method: 'DELETE' });
        _clearLocLines(selectedDeviceId);                    // day lines + live-append alias
        delete _locHistoryCache[selectedDeviceId];
        delete _locDaySelections[selectedDeviceId];
        const sel = document.getElementById('loc-day-select');
        if (sel) { sel.innerHTML = ''; sel.style.display = 'none'; }
        if (mapMarkers[selectedDeviceId])   { mapMarkers[selectedDeviceId].map = null;   delete mapMarkers[selectedDeviceId]; }
        showToast('Location history cleared', 'success');
      } catch (e) { showToast('Failed to clear location history', 'danger'); }
    }
  });
}

// ── Status tab ─────────────────────────────────────────────────────────────

function _fmtBytes(b) {
  if (!b) return '—';
  const gb = b / (1024 ** 3);
  return gb >= 1 ? gb.toFixed(1) + ' GB' : (b / (1024 ** 2)).toFixed(0) + ' MB';
}

async function loadStatusEvents(deviceId, btn) {
  if (!deviceId) return;
  const listEl   = document.getElementById('status-events-list');
  const countEl  = document.getElementById('status-event-count');
  const healthEl = document.getElementById('status-health');
  if (!listEl) return;
  listEl.innerHTML = '<p class="text-muted small">Loading…</p>';

  // Render device health from cached status
  const cached = deviceCache.get(deviceId);
  const st = cached?.status || {};
  if (healthEl) {
    const storage   = st.storage;
    const memory    = st.memory;
    const bat       = st.battery;
    const integrity = st.integrity ?? cached?.integrity ?? null;
    const verdict   = integrity?.verdict || 'UNKNOWN';
    const integrityMap = {
      VERIFIED:    { cls: 'success', icon: 'bi-shield-fill-check',      label: 'Verified'    },
      PARTIAL:     { cls: 'info',    icon: 'bi-shield-shaded',           label: 'Partial'     },
      UNVERIFIED:  { cls: 'warning', icon: 'bi-shield-fill-exclamation', label: 'Unverified'  },
      COMPROMISED: { cls: 'danger',  icon: 'bi-shield-slash-fill',       label: 'Compromised' },
      UNKNOWN:     { cls: 'secondary',icon: 'bi-shield',                 label: 'Unknown'     },
    };
    const vc = integrityMap[verdict] || integrityMap.UNKNOWN;
    // SELF_SIGNED custom build → AVB boot key is the trust anchor, not the attestation CA
    // chain; suppress the "chain root not pinned" warning (only meaningful for stock ROMs).
    const selfSigned = integrity?.verified_boot_state === 'SELF_SIGNED';
    const chainWarn  = integrity && !integrity.chain_verified && !selfSigned;
    const gOsNote = integrity?.grapheneos
      ? `<small class="text-success d-block">SentinelMDM${chainWarn ? ' <span class="text-warning" title="Attestation chain root not yet pinned — boot key is trusted">⚠</span>' : ' ✓'}</small>`
      : '';
    const chainLine = integrity
      ? (integrity.chain_verified
          ? `<small class="text-success d-block">✓ Chain verified (Google root)</small>`
          : selfSigned
            ? `<small class="text-success d-block">✓ Verified via custom boot key</small>`
            : `<small class="text-warning d-block" title="${integrity.attestation_root_spki ? 'Unknown root SPKI: ' + integrity.attestation_root_spki : 'Chain not traced to pinned root'}">⚠ Chain root not pinned${integrity.attestation_root_spki ? ' — SPKI: ' + integrity.attestation_root_spki.slice(0,12) + '…' : ''}</small>`)
      : '';
    const integrityCard = `<div class="col-sm-4">
      <div class="card p-2 text-center" style="background:#1a1a2e;border-color:#313244">
        <small class="text-muted text-uppercase fw-bold d-block mb-1" style="font-size:.6rem;letter-spacing:.07em">Integrity</small>
        <i class="bi ${vc.icon} text-${vc.cls} d-block" style="font-size:1.4rem"></i>
        <div class="fw-bold text-${vc.cls}" style="font-size:.8rem">${vc.label}</div>
        ${gOsNote}
        ${integrity ? `<small class="text-muted">${integrity.security_level || ''} · ${integrity.verified_boot_state || '?'}</small>` : '<small class="text-muted">Not checked yet</small>'}
        ${integrity ? `<small class="text-muted d-block">${integrity.device_locked ? 'Locked' : 'Unlocked'} · ${integrity.build_tags || '?'}</small>` : ''}
        ${chainLine}
        <button class="btn btn-outline-secondary btn-sm mt-2 py-0 px-2" style="font-size:.65rem"
          onclick="sendCmd('get_integrity_status',{})">
          <i class="bi bi-arrow-clockwise me-1"></i>Re-check
        </button>
      </div>
    </div>`;
    healthEl.innerHTML = [
      storage ? `<div class="col-sm-4"><div class="card p-2 text-center" style="background:#1a1a2e;border-color:#313244">
        <small class="text-muted text-uppercase fw-bold d-block mb-1" style="font-size:.6rem;letter-spacing:.07em">Storage</small>
        <div class="fw-bold">${_fmtBytes(storage.free)} free</div>
        <small class="text-muted">${_fmtBytes(storage.total)} total</small>
        <div class="progress mt-1" style="height:4px"><div class="progress-bar bg-info" style="width:${Math.round((storage.used/storage.total)*100)||0}%"></div></div>
      </div></div>` : '',
      memory  ? `<div class="col-sm-4"><div class="card p-2 text-center" style="background:#1a1a2e;border-color:#313244">
        <small class="text-muted text-uppercase fw-bold d-block mb-1" style="font-size:.6rem;letter-spacing:.07em">RAM</small>
        <div class="fw-bold">${_fmtBytes(memory.available)} free</div>
        <small class="text-muted">${_fmtBytes(memory.total)} total</small>
        <div class="progress mt-1" style="height:4px"><div class="progress-bar ${memory.lowMemory ? 'bg-danger' : 'bg-success'}" style="width:${Math.round(((memory.total-memory.available)/memory.total)*100)||0}%"></div></div>
      </div></div>` : '',
      bat     ? `<div class="col-sm-4"><div class="card p-2 text-center" style="background:#1a1a2e;border-color:#313244">
        <small class="text-muted text-uppercase fw-bold d-block mb-1" style="font-size:.6rem;letter-spacing:.07em">Battery</small>
        <div class="fw-bold">${bat.level ?? '—'}%</div>
        <small class="text-muted">${bat.status || '—'} · ${bat.plugType || '—'}</small>
        <div class="progress mt-1" style="height:4px"><div class="progress-bar ${(bat.level??100) < 20 ? 'bg-danger' : 'bg-success'}" style="width:${bat.level||0}%"></div></div>
      </div></div>` : '',
      integrityCard,
    ].join('');
  }

  try {
    const events = await fetch(`/api/devices/${deviceId}/status-events`).then(r => r.json());
    if (countEl) countEl.textContent = events.length;
    if (!events.length) { listEl.innerHTML = '<p class="text-muted small">No app or OS events recorded yet.</p>'; return; }
    listEl.innerHTML = events.map(ev => {
      const d = ev.data || {};
      const typeConf = {
        app_installed: { icon: 'bi-box-arrow-in-down', cls: 'text-success', label: 'Installed' },
        app_removed:   { icon: 'bi-trash3',            cls: 'text-danger',  label: 'Removed'   },
        app_updated:   { icon: 'bi-arrow-up-circle',   cls: 'text-info',    label: 'Updated'   },
        app_update:        { icon: 'bi-cloud-arrow-down',     cls: 'text-primary', label: 'Updating'      },
        app_update_failed: { icon: 'bi-exclamation-triangle', cls: 'text-danger',  label: 'Update failed' },
      };
      const tc = typeConf[d.type || ev.type] || { icon: 'bi-info-circle', cls: 'text-secondary', label: d.type || ev.type };
      const granted = (d.grantedPermissions || []).filter(p => p.includes('.') && !p.includes('android.permission.RECEIVE_BOOT_COMPLETED'));
      const permsHtml = granted.length
        ? `<div class="mt-1 d-flex flex-wrap gap-1">${granted.slice(0,8).map(p => `<span class="badge bg-secondary" style="font-size:.6rem">${p.split('.').pop()}</span>`).join('')}${granted.length > 8 ? `<span class="badge bg-secondary" style="font-size:.6rem">+${granted.length-8}</span>` : ''}</div>`
        : '';
      return `<div class="d-flex align-items-start gap-2 py-2 border-bottom border-secondary">
        <i class="bi ${tc.icon} ${tc.cls} mt-1" style="font-size:1.1rem;flex-shrink:0"></i>
        <div class="flex-grow-1 overflow-hidden">
          <div class="d-flex align-items-center gap-2">
            <span class="fw-medium text-truncate">${esc(d.name || d.package || ev.type)}</span>
            <span class="badge" style="background:#2a3a4a;font-size:.6rem">${tc.label}</span>
            ${d.version ? `<small class="text-muted">v${esc(d.version)}</small>` : ''}
          </div>
          <small class="text-muted font-monospace">${esc(d.package || '')}${d.phase ? ' · ' + esc(d.phase) : ''}${(d.phase === 'downloading' && d.total) ? ' · ' + Math.round((d.bytes || 0) / d.total * 100) + '%' : ''}</small>
          ${d.error ? `<small class="text-danger font-monospace d-block">${esc(d.error)}</small>` : ''}
          ${permsHtml}
        </div>
        <small class="text-muted flex-shrink-0">${ts(ev.timestamp)}</small>
      </div>`;
    }).join('');
  } catch (e) {
    listEl.innerHTML = '<p class="text-danger small">Failed to load status events.</p>';
  }
}

socket.on('status_event_update', data => {
  const ev = data.event || {};
  if (data.deviceId === selectedDeviceId) {
    const tab = document.querySelector('[data-tab="status"]');
    if (tab?.classList.contains('active')) loadStatusEvents(selectedDeviceId);
  }
  if (ev.type === 'install_blocked') {
    const cached = deviceCache.get(data.deviceId);
    const devLabel = cached?.name || data.deviceId;
    const modeNote = ev.filter_mode === 'whitelist' ? ' (not on whitelist)' : ' (blacklisted)';
    showToast(`🚫 Install blocked on ${esc(devLabel)}: ${esc(ev.package)}${modeNote}`, 'warning');
  }
});

let _sideloadFile = null;
function onSideloadFileChange(input) {
  _sideloadFile = input.files[0] || null;
  const btn = document.getElementById('btn-sideload-upload');
  const status = document.getElementById('sideload-status');
  if (_sideloadFile) {
    if (status) status.textContent = `${_sideloadFile.name} (${(_sideloadFile.size / 1024 / 1024).toFixed(1)} MB)`;
    if (btn) btn.disabled = false;
  } else {
    if (status) status.textContent = '';
    if (btn) btn.disabled = true;
  }
}

async function cmdSideloadApk() {
  if (!selectedDeviceId || !_sideloadFile) return;
  const btn = document.getElementById('btn-sideload-upload');
  const status = document.getElementById('sideload-status');
  const origLabel = btn.innerHTML;
  btn.disabled = true;
  btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span> Uploading…';
  if (status) status.textContent = '';
  try {
    const res = await fetch(`/api/devices/${selectedDeviceId}/install-apk`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/octet-stream',
        'X-Filename': _sideloadFile.name,
      },
      body: _sideloadFile,
    });
    if (!res.ok) {
      const err = await res.json().catch(() => ({ error: res.statusText }));
      showToast(`Install failed: ${err.error}`, 'danger');
    } else {
      showToast(`APK sent to device — installing…`, 'success');
      _sideloadFile = null;
      document.getElementById('sideload-file-input').value = '';
      if (status) status.textContent = '';
    }
  } catch (e) {
    showToast(`Upload error: ${e.message}`, 'danger');
  } finally {
    btn.innerHTML = origLabel;
    btn.disabled = true;
  }
}

socket.on('uninstall_result', d => {
  if (d.deviceId !== selectedDeviceId) return;
  if (d.success) {
    showToast(`Uninstalled: ${d.package || ''}`, 'success');
    // Remove from local appsData so the list updates immediately without a full Refresh.
    appsData = appsData.filter(a => a.package !== d.package);
    renderApps();
  } else {
    showToast(`Uninstall failed: ${d.error || 'unknown error'}`, 'danger');
  }
});

socket.on('app_list_update', d => {
  if (d.deviceId !== selectedDeviceId) return;
  appsData = d.apps || [];
  renderApps();
  loadAppSchedules(d.deviceId).then(renderApps);
  // Also refresh install filter and uninstall-blocked sections so they
  // populate even on first-time root-agent devices with no cached data.
  loadInstallFilter();
  sendCmd('get_uninstall_blocked', {}, null);
});

socket.on('battery_stats_update', d => {
  if (d.deviceId !== selectedDeviceId) return;
  const tab = document.getElementById('tab-battery');
  if (tab && !tab.classList.contains('d-none')) renderBatteryStats(d);
});

var loadBatteryStats = async function(deviceId) {
  if (!deviceId) return;
  const r = await fetch(`/api/devices/${deviceId}/battery-stats`);
  if (deviceId !== selectedDeviceId) return; // device switched mid-fetch — drop stale response
  if (!r.ok) return;
  const data = await r.json();
  if (data) renderBatteryStats(data);
}

function renderBatteryStats(data) {
  const batt = data.battery || {};
  const apps = data.apps || [];
  const ts   = data.timestamp;

  // Timestamp
  const tsEl = document.getElementById('battery-timestamp');
  if (tsEl && ts) tsEl.textContent = `as of ${new Date(ts).toLocaleTimeString()}`;

  // Overview cards
  const overview = document.getElementById('battery-overview');
  if (overview) {
    const pct     = batt.level ?? '?';
    const health  = batt.health || '?';
    const temp    = batt.temp != null ? `${batt.temp.toFixed(1)} °C` : '?';
    const status  = batt.status || '?';
    const plugged = batt.plugged || '?';
    const voltage = batt.voltage ? `${(batt.voltage / 1000).toFixed(2)} V` : null;
    const chargeMs = batt.chargeTimeRemainingMs;
    const chargeMins = chargeMs != null ? Math.round(chargeMs / 60000) : null;

    const battColor = pct === '?' ? '#6c757d' : pct > 50 ? '#a6e3a1' : pct > 20 ? '#f9e2af' : '#f38ba8';

    overview.innerHTML = `
      <div class="col-6 col-md-3">
        <div class="card text-center p-2" style="background:#1e1e2e;border-color:#313244">
          <div style="font-size:2rem;font-weight:700;color:${battColor}">${pct}%</div>
          <div class="text-muted small">Battery Level</div>
        </div>
      </div>
      <div class="col-6 col-md-3">
        <div class="card text-center p-2" style="background:#1e1e2e;border-color:#313244">
          <div style="font-size:1.5rem;font-weight:600;color:#cdd6f4">${status}</div>
          <div class="text-muted small">${plugged !== 'Unplugged' ? plugged : 'Not Charging'}${chargeMins != null ? ` · ${chargeMins}m left` : ''}</div>
        </div>
      </div>
      <div class="col-6 col-md-3">
        <div class="card text-center p-2" style="background:#1e1e2e;border-color:#313244">
          <div style="font-size:1.5rem;font-weight:600;color:#89dceb">${temp}</div>
          <div class="text-muted small">Temperature</div>
        </div>
      </div>
      <div class="col-6 col-md-3">
        <div class="card text-center p-2" style="background:#1e1e2e;border-color:#313244">
          <div style="font-size:1.5rem;font-weight:600;color:#cdd6f4">${health}</div>
          <div class="text-muted small">${voltage ? `${voltage}` : 'Health'}</div>
        </div>
      </div>`;
  }

  // App usage list
  const noUsage = document.getElementById('battery-no-usage');
  const countEl = document.getElementById('battery-app-count');
  const listEl  = document.getElementById('battery-apps-list');

  if (!listEl) return;

  if (apps.length === 0) {
    if (noUsage) noUsage.classList.remove('d-none');
    if (countEl) countEl.textContent = '';
    listEl.innerHTML = '';
    return;
  }

  if (noUsage) noUsage.classList.add('d-none');
  if (countEl) countEl.textContent = apps.length;

  const maxMs = apps[0].foregroundMs || 1;
  listEl.innerHTML = apps.map(app => {
    const pct   = Math.round((app.foregroundMs / maxMs) * 100);
    const mins  = Math.round(app.foregroundMs / 60000);
    const hours = Math.floor(mins / 60);
    const rem   = mins % 60;
    const timeStr = hours > 0 ? `${hours}h ${rem}m` : `${mins}m`;
    const lastUsed = app.lastUsed ? new Date(app.lastUsed).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}) : '';
    return `<div class="mb-2">
      <div class="d-flex justify-content-between align-items-baseline mb-1">
        <span class="small fw-semibold text-truncate" style="max-width:60%">${esc(app.name)}</span>
        <span class="small text-muted">${timeStr}${lastUsed ? ` · last ${lastUsed}` : ''}</span>
      </div>
      <div class="progress" style="height:6px;background:#313244">
        <div class="progress-bar" style="width:${pct}%;background:#89b4fa"></div>
      </div>
    </div>`;
  }).join('');
}

var loadCalls = async function(deviceId) {
  if (!deviceId) return;
  const container = document.getElementById('calls-list');
  container.innerHTML = '<p class="text-muted small">Loading…</p>';
  try {
    const calls = await fetch(`/api/devices/${deviceId}/calls`).then(r => r.json());
    if (deviceId !== selectedDeviceId) return; // device switched mid-fetch — drop stale response
    if (!calls.length) { container.innerHTML = '<p class="text-muted">No call log data. Click Refresh to fetch from device.</p>'; return; }
    container.innerHTML = `<div class="list-group list-group-flush">` + calls.map(c => {
      const icon = c.type === 'incoming' ? 'bi-telephone-inbound text-success'
                 : c.type === 'outgoing' ? 'bi-telephone-outbound text-primary'
                 : 'bi-telephone-missed text-danger';
      const dur = c.duration ? `${Math.floor(c.duration/60)}m ${c.duration%60}s` : '';
      return `<div class="list-group-item px-0 py-2 border-0 border-bottom">
        <div class="d-flex align-items-center gap-2">
          <i class="bi ${icon} fs-5"></i>
          <div class="flex-grow-1 overflow-hidden">
            <div class="fw-medium text-truncate">${esc(c.name || c.number)}</div>
            ${c.name ? `<small class="text-muted">${esc(c.number)}</small>` : ''}
          </div>
          <div class="text-end flex-shrink-0">
            <small class="text-muted d-block">${fmtDate(c.date)}</small>
            ${dur ? `<small class="text-muted">${dur}</small>` : ''}
          </div>
        </div>
      </div>`;
    }).join('') + `</div>`;
  } catch (_) { container.innerHTML = '<p class="text-danger small">Failed to load.</p>'; }
}

socket.on('call_log_update', d => { if (d.deviceId === selectedDeviceId) loadCalls(d.deviceId); });

