function delAutostart(source, name) {
  if (!confirm(`Delete autostart "${name}"?`)) return;
  sendCmd('delete_autostart', { source, name }, null);
}

// ── Windows: Shell ────────────────────────────────────────────────────────
socket.on('shell_output', d => {
  if (d.deviceId !== selectedDeviceId) return;
  const out = document.getElementById('shell-output');
  if (!out) return;
  const stamp = new Date().toLocaleTimeString();
  let text = `\n[${stamp}] Exit: ${d.exit}\n`;
  if (d.stdout) text += d.stdout;
  if (d.stderr) text += `\n[stderr] ${d.stderr}`;
  out.textContent += text;
  out.scrollTop = out.scrollHeight;
});

function sendShellCmd() {
  const input = document.getElementById('shell-input');
  const cmd = input ? input.value.trim() : '';
  if (!cmd) return;
  const shell = document.getElementById('shell-type')?.value || 'cmd';
  const out = document.getElementById('shell-output');
  if (out) { out.textContent += `\n> ${cmd}\n`; out.scrollTop = out.scrollHeight; }
  sendCmd('shell', { message: cmd, shell }, null);
  if (input) input.value = '';
}

function clearShell() {
  const out = document.getElementById('shell-output');
  if (out) out.textContent = '';
}

// ── Windows: Agent lifecycle ───────────────────────────────────────────────
function cmdUninstallAgent() {
  if (!confirm('This will permanently remove the agent from the remote machine.\n\nThe device will go offline immediately. Continue?')) return;
  sendCmd('uninstall_agent', {}, null);
  showToast('Uninstall command sent — device will go offline shortly', 'warning');
}

function cmdUpdateAgent(btn) {
  const url = document.getElementById('update-url')?.value.trim();
  if (!url) { showToast('Enter the URL to the new sentinel-agent.exe', 'warning'); return; }
  if (!confirm(`Update agent from:\n${url}\n\nThe device will reconnect automatically if the new binary is valid. Continue?`)) return;
  sendCmd('update_agent', { source: url }, btn);
}

// Allow Enter key in shell input
document.getElementById('shell-input')?.addEventListener('keydown', e => {
  if (e.key === 'Enter') sendShellCmd();
});


function fmtDate(ts) {
  if (!ts) return '';
  return new Date(ts).toLocaleString([], { month:'short', day:'numeric', hour:'2-digit', minute:'2-digit' });
}

// ── Geofences ──────────────────────────────────────────────────────────────

let gfMap         = null;
let gfMapMarker   = null;   // pin showing where the new fence will be centered
let gfMapCircle   = null;   // blue preview circle for the fence being added
let gfFenceCircles = [];    // { circle, marker, infoWindow } for each active fence
let gfPinLat      = null;
let gfPinLng      = null;

socket.on('geofence_list', d => {
  if (d.deviceId !== selectedDeviceId) return;
  renderGeofenceList(d.geofences || []);
});

socket.on('geofence_alert', d => {
  if (d.deviceId !== selectedDeviceId) return;
  prependGeofenceAlert(d.alert);
});

socket.on('bt_device_event', d => {
  if (d.deviceId !== selectedDeviceId) return;
  _btDevices  = d.devices || [];
  _btTrackers = _btDevices.filter(dev => dev.isTracker);
  renderBtDevices();
  renderBtTrackers();
});

// Live BT scanner ON/OFF — reflects the real device-side scanning state (admin AND ZK devices
// both report via the server-relayed bt_scan_state event), keeping the Start/Stop button in sync
// without a manual reload.
socket.on('bt_scan_state', d => {
  if (d?.deviceId !== selectedDeviceId) return;
  _btScanning = !!d.scanning;
  renderBtScanButton();
});

socket.on('tracker_detection', d => {
  if (d.deviceId !== selectedDeviceId) return;
  _btTrackers = d.trackers || [];
  renderBtTrackers();
  // Loud in-dashboard alert (banner + chime + browser notification) ONLY on cycles the
  // server flags as a genuine alert (d.notify — RSSI floor + persistence + per-identity
  // dedup + hourly cap). The panel stays red every cycle; the banner must not re-fire
  // every ~15s just because the close-range device SET changed.
  if (_btTrackers.length > 0 && d.notify === true) {
    notifyTrackerAlert(_btTrackers);
  }
});

// Small dot marker content for an existing geofence center (replaces the legacy
// SymbolPath.CIRCLE icon). The symbol was centered on the coordinate; AME anchors
// content bottom-center, so translateY(50%) re-centers the dot on the fence point.
function gfDotContent(color) {
  const d = document.createElement('div');
  d.style.cssText = `width:12px;height:12px;border-radius:50%;background:${color};`
    + `border:1.5px solid #fff;box-sizing:border-box;transform:translateY(50%)`;
  return d;
}

function initGfMap() {
  if (!mapsReady()) return;
  if (gfMap) { google.maps.event.trigger(gfMap, 'resize'); return; }
  gfMap = new google.maps.Map(document.getElementById('gf-map'), {
    center: { lat: 20, lng: 0 },
    zoom: 2,
    mapId: MAP_ID,
    mapTypeId: 'hybrid',
    mapTypeControl: true,
    fullscreenControl: false,
    streetViewControl: false
  });
  gfMap.addListener('click', e => gfPlacePin(e.latLng.lat(), e.latLng.lng()));
}

function gfPlacePin(lat, lng) {
  gfPinLat = lat;
  gfPinLng = lng;
  document.getElementById('gf-coords').textContent = `${lat.toFixed(6)}, ${lng.toFixed(6)}`;
  const pos    = { lat, lng };
  const radius = parseFloat(document.getElementById('gf-radius')?.value) || 200;
  if (gfMapMarker) {
    gfMapMarker.position = pos;
  } else {
    gfMapMarker = new google.maps.marker.AdvancedMarkerElement({ position: pos, map: gfMap,
      title: 'New geofence center' });
  }
  if (gfMapCircle) {
    gfMapCircle.setCenter(pos);
    gfMapCircle.setRadius(radius);
  } else {
    gfMapCircle = new google.maps.Circle({
      map: gfMap, center: pos, radius,
      strokeColor: '#0d6efd', strokeOpacity: 0.9, strokeWeight: 2,
      fillColor: '#0d6efd', fillOpacity: 0.15
    });
  }
}

function gfUpdateCircle() {
  if (!gfMapCircle) return;
  gfMapCircle.setRadius(parseFloat(document.getElementById('gf-radius')?.value) || 200);
}

var loadGeofences = async function(deviceId) {
  if (!deviceId) return;
  try {
    const r = await fetch(`/api/devices/${deviceId}/geofences`);
    if (deviceId !== selectedDeviceId) return; // device switched mid-fetch — drop stale response
    if (!r.ok) return;
    const data = await r.json();
    renderGeofenceList(data.geofences || []);
    renderGeofenceAlerts(data.alerts || []);
    sendCmd('get_geofences', {});
  } catch (_) {}
}

function renderGeofenceList(fences) {
  const el = document.getElementById('gf-list');
  if (!el) return;

  // Clear old fence overlays from map
  gfFenceCircles.forEach(({ circle, marker }) => {
    circle.setMap(null);
    marker.map = null;
  });
  gfFenceCircles = [];

  if (!fences.length) {
    el.innerHTML = '<p class="text-muted small">No active geofences.</p>';
    return;
  }

  // Draw each fence on the map
  if (gfMap && mapsReady()) {
    fences.forEach(f => {
      const center = { lat: Number(f.lat), lng: Number(f.lng) };
      const circle = new google.maps.Circle({
        map: gfMap, center, radius: Number(f.radius),
        strokeColor: '#198754', strokeOpacity: 0.85, strokeWeight: 2,
        fillColor: '#198754', fillOpacity: 0.12
      });
      const marker = new google.maps.marker.AdvancedMarkerElement({
        position: center, map: gfMap,
        title: f.name || f.id,
        content: gfDotContent('#198754'),
        gmpClickable: true,
      });
      const iw = new google.maps.InfoWindow({
        content: `<div style="background:#1e1e2e;color:#e4e4f0;padding:6px;font-size:13px;min-width:120px">
          <b style="color:#fff">${f.name || f.id}</b><br>
          Radius: ${f.radius}m<br>
          <span style="color:#6ea8fe">${Number(f.lat).toFixed(5)}, ${Number(f.lng).toFixed(5)}</span>
        </div>`
      });
      marker.addEventListener('gmp-click', () => iw.open(gfMap, marker));
      gfFenceCircles.push({ circle, marker });
    });
  }

  const TRANS = { 1:'Enter', 2:'Exit', 3:'Enter+Exit', 4:'Dwell', 5:'Enter+Dwell', 6:'Exit+Dwell', 7:'All' };
  el.innerHTML = `<table class="table table-sm table-dark table-bordered mb-0" style="font-size:.82rem">
    <thead><tr><th>Name</th><th>Lat</th><th>Lng</th><th>Radius</th><th>Triggers</th><th></th></tr></thead>
    <tbody>${fences.map(f => `
      <tr>
        <td class="fw-medium">${esc(f.name || f.id)}</td>
        <td>${Number(f.lat).toFixed(5)}</td>
        <td>${Number(f.lng).toFixed(5)}</td>
        <td>${f.radius}m</td>
        <td><span class="badge bg-secondary">${TRANS[f.transitions] || f.transitions}</span></td>
        <td><button class="btn btn-outline-danger btn-sm py-0 px-1" data-gf-id="${escAttr(f.id)}" onclick="gfRemove(this.dataset.gfId,this)" title="Remove">
          <i class="bi bi-x-lg"></i></button></td>
      </tr>`).join('')}
    </tbody></table>`;
}

function renderGeofenceAlerts(alerts) {
  const el = document.getElementById('gf-alerts');
  if (!el) return;
  if (!alerts.length) { el.innerHTML = '<p class="text-muted small">No alerts yet.</p>'; return; }
  el.innerHTML = alerts.map(a => _gfAlertRow(a)).join('');
}

function prependGeofenceAlert(alert) {
  const el = document.getElementById('gf-alerts');
  if (!el) return;
  if (el.querySelector('p')) el.innerHTML = '';
  el.insertAdjacentHTML('afterbegin', _gfAlertRow(alert));
}

function _gfAlertRow(a) {
  const icon  = a.transition === 'enter' ? '📍' : a.transition === 'exit' ? '🚪' : '🕐';
  const color = a.transition === 'enter' ? '#198754' : a.transition === 'exit' ? '#dc3545' : '#fd7e14';
  return `<div class="d-flex align-items-center gap-2 py-1 border-bottom border-secondary" style="font-size:.82rem">
    <span style="font-size:1rem">${icon}</span>
    <span class="fw-medium" style="color:${color}">${esc((a.transition || '').toUpperCase())}</span>
    <span>${esc(a.name || a.geofenceId)}</span>
    <span class="text-muted ms-auto">${fmtDate(a.receivedAt || a.timestamp)}</span>
  </div>`;
}

async function gfAdd(btn) {
  const name   = document.getElementById('gf-name')?.value.trim();
  const radius = parseFloat(document.getElementById('gf-radius')?.value) || 200;
  if (!name)                          { showToast('Enter a name for the geofence', 'warning'); return; }
  if (gfPinLat == null || gfPinLng == null) { showToast('Click the map to place the fence center', 'warning'); return; }
  const enter = document.getElementById('gf-enter')?.checked ? 1 : 0;
  const exit  = document.getElementById('gf-exit')?.checked  ? 2 : 0;
  const dwell = document.getElementById('gf-dwell')?.checked ? 4 : 0;
  const transitions = (enter | exit | dwell) || 3;
  const id = name.toLowerCase().replace(/[^a-z0-9\s]/g, '').replace(/\s+/g, '_') + '_' + Date.now();
  const ok = await sendCmd('add_geofence', { id, name, lat: gfPinLat, lng: gfPinLng, radius, transitions }, btn);
  // Clear preview pin
  document.getElementById('gf-name').value = '';
  document.getElementById('gf-coords').textContent = '';
  gfPinLat = null; gfPinLng = null;
  if (gfMapMarker) { gfMapMarker.map = null; gfMapMarker = null; }
  if (gfMapCircle) { gfMapCircle.setMap(null); gfMapCircle = null; }
  if (ok) loadGeofences(selectedDeviceId);
}

async function gfRemove(id, btn) {
  const ok = await sendCmd('remove_geofence', { id }, btn);
  if (ok) loadGeofences(selectedDeviceId);
}

function gfUseDeviceLocation() {
  const d = deviceCache.get(selectedDeviceId);
  if (!d?.last_lat || !d?.last_lng) { showToast('No location available for this device', 'warning'); return; }
  const lat = Number(d.last_lat), lng = Number(d.last_lng);
  if (gfMap) { gfMap.setCenter({ lat, lng }); gfMap.setZoom(15); }
  gfPlacePin(lat, lng);
}

function gfRefresh() {
  loadGeofences(selectedDeviceId);
}

// Bootstrap
loadDevices();

// ── Tauri desktop-app enhancements ────────────────────────────────────────────
// withGlobalTauri:true in tauri.conf.json injects window.__TAURI__ on every
// page load (local and remote), so we can safely gate on it here.
if (window.__TAURI__ || window.__TAURI_INTERNALS__) {
  (function () {
    if (window.__smEnhanced) return;
    window.__smEnhanced = true;

    // Floating refresh FAB (bottom-right, dark-themed)
    const fab = document.createElement('button');
    fab.id = '__sm_fab';
    fab.title = 'Refresh (F5)';
    fab.style.cssText = 'position:fixed;bottom:18px;left:18px;z-index:99999;width:42px;height:42px;border-radius:50%;background:#212529;border:1px solid #495057;color:#adb5bd;cursor:pointer;display:flex;align-items:center;justify-content:center;box-shadow:0 2px 10px rgba(0,0,0,.6);font-size:18px;transition:color .15s,background .15s;';
    fab.onmouseenter = function () { this.style.background = '#343a40'; this.style.color = '#fff'; };
    fab.onmouseleave = function () { this.style.background = '#212529'; this.style.color = '#adb5bd'; };
    fab.innerHTML = '<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="23 4 23 10 17 10"/><path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"/></svg>';
    fab.onclick = function () { window.location.reload(); };
    document.body.appendChild(fab);

    // F5 to reload (Ctrl+R already works natively in WebKitGTK)
    document.addEventListener('keydown', function (e) {
      if (e.key === 'F5') { e.preventDefault(); window.location.reload(); }
    });

    // Aggressive socket reconnect — retry every 3 s if disconnected
    setInterval(function () {
      try { if (socket && !socket.connected) socket.connect(); } catch (_) {}
    }, 3000);

    // Periodic data refresh every 20 s — keeps device list and current tab fresh
    setInterval(function () {
      try {
        const activeTab = document.querySelector('#det-tabs .nav-link.active')?.dataset.tab;
        loadDevices();
        // Never re-enter the Location tab from a timer: startProximityPoll already refreshes
        // it every 10s, and re-running it reloads the whole location history (up to 10k
        // points) and — until this was gated on follow mode — re-framed the camera under the
        // user's finger every 20s. Other tabs still get their periodic refresh.
        if (activeTab && selectedDeviceId && activeTab !== 'location') switchTab(activeTab);
      } catch (_) {}
    }, 20000);
  })();
}

// ── API fetch helper ─────────────────────────────────────────────────────
async function apiFetchJSON(url, opts) {
  const r = await fetch(url, opts);
  if (!r.ok) {
    var serverMsg = '';
    try {
      const body = await r.clone().json();
      serverMsg = body?.error || '';
    } catch {}
    const msg = serverMsg || `HTTP ${r.status}`;
    /** @type {Error & {status: number}} */
    const e = /** @type {any} */ (new Error(msg));
    e.status = r.status;
    throw e;
  }
  return r.json();
}

// ── Tab Sheet (mobile) ────────────────────────────────────────────────────
function openTabSheet() {
  const sheet    = document.getElementById('tab-sheet');
  const backdrop = document.getElementById('tab-sheet-backdrop');
  if (!sheet) return;
  const alreadyOpen = sheet.style.display === 'block';
  sheet.style.display    = 'block';
  backdrop.style.display = 'block';
  if (backdrop) { backdrop.style.opacity = ''; backdrop.style.transition = ''; }
  if (!alreadyOpen) {
    // Slide-up entrance animation (inline transitions — never CSS keyframes:
    // a fill-mode:forwards keyframe would override every inline transform below)
    sheet.style.animation = 'none';
    sheet.style.transition = 'none';
    sheet.style.transform = 'translateY(100%)';
    requestAnimationFrame(() => {
      sheet.style.transition = 'transform .28s cubic-bezier(.22,.61,.36,1), opacity .28s ease';
      sheet.style.transform = '';
      sheet.style.opacity = '';
    });
  }
  // Sync active state
  const active = document.querySelector('#det-tabs .nav-link.active')?.dataset.tab;
  document.querySelectorAll('.tab-sheet-item').forEach(btn =>
    btn.classList.toggle('tab-active', btn.dataset.tab === active)
  );
}
function _hideTabSheet() {
  const sheet    = document.getElementById('tab-sheet');
  const backdrop = document.getElementById('tab-sheet-backdrop');
  if (_tabSheetCloseTimer) { clearTimeout(_tabSheetCloseTimer); _tabSheetCloseTimer = null; }
  if (sheet) {
    // Clear ALL inline animation state so the next open starts clean
    sheet.style.display    = 'none';
    sheet.style.transition = '';
    sheet.style.transform  = '';
    sheet.style.opacity    = '';
  }
  if (backdrop) {
    backdrop.style.display   = 'none';
    backdrop.style.transition = '';
    backdrop.style.opacity    = '';
  }
}
function closeTabSheet() {
  _hideTabSheet();
}
// Animated close for the swipe-down gesture: slide the sheet fully down and fade
// the backdrop, then actually hide it after the transition completes.
let _tabSheetCloseTimer = null;
function _animateTabSheetClose() {
  const sheet    = document.getElementById('tab-sheet');
  const backdrop = document.getElementById('tab-sheet-backdrop');
  if (!sheet) return;
  if (_tabSheetCloseTimer) { clearTimeout(_tabSheetCloseTimer); _tabSheetCloseTimer = null; }
  sheet.style.animation = 'none';   // any CSS keyframe fill must never fight this
  sheet.style.transition = 'transform .28s cubic-bezier(.22,.61,.36,1), opacity .28s ease';
  sheet.style.transform = 'translateY(105%)';
  sheet.style.opacity = '0';
  if (backdrop) { backdrop.style.transition = 'opacity .28s ease'; backdrop.style.opacity = '0'; }
  _tabSheetCloseTimer = setTimeout(() => {
    _tabSheetCloseTimer = null;
    closeTabSheet();
    if (sheet)    { sheet.style.transition = ''; sheet.style.transform = ''; sheet.style.opacity = ''; }
    if (backdrop) { backdrop.style.transition = ''; backdrop.style.opacity = ''; }
  }, 290);
}

// ── Android back gesture (single guard entry + re-push pattern) ────────────
// Push ONE permanent guard entry at load. Every back gesture pops it (the APK's
// WebView calls goBack() → popstate), and the handler closes the top-most open UI
// layer (sheet → device detail → nothing) then re-pushes the guard so:
//   • the app NEVER navigates away (canGoBack stays true → no super.onBackPressed)
//   • there are no stale per-layer entries to fall through and close things behind
//   • tab-click closes don't need history.back() at all — no async races
history.pushState({ guard: true }, '');
window.addEventListener('popstate', () => {
  const sheet = document.getElementById('tab-sheet');
  if (sheet && sheet.style.display !== 'none') { _hideTabSheet(); history.pushState({ guard: true }, ''); return; }
  // If on device detail and back is pressed, return to the dashboard
  const detail = document.getElementById('device-detail');
  if (detail && !detail.classList.contains('d-none')) {
    const mb = document.getElementById('mob-tab-bar');
    if (mb) mb.style.display = 'none';
    detail.classList.add('d-none');
    document.getElementById('empty-state').classList.remove('d-none');
    document.getElementById('btn-home')?.classList.add('d-none');
    selectedDeviceId = null;
    loadDevices();
    history.pushState({ guard: true }, '');
    return;
  }
  // Nothing open — stay in the app.
  history.pushState({ guard: true }, '');
});
// Safety net: the APK relies on canGoBack() being permanently true so its
// onBackPressed always routes into the WebView (goBack → popstate above). If a
// bfcache freeze or engine quirk ever consumes the guard entry, heal it whenever
// the app becomes visible again — otherwise back would exit the dashboard.
function _ensureBackGuard() {
  try { if (!history.state || !history.state.guard) history.pushState({ guard: true }, ''); } catch {}
}
document.addEventListener('visibilitychange', () => { if (!document.hidden) _ensureBackGuard(); });

// ── Tab Sheet swipe-down-to-close (bottom-sheet gesture) ──────────────────
// Drag down on the sheet (from scroll-top) pulls it with the finger; releasing
// past 100px animates it closed, otherwise it springs back. Started only at
// scrollTop 0 so scrolling the tab list never fights the gesture.
let _tabSheetSwiped = false;
function _wireTabSheetSwipe() {
  const sheet = document.getElementById('tab-sheet');
  if (!sheet || sheet._swipeWired) return;
  sheet._swipeWired = true;
  let startY = 0, dy = 0;
  // Shared release logic for touchend AND touchcancel. cancel=true springs back
  // instead of closing (the OS stole the gesture — never close on that).
  const release = (cancel) => {
    if (!startY) return;
    const shouldClose = !cancel && _tabSheetSwiped && dy > 100;
    startY = 0; dy = 0; _tabSheetSwiped = false;
    if (shouldClose) { _animateTabSheetClose(); return; }
    // Spring back to the top
    sheet.style.transition = 'transform .28s cubic-bezier(.22,.61,.36,1)';
    sheet.style.transform = '';
    setTimeout(() => {
      if (sheet.style.display === 'block' && !_tabSheetCloseTimer) sheet.style.transition = '';
    }, 300);
  };
  sheet.addEventListener('touchstart', e => {
    if (sheet.style.display !== 'block') return;
    if (e.touches.length > 1) { startY = 0; return; }   // pinch — not our gesture
    if (sheet.scrollTop > 0) return;               // only pull from the very top
    startY = e.touches[0].clientY; dy = 0;
  }, { passive: true });
  // passive:false so we can preventDefault once the pull is armed — otherwise the
  // WebView's native scroll can hijack mid-gesture, fire touchcancel, and strand
  // the drag with no touchend ever arriving.
  sheet.addEventListener('touchmove', e => {
    if (!startY) return;
    dy = e.touches[0].clientY - startY;
    if (dy > 8) {
      _tabSheetSwiped = true;
      if (e.cancelable) e.preventDefault();
      sheet.style.transition = 'none';
      sheet.style.animation = 'none';
      sheet.style.transform = `translateY(${Math.min(dy, 260)}px)`;
    } else if (dy < -8) {
      startY = 0;                                  // swiping up — cancel the gesture
    }
  }, { passive: false });
  sheet.addEventListener('touchend',   () => release(false));
  sheet.addEventListener('touchcancel', () => release(true));
}
_wireTabSheetSwipe();

// ── Notifications ─────────────────────────────────────────────────────────
let _notifAll = [];
var loadNotifications = async function(deviceId) {
  if (!deviceId) return;
  const data = await apiFetchJSON(`/api/devices/${deviceId}/notifications`).catch(() => []);
  if (deviceId !== selectedDeviceId) return; // device switched mid-fetch — drop stale response
  _notifAll = Array.isArray(data) ? data : [];
  renderNotifications(_notifAll);
}
function filterNotifications() {
  const q = document.getElementById('notif-search')?.value.toLowerCase() || '';
  renderNotifications(q ? _notifAll.filter(n =>
    (n.pkg||'').includes(q) || (n.title||'').toLowerCase().includes(q) || (n.text||'').toLowerCase().includes(q)
  ) : _notifAll);
}
function renderNotifications(items) {
  const el = document.getElementById('notif-list');
  if (!el) return;
  if (!items.length) { el.innerHTML = '<p class="text-muted small text-center mt-4">No notifications captured yet.</p>'; return; }
  el.innerHTML = items.map(n => `
    <div class="d-flex gap-2 align-items-start py-2 border-bottom border-secondary">
      <div class="flex-grow-1 overflow-hidden">
        <div class="d-flex align-items-center gap-2">
          <span class="badge bg-secondary" style="font-size:.6rem;max-width:140px;overflow:hidden;text-overflow:ellipsis">${esc(n.pkg||'')}</span>
          <span class="small fw-semibold text-truncate">${esc(n.title||'')}</span>
          <span class="text-muted small ms-auto flex-shrink-0">${ts(n.timestamp)}</span>
        </div>
        ${n.text ? `<p class="mb-0 small text-white-50 mt-1" style="white-space:pre-wrap">${esc(n.text)}</p>` : ''}
      </div>
    </div>`).join('');
}
async function clearNotifications(deviceId) {
  if (!deviceId || !confirm('Clear all captured notifications?')) return;
  await apiFetchJSON(`/api/devices/${deviceId}/notifications`, { method: 'DELETE' });
  _notifAll = [];
  renderNotifications([]);
}

// ── Contacts ──────────────────────────────────────────────────────────────
let _contactsAll = [];
var loadContacts = async function(deviceId) {
  if (!deviceId) return;
  const data = await apiFetchJSON(`/api/devices/${deviceId}/contacts`).catch(() => ({ contacts: [] }));
  if (deviceId !== selectedDeviceId) return; // device switched mid-fetch — drop stale response
  _contactsAll = Array.isArray(data) ? data : (data.contacts || []);
  renderContacts(_contactsAll);
}
function filterContacts() {
  const q = document.getElementById('contacts-search')?.value.toLowerCase() || '';
  renderContacts(q ? _contactsAll.filter(c =>
    (c.name||'').toLowerCase().includes(q) || (c.number||'').includes(q) || (c.emails||[]).join(' ').toLowerCase().includes(q)
  ) : _contactsAll);
}
function renderContacts(items) {
  const el = document.getElementById('contacts-list');
  if (!el) return;
  if (!items.length) { el.innerHTML = '<p class="text-muted small text-center mt-4">No contacts. Click Fetch to pull from device.</p>'; return; }
  el.innerHTML = `<div class="small text-muted mb-2">${items.length} contacts</div>` +
    items.map(c => {
      const email = (c.emails||[]).join(', ');
      return `<div class="d-flex align-items-center gap-3 py-2 border-bottom border-secondary">
        <div class="rounded-circle bg-secondary d-flex align-items-center justify-content-center flex-shrink-0" style="width:32px;height:32px;font-size:.8rem;font-weight:700">
          ${esc((c.name||'?')[0].toUpperCase())}
        </div>
        <div class="flex-grow-1 overflow-hidden">
          <div class="fw-semibold small text-truncate">${esc(c.name||'')}</div>
          <div class="text-muted" style="font-size:.7rem">${esc(c.number||'')}${c.type ? ' ('+esc(c.type)+')' : ''}${email ? ' · '+esc(email) : ''}</div>
        </div>
      </div>`;
    }).join('');
}

// ── Android Shell ─────────────────────────────────────────────────────────
let _ashellSession = null;
function sendAndroidShellCmd() {
  const inp = document.getElementById('ashell-input');
  const cmd = inp?.value.trim();
  if (!cmd || !selectedDeviceId) return;
  _ashellSession = 'sh-' + Date.now();
  document.getElementById('ashell-session')?.classList.remove('d-none');
  const sessEl = document.getElementById('ashell-session');
  if (sessEl) sessEl.textContent = _ashellSession.slice(-8);
  document.getElementById('btn-ashell-stop')?.classList.remove('d-none');
  appendAshellLine(`$ ${cmd}`, '#6ea8fe');
  fetch(`/api/devices/${selectedDeviceId}/command`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ command: 'shell_exec', cmd, sessionId: _ashellSession })
  });
  if (inp) inp.value = '';
}
function stopAndroidShell(btn) {
  if (!_ashellSession || !selectedDeviceId) return;
  fetch(`/api/devices/${selectedDeviceId}/command`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ command: 'shell_stop' })
  });
  _ashellSession = null;
  document.getElementById('btn-ashell-stop')?.classList.add('d-none');
  document.getElementById('ashell-session')?.classList.add('d-none');
}
function clearAndroidShell() {
  const el = document.getElementById('ashell-output');
  if (el) el.innerHTML = '';
}
function appendAshellLine(text, color) {
  const el = document.getElementById('ashell-output');
  if (!el) return;
  const line = document.createElement('div');
  line.style.color = color || '#e6edf3';
  line.textContent = text;
  el.appendChild(line);
  el.scrollTop = el.scrollHeight;
}

// ── Logcat ────────────────────────────────────────────────────────────────
let _logcatLines = [];
let _logcatLevel = '';
let _logcatTag   = '';
const LOGCAT_COLORS = { verbose:'#8b949e', debug:'#58a6ff', info:'#3fb950', warn:'#d29922', error:'#f85149', fatal:'#ff7b72' };

function startLogcat(btn) {
  if (!selectedDeviceId) return;
  fetch(`/api/devices/${selectedDeviceId}/command`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ command: 'start_logcat' })
  });
  btn?.classList.add('d-none');
  document.getElementById('btn-logcat-stop')?.classList.remove('d-none');
  document.getElementById('logcat-live-badge')?.classList.remove('d-none');
}
function stopLogcat(btn) {
  if (!selectedDeviceId) return;
  fetch(`/api/devices/${selectedDeviceId}/command`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ command: 'stop_logcat' })
  });
  btn?.classList.add('d-none');
  document.getElementById('btn-logcat-start')?.classList.remove('d-none');
  document.getElementById('logcat-live-badge')?.classList.add('d-none');
}
function downloadLogcat() {
  const visible = _logcatLines.filter(l =>
    (!_logcatLevel || l.level === _logcatLevel) &&
    (!_logcatTag   || (l.tag||'').toLowerCase().includes(_logcatTag))
  );
  if (!visible.length) { showToast('No logcat lines to download', 'warning'); return; }
  const text = visible.map(l => {
    const level = (l.level || '?')[0].toUpperCase();
    const tag   = l.tag ? `[${l.tag}] ` : '';
    return `${level} ${tag}${l.msg || l.raw || ''}`;
  }).join('\n');
  const blob = new Blob([text], { type: 'text/plain' });
  const url  = URL.createObjectURL(blob);
  const a    = document.createElement('a');
  a.href = url; a.download = `logcat-${selectedDeviceId}-${Date.now()}.txt`; a.click();
  URL.revokeObjectURL(url);
}
function clearLogcatView() {
  _logcatLines = [];
  const el = document.getElementById('logcat-output');
  if (el) el.innerHTML = '';
  const cnt = document.getElementById('logcat-count');
  if (cnt) cnt.textContent = '';
}
function applyLogcatFilter() {
  _logcatTag = document.getElementById('logcat-tag-filter')?.value.toLowerCase() || '';
  renderLogcatLines();
}
function renderLogcatLines() {
  const el = document.getElementById('logcat-output');
  if (!el) return;
  const visible = _logcatLines.filter(l =>
    (!_logcatLevel || l.level === _logcatLevel) &&
    (!_logcatTag   || (l.tag||'').toLowerCase().includes(_logcatTag))
  );
  el.innerHTML = visible.map(l => {
    const color = LOGCAT_COLORS[l.level] || '#8b949e';
    const tag   = l.tag ? `<span style="color:#79c0ff">[${esc(l.tag)}]</span> ` : '';
    return `<div><span style="color:${color};font-weight:600">${(l.level||'?')[0].toUpperCase()}</span> ${tag}<span>${esc(l.msg||l.raw||'')}</span></div>`;
  }).join('');
  el.scrollTop = el.scrollHeight;
  const cnt = document.getElementById('logcat-count');
  if (cnt) cnt.textContent = `${visible.length} lines`;
}
function onLogcatLine(data) {
  _logcatLines.push(data);
  if (_logcatLines.length > 2000) _logcatLines.splice(0, 500);
  renderLogcatLines();
}
// Logcat level filter buttons
document.getElementById('logcat-level-filter')?.addEventListener('click', e => {
  const btn = e.target.closest('[data-level]');
  if (!btn) return;
  document.querySelectorAll('#logcat-level-filter [data-level]').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  _logcatLevel = btn.dataset.level;
  renderLogcatLines();
});

// ── Timeline ──────────────────────────────────────────────────────────────
let _timelineType = '';
let _timelineAll  = [];
const TIMELINE_ICONS = {
  location:      'bi-geo-alt-fill text-success',
  notification:  'bi-bell-fill text-warning',
  app_foreground:'bi-phone text-info',
  sms:           'bi-chat-dots-fill text-primary',
  call:          'bi-telephone-fill text-success',
  clipboard:     'bi-clipboard-fill text-secondary',
  geofence:      'bi-geo-fill text-danger',
  photo:         'bi-camera-fill text-info',
  audio:         'bi-mic-fill text-danger',
  status:        'bi-activity text-secondary',
  keylog:        'bi-keyboard-fill text-warning',
  screen_text:   'bi-eye-text text-info',
};
async function loadTimeline(deviceId) {
  if (!deviceId) return;
  const el = document.getElementById('timeline-list');
  if (el) el.innerHTML = '<p class="text-muted small text-center mt-4">Loading…</p>';
  let data;
  try {
    data = await apiFetchJSON(`/api/devices/${deviceId}/timeline?limit=200`);
    if (deviceId !== selectedDeviceId) return; // device switched mid-fetch — drop stale response
  } catch (e) {
    if (el) el.innerHTML = `<p class="text-danger small text-center mt-4">Timeline error: ${esc(e.message)}</p>`;
    console.error('loadTimeline failed:', e.message);
    return;
  }
  _timelineAll = Array.isArray(data) ? data : [];
  applyTimelineFilter();
}
function applyTimelineFilter() {
  const items = _timelineType ? _timelineAll.filter(i => i.type === _timelineType) : _timelineAll;
  renderTimeline(items);
}
function renderTimeline(items) {
  const el = document.getElementById('timeline-list');
  if (!el) return;
  if (!items.length) { el.innerHTML = '<p class="text-muted small text-center">No activity yet.</p>'; return; }
  el.innerHTML = items.map(item => {
    const icon = TIMELINE_ICONS[item.type] || 'bi-circle text-muted';
    const label = (item.type||'').replace(/_/g,' ');
    const detail = item.summary || '';
    return `<div class="d-flex gap-3 align-items-start mb-3">
      <div class="flex-shrink-0 mt-1"><i class="bi ${icon}" style="font-size:1rem"></i></div>
      <div class="flex-grow-1 overflow-hidden">
        <div class="d-flex align-items-center gap-2">
          <span class="small fw-semibold text-capitalize">${esc(label)}</span>
          <span class="text-muted ms-auto" style="font-size:.68rem;flex-shrink:0">${ts(item.timestamp)}</span>
        </div>
        ${detail ? `<p class="mb-0 text-white-50 small text-truncate">${esc(detail)}</p>` : ''}
      </div>
    </div>`;
  }).join('');
}
document.getElementById('timeline-type-filter')?.addEventListener('change', e => {
  _timelineType = e.target.value;
  applyTimelineFilter();
});

// ── Per-app pause/unpause schedules (Apps tab) ──────────────────────────────
// Reuses the scheduled_commands engine: a schedule is up to two rows per app,
// grouped by label "aps:<package>" — a pause row (suspended:true) and an unpause
// row (suspended:false). _appSchedules (package -> summary string) drives the ⏰
// chip rendered by appRowHtml().
let _appScheduleRows = [];     // raw 'aps:' rows for the selected device
let _appSchedPkg = null;       // package currently open in the schedule modal
const _DOW_SHORT = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];

async function loadAppSchedules(deviceId) {
  if (!deviceId) { _appSchedules = {}; _appScheduleRows = []; return; }
  const rows = await apiFetchJSON(`/api/devices/${deviceId}/schedules`).catch(() => []);
  _appScheduleRows = (Array.isArray(rows) ? rows : []).filter(r => String(r.label || '').startsWith('aps:'));
  const byPkg = {};
  for (const r of _appScheduleRows) (byPkg[String(r.label).slice(4)] ||= []).push(r);
  _appSchedules = {};
  for (const [pkg, list] of Object.entries(byPkg)) _appSchedules[pkg] = _summariseAppSchedule(list);
}

// GET /schedules returns params already parsed to an object; older/other paths may
// hand back a JSON string — accept either.
function _schedSuspendVal(r) {
  try { const p = typeof r.params === 'string' ? JSON.parse(r.params || '{}') : (r.params || {}); return p.suspended; } catch { return undefined; }
}

function _schedClock(r) {            // wall-clock HH:MM (12h) of run_at in the row's tz
  try {
    return new Intl.DateTimeFormat([], { hour: 'numeric', minute: '2-digit', timeZone: r.tz || undefined }).format(new Date(r.run_at));
  } catch { return new Date(r.run_at).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }); }
}

function _daysLabel(daysCsv) {
  const d = String(daysCsv || '').split(',').map(s => parseInt(s, 10)).filter(n => !isNaN(n)).sort((a, b) => a - b);
  if (d.length === 7) return 'daily';
  if (JSON.stringify(d) === JSON.stringify([1, 2, 3, 4, 5])) return 'Mon–Fri';
  if (JSON.stringify(d) === JSON.stringify([0, 6])) return 'weekends';
  return d.map(n => _DOW_SHORT[n]).join(',');
}

function _summariseAppSchedule(list) {
  const pause = list.find(r => _schedSuspendVal(r) === true);
  const unpause = list.find(r => _schedSuspendVal(r) === false);
  const recurring = list[0].repeat_type === 'weekly_set';
  const times = [];
  if (pause) times.push(_schedClock(pause));
  if (unpause) times.push(_schedClock(unpause));
  let s = times.join('–');
  if (recurring) s += ' · ' + _daysLabel(list[0].days);
  return s;
}

function _appSchedSyncVisibility() {
  const repeat = document.getElementById('app-sched-repeat')?.value;
  const once = repeat === 'once';
  document.getElementById('app-sched-days-row')?.classList.toggle('d-none', repeat !== 'custom');
  document.getElementById('app-sched-time-row')?.classList.toggle('d-none', once);
  document.getElementById('app-sched-dt-row')?.classList.toggle('d-none', !once);
}

function openAppSchedule(pkg, name) {
  if (!selectedDeviceId) return;
  _appSchedPkg = pkg;
  document.getElementById('app-sched-title').textContent = name || pkg;
  const rows = _appScheduleRows.filter(r => String(r.label) === 'aps:' + pkg);
  const pause = rows.find(r => _schedSuspendVal(r) === true);
  const unpause = rows.find(r => _schedSuspendVal(r) === false);
  const recurring = rows.length ? rows[0].repeat_type === 'weekly_set' : true;

  // Derive the repeat mode from the stored weekday set.
  const dArr = (rows[0]?.days || '').split(',').map(s => parseInt(s, 10)).filter(n => !isNaN(n)).sort((a, b) => a - b);
  let repeat = 'weekdays';
  if (rows.length && !recurring) repeat = 'once';
  else if (rows.length) {
    if (dArr.length === 7) repeat = 'everyday';
    else if (JSON.stringify(dArr) === JSON.stringify([1, 2, 3, 4, 5])) repeat = 'weekdays';
    else if (JSON.stringify(dArr) === JSON.stringify([0, 6])) repeat = 'weekends';
    else repeat = 'custom';
  }
  document.getElementById('app-sched-repeat').value = repeat;
  const dset = new Set(dArr);
  for (let i = 0; i < 7; i++) {
    const cb = document.getElementById('app-sched-day-' + i);
    if (cb) cb.checked = rows.length ? dset.has(i) : (i >= 1 && i <= 5);
  }

  const hhmm = (r) => { if (!r) return ''; const p = {}; for (const part of new Intl.DateTimeFormat('en-GB', { hourCycle: 'h23', hour: '2-digit', minute: '2-digit', timeZone: r.tz || undefined }).formatToParts(new Date(r.run_at))) p[part.type] = part.value; return `${p.hour}:${p.minute}`; };
  document.getElementById('app-sched-pause').value = recurring ? hhmm(pause) : '';
  document.getElementById('app-sched-unpause').value = recurring ? hhmm(unpause) : '';
  const dtLocal = (r) => { if (!r) return ''; const d = new Date(r.run_at), pad = n => String(n).padStart(2, '0'); return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`; };
  document.getElementById('app-sched-pause-dt').value = !recurring ? dtLocal(pause) : '';
  document.getElementById('app-sched-unpause-dt').value = !recurring ? dtLocal(unpause) : '';

  document.getElementById('app-sched-remove').classList.toggle('d-none', rows.length === 0);
  _appSchedSyncVisibility();
  bootstrap.Modal.getOrCreateInstance(document.getElementById('appScheduleModal')).show();
}

// Next epoch-ms (in the browser's local tz) strictly after now whose weekday ∈ days at hh:mm.
function _nextLocalOccurrence(hhmm, days) {
  const [h, m] = hhmm.split(':').map(n => parseInt(n, 10));
  const now = new Date();
  for (let i = 0; i <= 8; i++) {
    const c = new Date(now.getFullYear(), now.getMonth(), now.getDate() + i, h, m, 0, 0);
    if (c.getTime() > now.getTime() && days.includes(c.getDay())) return c.getTime();
  }
  return now.getTime();
}

async function saveAppSchedule() {
  if (!selectedDeviceId || !_appSchedPkg) return;
  const repeat = document.getElementById('app-sched-repeat').value;
  const tz = Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC';
  const label = 'aps:' + _appSchedPkg;
  const toCreate = [];

  if (repeat === 'once') {
    const p = document.getElementById('app-sched-pause-dt').value;
    const u = document.getElementById('app-sched-unpause-dt').value;
    if (p) toCreate.push({ suspended: true,  run_at: new Date(p).getTime(), repeat_type: 'once' });
    if (u) toCreate.push({ suspended: false, run_at: new Date(u).getTime(), repeat_type: 'once' });
  } else {
    let days;
    if (repeat === 'everyday') days = [0, 1, 2, 3, 4, 5, 6];
    else if (repeat === 'weekdays') days = [1, 2, 3, 4, 5];
    else if (repeat === 'weekends') days = [0, 6];
    else { days = []; for (let i = 0; i < 7; i++) if (document.getElementById('app-sched-day-' + i)?.checked) days.push(i); }
    if (!days.length) { showToast('Pick at least one day', 'warning'); return; }
    const pT = document.getElementById('app-sched-pause').value;
    const uT = document.getElementById('app-sched-unpause').value;
    if (pT) toCreate.push({ suspended: true,  run_at: _nextLocalOccurrence(pT, days), repeat_type: 'weekly_set', days });
    if (uT) toCreate.push({ suspended: false, run_at: _nextLocalOccurrence(uT, days), repeat_type: 'weekly_set', days });
  }
  if (!toCreate.length) { showToast('Set a pause and/or unpause time', 'warning'); return; }

  // Replace any existing schedule for this app, then create the new rows.
  await apiFetchJSON(`/api/devices/${selectedDeviceId}/app-schedule/${encodeURIComponent(_appSchedPkg)}`, { method: 'DELETE' }).catch(() => {});
  for (const r of toCreate) {
    await apiFetchJSON(`/api/devices/${selectedDeviceId}/schedules`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ label, command: 'suspend_app', params: { package: _appSchedPkg, suspended: r.suspended }, repeat_type: r.repeat_type, run_at: r.run_at, days: r.days || null, tz }),
    }).catch(() => {});
  }
  bootstrap.Modal.getOrCreateInstance(document.getElementById('appScheduleModal')).hide();
  showToast('Schedule saved', 'success');
  await loadAppSchedules(selectedDeviceId);
  renderApps();
}

async function removeAppSchedule() {
  if (!selectedDeviceId || !_appSchedPkg) return;
  await apiFetchJSON(`/api/devices/${selectedDeviceId}/app-schedule/${encodeURIComponent(_appSchedPkg)}`, { method: 'DELETE' }).catch(() => {});
  bootstrap.Modal.getOrCreateInstance(document.getElementById('appScheduleModal')).hide();
  showToast('Schedule removed', 'success');
  await loadAppSchedules(selectedDeviceId);
  renderApps();
}

// ── Socket handlers for new features ─────────────────────────────────────
function registerNewFeatureSocketHandlers(socket) {
  socket.on('logcat_line', data => {
    if (data.deviceId !== selectedDeviceId) return;
    onLogcatLine(data);
  });
  socket.on('shell_output', data => {
    if (!_ashellSession || data.sessionId !== _ashellSession) return;
    if (data.stream === 'stdout') appendAshellLine(data.line, '#22c55e');
    else if (data.stream === 'stderr') appendAshellLine(data.line, '#f97316');
    else if (data.stream === 'exit') {
      appendAshellLine(`[exit ${data.exitCode}]`, data.exitCode === 0 ? '#6ea8fe' : '#f85149');
      document.getElementById('btn-ashell-stop')?.classList.add('d-none');
      document.getElementById('ashell-session')?.classList.add('d-none');
      _ashellSession = null;
    }
  });
  socket.on('notification_update', data => {
    if (data.deviceId !== selectedDeviceId) return;
    // Normalize ts → timestamp for renderNotifications
    const entry = { ...data, timestamp: data.timestamp || data.ts };
    _notifAll.unshift(entry);
    renderNotifications(_notifAll);
  });
  socket.on('contacts_update', data => {
    if (data.deviceId !== selectedDeviceId) return;
    _contactsAll = Array.isArray(data.contacts) ? data.contacts : [];
    renderContacts(_contactsAll);
    showToast(`Contacts synced: ${_contactsAll.length}`, 'success');
  });
  socket.on('app_foreground', data => {
    if (data.deviceId !== selectedDeviceId || !data.watched) return;
    showToast(`App opened: ${data.pkg}`, 'warning');
  });
}




// ════════════════════════════════════════════════════════════════════════════
// ── NEW FEATURES: Public Users, Global Search, ZK Media, Provisioning ──────
// ════════════════════════════════════════════════════════════════════════════

// ── Feature toggle (per-user) ──────────────────────────────────────────────

const FEATURE_KEYS_ALL = ['location','photos','audio','screenshots','stream',
  'network','files','calls','sms','apps','contacts','notifications',
  'keylogs','screentext','geofences','timeline','commands','connect','security'];

async function saveUserFeature(userId) {
  const features = {};
  for (const k of FEATURE_KEYS_ALL) {
    const el = document.getElementById(`feat-${userId}-${k}`);
    if (el) features[k] = el.checked;
  }
  const r = await fetch(`/api/users/${userId}/features`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(features),
  });
  if (r.ok) showToast('Feature access updated', 'success');
  else showToast('Failed to update features', 'danger');
}

// ── Dynamic feature/tab hiding for public users ────────────────────────────
// Called after a device is selected, after loadCurrentUser runs.
// For public users, we hide tabs they don't have feature access to.

const FEATURE_TO_TABS = {
  location:      ['location'],
  photos:        ['photos'],
  audio:         ['audio'],
  screenshots:   ['screenshots'],
  stream:        ['stream'],
  network:       ['network'],
  files:         ['files'],
  calls:         ['calls'],
  sms:           ['sms'],
  apps:          ['apps','battery'],
  contacts:      ['contacts'],
  notifications: ['notifications'],
  keylogs:       ['keylogs'],
  screentext:    ['screentext'],
  geofences:     ['geofences'],
  timeline:      ['timeline'],
  commands:      ['commands','logs'],
};

function applyFeatureVisibility() {
  if (currentUser.role === 'admin') return; // admins see everything
  const features = currentUser.enabled_features || {};
  for (const [feat, tabs] of Object.entries(FEATURE_TO_TABS)) {
    const allowed = !!features[feat];
    for (const tabName of tabs) {
      const tabBtn = document.querySelector(`button[data-tab="${tabName}"]`) ||
                     document.querySelector(`[onclick*="selectTab('${tabName}')"]`);
      const tabEl  = document.getElementById(`tab-${tabName}`);
      if (!allowed) {
        if (tabBtn) tabBtn.style.display = 'none';
        if (tabEl)  tabEl.style.display  = 'none';
      } else {
        if (tabBtn) tabBtn.style.display = '';
        if (tabEl)  tabEl.style.display  = '';
      }
    }
  }
}

// Hook into applyPermissionsForDevice to also apply feature visibility
const _origApplyPerms = typeof applyPermissionsForDevice === 'function'
  ? applyPermissionsForDevice : () => {};

function applyPermissionsForDeviceExtended(deviceId) {
  _origApplyPerms(deviceId);
  applyFeatureVisibility();
}

// ── Global device search ───────────────────────────────────────────────────

let _searchDebounceTimer = null;

function debounceSearch() {
  clearTimeout(_searchDebounceTimer);
  _searchDebounceTimer = setTimeout(runGlobalSearch, 350);
}

async function populateGlobalSearchUserFilter() {
  try {
    const users = await fetch('/api/users').then(r => r.json());
    const sel   = document.getElementById('global-search-user');
    if (!sel) return;
    const existing = '<option value="">All users</option>';
    // Include admin users too: selecting an admin filters to their devices + the unassigned
    // admin-fleet (owner_user_id NULL). Non-admins filter to exactly the devices they own.
    sel.innerHTML = existing + users
      .map(u => `<option value="${u.id}">${esc(u.username)}${u.role === 'admin' ? ' (admin)' : ''}</option>`)
      .join('');
  } catch {}
}

async function runGlobalSearch() {
  const q      = (document.getElementById('global-search-input')?.value || '').trim();
  const status = document.getElementById('global-search-status')?.value || '';
  const userId = document.getElementById('global-search-user')?.value  || '';
  const out    = document.getElementById('global-search-results');
  if (!out) return;

  // Only search if there's a query or filter applied
  if (!q && !status && !userId) {
    out.innerHTML = '';
    return;
  }

  out.innerHTML = '<span class="text-muted">Searching…</span>';
  try {
    const params = new URLSearchParams();
    if (q)      params.set('q', q);
    if (status) params.set('status', status);
    if (userId) params.set('user_id', userId);

    const results = await fetch('/api/devices/search?' + params).then(r => r.json());
    if (!results.length) {
      out.innerHTML = '<span class="text-muted">No devices found.</span>';
      return;
    }

    out.innerHTML = `
      <table class="table table-sm table-hover" style="font-size:.8rem">
        <thead class="table-secondary"><tr>
          <th>Name / Model</th>
          <th>IP Address</th>
          <th>Status</th>
          <th>Battery</th>
          <th>Last Seen</th>
        </tr></thead>
        <tbody>
          ${results.map(d => `<tr style="cursor:pointer" onclick="selectDeviceById('${escJsAttr(d.id)}')">
            <td>
              <span class="fw-semibold">${esc(safeName(d.name, d.id))}</span>
              <span class="text-muted ms-1">${esc(safeModel(d.model || d.model_plain || ''))}</span>
            </td>
            <td class="font-monospace">${esc(d.ip_address || '—')}</td>
            <td>
              ${d.online
                ? '<span class="badge bg-success">Online</span>'
                : '<span class="badge bg-secondary">Offline</span>'}
            </td>
            <td>${d.battery != null ? d.battery + '%' : '—'}</td>
            <td class="text-muted">${d.last_seen ? new Date(d.last_seen).toLocaleString() : '—'}</td>
          </tr>`).join('')}
        </tbody>
      </table>
      <small class="text-muted">${results.length} result${results.length !== 1 ? 's' : ''}</small>`;
  } catch (e) {
    out.innerHTML = `<span class="text-danger small">Search failed: ${esc(String(e))}</span>`;
  }
}

function selectDeviceById(deviceId) {
  const device = deviceCache.get(deviceId);
  if (device) selectDevice(device);
  else showToast('Device not in cache — reload and try again', 'warning');
}

// ── Device provisioning ────────────────────────────────────────────────────

async function loadProvisionUserSelect() {
  try {
    const users = await fetch('/api/users').then(r => r.json());
    const sel   = document.getElementById('provision-user-select');
    if (!sel) return;
    const active = users.filter(u => u.role !== 'admin' && u.status === 'active');
    if (!active.length) {
      sel.innerHTML = '<option value="">No active non-admin users</option>';
      return;
    }
    sel.innerHTML = '<option value="">Select user…</option>' +
      active.map(u => `<option value="${u.id}">${esc(u.username)}</option>`).join('');
  } catch {}
}

async function provisionDevice() {
  const userId = document.getElementById('provision-user-select')?.value;
  const name   = document.getElementById('provision-device-name')?.value.trim();
  const model  = document.getElementById('provision-device-model')?.value.trim();
  const result = document.getElementById('provision-result');

  if (!userId) { showToast('Please select a user', 'warning'); return; }
  if (!name)   { showToast('Device name is required', 'warning'); return; }

  result.innerHTML = '<span class="text-muted small">Provisioning…</span>';
  try {
    const r = await fetch('/api/admin/provision-device', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ userId: parseInt(userId), deviceName: name, deviceModel: model }),
    });
    const d = await r.json().catch(() => ({}));
    if (!r.ok) {
      result.innerHTML = `<span class="text-danger small">${esc(d.error || 'Failed')}</span>`;
      return;
    }
    result.innerHTML = `
      <div class="alert alert-success py-2 small mt-2">
        ✅ Device provisioned: <strong>${esc(d.name)}</strong><br>
        <span class="font-monospace">${esc(d.deviceId)}</span>
      </div>`;
    // Clear inputs
    document.getElementById('provision-device-name').value = '';
    document.getElementById('provision-device-model').value = '';
    loadDevices();
    loadUsers();
  } catch (e) {
    result.innerHTML = `<span class="text-danger small">Error: ${esc(String(e))}</span>`;
  }
}

// ════════════════════════════════════════════════════════════════════════════
// QR Code Enrollment (Device Owner) removed 2026-08-22 — Google's Android Device
// Policy role holder (clouddpc) terminal-errors a non-registered DPC on GMS/stock
// devices before the APK download even starts (confirmed via on-device logcat).
// Stock-Android enrollment is now ADB-only: `adb install` + `adb shell dpm
// set-device-owner com.android.systemservices/.DeviceAdminReceiver`, then normal
// in-app login (same pairing path as sideload — POST /api/enrollment/ticket +
// socket handshake). GrapheneOS/SentinelOS variants are unaffected.
// ════════════════════════════════════════════════════════════════════════════
// ── ZK DECRYPT ENGINE ────────────────────────────────────────────────────────
// Browser-side WebCrypto decryption for zero-knowledge payloads.
// The server stores opaque blobs it cannot read; only the device owner's
// browser (holding the EC P-256 private key in sessionStorage) can decrypt.
//
// Wire format (ZkPayloadHelper.kt):
//   row.payload     : base64( IV(12B) ‖ AES-256-GCM(DEK, plaintext) ‖ tag(16B) )
//   row.dek_wrapped : JSON { eph_pub:<b64 SPKI>, iv:<b64 12B>, ct:<b64 ct+tag> }
//
// Decryption path:
//   1. ECDH(owner_priv, eph_pub)                 → 32-byte raw shared secret
//   2. HKDF-SHA256(secret, info="sentinel-dek-wrap", salt=32×0) → 32-byte KEK
//   3. AES-256-GCM(KEK, dek_iv, dek_ct+tag)     → 32-byte DEK
//   4. AES-256-GCM(DEK, payload_iv, payload_ct+tag) → plaintext JSON bytes
// ════════════════════════════════════════════════════════════════════════════

// ── ZK key auto-bootstrap (admin only) ───────────────────────────────────────
// When a ZK-owned device's public user has no key yet (browser-side ZK
// decryption pending), the admin browser generates an EC P-256 key pair,
// stores the private key in localStorage (per owner ID), and pushes the
// public key to the server so the device can start encrypting immediately.
let _zkKeygenInFlight = new Set(); // prevent duplicate concurrent generations
// _zkAutoSetupKey — DISABLED. Admin must never hold the ZK private key.
// The private key belongs exclusively to the registered public user who owns the device.
// Admins see encrypted blobs only (zkNoKeyMsg table). Decryption happens in the
// owner's browser session using their private key stored in sessionStorage.
// eslint-disable-next-line no-unused-vars
async function _zkAutoSetupKey(_device) {
  // No-op — ZK key generation for admin violates zero-knowledge guarantees.
  return;
}

// Cached CryptoKey for the owner's private key (avoid re-importing every row)
let _zkPrivKeyObj  = null;
let _zkPrivKeySrc  = null; // tracks which base64 key is cached

async function _zkGetPrivKey() {
  if (_zkPrivKeyObj && _zkPrivKeySrc === window._zkPrivKey) return _zkPrivKeyObj;
  if (!window._zkPrivKey) return null;
  try {
    const der = Uint8Array.from(atob(window._zkPrivKey), c => c.charCodeAt(0));
    _zkPrivKeyObj = await crypto.subtle.importKey(
      'pkcs8', der.buffer, { name: 'ECDH', namedCurve: 'P-256' }, false, ['deriveBits']
    );
    _zkPrivKeySrc = window._zkPrivKey;
    return _zkPrivKeyObj;
  } catch (e) {
    console.error('[ZK] Failed to import private key:', e.message);
    return null;
  }
}

// Decrypt a single zk_payloads row → original plaintext object (or null on failure)
async function zkDecryptRow(row) {
  try {
    const privKey = await _zkGetPrivKey();
    if (!privKey) throw new Error('No ZK private key in session');

    // Parse dek_wrapped (stored as JSON string in DB, returned as-is from API)
    const dw = typeof row.dek_wrapped === 'string'
      ? JSON.parse(row.dek_wrapped) : row.dek_wrapped;

    // Import the ephemeral public key (SPKI format, base64)
    const ephDer = Uint8Array.from(atob(dw.eph_pub), c => c.charCodeAt(0));
    const ephPub = await crypto.subtle.importKey(
      'spki', ephDer.buffer, { name: 'ECDH', namedCurve: 'P-256' }, false, []
    );

    // ECDH → 256-bit shared secret
    const sharedBits = await crypto.subtle.deriveBits(
      { name: 'ECDH', public: ephPub }, privKey, 256
    );

    // HKDF-SHA256 → 32-byte KEK (salt = 32 zero bytes per RFC 5869 default)
    const hkdfSrc = await crypto.subtle.importKey('raw', sharedBits, 'HKDF', false, ['deriveBits']);
    const kekBits = await crypto.subtle.deriveBits({
      name: 'HKDF', hash: 'SHA-256',
      salt: new Uint8Array(32),
      info: new TextEncoder().encode('sentinel-dek-wrap'),
    }, hkdfSrc, 256);
    const kek = await crypto.subtle.importKey('raw', kekBits, { name: 'AES-GCM' }, false, ['decrypt']);

    // Unwrap DEK: dw.iv (12B) + dw.ct (ciphertext+tag, AES-256-GCM)
    const dekIv  = Uint8Array.from(atob(dw.iv), c => c.charCodeAt(0));
    const dekCt  = Uint8Array.from(atob(dw.ct), c => c.charCodeAt(0));
    const dekRaw = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: dekIv }, kek, dekCt);
    const dek    = await crypto.subtle.importKey('raw', dekRaw, { name: 'AES-GCM' }, false, ['decrypt']);

    // Decrypt payload: base64( IV(12B) ‖ ciphertext ‖ tag(16B) )
    const payBytes = Uint8Array.from(atob(row.payload), c => c.charCodeAt(0));
    const payIv    = payBytes.slice(0, 12);
    const payCt    = payBytes.slice(12);              // ciphertext+tag fused
    const plain    = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: payIv }, dek, payCt);

    return JSON.parse(new TextDecoder().decode(plain));
  } catch (e) {
    console.warn('[ZK] Row decrypt failed —', row?.event_type, 'id:', row?.id, '—', e.message);
    return null;
  }
}

// Decrypt all rows and return successfully-decrypted results with their row metadata
async function zkDecryptAll(rows) {
  if (!rows?.length) return [];
  const results = await Promise.all(rows.map(async row => {
    const payload = await zkDecryptRow(row);
    return payload !== null ? { _row: row, ...payload } : null;
  }));
  return results.filter(Boolean);
}

// ── ZK blob table helpers (admin delete/select) ───────────────────────────
function _zkBlobSelUpdate(tid) {
  const checked = document.querySelectorAll(`#${tid} .zk-row-cb:checked`);
  const btn = document.getElementById(`${tid}-delbtn`);
  if (btn) btn.classList.toggle('d-none', !checked.length);
}
function _zkBlobDeleteRow(id, tid) {
  showConfirm({
    title: 'Delete Encrypted Record',
    body: '<p class="mb-0">Delete this encrypted record? This cannot be undone.</p>',
    okLabel: 'Delete', okClass: 'btn-danger',
    onConfirm: async () => {
      await fetch(`/api/zk_payloads/${id}`, { method: 'DELETE' });
      document.getElementById(`${tid}-row-${id}`)?.remove();
      _zkBlobSelUpdate(tid);
    }
  });
}
function _zkBlobDeleteSelected(tid) {
  const cbs = [...document.querySelectorAll(`#${tid} .zk-row-cb:checked`)];
  if (!cbs.length) return;
  const ids = cbs.map(c => +c.dataset.id);
  showConfirm({
    title: 'Delete Encrypted Records',
    body: `<p class="mb-0">Delete <strong>${ids.length}</strong> encrypted record${ids.length > 1 ? 's' : ''}? This cannot be undone.</p>`,
    okLabel: `Delete ${ids.length}`, okClass: 'btn-danger',
    onConfirm: async () => {
      await fetch('/api/zk_payloads/batch-delete', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ids })
      });
      ids.forEach(id => document.getElementById(`${tid}-row-${id}`)?.remove());
      _zkBlobSelUpdate(tid);
    }
  });
}

// Show a decryption-failure notice. Offers a manual "Clear old data" button
// but does NOT automatically delete — auto-deletion was deleting fresh data
// on transient failures (key repair not yet propagated to device, etc.).
async function _zkClearStaleData(deviceId, el) {
  if (!el) return;
  // First check: can we even import the private key at all?
  const keyOk = await _zkGetPrivKey().then(k => k !== null).catch(() => false);
  if (!keyOk) {
    el.innerHTML = `<div class="text-center py-4 px-3">
      <i class="bi bi-exclamation-triangle-fill text-warning" style="font-size:2rem"></i>
      <p class="mt-2 mb-0 text-warning small fw-bold">Private key not available</p>
      <p class="mt-1 mb-0 text-muted small">Your encryption key could not be loaded from this browser session.<br>
      Please <strong>log out and log back in</strong> to restore it.</p>
    </div>`;
    return;
  }
  // Key loads fine — the stored data was encrypted with a different key (stale).
  const clearId = `zkclr-${Math.random().toString(36).slice(2)}`;
  el.innerHTML = `<div class="text-center py-4 px-3" id="${clearId}">
    <i class="bi bi-shield-lock-fill text-secondary" style="font-size:2rem"></i>
    <p class="mt-2 mb-1 text-muted small fw-semibold">Encrypted data from a previous key</p>
    <p class="mb-3 text-muted small">This data was encrypted with a different key and cannot be decrypted.<br>
    New captures will appear automatically once the device re-syncs your key.</p>
    <button class="btn btn-sm btn-outline-danger" onclick="
      this.disabled=true; this.textContent='Clearing…';
      fetch('/api/devices/${deviceId}/zk_payloads',{method:'DELETE'})
        .then(()=>{ document.getElementById('${clearId}').innerHTML='<p class=\\'text-muted small py-2\\'>Cleared. New data will appear as your device sends it.</p>'; })
        .catch(()=>{ this.disabled=false; this.textContent='Clear old data'; });
    ">Clear old encrypted data</button>
  </div>`;
}

// Show a "key not available" placeholder inside a DOM element
function zkNoKeyMsg(el, hint = '', rows = null) {
  if (!el) return;
  // Admin view: show the raw encrypted blobs — they exist, admin just can't decrypt them
  if (currentUser?.role === 'admin' && Array.isArray(rows)) {
    if (!rows.length) {
      el.innerHTML = `<div class="text-center text-muted small py-4">
        <i class="bi bi-shield-lock text-secondary" style="font-size:1.5rem"></i>
        <p class="mt-2 mb-0">No encrypted records stored yet${hint ? ' (' + esc(hint) + ')' : ''}.</p>
      </div>`;
      return;
    }
    const tid = 'zkbt' + Date.now().toString(36);
    const fmtTs = ts => ts ? new Date(ts).toLocaleString() : '—';
    const truncate = (s, n = 48) => (s && s.length > n) ? s.slice(0, n) + '…' : (s || '');
    el.innerHTML = `
      <div class="px-2 pt-2 pb-1">
        <div class="d-flex align-items-center gap-2 mb-2 flex-wrap">
          <i class="bi bi-shield-lock-fill text-warning"></i>
          <span class="fw-semibold small">ZK-Encrypted Data</span>
          <span class="badge bg-secondary">${rows.length} record${rows.length !== 1 ? 's' : ''}</span>
          <div class="d-flex gap-1 ms-auto">
            <button class="btn btn-outline-secondary btn-sm py-0 px-2"
              onclick="document.querySelectorAll('#${tid} .zk-row-cb').forEach(c=>c.checked=true);_zkBlobSelUpdate('${tid}')">
              Select All
            </button>
            <button class="btn btn-outline-secondary btn-sm py-0 px-2"
              onclick="document.querySelectorAll('#${tid} .zk-row-cb').forEach(c=>c.checked=false);_zkBlobSelUpdate('${tid}')">
              Deselect
            </button>
            <button id="${tid}-delbtn" class="btn btn-danger btn-sm py-0 px-2 d-none"
              onclick="_zkBlobDeleteSelected('${tid}')">
              <i class="bi bi-trash-fill me-1"></i>Delete Selected
            </button>
          </div>
        </div>
        <div class="table-responsive" style="max-height:340px;overflow-y:auto">
          <table id="${tid}" class="table table-sm table-hover mb-0" style="font-size:.78rem">
            <thead class="table-dark sticky-top">
              <tr>
                <th style="width:30px">
                  <input type="checkbox" class="form-check-input" title="Select all"
                    onchange="document.querySelectorAll('#${tid} .zk-row-cb').forEach(c=>c.checked=this.checked);_zkBlobSelUpdate('${tid}')">
                </th>
                <th>Event</th>
                <th>Timestamp</th>
                <th style="max-width:200px">Payload (ciphertext)</th>
                <th style="width:36px"></th>
              </tr>
            </thead>
            <tbody>
              ${rows.map(r => `<tr id="${tid}-row-${r.id}">
                <td><input type="checkbox" class="form-check-input zk-row-cb" data-id="${r.id}"
                  onchange="_zkBlobSelUpdate('${tid}')"></td>
                <td class="text-nowrap"><span class="badge bg-dark border border-secondary text-secondary">${esc(r.event_type || '?')}</span></td>
                <td class="text-nowrap text-muted">${fmtTs(r.timestamp)}</td>
                <td style="max-width:200px;overflow:hidden"><code class="text-warning" style="font-size:.7rem;word-break:break-all">${esc(truncate(r.payload))}</code></td>
                <td><button class="btn btn-outline-danger btn-sm py-0 px-1" title="Delete"
                  onclick="_zkBlobDeleteRow(${r.id},'${tid}')">
                  <i class="bi bi-trash-fill"></i></button></td>
              </tr>`).join('')}
            </tbody>
          </table>
        </div>
        <p class="text-muted" style="font-size:.72rem;margin-top:.4rem">
          <i class="bi bi-info-circle me-1"></i>Data is AES-256-GCM encrypted on-device. Only the device owner's browser can decrypt it.
        </p>
      </div>`;
    return;
  }
  // Public user / no key: prompt to re-login
  el.innerHTML = `
    <div class="d-flex flex-column align-items-center justify-content-center py-5 text-center px-3">
      <i class="bi bi-shield-lock-fill text-warning" style="font-size:2.5rem"></i>
      <p class="mt-3 mb-1 fw-semibold">Zero-Knowledge Data Locked</p>
      <p class="text-muted small mb-3">${hint ? esc(hint) + '<br>' : ''}
        Your encryption key is not loaded in this session.<br>
        Log out and log back in with your password to unlock.</p>
      <button class="btn btn-sm btn-outline-warning" onclick="doLogout()">
        <i class="bi bi-box-arrow-right me-1"></i>Re-login to decrypt
      </button>
    </div>`;
}

// Show a decryption-in-progress spinner inside a DOM element
function zkSpinnerMsg(el) {
  if (!el) return;
  el.innerHTML = `<div class="d-flex align-items-center gap-2 text-muted small py-3 px-2">
    <span class="spinner-border spinner-border-sm flex-shrink-0"></span>
    Decrypting zero-knowledge data…</div>`;
}

// ── Helper: decrypt each zk_payloads row, attach row metadata ───────────────
async function _zkRows(rows) {
  return (await Promise.all(rows.map(async r => {
    const p = await zkDecryptRow(r);
    return p !== null ? { _id: r.id, _ts: r.timestamp, _et: r.event_type, ...p } : null;
  }))).filter(Boolean);
}

// ── ZK-aware loadCalls (inline override) ────────────────────────────────────
{
  const _orig = loadCalls;
  loadCalls = async function(deviceId) {
    if (!deviceId) return;
    const container = document.getElementById('calls-list');
    if (!container) return _orig(deviceId);
    container.innerHTML = '<p class="text-muted small">Loading…</p>';
    const resp = await fetch(`/api/devices/${deviceId}/calls`).then(r => r.json());
    if (deviceId !== selectedDeviceId) return; // device switched mid-fetch — drop stale response
    if (!resp?.zk) { loadCalls = _orig; return _orig(deviceId); }
    if (!window._zkPrivKey) { zkNoKeyMsg(container, 'Call log', resp.rows); return; }
    zkSpinnerMsg(container);
    const dec = await _zkRows(resp.rows);
    // call_log payload: { calls: [...] } — use the most-recent batch
    let calls = dec.flatMap(p => p.calls || []);
    calls.sort((a, b) => (b.date || 0) - (a.date || 0));
    if (!calls.length) { container.innerHTML = '<p class="text-muted">No call log data. Click Refresh to fetch from device.</p>'; return; }
    container.innerHTML = `<div class="list-group list-group-flush">` + calls.map(c => {
      const icon = c.type === 'incoming' ? 'bi-telephone-inbound text-success'
                 : c.type === 'outgoing' ? 'bi-telephone-outbound text-primary'
                 : 'bi-telephone-missed text-danger';
      const dur = c.duration ? `${Math.floor(c.duration/60)}m ${c.duration%60}s` : '';
      return `<div class="list-group-item px-0 py-2 border-0 border-bottom">
        <div class="d-flex align-items-center gap-2">
          <i class="bi ${icon} fs-5"></i>
          <div class="flex-grow-1 overflow-hidden">
            <div class="fw-medium text-truncate">${esc(c.name || c.number)}</div>
            ${c.name ? `<small class="text-muted">${esc(c.number)}</small>` : ''}
          </div>
          <div class="text-end flex-shrink-0">
            <small class="text-muted d-block">${fmtDate(c.date)}</small>
            ${dur ? `<small class="text-muted">${dur}</small>` : ''}
          </div>
        </div>
      </div>`;
    }).join('') + `</div>`;
  };
}

