    const resp = await fetch(`/api/devices/${deviceId}/apps`).then(r => r.json());
    if (deviceId !== selectedDeviceId) return; // device switched mid-fetch — drop stale response
    if (!resp?.zk) { loadApps = _orig; return _orig(deviceId); }
    if (!window._zkPrivKey) { zkNoKeyMsg(container, 'App list', resp.rows); return; }
    zkSpinnerMsg(container);
    const dec = await _zkRows(resp.rows);
    // app_list payload: { apps: [...] }
    appsData = dec.flatMap(p => p.apps || []);
