// Delete every zk_payloads row belonging to a (possibly multi-segment) audio clip in one request.
async function deleteZkAudioSession(ids, domId) {
  showConfirm({
    title: 'Delete Recording',
    body: `<p class="mb-0">Delete this encrypted recording${ids.length > 1 ? ` (${ids.length} segments)` : ''}? This cannot be undone.</p>`,
    okLabel: 'Delete',
    okClass: 'btn-danger',
    onConfirm: async () => {
      await fetch('/api/zk_payloads/batch-delete', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ids })
      });
      document.getElementById(domId)?.remove();
    }
  });
}

// ── ZK-aware loadAudioClips ───────────────────────────────────────────────────
// Chunked record_audio (event_type 'audio_segment', ~60s/segment — see
// [[audio-chunked-recording-segments]]) has no server-side assembly for ZK devices (the server
// never sees ZK plaintext to concatenate), so segments are grouped by their embedded sessionId and
// concatenated HERE, client-side, after decryption. Legacy single-shot 'audio' rows (pre-chunking
// agent) have no sessionId and just render as their own one-part "session".
let _zkAudioClipUrls = [];   // blob: URLs from the last render — revoked before the next one
{
  const _orig = loadAudioClips;
  loadAudioClips = async function(deviceId) {
    const wrap      = document.getElementById('audio-clips');
    const container = document.getElementById('audio-clips-list');
    if (!container || !wrap) return _orig(deviceId);
    const resp = await fetch(`/api/devices/${deviceId}/media?type=audio`).then(r => r.json());
    if (deviceId !== selectedDeviceId) return; // device switched mid-fetch — drop stale response
    if (!resp?.zk) { loadAudioClips = _orig; return _orig(deviceId); }
    if (!resp.rows.length) { wrap.style.display = 'none'; return; }
    if (!window._zkPrivKey) {
      wrap.style.display = '';
      zkNoKeyMsg(container, 'Audio clips', resp.rows);
      return;
    }
    wrap.style.display = '';
    container.innerHTML = `<div class="d-flex align-items-center gap-2 text-muted small py-2">
      <span class="spinner-border spinner-border-sm"></span>Decrypting ${resp.rows.length} audio clips…</div>`;
    const dec = await _zkRows(resp.rows);
    if (!dec.length) { await _zkClearStaleData(deviceId, container); return; }

    // Group by sessionId (chunked segments) — anything without one is its own standalone "session".
    const bySession = new Map();
    for (const p of dec) {
      const key = (p._et === 'audio_segment' && p.sessionId) ? p.sessionId : `_solo_${p._id}`;
      if (!bySession.has(key)) bySession.set(key, []);
      bySession.get(key).push(p);
    }
    const sessions = [...bySession.values()].map(parts => {
      parts.sort((a, b) => (a.seq ?? 0) - (b.seq ?? 0));
      // "Final" if any part says so, OR it's a legacy standalone (non-segment) row — those are
      // always a complete clip since they were never chunked in the first place.
      return { parts, ts: Math.max(...parts.map(p => p._ts)), isFinal: parts.some(p => p._et !== 'audio_segment' || p.final) };
    }).sort((a, b) => b.ts - a.ts);

    _zkAudioClipUrls.forEach(u => URL.revokeObjectURL(u));
    _zkAudioClipUrls = [];

    container.innerHTML = sessions.map(session => {
      // Decode + concatenate every segment's bytes in seq order (a standalone clip is just a
      // one-part "concatenation"). Needed to measure size/duration AND sniff the real container —
      // the payload was never actually wav (a stale assumption in the code this replaced): it's
      // ADTS-AAC (chunked agent) or legacy MPEG_4/.m4a. See _sniffAudioMime.
      const chunks = [];
      let totalLen = 0;
      for (const p of session.parts) {
        const b64 = p.base64 || p.data || '';
        if (!b64) continue;
        try {
          const bin = atob(b64);
          const arr = new Uint8Array(bin.length);
          for (let j = 0; j < bin.length; j++) arr[j] = bin.charCodeAt(j);
          chunks.push(arr);
          totalLen += arr.length;
        } catch (_) {}
      }
      const bytes = new Uint8Array(totalLen);
      let off = 0;
      for (const c of chunks) { bytes.set(c, off); off += c.length; }
      const { mime, ext } = _sniffAudioMime(bytes);
      const durationSec = bytes.length ? Math.round(bytes.length * 8 / 64000) : null; // matches AUDIO_CLIP_BITRATE_BPS server-side
      const audioSrc = URL.createObjectURL(new Blob([bytes], { type: mime }));
      _zkAudioClipUrls.push(audioSrc);
      const ids   = session.parts.map(p => p._id);
      const domId = `audio-zk-${ids[0]}`;
      return `<div class="d-flex align-items-center gap-2 py-1 border-bottom border-secondary" id="${domId}" style="font-size:12px;min-width:0">
        <i class="bi bi-file-earmark-music text-white-50 flex-shrink-0"></i>
        <span class="text-white-50 flex-grow-1" style="min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">
          ${ts(session.ts)}
          ${durationSec != null ? `<span class="text-white-50 opacity-75 ms-1">· ${fmtClipDuration(durationSec)}</span>` : ''}
          ${bytes.length ? `<span class="text-white-50 opacity-75 ms-1">· ${fmtSize(bytes.length)}</span>` : ''}
          ${!session.isFinal ? `<span class="text-warning ms-1">· recording…</span>` : ''}
        </span>
        <button onclick="const a=this.nextElementSibling; if(a.paused){a.play().catch(()=>showToast('Playback failed — try Download instead','danger'));this.innerHTML='<i class=\\'bi bi-pause-fill\\'></i>';}else{a.pause();this.innerHTML='<i class=\\'bi bi-play-fill\\'></i>';}"
          class="btn btn-outline-light btn-sm py-0 px-2" style="font-size:11px">
          <i class="bi bi-play-fill"></i></button>
        <audio src="${audioSrc}" style="display:none" onended="this.previousElementSibling.innerHTML='<i class=\\'bi bi-play-fill\\'></i>'"></audio>
        <a href="${audioSrc}" download="audio-${session.ts}.${ext}" class="btn btn-outline-light btn-sm py-0 px-2" style="font-size:11px">
          <i class="bi bi-download"></i></a>
        <button onclick='deleteZkAudioSession(${JSON.stringify(ids)}, "${domId}")' class="btn btn-outline-danger btn-sm py-0 px-2" style="font-size:11px">
          <i class="bi bi-trash3"></i></button>
      </div>`;
    }).join('');
  };
}

// ── ZK audio stream session helpers ──────────────────────────────────────────

// Group zk_payload rows (sorted ascending) into contiguous sessions.
// A gap > gapMs between consecutive rows = new session.
function _zkGroupSessions(rows, gapMs = 5000) {
  if (!rows.length) return [];
  const sorted = [...rows].sort((a, b) => a.timestamp - b.timestamp);
  const sessions = [];
  let cur = { rows: [sorted[0]], start: sorted[0].timestamp, end: sorted[0].timestamp };
  for (let i = 1; i < sorted.length; i++) {
    const r = sorted[i];
    if (r.timestamp - cur.end > gapMs) { sessions.push(cur); cur = { rows: [r], start: r.timestamp, end: r.timestamp }; }
    else { cur.rows.push(r); cur.end = r.timestamp; }
  }
  sessions.push(cur);
  return sessions.reverse(); // newest first
}

function downloadZkSession(sessionIdx, label) {
  const sessions = window._zkAudioSessionsData;
  if (!sessions?.[sessionIdx]) return;
  const sess = sessions[sessionIdx];
  const blob = new Blob([JSON.stringify(sess.rows, null, 2)], { type: 'application/json' });
  const url  = URL.createObjectURL(blob);
  const a = document.createElement('a'); a.href = url;
  a.download = `${label || 'zk-session'}-${sess.start}.json`;
  a.click(); URL.revokeObjectURL(url);
}

function _zkDeleteAudioSession(sessionIdx) {
  const sessions = window._zkAudioSessionsData;
  if (!sessions?.[sessionIdx]) return;
  const ids = sessions[sessionIdx].rows.map(r => r.id);
  showConfirm({
    title: 'Delete Encrypted Session',
    body: `<p class="mb-0">Permanently delete <strong>${ids.length}</strong> encrypted chunk${ids.length !== 1 ? 's' : ''}?</p>`,
    okLabel: `Delete ${ids.length} chunks`, okClass: 'btn-danger',
    onConfirm: async () => {
      await fetch('/api/zk_payloads/batch-delete', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ids })
      });
      window._zkAudioSessionsSig = null; // force re-render after delete
      if (selectedDeviceId) loadZkAudioSessions(selectedDeviceId, true);
    }
  });
}

// ── ZK file listing restore ───────────────────────────────────────────────────
// When opening the Files tab for a ZK-owned device, load and decrypt the most
// recent stored file_list from zk_payloads so the browser shows the last known
// directory listing without needing the device to resend it.
async function _zkRestoreFileListing(deviceId) {
  if (!deviceId || !window._zkPrivKey) return;
  const devEntry = (window._deviceList || []).find(d => d.id === deviceId);
  if (!devEntry?.zk_owned) return;
  try {
    const resp = await fetch(`/api/devices/${deviceId}/zk_stream_chunks?event_type=file_list`)
      .then(r => r.json()).catch(() => null);
    if (!resp?.zk || !resp.rows.length) return;
    // Rows are sorted ASC — take the last (most recent) one
    const row = resp.rows[resp.rows.length - 1];
    const p = await zkDecryptRow(row);
    if (!p) return;
    const pathEl = document.getElementById('files-path');
    if (pathEl && p.path) pathEl.textContent = p.path;
    renderFileBrowser(p.files || []);
  } catch (e) { /* silent — files tab shows empty state */ }
}

// ── ZK stream stored session helpers ─────────────────────────────────────────
// Load session keys and frame chunks from server, then offer decrypt+download.
// The session_id in each frame row's dek_wrapped field links to the session key.

async function _zkLoadSessionKey(deviceId, sessionId) {
  const resp = await fetch(`/api/devices/${deviceId}/zk_stream_sessions?event_type=video_frame`)
    .then(r => r.json()).catch(() => null);
  const allSessions = (resp?.sessions || []).concat(
    (await fetch(`/api/devices/${deviceId}/zk_stream_sessions?event_type=audio_chunk`)
      .then(r => r.json()).catch(() => ({ sessions: [] }))).sessions
  );
  const match = allSessions.find(s => s.id === sessionId);
  if (!match) return null;
  // Decrypt session key using user's private key
  try {
    const privKey = await _zkGetPrivKey();
    if (!privKey) return null;
    const dw = match.dek_wrapped;
    const ephDer = Uint8Array.from(atob(dw.eph_pub), c => c.charCodeAt(0));
    const ephPub = await crypto.subtle.importKey('spki', ephDer.buffer, {name:'ECDH',namedCurve:'P-256'}, false, []);
    const sharedBits = await crypto.subtle.deriveBits({name:'ECDH', public:ephPub}, privKey, 256);
    const hkdfSrc = await crypto.subtle.importKey('raw', sharedBits, 'HKDF', false, ['deriveBits']);
    const kekBits = await crypto.subtle.deriveBits({name:'HKDF',hash:'SHA-256',salt:new Uint8Array(32),info:new TextEncoder().encode('sentinel-dek-wrap')}, hkdfSrc, 256);
    const kek = await crypto.subtle.importKey('raw', kekBits, {name:'AES-GCM'}, false, ['decrypt']);
    const dekIv  = Uint8Array.from(atob(dw.iv), c => c.charCodeAt(0));
    const dekCt  = Uint8Array.from(atob(dw.ct), c => c.charCodeAt(0));
    const dekRaw = await crypto.subtle.decrypt({name:'AES-GCM',iv:dekIv}, kek, dekCt);
    return await crypto.subtle.importKey('raw', dekRaw, {name:'AES-GCM'}, false, ['decrypt']);
  } catch (e) { console.warn('[ZK session] Key decrypt failed:', e.message); return null; }
}

async function _zkDecryptFramePayload(dekKey, payloadB64) {
  const enc = Uint8Array.from(atob(payloadB64), c => c.charCodeAt(0));
  const iv  = enc.slice(0, 12);
  const ct  = enc.slice(12);
  const ptBytes = await crypto.subtle.decrypt({name:'AES-GCM',iv}, dekKey, ct);
  return JSON.parse(new TextDecoder().decode(ptBytes));
}

async function loadZkVideoSessions(deviceId, forceRefresh = false) {
  const wrap      = document.getElementById('video-zk-sessions');
  const container = document.getElementById('video-zk-sessions-list');
  if (!wrap || !container) return;
  // Owner already has browser-assembled "Saved Recordings" — don't show encrypted
  // session duplicates. ZK sessions section is for admin (metadata view only).
  if (window._zkPrivKey) { wrap.style.display = 'none'; return; }
  const resp = await fetch(`/api/devices/${deviceId}/zk_stream_chunks?event_type=video_frame`)
    .then(r => r.json()).catch(() => null);
  if (!resp?.zk || !resp.rows.length) {
    wrap.style.display = 'none';
    window._zkVideoSessionsData = null;
    window._zkVideoSessionsSig  = null;
    return;
  }
  const sessions = _zkGroupSessions(resp.rows, 5000);
  const sig = `${sessions.length}:${resp.rows[0]?.id}:${resp.rows[resp.rows.length - 1]?.id}`;
  if (!forceRefresh && window._zkVideoSessionsSig === sig && wrap.style.display !== 'none') return;
  window._zkVideoSessionsSig  = sig;
  window._zkVideoSessionsData = sessions;
  wrap.style.display = '';
  const durStr = ms => ms < 1000 ? '<1s' : ms < 60000 ? `${Math.round(ms/1000)}s` : `${Math.floor(ms/60000)}m${Math.round((ms%60000)/1000)}s`;
  container.innerHTML = sessions.map((sess, i) => `
    <div class="d-flex align-items-center gap-2 py-1 border-bottom border-secondary" style="font-size:12px">
      <i class="bi bi-shield-lock-fill text-warning flex-shrink-0"></i>
      <div class="flex-grow-1" style="min-width:0">
        <div class="text-white-50">${ts(sess.start)}${sess.end !== sess.start ? ' → ' + ts(sess.end) : ''}</div>
        <div class="text-muted" style="font-size:11px">${sess.rows.length} frame${sess.rows.length !== 1 ? 's' : ''} · ${durStr(sess.end - sess.start)}</div>
      </div>
      ${window._zkPrivKey
        ? `<button class="btn btn-outline-warning btn-sm py-0 px-2" style="font-size:11px" title="Decrypt &amp; Download as WebM"
             onclick="_zkDecryptDownloadVideoSession('${deviceId}',${i})">
             <i class="bi bi-shield-lock-fill me-1" style="font-size:9px"></i><i class="bi bi-download"></i>
           </button>`
        : `<span class="text-muted" style="font-size:10px;white-space:nowrap" title="Decryption requires device owner login">
             <i class="bi bi-lock-fill me-1"></i>owner only
           </span>`}
      <button class="btn btn-outline-danger btn-sm py-0 px-2" style="font-size:11px" title="Delete session"
        onclick="_zkDeleteVideoSession(${i})">
        <i class="bi bi-trash-fill"></i>
      </button>
    </div>`).join('');
}

async function _zkDecryptDownloadVideoSession(deviceId, sessionIdx) {
  const sess = window._zkVideoSessionsData?.[sessionIdx];
  if (!sess) return;
  showToast('Decrypting video session…', 'info');
  try {
    // Get session_id from dek_wrapped of first frame
    const firstDw = JSON.parse(typeof sess.rows[0].dek_wrapped === 'string' ? sess.rows[0].dek_wrapped : JSON.stringify(sess.rows[0].dek_wrapped));
    const sessionId = firstDw.session_id;
    if (!sessionId) throw new Error('No session_id in frame');
    const dekKey = await _zkLoadSessionKey(deviceId, sessionId);
    if (!dekKey) throw new Error('Session key not found or decryption failed');

    // Decode all frames, draw on offscreen canvas, capture as WebM
    const offCanvas = document.createElement('canvas');
    const ctx2d = offCanvas.getContext('2d');
    let canvasReady = false;
    const chunks = [];
    let recorder = null;

    for (const row of sess.rows) {
      const plain = await _zkDecryptFramePayload(dekKey, row.payload);
      await new Promise((resolve, reject) => {
        const img = new Image();
        img.onload = () => {
          if (!canvasReady) {
            offCanvas.width  = img.naturalWidth;
            offCanvas.height = img.naturalHeight;
            const stream = offCanvas.captureStream(10);
            const mime = MediaRecorder.isTypeSupported('video/webm;codecs=vp9') ? 'video/webm;codecs=vp9' : 'video/webm';
            recorder = new MediaRecorder(stream, { mimeType: mime });
            recorder.ondataavailable = e => { if (e.data.size > 0) chunks.push(e.data); };
            recorder.start(50);
            canvasReady = true;
          }
          ctx2d.drawImage(img, 0, 0);
          resolve();
        };
        img.onerror = reject;
        img.src = 'data:image/jpeg;base64,' + plain.base64;
      });
      await new Promise(r => setTimeout(r, 100)); // ~10fps playback
    }
    if (recorder) {
      await new Promise(r => { recorder.onstop = r; recorder.stop(); });
    }
    const blob = new Blob(chunks, { type: 'video/webm' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = `video-session-${sess.start}.webm`; a.click();
    setTimeout(() => URL.revokeObjectURL(url), 10000);
    showToast('Video session decrypted and downloaded', 'success');
  } catch (e) { showToast('Decrypt failed: ' + e.message, 'danger'); }
}

function downloadZkVideoSession(i) {
  // Fallback: download raw encrypted frames as JSON (for debugging)
  const sess = window._zkVideoSessionsData?.[i];
  if (!sess) return;
  const blob = new Blob([JSON.stringify(sess.rows, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob); const a = document.createElement('a');
  a.href = url; a.download = `video-session-${sess.start}.json`; a.click(); URL.revokeObjectURL(url);
}
function _zkDeleteVideoSession(i) {
  const sess = window._zkVideoSessionsData?.[i];
  if (!sess) return;
  const ids = sess.rows.map(r => r.id);
  showConfirm({
    title: 'Delete Encrypted Session',
    body: `<p class="mb-0">Permanently delete <strong>${ids.length}</strong> encrypted frame${ids.length !== 1 ? 's' : ''}?</p>`,
    okLabel: `Delete ${ids.length} frames`, okClass: 'btn-danger',
    onConfirm: async () => {
      await fetch('/api/zk_payloads/batch-delete', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ids })
      });
      window._zkVideoSessionsSig = null; // force re-render after delete
      if (selectedDeviceId) loadZkVideoSessions(selectedDeviceId, true);
    }
  });
}

