async function _zkDecryptDownloadAudioSession(deviceId, sessionIdx) {
  const sess = window._zkAudioSessionsData?.[sessionIdx];
  if (!sess) return;
  showToast('Decrypting audio session…', 'info');
  try {
    const firstDw = JSON.parse(typeof sess.rows[0].dek_wrapped === 'string' ? sess.rows[0].dek_wrapped : JSON.stringify(sess.rows[0].dek_wrapped));
    const sessionId = firstDw.session_id;
    if (!sessionId) throw new Error('No session_id in chunk');
    const dekKey = await _zkLoadSessionKey(deviceId, sessionId);
    if (!dekKey) throw new Error('Session key not found or decryption failed');

    // Decrypt all PCM chunks and assemble as WAV
    const pcmChunks = [];
    let sr = 16000;
    for (const row of sess.rows) {
      const plain = await _zkDecryptFramePayload(dekKey, row.payload);
      if (plain.sampleRate) sr = plain.sampleRate;
      const raw = atob(plain.base64);
      const bytes = new Uint8Array(raw.length);
      for (let j = 0; j < raw.length; j++) bytes[j] = raw.charCodeAt(j);
      pcmChunks.push(new Int16Array(bytes.buffer));
    }
    const total = pcmChunks.reduce((n, c) => n + c.length, 0);
    const all   = new Int16Array(total);
    let off = 0;
    for (const c of pcmChunks) { all.set(c, off); off += c.length; }
    const dlen = all.byteLength;
    const buf  = new ArrayBuffer(44 + dlen);
    const v    = new DataView(buf);
    const ws   = (o, s) => { for (let i = 0; i < s.length; i++) v.setUint8(o+i, s.charCodeAt(i)); };
    ws(0,'RIFF'); v.setUint32(4,36+dlen,true); ws(8,'WAVE');
    ws(12,'fmt '); v.setUint32(16,16,true); v.setUint16(20,1,true);
    v.setUint16(22,1,true); v.setUint32(24,sr,true);
    v.setUint32(28,sr*2,true); v.setUint16(32,2,true); v.setUint16(34,16,true);
    ws(36,'data'); v.setUint32(40,dlen,true);
    new Int16Array(buf,44).set(all);
    const blob = new Blob([buf], { type:'audio/wav' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = `audio-session-${sess.start}.wav`; a.click();
    setTimeout(() => URL.revokeObjectURL(url), 10000);
    showToast('Audio session decrypted and downloaded', 'success');
  } catch (e) { showToast('Decrypt failed: ' + e.message, 'danger'); }
}

// ── User wipe (forgot password / key lost) ────────────────────────────────────
// Shows a two-step confirmation, then calls DELETE /api/users/:id/wipe.
// Recovery flow after wipe:
//   1. User re-registers themselves on the parent website (new password → new key pair,
//      account activates immediately — no admin approval step)
//   2. Admin re-assigns device ownership to the new account (Devices → Owner)
//   3. Device receives new ZK pub key and resumes encrypting for the new owner
function wipeUser(userId, username) {
  showConfirm({
    title: '⚠️ Wipe User Account',
    body: `<div class="alert alert-danger py-2 mb-3" style="font-size:.85rem">
      <strong>This is irreversible.</strong> All zero-knowledge encrypted data for
      <strong>${esc(username)}</strong> will be permanently deleted — the server never
      held the decryption key, so this data cannot be recovered.
    </div>
    <p class="mb-2 small">This action will:</p>
    <ul class="small mb-3">
      <li>Delete all encrypted payloads (location, photos, logs, etc.)</li>
      <li>Un-assign their device(s) and clear the device's ZK encryption key</li>
      <li>Delete the user account</li>
    </ul>
    <p class="small mb-2"><strong>After wiping:</strong> the user re-registers themselves
      on the parent website with a new password (which generates a new encryption key pair).
      You then approve their new registration and re-assign their device to the new account —
      the device picks up the new key immediately.</p>
    <p class="small mb-0 text-warning">You'll be asked to type the username to confirm.</p>`,
    okLabel: 'Continue to wipe…',
    okClass: 'btn-danger',
    // Type-to-confirm uses a native prompt(): the Users list is itself a modal, and a
    // nested Bootstrap modal's text input can't reliably take focus (the parent modal's
    // focus-trap steals it), which previously made the wipe silently fail.
    onConfirm: async () => {
      const typed = prompt(`Type the username "${username}" to permanently wipe & delete this account:`);
      if (typed == null) return;                          // cancelled
      if (typed.trim() !== username) { showToast('Username did not match — wipe cancelled.', 'warning'); return; }
      const r = await fetch(`/api/users/${userId}/wipe`, { method: 'DELETE' });
      const d = await r.json().catch(() => ({}));
      if (r.ok) {
        showToast(`User "${username}" wiped — ${d.devicesReleased || 0} device(s) released`, 'success');
        loadUsers();
        loadDevices();
      } else {
        showToast(d.error || 'Wipe failed', 'danger');
      }
    },
  });
}

