// ── Admin notification provider configuration ─────────────────────────────
// ── Admin browser-push event toggles ─────────────────────────────────────────
// Sign-in ('login') alerts are always on and rendered as a locked switch; every
// other event can be toggled. Backed by GET/POST /api/admin/notify-prefs.
async function loadPushNotifyPrefs() {
  const box = document.getElementById('push-notify-toggles');
  if (!box) return;
  try {
    const data   = await fetch('/api/admin/notify-prefs').then(r => r.json());
    const prefs  = data.prefs  || {};
    const locked = data.locked || ['login'];
    const labels = {
      login:      ['Sign-in alerts',     'Every successful dashboard login (always on)'],
      enrollment: ['New device / user',  'A device enrolls or a new user registers'],
      offline:    ['Device offline',     'A device disconnects from the server'],
      geofence:   ['Geofence crossings', 'A fleet device enters or leaves a zone'],
      theft:      ['Theft mode',         'Theft mode is activated on a device'],
      support:    ['Support messages',   'A new contact / support message arrives'],
    };
    const order = ['login', 'enrollment', 'offline', 'geofence', 'theft', 'support'];
    let html = `<div class="card bg-dark border-secondary mb-3"><div class="card-body">
      <h6 class="fw-bold mb-1"><i class="bi bi-bell me-2"></i>Browser Push Alerts</h6>
      <p class="text-muted small mb-2">Pick which events push a notification to admin browsers. Enable the bell (top-right) on each browser that should receive them.</p>`;
    for (const t of order) {
      const on       = prefs[t] !== false;
      const isLocked = locked.includes(t);
      const [name, desc] = labels[t] || [t, ''];
      html += `<div class="d-flex align-items-center justify-content-between py-2 border-top border-secondary">
        <div class="me-3"><div class="fw-semibold text-light">${name}${isLocked ? ' <span class="badge bg-secondary ms-1" style="font-size:.6rem;vertical-align:middle">ALWAYS ON</span>' : ''}</div>
          <div class="text-muted small">${desc}</div></div>
        <div class="form-check form-switch m-0">
          <input class="form-check-input" type="checkbox" role="switch" ${on ? 'checked' : ''} ${isLocked ? 'disabled' : ''}
                 onchange="savePushNotifyPref('${t}', this.checked)">
        </div></div>`;
    }
    html += `</div></div>`;
    box.innerHTML = html;
  } catch (e) {
    box.innerHTML = '<div class="text-danger small mb-3">Failed to load push preferences.</div>';
  }
}

async function savePushNotifyPref(type, on) {
  try {
    const cur   = await fetch('/api/admin/notify-prefs').then(r => r.json());
    const prefs = cur.prefs || {};
    prefs[type] = on;
    const r = await fetch('/api/admin/notify-prefs', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ prefs }),
    });
    if (r.ok) showToast('Notification preference saved', 'success');
    else      showToast('Failed to save preference', 'danger');
  } catch (e) { showToast('Failed to save preference', 'danger'); }
}

