async function saveNotifConfig() {
  const webhookEl = document.getElementById('notif-discord-webhook');
  if (!webhookEl) return;
  const r = await fetch('/api/admin/notif-config', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ discord_webhook: webhookEl.value.trim() }),
  });
  if (r.ok) { showToast('Notification config saved', 'success'); loadNotifConfig(); }
  else showToast('Failed to save notification config', 'danger');
}

async function clearDiscordWebhook() {
  const r = await fetch('/api/admin/notif-config', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ discord_webhook: '' }),
  });
  if (r.ok) { showToast('Discord webhook cleared', 'success'); loadNotifConfig(); }
  else showToast('Failed to clear webhook', 'danger');
}

async function testAdminNotif() {
  const r = await fetch('/api/admin/notif-test', { method: 'POST' });
  const data = await r.json().catch(() => ({}));
  if (r.ok) showToast('Test notification sent to all admin channels', 'success');
  else showToast(data.error || 'Test failed', 'danger');
}

