// ── Block Telemetry — block / restore (kill switch, v2 self-refreshing) ─────
// Same shape as Windows Update above, but tracks BOTH enabledAt (blocking turned on) and
// disabledAt (blocking turned off) — see telemetry_block() in bastion-web.py. hostCount/ipCount
// (only present right after a Block call, not on a plain status refresh) reflect that the domain
// list now auto-updates from a maintained source + a daily on-device refresh task, so the count
// can legitimately change over time — shown so that's visible rather than a mystery.
function _raTelemetryRender(data) {
  const status = document.getElementById('ra-telemetry-status');
  const blockBtn = document.getElementById('ra-telemetry-block-btn');
  const unblockBtn = document.getElementById('ra-telemetry-unblock-btn');
  if (!status || !blockBtn || !unblockBtn) return;
  const blocked = !!(data && data.blocked);
  blockBtn.classList.toggle('d-none', blocked);
  unblockBtn.classList.toggle('d-none', !blocked);
  const fmt = (iso) => { if (!iso) return ''; const d = new Date(iso); return isNaN(d.getTime()) ? '' : d.toLocaleDateString(); };
  const counts = (data && Number.isFinite(data.hostCount)) ? ` — ${data.hostCount} hosts blocked, refreshed daily` : '';
  if (blocked) {
    const when = fmt(data.enabledAt);
    status.textContent = `Blocked${when ? ` on ${when}` : ''}${counts}`;
    status.className = 'small text-danger align-self-center';
  } else {
    const when = fmt(data.disabledAt);
    const prevBlockedAt = fmt(data.enabledAt);
    status.textContent = when
      ? `Restored on ${when}${prevBlockedAt ? ` (was blocked since ${prevBlockedAt})` : ''}`
      : 'Not blocked';
    status.className = 'small text-success align-self-center';
  }
}

function raTelemetryRefresh() {
  const status = document.getElementById('ra-telemetry-status');
  if (!status || !selectedDeviceId) return;
  const deviceId = selectedDeviceId;
  fetch(`/api/devices/${deviceId}/remote-assist/telemetry/block-status`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' })
    .then(r => r.json())
    .then(data => { if (selectedDeviceId === deviceId && data && data.ok !== false) _raTelemetryRender(data); })
    .catch(() => {});
}

function raTelemetrySet(enable) {
  const status = document.getElementById('ra-telemetry-status');
  const blockBtn = document.getElementById('ra-telemetry-block-btn');
  const unblockBtn = document.getElementById('ra-telemetry-unblock-btn');
  if (!status || !selectedDeviceId) return;
  const deviceId = selectedDeviceId;
  const run = () => {
    blockBtn.disabled = true; unblockBtn.disabled = true;
    status.textContent = enable ? 'Restoring…' : 'Blocking…';
    status.className = 'small text-info align-self-center';
    const action = enable ? 'unblock' : 'block';
    fetch(`/api/devices/${deviceId}/remote-assist/telemetry/${action}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' })
      .then(r => r.json())
      .then(data => {
        if (selectedDeviceId !== deviceId) return;
        blockBtn.disabled = false; unblockBtn.disabled = false;
        if (data && data.ok) { _raTelemetryRender(data); }
        else { status.textContent = `Failed: ${(data && data.error) || 'Unknown error'}`; status.className = 'small text-danger align-self-center'; }
      })
      .catch(e => {
        if (selectedDeviceId !== deviceId) return;
        blockBtn.disabled = false; unblockBtn.disabled = false;
        status.textContent = `Error: ${e.message}`; status.className = 'small text-danger align-self-center';
      });
  };
  if (!enable) {
    showConfirm({
      title: 'Block Windows telemetry?',
      body: 'Blocks OS-level telemetry on this PC: registry policy, telemetry services, and known Microsoft telemetry hosts (auto-updated from a maintained list + re-checked daily, so new endpoints get picked up over time). Windows Update itself is left untouched. You can restore it here any time.',
      okLabel: 'Block Telemetry',
      okClass: 'btn-danger',
      onConfirm: run,
    });
  } else {
    run();
  }
}
