// ── Sentry Mode — endpoint honeypot (enable / disable) ─────────────────────────
// Five independent primitives: credential manager decoys, SMB share decoy, registry
// persistence traps, browser credential guard, and LSASS access watch. The bastion
// poller drains outbox findings into sentry_events every 15 minutes; endpoints here
// just toggle enable/disable and show per-rule status.
function _raSentryRender(data) {
  const status = document.getElementById('ra-sentry-status');
  const enableBtn = document.getElementById('ra-sentry-enable-btn');
  const disableBtn = document.getElementById('ra-sentry-disable-btn');
  const rulesDiv = document.getElementById('ra-sentry-rules');
  const findingsDiv = document.getElementById('ra-sentry-findings');
  if (!status || !enableBtn || !disableBtn) return;
  const enabled = !!(data && data.enabled);
  enableBtn.classList.toggle('d-none', enabled);
  disableBtn.classList.toggle('d-none', !enabled);
  const fmt = (iso) => { if (!iso) return ''; const d = new Date(iso); return isNaN(d.getTime()) ? '' : d.toLocaleDateString(); };
  if (enabled) {
    const when = fmt(data.enabledAt);
    status.textContent = `Active${when ? ` since ${when}` : ''}`;
    status.className = 'small text-danger align-self-center';
  } else {
    const when = fmt(data.disabledAt);
    status.textContent = when ? `Disabled on ${when}` : 'Inactive';
    status.className = 'small text-success align-self-center';
  }
  // Per-rule status badges — only show when actually enabled
  if (rulesDiv && enabled && data && data.rules) {
    const rules = data.rules;
    rulesDiv.classList.remove('d-none');
    const setBadge = (id, rule) => {
      const el = document.getElementById(`ra-sentry-${id}`);
      if (el) { el.textContent = rules.includes(rule) ? 'ON' : 'OFF'; el.className = rules.includes(rule) ? 'badge bg-success ms-1' : 'badge bg-secondary ms-1'; }
    };
    setBadge('cred-manager', 'cred_manager');
    setBadge('smb-share', 'smb_share');
    setBadge('reg-persist', 'reg_persist');
    setBadge('browser-guard', 'browser_guard');
    setBadge('lsass-watch', 'lsass_watch');
  } else if (rulesDiv) {
    rulesDiv.classList.add('d-none');
  }
  // Show last findings count if any
  if (findingsDiv) {
    if (data && Number.isFinite(data.findings)) {
      findingsDiv.classList.remove('d-none');
      findingsDiv.textContent = `Last check: ${data.findings} finding(s)`;
      findingsDiv.className = data.findings > 0 ? 'small text-warning mt-1' : 'small text-muted mt-1';
    } else {
      findingsDiv.classList.add('d-none');
    }
  }
}

