  const status = document.getElementById('ra-sentry-status');
  if (!status || !selectedDeviceId) return;
  const deviceId = selectedDeviceId;
  fetch(`/api/devices/${deviceId}/remote-assist/sentry/status`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' })
