// ── Learn Mode — alert baseline ───────────────────────────────────────────────
// Pure server-side feature (no bastion/Hop-2 round trip, no agent version dependency) — it gates
// the SERVER's alert dispatch, so it works on a disconnected device too. That's why these routes
// are /api/devices/:id/learn-mode rather than the /remote-assist/* family around it.
const _LEARN_CATEGORY_LABEL = {
  arp_recon: 'Network scanning',
  edr_alert: 'EDR',
  sentry: 'Sentry decoy',
};
function _raLearnRender(d) {
  const status = document.getElementById('ra-learn-status');
  const banner = document.getElementById('ra-learn-banner');
  const stopBtn = document.getElementById('ra-learn-stop-btn');
  const reviewRow = document.getElementById('ra-learn-review-row');
  const list = document.getElementById('ra-learn-observations');
  if (!status || !list) return;
  const obs = Array.isArray(d.observations) ? d.observations : [];
  const pending = obs.filter(o => !o.decision).length;
  const accepted = obs.filter(o => o.decision === 'accepted').length;

  if (d.active) {
    const left = Math.max(0, Number(d.expires_at) - Date.now());
    const days = Math.floor(left / 86400000);
    const hours = Math.floor((left % 86400000) / 3600000);
    banner.className = 'alert alert-info py-2 px-3 small mb-2';
    banner.innerHTML = `<i class="bi bi-mortarboard me-1"></i><strong>Learn Mode is ON</strong> — alerts from these detectors are paused for another ${days}d ${hours}h (until ${esc(new Date(Number(d.expires_at)).toLocaleString())}). Everything is still being recorded.`;
    stopBtn.classList.remove('d-none');
    status.textContent = `${obs.length} signature(s) collected`;
    status.className = 'small text-info align-self-center';
  } else {
    stopBtn.classList.add('d-none');
    if (pending) {
      banner.className = 'alert alert-warning py-2 px-3 small mb-2';
      banner.innerHTML = `<i class="bi bi-exclamation-triangle me-1"></i><strong>Review needed</strong> — Learn Mode has finished and alerts are LIVE again. ${pending} item(s) below are still unreviewed and will keep alerting until you mark them normal.`;
    } else {
      banner.className = 'alert alert-info py-2 px-3 small d-none mb-2';
      banner.innerHTML = '';
    }
    status.textContent = accepted
      ? `Off · ${accepted} signature(s) baselined as normal`
      : 'Off — alerts are live';
    status.className = 'small text-muted align-self-center';
  }
  reviewRow.classList.toggle('d-none', !pending);

  if (!obs.length) {
    list.innerHTML = '<div class="text-muted p-2">Nothing recorded yet. Start Learn Mode to collect this PC\'s normal behaviour.</div>';
    return;
  }
  list.innerHTML = obs.map(o => {
    const cat = _LEARN_CATEGORY_LABEL[o.category] || o.category;
    const badge = o.decision === 'accepted'
      ? '<span class="badge bg-success-subtle text-success border border-success">Normal — muted</span>'
      : o.decision === 'rejected'
        ? '<span class="badge bg-danger-subtle text-danger border border-danger">Keeps alerting</span>'
        : '<span class="badge bg-warning-subtle text-warning border border-warning">Needs review</span>';
    // Accepted rows keep counting hits, so "last seen" tells you a muted signature is still live.
    const seen = o.last_seen ? new Date(Number(o.last_seen)).toLocaleString() : '';
    const sigAttr = escJsAttr(o.signature); const catAttr = escJsAttr(o.category);
    return `<div class="border-bottom py-1 px-1">
      <div class="d-flex justify-content-between align-items-start gap-2 flex-wrap">
        <div style="min-width:0;flex:1">
          <div><span class="badge bg-secondary-subtle text-secondary border me-1">${esc(cat)}</span>${badge}
            <span class="text-muted ms-1">×${Number(o.hits) || 1}</span></div>
          <div class="text-break" style="font-family:monospace;font-size:.78rem">${esc(o.detail || o.signature)}</div>
          <div class="text-muted" style="font-size:.72rem">last seen ${esc(seen)}</div>
        </div>
        <div class="d-flex gap-1 flex-shrink-0">
          ${o.decision === 'accepted'
            ? `<button class="btn btn-sm btn-outline-secondary py-0" onclick="raLearnDecide('${catAttr}','${sigAttr}','pending')">Undo</button>`
            : `<button class="btn btn-sm btn-outline-success py-0" onclick="raLearnDecide('${catAttr}','${sigAttr}','accepted')">Normal</button>`}
          ${o.decision === 'rejected'
            ? `<button class="btn btn-sm btn-outline-secondary py-0" onclick="raLearnDecide('${catAttr}','${sigAttr}','pending')">Undo</button>`
            : `<button class="btn btn-sm btn-outline-danger py-0" onclick="raLearnDecide('${catAttr}','${sigAttr}','rejected')">Keep alerting</button>`}
        </div>
      </div>
    </div>`;
  }).join('');
}

