function raLearnStart(days) {
  if (!selectedDeviceId) return;
  const deviceId = selectedDeviceId;
  showConfirm({
    title: `Start Learn Mode for ${days} days?`,
    body: `Alerts from Network Scanning, EDR and Sentry on this PC will be PAUSED for ${days} days while their findings are recorded instead. Ransomware, Defender-tampering and sensor-blinding alerts keep firing throughout. When the ${days} days are up you'll be notified to review what was collected, and alerts resume automatically.`,
    okLabel: `Start ${days}-day Learn Mode`,
    okClass: 'btn-info',
    onConfirm: () => {
      fetch(`/api/devices/${deviceId}/learn-mode`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ days }),
      }).then(r => r.json())
        .then(d => {
          if (selectedDeviceId !== deviceId) return;
          if (d && d.ok) raLearnRefresh();
          else showToast((d && d.error) || 'Could not start Learn Mode', 'danger');
        })
        .catch(e => showToast(e.message, 'danger'));
    },
  });
}

function raLearnStop() {
  if (!selectedDeviceId) return;
  const deviceId = selectedDeviceId;
  fetch(`/api/devices/${deviceId}/learn-mode`, { method: 'DELETE' })
    .then(r => r.json())
    .then(() => { if (selectedDeviceId === deviceId) raLearnRefresh(); })
    .catch(() => {});
}

function raLearnDecide(category, signature, decision) {
  if (!selectedDeviceId) return;
  const deviceId = selectedDeviceId;
  fetch(`/api/devices/${deviceId}/learn-mode/decide`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ category, signature, decision }),
  }).then(r => r.json())
    .then(d => {
      if (selectedDeviceId !== deviceId) return;
      if (d && d.ok) raLearnRefresh();
      else showToast((d && d.error) || 'Could not save decision', 'danger');
    })
    .catch(e => showToast(e.message, 'danger'));
}

function raLearnAcceptAll() {
  if (!selectedDeviceId) return;
  const deviceId = selectedDeviceId;
  showConfirm({
    title: 'Accept all pending as normal?',
    body: 'Every unreviewed item below will stop alerting on this PC from now on. You can undo any of them individually afterwards.',
    okLabel: 'Accept all',
    okClass: 'btn-success',
    onConfirm: () => {
      fetch(`/api/devices/${deviceId}/learn-mode/accept-all`, { method: 'POST' })
        .then(r => r.json())
        .then(() => { if (selectedDeviceId === deviceId) raLearnRefresh(); })
        .catch(e => showToast(e.message, 'danger'));
    },
  });
}
// ── End Learn Mode ────────────────────────────────────────────────────────────

// ── Defender Exclusion (exclude folder only — does NOT touch sample submission) ──
function _raDefenderExclusionRender(data) {
  const status = document.getElementById('ra-defender-status');
  const blockBtn = document.getElementById('ra-defender-block-btn');
  const unblockBtn = document.getElementById('ra-defender-unblock-btn');
  if (!status || !blockBtn || !unblockBtn) return;
  const excluded = !!(data && data.excluded);
  blockBtn.classList.toggle('d-none', excluded);
  unblockBtn.classList.toggle('d-none', !excluded);
  const fmt = (iso) => { if (!iso) return ''; const d = new Date(iso); return isNaN(d.getTime()) ? '' : d.toLocaleDateString(); };
  if (excluded) {
    const when = fmt(data.addedAt);
    status.textContent = `Excluded${when ? ` on ${when}` : ''} — folder + Snap exe excluded from Defender scanning`;
    status.className = 'small text-danger align-self-center';
  } else {
    const when = fmt(data.removedAt);
    status.textContent = when ? `Restored on ${when}` : 'Not excluded';
    status.className = 'small text-success align-self-center';
  }
}

function raDefenderExclusionRefresh() {
  const status = document.getElementById('ra-defender-status');
  if (!status || !selectedDeviceId) return;
  const deviceId = selectedDeviceId;
  fetch(`/api/devices/${deviceId}/remote-assist/defender-exclusion/status`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' })
    .then(r => r.json())
    .then(data => { if (selectedDeviceId === deviceId && data && data.ok !== false) _raDefenderExclusionRender(data); })
    .catch(() => {});
}

function raDefenderExclusionSet(enable) {
  const status = document.getElementById('ra-defender-status');
  const blockBtn = document.getElementById('ra-defender-block-btn');
  const unblockBtn = document.getElementById('ra-defender-unblock-btn');
  if (!status || !selectedDeviceId) return;
  const deviceId = selectedDeviceId;
  const run = () => {
    blockBtn.disabled = true; unblockBtn.disabled = true;
    status.textContent = enable ? 'Removing exclusion…' : 'Excluding folder…';
    status.className = 'small text-info align-self-center';
    const action = enable ? 'restore' : 'exclude';
    fetch(`/api/devices/${deviceId}/remote-assist/defender-exclusion/${action}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' })
      .then(r => r.json())
      .then(data => {
        if (selectedDeviceId !== deviceId) return;
        blockBtn.disabled = false; unblockBtn.disabled = false;
        if (data && data.ok) { _raDefenderExclusionRender(data); }
        else { status.textContent = `Failed: ${(data && data.error) || 'Unknown error'}`; status.className = 'small text-danger align-self-center'; }
      })
      .catch(e => {
        if (selectedDeviceId !== deviceId) return;
        blockBtn.disabled = false; unblockBtn.disabled = false;
        status.textContent = `Error: ${e.message}`; status.className = 'small text-danger align-self-center';
      });
  };
  if (!enable) {
    showConfirm({
      title: 'Exclude SentinelRemoteAssist from Defender?',
      body: 'Adds the SentinelRemoteAssist installation folder to Windows Defender path exclusions. Prevents Defender from scanning or quarantining the agent\'s own executables. Does not change Windows Defender sample submission settings.',
      okLabel: 'Exclude',
      okClass: 'btn-danger',
      onConfirm: run,
    });
  } else {
    run();
  }
}
// ── End Defender Exclusion ───────────────────────────────────────────────────

// ── ARP Scan (network discovery, "ARPwatch"-style) ───────────────────────────
// Renders the SERVER's persisted, diffed view (GET /remote-assist/arp-scan — roster + recent
// events + latest AI summary), never a raw bastion cache — the diffing/spoof-flagging happens
// server-side in ingestArpScanResult(). mac_changed_for_ip events (a known IP now answering from
// a different MAC — the ARPwatch "flip-flop" signal) render in the danger color; everything else
// (new_device/ip_changed) is routine and rendered muted.
function _raArpEventBadge(mac, events) {
  const flagged = (events || []).find(e => e.mac_address === mac && e.event_type === 'mac_changed_for_ip');
  return flagged
    ? `<span class="badge bg-danger ms-1" title="IP ${escHtml(flagged.ip_address)} previously answered from ${escHtml(flagged.prior_value || 'a different MAC')}">possible spoof</span>`
    : '';
}

// Dark-space/canary IPs — see arp_canary_ips (server.js) for the confirm-after-3-scans state
// machine this reflects. Purely informational here (no toggle — designation is automatic,
// piggybacks on the scan above); a hit shows up as its own 'canary_hit' badge-worthy event in the
// roster/AI summary, same alert plumbing as the spoof badge above.
function _renderArpCanaries(canaries) {
  const el = document.getElementById('ra-arp-canary');
  if (!el) return;
  const list = canaries || [];
  if (!list.length) { el.textContent = ''; return; }
  const parts = list.map(c => {
    const label = escHtml(c.ip_address);
    return c.confirmed_at
      ? `${label} <span class="text-success">(watching)</span>`
      : `${label} <span class="text-muted">(confirming ${c.consecutive_dark_scans || 0}/3)</span>`;
  });
  el.innerHTML = `Canary IPs: ${parts.join(', ')}`;
}

async function raArpScanRefresh() {
  const rosterEl = document.getElementById('ra-arp-roster');
  const summaryWrap = document.getElementById('ra-arp-summary-wrap');
  const summaryEl = document.getElementById('ra-arp-summary');
  const scheduleEl = document.getElementById('ra-arp-schedule');
  if (!rosterEl || !selectedDeviceId) return;
  const deviceId = selectedDeviceId;
  try {
    const [data, sched] = await Promise.all([
      fetch(`/api/devices/${deviceId}/remote-assist/arp-scan`).then(r => r.json()),
      fetch(`/api/devices/${deviceId}/remote-assist/arp-scan-schedule`).then(r => r.json()).catch(() => null),
    ]);
    // Bail without touching any shared DOM if the admin has since navigated to a different
    // device -- this whole panel is a shared singleton repainted per-device, not one instance
    // per device, so a slow response for a device we've since left must never overwrite whatever
    // is now on screen for the newly-selected device.
    if (selectedDeviceId !== deviceId) return;
    if (scheduleEl && sched && Number.isFinite(sched.minutes)) scheduleEl.value = String(sched.minutes);
    // raArpScanSetSchedule() writes its confirmation text ("Auto-scan every N min") into this same
    // shared #ra-arp-status element — without resetting it here, switching to a DIFFERENT device
    // kept showing whatever interval was last manually set on a PREVIOUS device, even though the
    // dropdown itself (scheduleEl, above) was already correctly refreshed per-device. Found live
    // 2026-07-22: dropdown correctly showed "Off" for this device while the text next to it still
    // said "Auto-scan every 5 min" from the last device that was actually changed.
    const statusEl = document.getElementById('ra-arp-status');
    if (statusEl && sched && Number.isFinite(sched.minutes)) {
      statusEl.textContent = _fmtArpScanInterval(sched.minutes);
      statusEl.className = 'small text-muted align-self-center';
    }
    const roster = data?.roster || [];
    rosterEl.innerHTML = roster.length
      ? roster.map(r => {
        const portBadges = (r.openPorts && r.openPorts.length)
          ? `<span class="ms-2">${r.openPorts.map(p => `<span class="badge text-bg-secondary" style="font-size:.62rem">${escHtml(String(p))}</span>`).join(' ')}</span>`
          : '';
        const webUi = (r.webUi && r.webUi.length)
          ? r.webUi.map(w => `<div class="small text-muted" style="font-size:.68rem"><i class="bi bi-window me-1"></i><a href="${escAttr(w.url)}" target="_blank" rel="noopener" class="text-info">${escHtml(w.title || w.url)}</a>${w.server ? ` <span class="text-white-50">(${escHtml(w.server)})</span>` : ''}</div>`).join('')
          : '';
        return `
        <div class="py-1 border-bottom border-secondary-subtle">
          <div class="d-flex justify-content-between align-items-center">
            <div class="text-truncate me-2">
              <span class="font-monospace">${escHtml(r.ip_address)}</span>
              <span class="text-muted font-monospace ms-2">${escHtml(r.mac_address)}</span>
              ${r.hostname ? `<span class="text-muted ms-2">${escHtml(r.hostname)}</span>` : ''}
              ${portBadges}
              ${_raArpEventBadge(r.mac_address, data.events)}
              ${r.trusted ? '<span class="badge bg-success ms-2">Trusted scanner</span>' : ''}
            </div>
            <div class="d-flex align-items-center gap-2 flex-shrink-0">
              <span class="text-muted" style="font-size:.7rem">${ts(r.last_seen)}</span>
              <div class="form-check form-switch m-0" title="Authorized scanner — suppresses ARP Sweep Detection alerts on every device in your account (Nmap/Fing/etc you run intentionally). Does not affect spoofing alerts.">
                <input class="form-check-input" type="checkbox" role="switch"
                  id="ra-arp-trust-${escAttr(r.mac_address.replace(/:/g, ''))}"
                  ${r.trusted ? 'checked' : ''}
                  onchange="raArpToggleTrust('${escJsAttr(r.mac_address)}', this.checked)">
                <label class="form-check-label small text-muted" for="ra-arp-trust-${escAttr(r.mac_address.replace(/:/g, ''))}">Trust</label>
              </div>
            </div>
          </div>
          ${webUi}
        </div>`;
      }).join('')
      : '<div class="text-muted small p-1">No devices found yet — click Scan Now.</div>';
    if (data?.latestSummary?.summary) {
      summaryWrap?.classList.remove('d-none');
      if (summaryEl) summaryEl.textContent = data.latestSummary.summary;
      const whenEl = document.getElementById('ra-arp-summary-when');
      if (whenEl) whenEl.textContent = `(generated ${ts(data.latestSummary.generated_at)})`;
    } else {
      summaryWrap?.classList.add('d-none');
    }
    _renderArpCanaries(data?.canaries);
    // Also refresh the manually-configured VLAN subnets list.
    raArpVlanRefresh();
  } catch (_) { /* best-effort — leave whatever was already rendered */ }
}

// "Trust this Device" / "Authorized Scanner" — suppresses future ARP Sweep Detection alerts for
// this MAC on every device under the same owner (server.js's ingestArpSweepEvents() checks
// arp_neighbors.trusted owner-scoped before notifyUser()).
function raArpToggleTrust(mac, trusted) {
  if (!selectedDeviceId) return;
  fetch(`/api/devices/${selectedDeviceId}/remote-assist/arp-scan/trust`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ mac, trusted }),
  })
    .then(r => r.json())
    .then(data => {
      if (!data.ok) { showToast(data.error || 'Failed to update trust', 'danger'); raArpScanRefresh(); return; }
      showToast(trusted ? `${mac} marked as a trusted scanner` : `${mac} no longer trusted`, 'success');
      raArpScanRefresh();
    })
    .catch(e => { showToast(e.message, 'danger'); raArpScanRefresh(); });
}

function raArpScanNow() {
  const btn = document.getElementById('ra-arp-scan-btn');
  const status = document.getElementById('ra-arp-status');
  if (!status || !selectedDeviceId) return;
  const deviceId = selectedDeviceId;
  if (btn) { btn.disabled = true; btn.textContent = 'Scanning…'; }
  status.textContent = 'Scanning local network (this can take up to a minute)...';
  status.className = 'small text-info align-self-center';
  fetch(`/api/devices/${deviceId}/remote-assist/arp-scan`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' })
    .then(r => r.json())
    .then(data => {
      // Server-side, this scan ran against `deviceId` correctly regardless of what happens below --
      // this guard only stops the button/status UI from being clobbered onto a different device's
      // panel if the admin has since navigated away (shared singleton DOM).
      if (selectedDeviceId !== deviceId) return;
      if (btn) { btn.disabled = false; btn.innerHTML = '<i class="bi bi-search me-1"></i>Scan Now'; }
      if (data && data.ok) {
        status.textContent = `Found ${data.deviceCount ?? (data.devices || []).length} device(s) on ${(data.subnets || []).join(', ') || 'the local network'}.`;
        status.className = 'small text-success align-self-center';
        raArpScanRefresh();
      } else {
        status.textContent = `Failed: ${(data && data.error) || 'Unknown error'}`;
        status.className = 'small text-danger align-self-center';
      }
    })
    .catch(e => {
      if (selectedDeviceId !== deviceId) return;
      if (btn) { btn.disabled = false; btn.innerHTML = '<i class="bi bi-search me-1"></i>Scan Now'; }
      status.textContent = `Error: ${e.message}`; status.className = 'small text-danger align-self-center';
    });
}

function _fmtArpScanInterval(minutes) {
  const m = Number(minutes);
  if (!(m > 0)) return 'Auto-scan off';
  if (m % 1440 === 0) return `Auto-scan every ${m / 1440}d`;
  if (m % 60 === 0) return `Auto-scan every ${m / 60}h`;
  return `Auto-scan every ${m} min`;
}

function raArpScanSetSchedule(minutes) {
  const status = document.getElementById('ra-arp-status');
  if (!selectedDeviceId) return;
  const deviceId = selectedDeviceId;
  fetch(`/api/devices/${deviceId}/remote-assist/arp-scan-schedule`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ minutes: Number(minutes) }),
  })
    .then(r => r.json())
    .then(data => {
      // The POST itself already landed correctly on `deviceId` server-side -- this guard only
      // stops the CONFIRMATION TEXT from painting onto a different device's panel if the admin
      // has since navigated away (shared singleton DOM, see raArpScanRefresh's comment above).
      if (!status || selectedDeviceId !== deviceId) return;
      if (data && data.ok) {
        status.textContent = _fmtArpScanInterval(data.minutes ?? minutes);
        status.className = 'small text-muted align-self-center';
      } else {
        status.textContent = `Failed: ${(data && data.error) || 'Unknown error'}`;
        status.className = 'small text-danger align-self-center';
      }
    })
    .catch(e => { if (status && selectedDeviceId === deviceId) { status.textContent = `Error: ${e.message}`; status.className = 'small text-danger align-self-center'; } });
}
// ── End ARP Scan ──────────────────────────────────────────────────────────────

// ── ARP Scan VLANs — manual subnet configuration ─────────────────────────────
// Lets the user add/remove extra VLAN subnets the device should scan alongside auto-detected
// local interfaces. Stored bastion-side; passed to the scan scripts on every run.
function raArpVlanToggleForm() {
  const form = document.getElementById('ra-arp-vlan-form');
  if (!form) return;
  form.classList.toggle('d-none');
  if (!form.classList.contains('d-none')) {
    const subnetEl = document.getElementById('ra-arp-vlan-subnet');
    if (subnetEl) { subnetEl.value = ''; subnetEl.focus(); }
  }
}

async function raArpVlanRefresh() {
  const el = document.getElementById('ra-arp-vlans');
  if (!el || !selectedDeviceId) return;
  const deviceId = selectedDeviceId;
  try {
    const data = await fetch(`/api/devices/${deviceId}/remote-assist/arp-vlans`).then(r => r.json());
    if (selectedDeviceId !== deviceId) return;
    _renderVlanList(el, data?.vlans || []);
  } catch (_) { el.textContent = 'No manual VLANs configured'; }
}

function raArpVlanAdd() {
  const subnetEl = document.getElementById('ra-arp-vlan-subnet');
  const labelEl = document.getElementById('ra-arp-vlan-label');
  const vlanIdEl = document.getElementById('ra-arp-vlan-id');
  if (!subnetEl || !selectedDeviceId) return;
  const subnet = subnetEl.value.trim();
  if (!subnet) { showToast('Subnet is required', 'warning'); return; }
  if (!/^\d+\.\d+\.\d+\.\d+\/\d{1,2}$/.test(subnet)) { showToast('Invalid CIDR format (use e.g. 192.168.1.0/24)', 'warning'); return; }
  const label = labelEl?.value?.trim() || '';
  const vlanId = vlanIdEl?.value ? Number(vlanIdEl.value) : null;
  const deviceId = selectedDeviceId;
  fetch(`/api/devices/${deviceId}/remote-assist/arp-vlans`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ action: 'add', subnet, label, vlanId }),
  })
    .then(r => r.json())
    .then(data => {
      if (selectedDeviceId !== deviceId) return;
      if (data.ok) {
        showToast(`VLAN ${subnet} added`, 'success');
        // Hide form and clear inputs
        const form = document.getElementById('ra-arp-vlan-form');
        if (form) form.classList.add('d-none');
        if (subnetEl) subnetEl.value = '';
        if (labelEl) labelEl.value = '';
        if (vlanIdEl) vlanIdEl.value = '';
        // Re-render the VLAN list from the response
        const vlansEl = document.getElementById('ra-arp-vlans');
        if (vlansEl && data.vlans) {
          _renderVlanList(vlansEl, data.vlans);
        } else {
          raArpVlanRefresh();
        }
      } else {
        showToast(data.error || 'Failed to add VLAN', 'danger');
      }
    })
    .catch(e => { if (selectedDeviceId === deviceId) showToast(e.message, 'danger'); });
}

function raArpVlanRemove(subnet) {
  if (!selectedDeviceId) return;
  const deviceId = selectedDeviceId;
  fetch(`/api/devices/${deviceId}/remote-assist/arp-vlans`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ action: 'remove', subnet }),
  })
    .then(r => r.json())
    .then(data => {
      if (selectedDeviceId !== deviceId) return;
      if (data.ok) {
        showToast(`VLAN ${subnet} removed`, 'success');
        const vlansEl = document.getElementById('ra-arp-vlans');
        if (vlansEl && data.vlans) {
          _renderVlanList(vlansEl, data.vlans);
        } else {
          raArpVlanRefresh();
        }
      } else {
        showToast(data.error || 'Failed to remove VLAN', 'danger');
      }
    })
    .catch(e => { if (selectedDeviceId === deviceId) showToast(e.message, 'danger'); });
}

function _renderVlanList(el, vlans) {
  if (!vlans.length) { el.textContent = 'No manual VLANs configured'; return; }
  el.innerHTML = vlans.map(v => {
    const idBadge = v.vlanId != null ? `<span class="badge text-bg-secondary ms-1" style="font-size:.6rem">VLAN ${escHtml(String(v.vlanId))}</span>` : '';
    return `<div class="d-inline-flex align-items-center gap-1 me-2 mb-1 p-1 border border-secondary-subtle rounded" style="background:var(--bs-body-bg)">
      <span class="font-monospace">${escHtml(v.subnet)}</span>
      ${v.label ? `<span class="text-muted">${escHtml(v.label)}</span>` : ''}
      ${idBadge}
      <button class="btn btn-sm btn-outline-danger border-0 py-0" style="font-size:.65rem" onclick="raArpVlanRemove('${escJsAttr(v.subnet)}')" title="Remove"><i class="bi bi-x"></i></button>
    </div>`;
  }).join('');
}
// ── End ARP Scan VLANs ───────────────────────────────────────────────────────

// ── ARP Sweep (velocity) Detection — continuous pktmon-based watch, opt-in ──
// Enable/disable shape mirrors Block Telemetry above; status shape is different (task-registration
// + heartbeat freshness, not a blocked/restored timestamp pair) — see arp_sweep_watch_status() in
// bastion-web.py.
// ── "starting up…" self-poll ────────────────────────────────────────────────
// raArpSweepRefresh() is only called on device-select and immediately after enable/disable —
// there is no standing poll. Enabling registers+starts the watcher, but its first ~4s pktmon
// capture window hasn't written heartbeat.json yet, so that one immediate refresh legitimately
// sees heartbeat:null and renders "Enabled — starting up…". With nothing ever re-checking, the
// panel then sat on that text FOREVER (until the device was reselected) even though the watcher
// was fully live — reported 2026-08-03, on a box where sweep detection was provably working (it
// had just caught a real 253-target nmap sweep). Cosmetic, but it reads as a hung feature.
// Self-terminating: only runs while the panel is showing a not-yet-confirmed state, stops as soon
// as a fresh heartbeat lands, on device change, or after the cap.
let _raArpSweepPollTimer = null;
let _raArpSweepPollTries = 0;
function _raArpSweepStopPoll() {
  if (_raArpSweepPollTimer) { clearInterval(_raArpSweepPollTimer); _raArpSweepPollTimer = null; }
  _raArpSweepPollTries = 0;
}
function _raArpSweepEnsurePoll(deviceId) {
  if (_raArpSweepPollTimer) return;          // already polling — never stack timers
  _raArpSweepPollTries = 0;
  _raArpSweepPollTimer = setInterval(() => {
    // 20 x 8s = ~160s cap. The loop writes a heartbeat every ~4s, so a healthy watcher flips
    // on the first or second tick; the cap only matters when it genuinely never comes up, and
    // that case must NOT poll forever.
    if (selectedDeviceId !== deviceId || ++_raArpSweepPollTries > 20) { _raArpSweepStopPoll(); return; }
    raArpSweepRefresh();
  }, 8000);
}

function _raArpSweepRender(data) {
  const status = document.getElementById('ra-arpsweep-status');
  const enableBtn = document.getElementById('ra-arpsweep-enable-btn');
  const disableBtn = document.getElementById('ra-arpsweep-disable-btn');
  if (!status || !enableBtn || !disableBtn) return;
  const installed = !!(data && data.installed);
  enableBtn.classList.toggle('d-none', installed);
  disableBtn.classList.toggle('d-none', !installed);
  if (!installed) {
    status.textContent = 'Disabled';
    status.className = 'small text-muted align-self-center';
    _raArpSweepStopPoll();
    return;
  }
  const hbTs = data.heartbeat && data.heartbeat.ts ? new Date(data.heartbeat.ts).getTime() : NaN;
  const ageSec = Number.isFinite(hbTs) ? Math.max(0, Math.round((Date.now() - hbTs) / 1000)) : null;
  if (data.taskState === 'Running' && ageSec !== null && ageSec < 120) {
    status.textContent = `Enabled — actively watching (last check ${ageSec}s ago)`;
    status.className = 'small text-success align-self-center';
    _raArpSweepStopPoll();                   // confirmed live — nothing left to wait for
  } else if (data.taskState === 'Running') {
    status.textContent = 'Enabled — starting up…';
    status.className = 'small text-info align-self-center';
    _raArpSweepEnsurePoll(selectedDeviceId); // keep checking until the first heartbeat lands
  } else {
    status.textContent = `Enabled — task state: ${data.taskState || 'unknown'}`;
    status.className = 'small text-warning align-self-center';
    _raArpSweepEnsurePoll(selectedDeviceId); // e.g. Ready/Queued — may still transition to Running
  }
}

function raArpSweepRefresh() {
  const status = document.getElementById('ra-arpsweep-status');
  if (!status || !selectedDeviceId) return;
  const deviceId = selectedDeviceId;
  fetch(`/api/devices/${deviceId}/remote-assist/arp-sweep-watch`)
    .then(r => r.json())
    .then(data => { if (selectedDeviceId === deviceId && data && data.ok !== false) _raArpSweepRender(data); })
    .catch(() => {});
}

function raArpSweepSet(enable) {
  const status = document.getElementById('ra-arpsweep-status');
  const enableBtn = document.getElementById('ra-arpsweep-enable-btn');
  const disableBtn = document.getElementById('ra-arpsweep-disable-btn');
  if (!status || !selectedDeviceId) return;
  const deviceId = selectedDeviceId;
  const run = () => {
    enableBtn.disabled = true; disableBtn.disabled = true;
    status.textContent = enable ? 'Enabling…' : 'Disabling…';
    status.className = 'small text-info align-self-center';
    fetch(`/api/devices/${deviceId}/remote-assist/arp-sweep-watch`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ enable }),
    })
      .then(r => r.json())
      .then(data => {
        if (selectedDeviceId !== deviceId) return;
        enableBtn.disabled = false; disableBtn.disabled = false;
        if (data && data.ok) { raArpSweepRefresh(); }
        else { status.textContent = `Failed: ${(data && data.error) || 'Unknown error'}`; status.className = 'small text-danger align-self-center'; }
      })
      .catch(e => {
        if (selectedDeviceId !== deviceId) return;
        enableBtn.disabled = false; disableBtn.disabled = false;
        status.textContent = `Error: ${e.message}`; status.className = 'small text-danger align-self-center';
      });
  };
  if (enable) {
    showConfirm({
      title: 'Enable ARP sweep detection?',
      body: 'Installs a continuous background watcher on this device filtered to ARP traffic only (Windows: built-in pktmon; Linux: sentineld native packet watch). Heavier than the scan above — runs indefinitely until you disable it.',
      okLabel: 'Enable',
      okClass: 'btn-primary',
      onConfirm: run,
    });
  } else {
    run();
  }
}
// ── End ARP Sweep Detection ──────────────────────────────────────────────────

// ── EDR — Behavioral Telemetry (read-only alert feed + enable/disable) ───────
// Phase 1 scope: no remote kill/isolate actions here yet (those land with the Active Remediation
// phase) — this panel is purely "turn Sysmon-backed watching on/off" + "show what it's found."
// Same enable/disable/status shape as ARP Sweep Detection above; events render newest-first, HIGH
// severity visually distinct (those are the ones that also paged you via the worker's poller).
function _raEdrRenderStatus(enabled) {
  const enableBtn = document.getElementById('ra-edr-enable-btn');
  const disableBtn = document.getElementById('ra-edr-disable-btn');
  if (!enableBtn || !disableBtn) return;
  enableBtn.classList.toggle('d-none', !!enabled);
  disableBtn.classList.toggle('d-none', !enabled);
}

// Phase 4 — best-effort forensic context ride-along (BuildLineageContext in EdrWatcher.cs): the
// correlated process's own parent chain + any network connections Sysmon observed for it. Absent
// whenever Sysmon never saw the ProcessGuid (unhealthy, or predates the watcher's own TTL window)
// — render nothing rather than a confusing empty section.
function _raEdrLineageSummary(ctx) {
  if (!ctx || typeof ctx !== 'object') return '';
  const chain = [ctx.parent_image, ctx.image].filter(Boolean).map(esc).join(' → ');
  const conns = Array.isArray(ctx.network_connections) && ctx.network_connections.length
    ? ` | Network: ${ctx.network_connections.slice(0, 8).map(esc).join(', ')}`
    : '';
  if (!chain && !conns) return '';
  return `<div class="small text-muted" style="word-break:break-all">Lineage: ${chain || esc(ctx.image || '')}${conns}</div>`;
}

function _raEdrRenderEvents(events) {
  const wrap = document.getElementById('ra-edr-events');
  if (!wrap) return;
  if (!Array.isArray(events) || !events.length) {
    wrap.innerHTML = '<div class="text-muted p-1">No findings yet.</div>';
    return;
  }
  const RULE_LABEL = {
    process_lineage: 'Suspicious process lineage',
    create_remote_thread: 'CreateRemoteThread (hollowing-adjacent)',
    lsass_access: 'LSASS access (credential-dump indicator)',
    canary_file_touch: 'Canary file touched — autonomous kill+isolate',
    mass_file_modification: 'Mass file modification pattern (possible ransomware)',
    process_hollowing_indicator: 'Process hollowing indicator (experimental)',
    driver_load: 'Unusual kernel driver loaded',
    registry_persistence: 'Registry persistence attempt',
    process_tamper: 'Process tampering',
    shadow_copy_attack: 'Shadow copy deleted (ransomware indicator)',
    unusual_outbound_connection: 'Unusual outbound connection',
    sysmon_sensor_down: 'Sysmon sensor down',
    defender_disabled: 'Windows Defender disabled',
    agent_process_killed: 'Sentinel tooling process terminated',
    agent_process_killed_info: 'LSASS-accessing process terminated',
  };
  // Admin-dismissed ("mark safe") findings are persisted server-side (see /edr/safe) and hidden
  // from the default feed; the toggle in the panel header shows them for review/undo.
  const showSafe = document.getElementById('ra-edr-show-safe')?.checked;
  const safeEvents = events.filter(e => e.safe);
  const visible = events.filter(e => !e.safe);
  if (!showSafe && visible.length === 0 && safeEvents.length) {
    wrap.innerHTML = `<div class="text-muted p-1">All ${safeEvents.length} finding(s) marked safe. <button class="btn btn-sm btn-outline-secondary py-0 px-1" onclick="document.getElementById('ra-edr-show-safe').checked=true;raEdrRefresh()">Show</button></div>`;
    return;
  }
  const list = showSafe ? events : visible;
  // Group findings by rule (collapsible), preserving first-seen rule order and in-group event
  // order. Collapse state persists across re-renders via the global show/hide listeners that
  // track every collapse id in _openDayGroups (same mechanism as the Logs/Screen-Text day
  // groups — the `edr-grp-` ids are unique so there's no collision with the `*-day-` ids).
  const groups = new Map(); // rule → {label, events:[]}
  for (const e of list.slice(0, 100)) {
    const rule = e.rule || 'unknown';
    if (!groups.has(rule)) groups.set(rule, { label: RULE_LABEL[rule] || rule, events: [] });
    groups.get(rule).events.push(e);
  }
  wrap.innerHTML = [...groups.entries()].map(([rule, g]) => {
    const colId = 'edr-grp-' + rule.replace(/[^\w-]/g, '-');
    const isOpen = _openDayGroups.has(colId);
    const highCount = g.events.filter(x => x.severity === 'high').length;
    // Group header badge reflects the worst severity present in the group.
    const badgeClass = highCount ? 'bg-danger' : 'bg-secondary';
    return `<div class="mb-2">
      <div class="d-flex align-items-center gap-2 mb-1">
        <div class="d-flex align-items-center gap-1 flex-shrink-0" role="button"
             data-bs-toggle="collapse" data-bs-target="#${colId}" style="cursor:pointer">
          <span class="badge ${badgeClass} px-2 py-1" style="font-size:.72rem;white-space:nowrap">
            <i class="bi bi-chevron-${isOpen ? 'down' : 'right'} me-1"></i>
            ${esc(g.label)}
            <span class="ms-2 opacity-75">${g.events.length}</span>
            ${highCount ? `<span class="ms-1 opacity-75">${highCount} high</span>` : ''}
          </span>
        </div>
        <hr class="flex-grow-1 m-0" style="border-color:rgba(255,255,255,.12)">
      </div>
      <div class="collapse${isOpen ? ' show' : ''}" id="${colId}">
        ${g.events.map(e => {
          const high = e.severity === 'high';
          const when = e.time ? new Date(e.time).toLocaleString() : '';
          const detail = esc(e.reason || e.command_line || e.image || e.source_image || e.target_image || '');
          const itemBadgeClass = high ? 'bg-danger' : 'bg-secondary';
          // Only offer "Delete file" when the finding actually names a plausible absolute Windows
          // file path — bastion re-validates this server-side anyway (delete_edr_file() looks the
          // path up from the stored finding itself, never trusts anything from the browser), this
          // is just to avoid showing a dead-end button on findings with no deletable target.
          const deletable = /^[A-Za-z]:\\/.test(e.image || '');
          const delBtn = deletable
            ? `<button class="btn btn-sm btn-outline-danger py-0 px-1 ms-2" onclick="raEdrDeleteFile(${e.id}, '${escJsAttr(e.image)}')"><i class="bi bi-trash3"></i> Delete file</button>`
            : '';
          // Per-process suppression — available for any event with a source_image basename.
          const sourceBase = (e.source_image || '').split('\\').pop().toLowerCase();
          const suppressBtn = sourceBase
            ? `<button class="btn btn-sm btn-outline-secondary py-0 px-1 ms-1" onclick="raEdrSuppressProcess('${escJsAttr(sourceBase)}')" title="Mute this process in the EDR feed"><i class="bi bi-volume-mute"></i></button>`
            : '';
          // Per-finding "mark safe" — persisted server-side, hidden from the default feed (undoable).
          // Args are escJsAttr'd single-quoted JS strings (NEVER raw JSON.stringify — the wrapping
          // double quotes truncate the double-quoted onclick attribute at the first argument, making
          // the click a silent JS SyntaxError; found live 2026-08-01, the button had never worked).
          const safeBtn = e.safe
             ? `<button class="btn btn-sm btn-outline-secondary py-0 px-1 ms-1" onclick="raEdrUnsafe(${e.id})" title="Bring this finding back"><i class="bi bi-arrow-counterclockwise"></i> Unmark</button>`
            : `<button class="btn btn-sm btn-outline-success py-0 px-1 ms-1" onclick="raEdrMarkSafe(${e.id}, '${escJsAttr(e.rule || '')}', '${escJsAttr(e.reason || '')}', '${escJsAttr(e.image || '')}', '${escJsAttr(e.time || '')}')" title="Dismiss this finding as safe"><i class="bi bi-shield-check"></i> Mark safe</button>`;
          const lineage = _raEdrLineageSummary(e.lineage_context);
          const safeBadge = e.safe ? ' <span class="badge bg-success ms-1">SAFE</span>' : '';
          return `<div class="border-bottom py-1${e.safe ? ' opacity-50' : ''}">
      <span class="badge ${itemBadgeClass} me-1">${esc((e.severity || '').toUpperCase())}</span>
      <span class="fw-bold">${esc(g.label)}</span>
      <span class="text-muted ms-1">${esc(when)}</span>
      ${safeBadge}
      ${delBtn}
      ${suppressBtn}
      ${safeBtn}
      <div class="small text-muted" style="word-break:break-all">${detail}</div>
      ${lineage}
    </div>`;
        }).join('')}
      </div>
    </div>`;
  }).join('');
}

function raEdrMarkSafe(eventId, rule, reason, image, time) {
  if (!selectedDeviceId) return;
  fetch(`/api/devices/${selectedDeviceId}/remote-assist/edr/safe`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ eventId, rule, reason, image, time }),
  })
    .then(r => r.json())
    .then(data => {
      if (data && data.ok) { showToast('Marked safe', 'success'); raEdrRefresh(); }
      else showToast(`Failed: ${(data && data.error) || 'Unknown error'}`, 'danger');
    })
    .catch(e => showToast(`Error: ${e.message}`, 'danger'));
}

function raEdrUnsafe(eventId) {
  if (!selectedDeviceId) return;
  fetch(`/api/devices/${selectedDeviceId}/remote-assist/edr/unsafe`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ eventId }),
  })
    .then(r => r.json())
    .then(data => {
      if (data && data.ok) { showToast('Finding restored', 'success'); raEdrRefresh(); }
      else showToast(`Failed: ${(data && data.error) || 'Unknown error'}`, 'danger');
    })
    .catch(e => showToast(`Error: ${e.message}`, 'danger'));
}

// Wipe the whole EDR findings feed for this device ("Clear history" button in the panel header).
// Confirmation-gated like raEdrDeleteFile — this deletes every accumulated finding, and also
// forgets all "mark safe" dismissals (their event ids restart at 1 after the clear, so stale
// safe-rows could silently hide unrelated future findings — the server route deletes them).
// Only the bastion-side events.jsonl is removed; the Sysmon watcher stays enabled and keeps
// appending new findings, and per-process suppression (denylist) is left intact.
function raEdrClear() {
  if (!selectedDeviceId) return;
  showConfirm({
    title: 'Clear EDR history?',
    body: 'Deletes every accumulated finding for this device from the EDR feed. The watcher stays enabled and new findings will keep appearing. This cannot be undone.',
    okLabel: 'Clear History',
    okClass: 'btn-danger',
    onConfirm: () => {
      fetch(`/api/devices/${selectedDeviceId}/remote-assist/edr/clear`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}',
      })
        .then(r => r.json())
        .then(data => {
          showToast(data && data.ok ? 'EDR history cleared' : `Failed: ${(data && data.error) || 'Unknown error'}`, data && data.ok ? 'success' : 'danger');
          raEdrRefresh();
        })
        .catch(e => showToast(`Error: ${e.message}`, 'danger'));
    },
  });
}

function raEdrDeleteFile(eventId, path) {
  if (!selectedDeviceId) return;
  showConfirm({
    title: 'Delete this file?',
    // showConfirm's body is set via innerHTML — esc() (TEXT-context) since `path` originates from
    // a device-reported file name and could contain HTML-significant characters.
    body: `Deletes ${esc(path)} from the device. This cannot be undone.`,
    okLabel: 'Delete File',
    okClass: 'btn-danger',
    onConfirm: () => {
      fetch(`/api/devices/${selectedDeviceId}/remote-assist/edr/file-delete`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ eventId }),
      })
        .then(r => r.json())
        .then(data => {
          showToast(data && data.ok ? 'File deleted' : `Failed: ${(data && data.error) || 'Unknown error'}`, data && data.ok ? 'success' : 'danger');
        })
        .catch(e => showToast(`Error: ${e.message}`, 'danger'));
    },
  });
}

// enable_status/enable_error ride along on the events response (get_edr_events() in
// bastion-web.py enriches it) rather than needing a separate round trip — see enable_edr()'s doc
// comment for why the enable action itself is fire-and-forget (backgrounded bastion-side; a
// synchronous Sysmon-install+provision chain can exceed Cloudflare's ~100s dashboard proxy
// timeout, hit live on the very first real attempt 2026-07-19).
const EDR_ENABLE_STATUS_LABEL = {
  installing_sysmon: 'Installing Sysmon…',
  provisioning: 'Provisioning watcher…',
};
function _raEdrRenderEnableProgress(data) {
  const status = document.getElementById('ra-edr-status');
  if (!status) return null; // returns the terminal state ('enabled'|'failed'|null=still in progress)
  const st = data && data.enable_status;
  if (st === 'enabled') {
    status.textContent = '';
    status.className = 'small text-muted align-self-center';
    return 'enabled';
  }
  if (st === 'failed') {
    status.textContent = `Failed: ${(data && data.enable_error) || 'Unknown error'}`;
    status.className = 'small text-danger align-self-center';
    return 'failed';
  }
  if (st && EDR_ENABLE_STATUS_LABEL[st]) {
    status.textContent = EDR_ENABLE_STATUS_LABEL[st];
    status.className = 'small text-info align-self-center';
  }
  return null;
}

function raEdrRefresh() {
  if (!selectedDeviceId) return;
  const deviceId = selectedDeviceId;
  fetch(`/api/devices/${deviceId}/remote-assist/edr/status`)
    .then(r => r.json())
    .then(data => { if (selectedDeviceId === deviceId && data && data.ok !== false) _raEdrRenderStatus(data.enabled); })
    .catch(() => {});
  fetch(`/api/devices/${deviceId}/remote-assist/edr/events?severity=all`)
    .then(r => r.json())
    .then(data => {
      if (selectedDeviceId !== deviceId || !data || data.ok === false) return;
      _raEdrRenderEvents(data.events);
      _raEdrRenderStatus(data.enabled);
    })
    .catch(() => {});
}

// Polls the events endpoint (which carries enable_status) every 4s until the backgrounded
// bastion-side install reaches a terminal state, or ~3 minutes elapse (belt-and-suspenders —
// enable_edr()'s own PS1 timeouts should always resolve well before this). Keeps polling the SAME
// device the install was started on even if the admin navigates elsewhere (the install itself is
// running server-side regardless of what's on screen) but stops touching the shared DOM once the
// admin is no longer looking at that device's panel.
function _raEdrPollEnableProgress(deviceId) {
  let elapsedMs = 0;
  const POLL_MS = 4000, MAX_MS = 3 * 60 * 1000;
  const tick = () => {
    fetch(`/api/devices/${deviceId}/remote-assist/edr/events?severity=all`)
      .then(r => r.json())
      .then(data => {
        if (!data || data.ok === false) return;
        const onScreen = selectedDeviceId === deviceId;
        const enableBtn = onScreen ? document.getElementById('ra-edr-enable-btn') : null;
        const disableBtn = onScreen ? document.getElementById('ra-edr-disable-btn') : null;
        if (onScreen) _raEdrRenderEvents(data.events);
        const terminal = onScreen ? _raEdrRenderEnableProgress(data) : (data.enable_status === 'enabled' ? 'enabled' : data.enable_status === 'failed' ? 'failed' : null);
        if (terminal === 'enabled') {
          if (enableBtn) enableBtn.disabled = false;
          if (disableBtn) disableBtn.disabled = false;
          if (onScreen) _raEdrRenderStatus(true);
          return;
        }
        if (terminal === 'failed') {
          if (enableBtn) enableBtn.disabled = false;
          if (disableBtn) disableBtn.disabled = false;
          if (onScreen) _raEdrRenderStatus(false);
          return;
        }
        elapsedMs += POLL_MS;
        if (elapsedMs < MAX_MS) { setTimeout(tick, POLL_MS); }
        else if (onScreen) {
          if (enableBtn) enableBtn.disabled = false;
          if (disableBtn) disableBtn.disabled = false;
          const status = document.getElementById('ra-edr-status');
          if (status) { status.textContent = 'Still installing — check back shortly.'; status.className = 'small text-warning align-self-center'; }
        }
      })
      .catch(() => { elapsedMs += POLL_MS; if (elapsedMs < MAX_MS) setTimeout(tick, POLL_MS); });
  };
  setTimeout(tick, POLL_MS);
}

function raEdrSet(enable) {
  const status = document.getElementById('ra-edr-status');
  const enableBtn = document.getElementById('ra-edr-enable-btn');
  const disableBtn = document.getElementById('ra-edr-disable-btn');
  if (!status || !selectedDeviceId) return;
  const deviceId = selectedDeviceId;
  const run = () => {
    enableBtn.disabled = true; disableBtn.disabled = true;
    status.textContent = enable ? 'Starting install (Sysmon download + setup — may take a minute or two)…' : 'Disabling…';
    status.className = 'small text-info align-self-center';
    const action = enable ? 'enable' : 'disable';
    fetch(`/api/devices/${deviceId}/remote-assist/edr/${action}`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}',
    })
      .then(r => r.json())
      .then(data => {
        if (data && data.ok && enable) {
          // Fire-and-forget accepted — bastion is installing in the background; poll for progress
          // rather than treating this response as final (see _raEdrPollEnableProgress's comment).
          _raEdrPollEnableProgress(deviceId);
          return;
        }
        if (selectedDeviceId !== deviceId) return;
        enableBtn.disabled = false; disableBtn.disabled = false;
        if (data && data.ok) {
          status.textContent = '';
          _raEdrRenderStatus(enable);
          raEdrRefresh();
        } else { status.textContent = `Failed: ${(data && data.error) || 'Unknown error'}`; status.className = 'small text-danger align-self-center'; }
      })
      .catch(e => {
        if (selectedDeviceId !== deviceId) return;
        enableBtn.disabled = false; disableBtn.disabled = false;
        status.textContent = `Error: ${e.message}`; status.className = 'small text-danger align-self-center';
      });
  };
  if (enable) {
    showConfirm({
      title: 'Enable EDR on this PC?',
      body: 'Installs Sysmon (Microsoft\'s own signed telemetry driver) and a background watcher that reports suspicious process lineage and LSASS credential-dump access attempts. Detective only, not preventive — see the panel description for what this can and can\'t catch.',
      okLabel: 'Enable EDR',
      okClass: 'btn-primary',
      onConfirm: run,
    });
  } else {
    run();
  }
}

// ── EDR Phase 2 — Remote Process Intervention + Dynamic Host Isolation ───────
function raEdrProcessListLoad() {
  const status = document.getElementById('ra-edr-proclist-status');
  const wrap = document.getElementById('ra-edr-proclist');
  const btn = document.getElementById('ra-edr-proclist-btn');
  if (!status || !wrap || !selectedDeviceId) return;
  const deviceId = selectedDeviceId;
  btn.disabled = true;
  status.textContent = 'Loading…';
  status.className = 'small text-info align-self-center';
  fetch(`/api/devices/${deviceId}/remote-assist/edr/process-list`)
    .then(r => r.json())
    .then(data => {
      if (selectedDeviceId !== deviceId) return;
      btn.disabled = false;
      if (!data || data.ok === false || !Array.isArray(data.rows)) {
        status.textContent = `Failed: ${(data && data.error) || 'Unknown error'}`;
        status.className = 'small text-danger align-self-center';
        return;
      }
      status.textContent = `${data.rows.length} processes`;
      status.className = 'small text-muted align-self-center';
      wrap.classList.remove('d-none');
      const rows = data.rows.slice().sort((a, b) => (a.name || '').localeCompare(b.name || ''));
      wrap.innerHTML = `<table class="table table-sm table-borderless mb-0">
        <tbody>${rows.map(p => `<tr>
          <td class="text-muted" style="width:4rem">${esc(p.pid)}</td>
          <td>${esc(p.name)}<div class="text-muted" style="word-break:break-all">${esc(p.cmd || p.path || '')}</div></td>
          <td class="text-end" style="width:11rem">
             <button class="btn btn-sm btn-outline-secondary py-0 px-1" title="Freeze every thread — inspect without killing" onclick="raEdrSuspendPid(${p.pid}, '${escJsAttr(p.name || String(p.pid))}')"><i class="bi bi-pause-circle"></i> Suspend</button>
            <button class="btn btn-sm btn-outline-secondary py-0 px-1" title="Undo Suspend" onclick="raEdrResumePid(${p.pid}, '${escJsAttr(p.name || String(p.pid))}')"><i class="bi bi-play-circle"></i> Resume</button>
            <button class="btn btn-sm btn-outline-danger py-0 px-1" onclick="raEdrKillPid(${p.pid}, '${escJsAttr(p.name || String(p.pid))}')"><i class="bi bi-x-circle"></i> Kill</button>
          </td>
        </tr>`).join('')}</tbody>
      </table>`;
    })
    .catch(e => {
      btn.disabled = false;
      status.textContent = `Error: ${e.message}`;
      status.className = 'small text-danger align-self-center';
    });
}

function raEdrSuppressProcess(process) {
  if (!selectedDeviceId || !process) return;
  showConfirm({
    title: `Suppress ${process} in EDR feed?`,
    body: `All future events from "${process}" will be hidden in the EDR tab for this device. Use the fleet panel to undo.`,
    okLabel: 'Suppress',
    okClass: 'btn-danger',
    onConfirm: () => {
      fetch(`/api/devices/${selectedDeviceId}/remote-assist/edr/denylist/add`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ process }),
      })
        .then(r => r.json())
        .then(data => {
          showToast(data.ok ? `Suppressed ${process}` : (data.error || 'Failed'), data.ok ? 'success' : 'danger');
          if (data.ok) raEdrRefresh();
        })
        .catch(() => showToast('Failed to suppress process', 'danger'));
    },
  });
}

function raEdrKillPid(pid, name) {
  if (!selectedDeviceId) return;
  showConfirm({
    title: `Kill ${esc(name)} (PID ${pid})?`,
    body: 'Force-kills this process and its entire child-process tree. This cannot be undone.',
    okLabel: 'Kill Process',
    okClass: 'btn-danger',
    onConfirm: () => {
      fetch(`/api/devices/${selectedDeviceId}/remote-assist/edr/process-kill`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ pid }),
      })
        .then(r => r.json())
        .then(data => {
          showToast(data && data.ok ? 'Process killed' : `Failed: ${(data && data.error) || 'Unknown error'}`, data && data.ok ? 'success' : 'danger');
          if (data && data.ok) raEdrProcessListLoad();
        })
        .catch(e => showToast(`Error: ${e.message}`, 'danger'));
    },
  });
}

// Phase 4 — freeze/unfreeze every thread of a PID (no per-process "is it suspended" live check —
// Win32_Process/CIM has no such field; the process list simply always shows both buttons, same as
// Kill always being available regardless of what state the process is already in).
function raEdrSuspendPid(pid, name) {
  if (!selectedDeviceId) return;
  fetch(`/api/devices/${selectedDeviceId}/remote-assist/edr/process-suspend`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ pid }),
  })
    .then(r => r.json())
    .then(data => showToast(data && data.ok ? `${esc(name)} suspended` : `Failed: ${(data && data.error) || 'Unknown error'}`, data && data.ok ? 'success' : 'danger'))
    .catch(e => showToast(`Error: ${e.message}`, 'danger'));
}

function raEdrResumePid(pid, name) {
  if (!selectedDeviceId) return;
  fetch(`/api/devices/${selectedDeviceId}/remote-assist/edr/process-resume`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ pid }),
  })
    .then(r => r.json())
    .then(data => showToast(data && data.ok ? `${esc(name)} resumed` : `Failed: ${(data && data.error) || 'Unknown error'}`, data && data.ok ? 'success' : 'danger'))
    .catch(e => showToast(`Error: ${e.message}`, 'danger'));
}

// `stale` = server.js couldn't reach bastion for a live confirmation and fell back to the last
// known local flag (see getEdrIsolated()'s doc comment) — shown as "(unconfirmed)" rather than
// silently rendering identically to a fresh, confirmed check.
function _raEdrIsolateRenderStatus(isolated, stale) {
  const blockBtn = document.getElementById('ra-edr-isolate-block-btn');
  const unblockBtn = document.getElementById('ra-edr-isolate-unblock-btn');
  const status = document.getElementById('ra-edr-isolate-status');
  if (!blockBtn || !unblockBtn) return;
  blockBtn.classList.toggle('d-none', !!isolated);
  unblockBtn.classList.toggle('d-none', !isolated);
  if (status) {
    const suffix = stale ? ' (unconfirmed — last known state)' : '';
    status.textContent = isolated ? `Isolated — network cut off except this tunnel${suffix}` : (stale ? `Not isolated${suffix}` : '');
    status.className = isolated ? 'small text-danger align-self-center' : (stale ? 'small text-muted align-self-center' : 'small text-muted align-self-center');
  }
}

function raEdrIsolateRefresh() {
  if (!selectedDeviceId) return;
  const deviceId = selectedDeviceId;
  fetch(`/api/devices/${deviceId}/remote-assist/edr/isolate-status`)
    .then(r => r.json())
    .then(data => { if (selectedDeviceId === deviceId && data && data.ok !== false) _raEdrIsolateRenderStatus(data.isolated, data.stale); })
    .catch(() => {});
}

function raEdrIsolateSet(enable) {
  const status = document.getElementById('ra-edr-isolate-status');
  const blockBtn = document.getElementById('ra-edr-isolate-block-btn');
  const unblockBtn = document.getElementById('ra-edr-isolate-unblock-btn');
  if (!status || !selectedDeviceId) return;
  const deviceId = selectedDeviceId;
  const run = () => {
    blockBtn.disabled = true; unblockBtn.disabled = true;
    status.textContent = enable ? 'Isolating…' : 'Restoring…';
    status.className = 'small text-info align-self-center';
    const action = enable ? 'block' : 'unblock';
    fetch(`/api/devices/${deviceId}/remote-assist/edr/isolate/${action}`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}',
    })
      .then(r => r.json())
      .then(data => {
        if (selectedDeviceId !== deviceId) return;
        blockBtn.disabled = false; unblockBtn.disabled = false;
        if (data && data.ok) { _raEdrIsolateRenderStatus(enable); }
        else { status.textContent = `Failed: ${(data && data.error) || 'Unknown error'}`; status.className = 'small text-danger align-self-center'; }
      })
      .catch(e => {
        if (selectedDeviceId !== deviceId) return;
        blockBtn.disabled = false; unblockBtn.disabled = false;
        status.textContent = `Error: ${e.message}`; status.className = 'small text-danger align-self-center';
      });
  };
  if (enable) {
    showConfirm({
      title: 'Isolate this PC from the network?',
      body: 'Blocks ALL inbound and outbound network traffic except this Remote Assist management tunnel. The device owner loses internet access entirely until you Restore. Use only when something looks actively compromised.',
      okLabel: 'Isolate Now',
      okClass: 'btn-danger',
      onConfirm: run,
    });
  } else {
    run();
  }
}
// ── End EDR ────────────────────────────────────────────────────────────────


// ── Windows Fleet Panel — global controls across every remote_assist device ─────────────────
// Same primitives as the per-device Reverse SSH tab above; server.js's fleetFanOut() does the
// per-device access-control filtering (a ZK-owned device is excluded here exactly like it's
// 403'd one at a time), so this panel never needs a device selected at all.
let _wfSrpBlockedMerged = [];

function toggleWindowsFleetPanel() {
  const panel = document.getElementById('windows-fleet-panel');
  if (!panel) return;
  const opening = panel.style.display !== 'flex';
  panel.style.display = opening ? 'flex' : 'none';
  if (opening) wfPopulateGroupSelect();
}

// Populates the Target dropdown from the caller's own sidebar device groups (device_groups /
// window._deviceGroups — same groups the sidebar itself uses), restricted to groups that
// actually contain at least one Windows SentinelRemoteAssist device (nothing else is fleet-
// controllable, so an empty group would just be a dead option). Called when the panel opens and
// whenever the device list refreshes while it's open, so a newly-created/renamed group shows up
// without having to close and reopen the panel.
function wfPopulateGroupSelect() {
  const sel = document.getElementById('wf-group-select');
  if (!sel) return;
  const prev = sel.value;
  const devices = window._deviceList || [];
  const groups = (window._deviceGroups || []).slice().sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0));
  const counts = new Map();
  for (const d of devices) {
    if ((d.platform === 'windows' || d.platform === 'linux') && d.agent_kind === 'remote_assist' && d.ui_group_id) {
      counts.set(d.ui_group_id, (counts.get(d.ui_group_id) || 0) + 1);
    }
  }
  const opts = ['<option value="">All Devices</option>'];
  for (const g of groups) {
    const n = counts.get(g.id) || 0;
    if (!n) continue;
    opts.push(`<option value="${escAttr(g.id)}">${escHtml(g.name)} (${n})</option>`);
  }
  sel.innerHTML = opts.join('');
  if (prev && [...sel.options].some(o => o.value === prev)) sel.value = prev;
}

// Read at click-time by every wf* action below — '' (All Devices) is sent as groupId:null so
// server.js's fleetControllableRemoteAssistDeviceIds() runs its normal unscoped query.
function wfGroupId() {
  return document.getElementById('wf-group-select')?.value || null;
}

// Human-readable scope for confirm-dialog/status copy — "every device" for All Devices, or the
// selected group's name (device count stripped) otherwise.
function wfScopeLabel() {
  const sel = document.getElementById('wf-group-select');
  const opt = sel?.selectedOptions?.[0];
  return (sel?.value && opt) ? `the "${opt.textContent.replace(/\s*\(\d+\)$/, '')}" group` : 'every device';
}

function wfGroupChanged() {
  // Nothing already-loaded should silently go stale after switching target — the Check
  // Blocked & Ran list is the one panel section with meaningful loaded state to refresh here
  // (everything else is action buttons with no persistent result to re-scope).
  const activityResults = document.getElementById('wf-srp-activity-results');
  if (activityResults && !activityResults.classList.contains('d-none')) wfLoadSrpActivity();
}

function _wfUpdateDeviceCount(n) {
  const el = document.getElementById('wf-device-count');
  if (el) el.textContent = `${n} device${n === 1 ? '' : 's'}`;
}

function wfSetInstallMode(enable) {
  const status = document.getElementById('wf-install-mode-status');
  if (!status) return;
  const run = () => {
    status.textContent = enable ? 'Enabling Install Mode...' : 'Restoring enforcement...';
    status.className = 'small text-info';
    fetch('/api/remote-assist/fleet/install-mode', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ mode: enable ? 'audit' : 'enforce', groupId: wfGroupId() }),
    })
      .then(r => r.json())
      .then(data => {
        const results = data.results || [];
        _wfUpdateDeviceCount(results.length);
        const okN = results.filter(r => r.ok).length;
        status.textContent = `${enable ? 'Install Mode enabled' : 'Enforcement restored'} on ${okN}/${results.length} device(s).`;
        status.className = okN === results.length ? 'small text-success' : 'small text-warning';
        showToast(`${enable ? 'Install Mode enabled' : 'Enforcement restored'} (${okN}/${results.length})`, okN === results.length ? 'success' : 'warning');
      })
      .catch(e => { status.textContent = `Error: ${e.message}`; status.className = 'small text-danger'; });
  };
  if (enable) {
    showConfirm({
      title: `Enable Install Mode on ${wfScopeLabel()}?`,
      body: `AppLocker will temporarily allow EVERY app/.exe to run on ${wfScopeLabel()} — nothing is blocked while Install Mode is on. Switch back to Enforce when you're done.`,
      okLabel: 'Enable',
      okClass: 'btn-warning',
      onConfirm: run,
    });
  } else {
    run();
  }
}

// Fleet "Update Agent" — same fan-out primitive as wfSetInstallMode above; the gating that keeps
// this from ever force-pushing to a public user's device lives server-side in
// fleetControllableRemoteAssistDeviceIds() (see the route's own doc comment), not here.
function wfUpdateAgent(btn) {
  const status = document.getElementById('wf-agent-update-status');
  if (!status) return;
  showConfirm({
    title: `Update Agent on ${wfScopeLabel()}?`,
    body: `Pushes the current agent build to every connected, controllable device in ${wfScopeLabel()}. Each device briefly disconnects during the swap.`,
    okLabel: 'Update',
    okClass: 'btn-danger',
    onConfirm: () => {
      status.textContent = 'Updating…';
      status.className = 'small text-info';
      fetch('/api/remote-assist/fleet/agent-update', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ groupId: wfGroupId() }),
      })
        .then(r => r.json())
        .then(data => {
          const results = data.results || [];
          _wfUpdateDeviceCount(results.length);
          const okN = results.filter(r => r.ok).length;
          status.textContent = `Updated ${okN}/${results.length} device(s).`;
          status.className = okN === results.length && results.length ? 'small text-success' : 'small text-warning';
          showToast(`Agent update: ${okN}/${results.length}`, okN === results.length && results.length ? 'success' : 'warning');
        })
        .catch(e => { status.textContent = `Error: ${e.message}`; status.className = 'small text-danger'; });
    },
  });
}

// Same live AppLocker-log endpoint as the per-device Reverse SSH tab's "Check Blocked & Ran"
// button (server.js's /api/remote-assist/fleet/srp/activity, mirroring bastionClient.srpActivity)
// — normal Enforce-mode 8002/8003/8004 events, no Install Mode toggle, no full filesystem scan.
// Replaces the old fleet "Show What Ran" (which only ever surfaced Install-Mode-only 8003 events).
let _wfSrpRanMerged = [];

function wfLoadSrpActivity() {
  const status = document.getElementById('wf-srp-activity-status');
  const results = document.getElementById('wf-srp-activity-results');
  if (!status) return;
  status.textContent = 'Reading AppLocker logs...';
  results?.classList.add('d-none');
  const qs = wfGroupId() ? `?groupId=${encodeURIComponent(wfGroupId())}` : '';
  fetch(`/api/remote-assist/fleet/srp/activity${qs}`)
    .then(r => r.json())
    .then(data => {
      const devices = data.devices || [];
      _wfUpdateDeviceCount(devices.length);
      _wfSrpBlockedMerged = data.merged || [];
      _wfSrpRanMerged = data.mergedRan || [];
      if (!_wfSrpBlockedMerged.length && !_wfSrpRanMerged.length) {
        status.textContent = devices.length ? `No AppLocker activity on any of ${devices.length} device(s) yet.` : 'No controllable devices in this scope.';
        return;
      }
      status.textContent = `${devices.length} device(s) — ${_wfSrpBlockedMerged.length} blocked path(s), ${_wfSrpRanMerged.length} ran/allowed path(s).`;
      const blockedCountEl = document.getElementById('wf-srp-blocked-count');
      const blockedListEl = document.getElementById('wf-srp-blocked-list');
      if (blockedCountEl) blockedCountEl.textContent = `${_wfSrpBlockedMerged.length} path(s)`;
      if (blockedListEl) {
        blockedListEl.innerHTML = _wfSrpBlockedMerged.length ? _wfSrpBlockedMerged.map((e, i) => `
          <div class="d-flex align-items-start gap-2 py-1 border-bottom border-secondary-subtle">
            <div class="form-check flex-grow-1">
              <input class="form-check-input wf-srp-blocked-chk" type="checkbox" id="wf-srp-blocked-${i}" data-index="${i}">
              <label class="form-check-label small d-block" for="wf-srp-blocked-${i}">
                <span class="font-monospace" style="word-break:break-all">${escHtml(e.path || '')}</span>
                <span class="text-muted"> — blocked ${e.count}x on ${e.deviceIds.length} device(s)</span>
              </label>
            </div>
          </div>`).join('') : '<div class="small text-muted">Nothing blocked in this scope.</div>';
      }
      const ranCountEl = document.getElementById('wf-srp-ran-count');
      const ranListEl = document.getElementById('wf-srp-ran-list');
      if (ranCountEl) ranCountEl.textContent = `${_wfSrpRanMerged.length} path(s)`;
      if (ranListEl) {
        ranListEl.innerHTML = _wfSrpRanMerged.length ? _wfSrpRanMerged.map(e => `
          <div class="small py-1 border-bottom border-secondary-subtle">
            <span class="font-monospace" style="word-break:break-all">${escHtml(e.path || '')}</span>
            <span class="text-muted"> — ran ${e.count}x on ${e.deviceIds.length} device(s)</span>
          </div>`).join('') : '<div class="small text-muted">Nothing ran in this scope.</div>';
      }
      document.getElementById('wf-srp-blocked-selectall')?.removeAttribute('checked');
      results?.classList.remove('d-none');
    })
    .catch(e => { status.textContent = `Error: ${e.message}`; });
}

function wfSrpBlockedSelectAll(checked) {
  document.querySelectorAll('.wf-srp-blocked-chk').forEach(cb => cb.checked = checked);
}

function wfSrpApprove() {
  const btn = document.getElementById('wf-srp-approve-btn');
  const status = document.getElementById('wf-srp-approve-status');
  if (!btn || !status) return;
  const paths = [];
  document.querySelectorAll('.wf-srp-blocked-chk:checked').forEach(cb => {
    const e = _wfSrpBlockedMerged[parseInt(cb.dataset.index, 10)];
    if (e?.path) paths.push(e.path);
  });
  if (!paths.length) { showToast('Select at least one path first', 'warning'); return; }
  btn.disabled = true; btn.textContent = 'Approving...';
  status.classList.remove('d-none');
  status.textContent = `Approving on ${wfScopeLabel()}...`;
  status.className = 'small mt-1 text-info';
  fetch('/api/remote-assist/fleet/what-ran/approve', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ paths, groupId: wfGroupId() }),
  })
    .then(r => r.json())
    .then(data => {
      const results = data.results || [];
      _wfUpdateDeviceCount(results.length);
      const okN = results.filter(r => r.ok).length;
      status.textContent = `Approved ${paths.length} path(s) on ${okN}/${results.length} device(s).`;
      status.className = okN === results.length ? 'small mt-1 text-success' : 'small mt-1 text-warning';
      showToast(`Approved on ${okN}/${results.length} device(s)`, okN === results.length ? 'success' : 'warning');
      btn.disabled = false; btn.textContent = 'Approve Selected';
      wfLoadSrpActivity();
    })
    .catch(e => {
      status.textContent = `Error: ${e.message}`; status.className = 'small mt-1 text-danger';
      btn.disabled = false; btn.textContent = 'Approve Selected';
    });
}

function wfRunItAuditAll() {
  const btn = document.getElementById('wf-itaudit-btn');
  const status = document.getElementById('wf-itaudit-status');
  const resultsEl = document.getElementById('wf-itaudit-results');
  if (!btn || !status) return;
  btn.disabled = true;
  status.textContent = `Starting IT Mode Audit on ${wfScopeLabel()}...`;
  status.className = 'small text-info mt-2';
  if (resultsEl) resultsEl.innerHTML = '';
  fetch('/api/remote-assist/fleet/it-audit/run', {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ groupId: wfGroupId() }),
  })
    .then(r => r.json())
    .then(data => {
      const results = data.results || [];
      _wfUpdateDeviceCount(results.length);
      const okN = results.filter(r => r.ok).length;
      status.textContent = `Started on ${okN}/${results.length} device(s) — check each device's Connection & Maintenance tab for progress/findings.`;
      status.className = okN === results.length ? 'small text-success mt-2' : 'small text-warning mt-2';
      if (resultsEl) {
        resultsEl.innerHTML = results.map(r => `
          <div class="d-flex justify-content-between gap-2">
            <span>${escHtml(r.deviceName)}</span>
            <span class="${r.ok ? 'text-success' : 'text-danger'}">${r.ok ? 'started' : escHtml(r.error || 'failed')}</span>
          </div>`).join('');
      }
      btn.disabled = false;
    })
    .catch(e => {
      status.textContent = `Error: ${e.message}`; status.className = 'small text-danger mt-2';
      btn.disabled = false;
    });
}

function wfWinUpdateAll(action, includeFeature) {
  const status = document.getElementById('wf-winupdate-status');
  if (!status) return;
  const isSecurityStart = action === 'security-start';
  const forceLabel = includeFeature ? 'Force Feature Update' : isSecurityStart ? 'Force Security Update' : 'Force Update';
  const verbing = action === 'unblock' ? 'Re-enabling' : action === 'force-start' || isSecurityStart ? `Starting ${forceLabel}` : 'Disabling';
  const verbed = action === 'unblock' ? 'Re-enabled' : action === 'force-start' || isSecurityStart ? `started ${forceLabel} on` : 'Disabled';
  const body = { groupId: wfGroupId() };
  if (isSecurityStart) Object.assign(body, { securityOnly: true });
  else if (action === 'force-start' && includeFeature) Object.assign(body, { includeFeatureUpdates: true, maxDurationMinutes: 480, maxReboots: 6 });
  const run = () => {
    status.textContent = `${verbing} on ${wfScopeLabel()}...`;
    status.className = 'small text-info mt-2';
    fetch(`/api/remote-assist/fleet/winupdate/${action}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) })
      .then(r => r.json())
      .then(data => {
        const results = data.results || [];
        _wfUpdateDeviceCount(results.length);
        const okN = results.filter(r => r.ok).length;
        status.textContent = `${verbed} ${okN}/${results.length} device(s).`;
        status.className = okN === results.length ? 'small text-success mt-2' : 'small text-warning mt-2';
        showToast(`Windows Update: ${verbed.toLowerCase()} (${okN}/${results.length})`, okN === results.length ? 'success' : 'warning');
      })
      .catch(e => { status.textContent = `Error: ${e.message}`; status.className = 'small text-danger mt-2'; });
  };
  if (action === 'block') {
    showConfirm({
      title: `Disable Windows Update on ${wfScopeLabel()}?`,
      body: `No updates (including security patches) will install on ${wfScopeLabel()} until you re-enable it here.`,
      okLabel: 'Disable',
      okClass: 'btn-danger',
      onConfirm: run,
    });
  } else if (action === 'force-start' && includeFeature) {
    showConfirm({
      title: `Force Feature Update on ${wfScopeLabel()}?`,
      body: `Temporarily re-enables Windows Update and installs EVERYTHING pending, including the next major Windows version upgrade, on ${wfScopeLabel()} — a much bigger download and longer install than a regular catch-up. May restart each PC automatically — one or more times, each with a 5-minute on-screen warning — until fully caught up. Windows Update is automatically re-disabled again per-device once finished. Check each device's own page for progress.`,
      okLabel: 'Force Feature Update',
      okClass: 'btn-danger',
      onConfirm: run,
    });
  } else if (isSecurityStart) {
    showConfirm({
      title: `Force Security Update on ${wfScopeLabel()}?`,
      body: `Temporarily re-enables Windows Update and installs ONLY security patches (exploit / 0-day fixes) on ${wfScopeLabel()} — nothing else. May restart each PC automatically — one or more times, each with a 5-minute on-screen warning — until caught up. Windows Update is automatically re-disabled again per-device once finished. Check each device's own page for progress.`,
      okLabel: 'Force Security Update',
      okClass: 'btn-danger',
      onConfirm: run,
    });
  } else if (action === 'force-start') {
    showConfirm({
      title: `Force Update Now on ${wfScopeLabel()}?`,
      body: `Temporarily re-enables Windows Update, installs everything pending (except major version upgrades), and may restart each PC automatically — one or more times, each with a 5-minute on-screen warning — until fully caught up. Windows Update is automatically re-disabled again per-device once finished. Check each device's own page for progress.`,
      okLabel: 'Force Update Now',
      okClass: 'btn-warning',
      onConfirm: run,
    });
  } else {
    run();
  }
}

function wfEdrIsolateAll(action) {
  const status = document.getElementById('wf-edr-isolate-status');
  if (!status) return;
  const run = () => {
    status.textContent = action === 'unblock' ? `Restoring network on ${wfScopeLabel()}...` : `Isolating ${wfScopeLabel()}...`;
    status.className = 'small text-info mt-2';
    fetch(`/api/remote-assist/fleet/edr-isolate/${action}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ groupId: wfGroupId() }) })
      .then(r => r.json())
      .then(data => {
        const results = data.results || [];
        _wfUpdateDeviceCount(results.length);
        const okN = results.filter(r => r.ok).length;
        status.textContent = `${action === 'unblock' ? 'Restored' : 'Isolated'} ${okN}/${results.length} device(s).`;
        status.className = okN === results.length ? 'small text-success mt-2' : 'small text-warning mt-2';
        showToast(`Host isolation ${action === 'unblock' ? 'restored' : 'enabled'} (${okN}/${results.length})`, okN === results.length ? 'success' : 'warning');
      })
      .catch(e => { status.textContent = `Error: ${e.message}`; status.className = 'small text-danger mt-2'; });
  };
  if (action === 'block') {
    showConfirm({
      title: `Isolate ${wfScopeLabel()} from the network?`,
      body: `Blocks all inbound/outbound network traffic on ${wfScopeLabel()} (within your controllable fleet) except the Remote Assist management tunnel itself. Every affected device owner loses internet access until you Restore. This is a heavy action.`,
      okLabel: 'Isolate',
      okClass: 'btn-danger',
      onConfirm: run,
    });
  } else {
    run();
  }
}

function wfTelemetryAll(action) {
  const status = document.getElementById('wf-telemetry-status');
  if (!status) return;
  const run = () => {
    status.textContent = action === 'unblock' ? `Restoring on ${wfScopeLabel()}...` : `Blocking on ${wfScopeLabel()}...`;
    status.className = 'small text-info mt-2';
    fetch(`/api/remote-assist/fleet/telemetry/${action}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ groupId: wfGroupId() }) })
      .then(r => r.json())
      .then(data => {
        const results = data.results || [];
        _wfUpdateDeviceCount(results.length);
        const okN = results.filter(r => r.ok).length;
        status.textContent = `${action === 'unblock' ? 'Restored' : 'Blocked'} on ${okN}/${results.length} device(s).`;
        status.className = okN === results.length ? 'small text-success mt-2' : 'small text-warning mt-2';
        showToast(`Telemetry ${action === 'unblock' ? 'restored' : 'blocked'} (${okN}/${results.length})`, okN === results.length ? 'success' : 'warning');
      })
      .catch(e => { status.textContent = `Error: ${e.message}`; status.className = 'small text-danger mt-2'; });
  };
  if (action === 'block') {
    showConfirm({
      title: `Block Windows telemetry on ${wfScopeLabel()}?`,
      body: `Blocks OS-level telemetry on ${wfScopeLabel()}: registry policy, telemetry services, and known Microsoft telemetry hosts (auto-updated from a maintained list + re-checked daily on each device). Windows Update itself is left untouched. You can restore it here any time.`,
      okLabel: 'Block',
      okClass: 'btn-danger',
      onConfirm: run,
    });
  } else {
    run();
  }
}

function wfSentryAll(action) {
  const status = document.getElementById('wf-sentry-status');
  if (!status) return;
  const run = () => {
    status.textContent = action === 'disable' ? `Disabling on ${wfScopeLabel()}...` : `Deploying on ${wfScopeLabel()}...`;
    status.className = 'small text-info mt-2';
    fetch(`/api/remote-assist/fleet/sentry/${action}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ groupId: wfGroupId() }) })
      .then(r => r.json())
      .then(data => {
        const results = data.results || [];
        _wfUpdateDeviceCount(results.length);
        const okN = results.filter(r => r.ok).length;
        status.textContent = `${action === 'disable' ? 'Disabled' : 'Enabled'} on ${okN}/${results.length} device(s).`;
        status.className = okN === results.length ? 'small text-success mt-2' : 'small text-warning mt-2';
        showToast(`Sentry ${action === 'disable' ? 'disabled' : 'enabled'} (${okN}/${results.length})`, okN === results.length ? 'success' : 'warning');
      })
      .catch(e => { status.textContent = `Error: ${e.message}`; status.className = 'small text-danger mt-2'; });
  };
  if (action === 'enable') {
    showConfirm({
      title: `Enable Sentry Mode on ${wfScopeLabel()}?`,
      body: `Deploys endpoint honeypot decoys (fake credentials, SMB share, registry traps, browser guard, LSASS watch) on ${wfScopeLabel()}. Each device will run a background watch task. You can disable later to clean up all artifacts.`,
      okLabel: 'Enable Sentry',
      okClass: 'btn-danger',
      onConfirm: run,
    });
  } else {
    run();
  }
}

