function wfArpScanAll() {
  const status = document.getElementById('wf-arp-status');
  if (!status) return;
  status.textContent = `Scanning ${wfScopeLabel()}'s local network (this can take a while)...`;
  status.className = 'small text-info mt-2';
  fetch('/api/remote-assist/fleet/arp-scan', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ groupId: wfGroupId() }) })
    .then(r => r.json())
    .then(data => {
      const results = data.results || [];
      _wfUpdateDeviceCount(results.length);
      const okN = results.filter(r => r.ok).length;
      const totalFound = results.reduce((n, r) => n + (r.ok ? (r.data?.deviceCount ?? (r.data?.devices || []).length) : 0), 0);
      status.textContent = `Scanned ${okN}/${results.length} device(s), ${totalFound} network device(s) found total.`;
      status.className = okN === results.length ? 'small text-success mt-2' : 'small text-warning mt-2';
      showToast(`ARP scan complete (${okN}/${results.length})`, okN === results.length ? 'success' : 'warning');
      if (selectedDeviceId) raArpScanRefresh();
    })
    .catch(e => { status.textContent = `Error: ${e.message}`; status.className = 'small text-danger mt-2'; });
}

