function wfRunPowerShellAll() {
  const scriptEl = document.getElementById('wf-ps-script');
  const timeoutEl = document.getElementById('wf-ps-timeout');
  const btn = document.getElementById('wf-ps-run-btn');
  const status = document.getElementById('wf-ps-status');
  const resultsEl = document.getElementById('wf-ps-results');
  if (!scriptEl || !btn || !status) return;
  const script = scriptEl.value;
  if (!script.trim()) { showToast('Enter a script first', 'warning'); return; }
  const timeoutSec = parseInt(timeoutEl?.value, 10) || 60;
  const run = () => {
    btn.disabled = true; btn.textContent = 'Running...';
    status.textContent = `Running on ${wfScopeLabel()} (this can take a while)...`;
    status.className = 'small text-info mb-2';
    if (resultsEl) resultsEl.innerHTML = '';
    fetch('/api/remote-assist/fleet/powershell', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ script, timeoutSec, groupId: wfGroupId() }),
    })
      .then(r => r.json())
      .then(data => {
        const results = data.results || [];
        _wfUpdateDeviceCount(results.length);
        const okN = results.filter(r => r.ok).length;
        status.textContent = `Completed on ${okN}/${results.length} device(s).`;
        status.className = okN === results.length ? 'small text-success mb-2' : 'small text-warning mb-2';
        if (resultsEl) {
          resultsEl.innerHTML = results.map((r, i) => {
            const out = (r.data?.stdout || '').trim();
            const err = (r.data?.stderr || '').trim();
            // Some commands (Restart-Computer, Stop-Service, ...) legitimately print nothing on
            // success — empty stdout + exit 0 means "ran fine", not "did it even work?", so say so
            // explicitly rather than leaving a bare "(no output)" that reads as ambiguous/broken.
            const bodyText = r.ok
              ? (out || '(command completed — no console output)')
              : (r.error || err || 'failed');
            return `
            <div class="mb-2 border border-secondary-subtle rounded p-2">
              <div class="d-flex justify-content-between gap-2 mb-1">
                <span class="fw-semibold">${escHtml(r.deviceName)}</span>
                <span class="${r.ok ? 'text-success' : 'text-danger'}">${r.ok ? `exit ${r.data?.exitCode ?? 0}` : 'failed'}</span>
              </div>
              <pre class="font-monospace mb-0" style="font-size:.7rem;white-space:pre-wrap;word-break:break-all;max-height:180px;overflow-y:auto">${escHtml(bodyText)}</pre>
              ${(r.ok && err) ? `<pre class="font-monospace mb-0 text-warning" style="font-size:.7rem;white-space:pre-wrap;word-break:break-all">${escHtml(err)}</pre>` : ''}
            </div>`;
          }).join('');
        }
        btn.disabled = false; btn.textContent = 'Run on All';
      })
      .catch(e => {
        status.textContent = `Error: ${e.message}`; status.className = 'small text-danger mb-2';
        btn.disabled = false; btn.textContent = 'Run on All';
      });
  };
  showConfirm({
    title: `Run PowerShell on ${wfScopeLabel()}?`,
    body: `<pre class="font-monospace mb-0" style="font-size:.75rem;white-space:pre-wrap;word-break:break-all;max-height:200px;overflow-y:auto">${escHtml(script.slice(0, 500))}${script.length > 500 ? '\u2026' : ''}</pre>`,
    okLabel: 'Run',
    okClass: 'btn-danger',
    onConfirm: run,
  });
}
