// Lock Down — disable user access to system tools while agent (SYSTEM) retains access
function wfLockdownAll(action) {
  const status = document.getElementById('wf-lockdown-status');
  if (!status) return;
  const lockScript = `# === LOCKDOWN: disable user access to system tools ===

# Ensure Application Identity service is running (required for SRP enforcement)
Set-Service -Name AppIDSvc -StartupType Automatic -ErrorAction SilentlyContinue
Start-Service AppIDSvc -ErrorAction SilentlyContinue

# Disable Task Manager via registry (HKLM — immediate effect on NEW instances)
New-ItemProperty -Path "HKLM:\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System" -Name "DisableTaskMgr" -Value 1 -PropertyType DWord -Force | Out-Null

# Disable Registry Editor via registry (HKLM)
New-ItemProperty -Path "HKLM:\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System" -Name "DisableRegistryTools" -Value 1 -PropertyType DWord -Force | Out-Null

# Disable CMD via SRP (Software Restriction Policies) — hash-based, applies immediately
$srpPath = "HKLM:\\SOFTWARE\\Policies\\Microsoft\\Windows\\Safer"
New-ItemProperty -Path "$srpPath\\CodeIdentifiers" -Name "TransparentEnabled" -Value 1 -PropertyType DWord -Force | Out-Null
New-ItemProperty -Path "$srpPath\\CodeIdentifiers" -Name "DefaultLevel" -Value 0 -PropertyType DWord -Force | Out-Null
$cmdPath = "$env:SystemRoot\\System32\\cmd.exe"
$cmdHash = (Get-FileHash $cmdPath -Algorithm SHA256).Hash
$srpRule = "HKLM:\\SOFTWARE\\Policies\\Microsoft\\Windows\\Safer\\CodeIdentifiers\\0\\Paths\\{$cmdHash}"
New-ItemProperty -Path $srpRule -Name "ItemData" -Value 2 -PropertyType DWord -Force | Out-Null
New-ItemProperty -Path $srpRule -Name "Description" -Value "Blocked by Sentinel lockdown" -PropertyType String -Force | Out-Null

# Block powershell.exe
$psPath = "$env:SystemRoot\\System32\\WindowsPowerShell\\v1.0\\powershell.exe"
if (Test-Path $psPath) {
  $psHash = (Get-FileHash $psPath -Algorithm SHA256).Hash
  $psRule = "HKLM:\\SOFTWARE\\Policies\\Microsoft\\Windows\\Safer\\CodeIdentifiers\\0\\Paths\\{$psHash}"
  New-ItemProperty -Path $psRule -Name "ItemData" -Value 2 -PropertyType DWord -Force | Out-Null
  New-ItemProperty -Path $psRule -Name "Description" -Value "Blocked by Sentinel lockdown" -PropertyType String -Force | Out-Null
}

# UAC hardening
New-ItemProperty -Path "HKLM:\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System" -Name "ConsentPromptBehaviorAdmin" -Value 3 -PropertyType DWord -Force | Out-Null
New-ItemProperty -Path "HKLM:\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System" -Name "PromptOnSecureDesktop" -Value 1 -PropertyType DWord -Force | Out-Null

# Disable Windows Script Host
New-ItemProperty -Path "HKLM:\\SOFTWARE\\Microsoft\\Windows Script Host\\Settings" -Name "Enabled" -Value 0 -PropertyType DWord -Force | Out-Null

Write-Output "LOCKDOWN_APPLIED"`;
  const unlockScript = `# === UNLOCKDOWN: restore user access ===
Remove-ItemProperty -Path "HKLM:\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System" -Name "DisableTaskMgr" -ErrorAction SilentlyContinue
Remove-ItemProperty -Path "HKLM:\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System" -Name "DisableRegistryTools" -ErrorAction SilentlyContinue
Remove-Item -Path "HKLM:\\SOFTWARE\\Policies\\Microsoft\\Windows\\Safer\\CodeIdentifiers\\0\\Paths" -Recurse -Force -ErrorAction SilentlyContinue
New-ItemProperty -Path "HKLM:\\SOFTWARE\\Policies\\Microsoft\\Windows\\Safer\\CodeIdentifiers" -Name "DefaultLevel" -Value 262144 -PropertyType DWord -Force | Out-Null
New-ItemProperty -Path "HKLM:\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System" -Name "ConsentPromptBehaviorAdmin" -Value 5 -PropertyType DWord -Force | Out-Null
Remove-ItemProperty -Path "HKLM:\\SOFTWARE\\Microsoft\\Windows Script Host\\Settings" -Name "Enabled" -ErrorAction SilentlyContinue
Write-Output "LOCKDOWN_REMOVED"`;
  const script = action === 'unlock' ? unlockScript : lockScript;
  const run = () => {
    status.textContent = action === 'unlock' ? `Restoring tools on ${wfScopeLabel()}...` : `Locking down ${wfScopeLabel()}...`;
    status.className = 'small text-info mt-2';
    fetch('/api/remote-assist/fleet/powershell', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ script, groupId: wfGroupId() }),
    })
      .then(r => r.json())
      .then(data => {
        const results = data.results || [];
        _wfUpdateDeviceCount(results.length);
        const okN = results.filter(r => r.ok).length;
        status.textContent = `${action === 'unlock' ? 'Restored' : 'Locked down'} on ${okN}/${results.length} device(s).`;
        status.className = okN === results.length ? 'small text-success mt-2' : 'small text-warning mt-2';
        showToast(`Lockdown ${action === 'unlock' ? 'removed' : 'applied'} (${okN}/${results.length})`, okN === results.length ? 'success' : 'warning');
      })
      .catch(e => { status.textContent = `Error: ${e.message}`; status.className = 'small text-danger mt-2'; });
  };
  showConfirm({
    title: `${action === 'unlock' ? 'Restore tools on' : 'Lock down'} ${wfScopeLabel()}?`,
    body: `<b>Disables for the user:</b> Task Manager, Registry Editor, CMD, unsigned PowerShell scripts<br><b>UAC:</b> Always prompt for password on secure desktop<br><b>Windows Script Host:</b> Disabled<br><br><b>Agent (SYSTEM) retains full access to everything.</b>`,
    okLabel: action === 'unlock' ? 'Restore' : 'Lock Down',
    okClass: 'btn-danger',
    onConfirm: run,
  });
}

// Create Standard User — non-admin account for daily use
function wfCreateStandardUser() {
  const pw = document.getElementById('wf-stduser-password')?.value;
  const name = document.getElementById('wf-stduser-name')?.value || 'User';
  const status = document.getElementById('wf-lockdown-status');
  if (!status) return;
  if (!pw || pw.length < 4) { showToast('Password must be at least 4 characters', 'warning'); return; }
  const script = `# Create standard (non-admin) user for daily use
$exists = Get-LocalUser -Name "${name}" -ErrorAction SilentlyContinue
if ($exists) { Write-Output "USER_EXISTS"; exit 0 }
New-LocalUser "${name}" -Password (ConvertTo-SecureString "${pw}" -AsPlainText -Force) -FullName "${name}" -Description "Standard user — daily use" -PasswordNeverExpires | Out-Null
Add-LocalGroupMember -Group "Users" -Member "${name}" -ErrorAction SilentlyContinue
# Do NOT add to Administrators — this is a standard user
Write-Output "USER_CREATED"`;
  status.textContent = `Creating standard user "${name}" on ${wfScopeLabel()}...`;
  status.className = 'small text-info mt-2';
  fetch('/api/remote-assist/fleet/powershell', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ script, groupId: wfGroupId() }),
  })
    .then(r => r.json())
    .then(data => {
      const results = data.results || [];
      _wfUpdateDeviceCount(results.length);
      const okN = results.filter(r => r.ok).length;
      status.textContent = `User "${name}" created on ${okN}/${results.length} device(s).`;
      status.className = okN === results.length ? 'small text-success mt-2' : 'small text-warning mt-2';
      showToast(`Standard user created (${okN}/${results.length})`, okN === results.length ? 'success' : 'warning');
    })
    .catch(e => { status.textContent = `Error: ${e.message}`; status.className = 'small text-danger mt-2'; });
}

// Hide admin account from login screen
function wfHideAdminAccount() {
  const status = document.getElementById('wf-lockdown-status');
  if (!status) return;
  const script = `# Hide admin account from login screen (still accessible via Ctrl+Alt+Del)
$adminName = (Get-LocalUser | Where-Object { $_.Name -ne "User" -and $_.Enabled } | Select-Object -First 1).Name
if (-not $adminName) { $adminName = (Get-LocalUser | Where-Object { $_.Enabled } | Select-Object -First 1).Name }
if (-not $adminName) { Write-Output "NO_ADMIN_FOUND"; exit 0 }
New-ItemProperty -Path "HKLM:\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\Winlogon\\SpecialAccounts\\UserList" -Name $adminName -Value 0 -PropertyType DWord -Force | Out-Null
Write-Output "ADMIN_HIDDEN: $adminName"`;
  status.textContent = `Hiding admin account on ${wfScopeLabel()}...`;
  status.className = 'small text-info mt-2';
  fetch('/api/remote-assist/fleet/powershell', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ script, groupId: wfGroupId() }),
  })
    .then(r => r.json())
    .then(data => {
      const results = data.results || [];
      _wfUpdateDeviceCount(results.length);
      const okN = results.filter(r => r.ok).length;
      status.textContent = `Admin account hidden on ${okN}/${results.length} device(s).`;
      status.className = okN === results.length ? 'small text-success mt-2' : 'small text-warning mt-2';
      showToast(`Admin hidden (${okN}/${results.length})`, okN === results.length ? 'success' : 'warning');
    })
    .catch(e => { status.textContent = `Error: ${e.message}`; status.className = 'small text-danger mt-2'; });
}

