// Hides the Remote Assist tab entirely for admin viewing a ZK-owned (public-user-claimed)
// device — dashboard-side backstop; the real enforcement is the server's hard 403
// (requireDeviceController(), reused unchanged) plus the private key never existing server-side
// at all for such a device.
function applyRemoteAssistGating(device) {
  const navItem = document.querySelector('[data-tab="remote-assist"]')?.closest('.nav-item');
  const sheetItem = document.querySelector('.tab-sheet-item[data-tab="remote-assist"]');
  const hideForAdmin = currentUser.role === 'admin' && currentUser.account_type !== 'public' && device.zk_owned;
  if (navItem) navItem.style.display = hideForAdmin ? 'none' : '';
  if (sheetItem) sheetItem.style.display = hideForAdmin ? 'none' : '';
  if (hideForAdmin) {
    document.getElementById('ra-session-panel')?.classList.add('d-none');
  }
}

// ── All Alerts nav badge — background refresh every 90s (active count only). ──
// Keeps the navbar badge honest without the user opening the panel; skipped while the panel
// is open (its own loads keep it fresh) and before the user session resolves.
setInterval(async () => {
  if (!currentUser?.username) return;
  const panel = document.getElementById('all-alerts-panel');
  if (panel && panel.style.display === 'flex') return;
  try {
    const r = await fetch('/api/users/me/alerts');
    if (!r.ok) return;
    const data = await r.json();
    const badge = document.getElementById('all-alerts-nav-badge');
    if (badge) {
      badge.textContent = data.activeCount;
      badge.classList.toggle('d-none', !data.activeCount);
    }
    if (!_allAlertsCache) _allAlertsCache = data;
  } catch { /* silent — the panel load retries on open */ }
}, 90000);

